  FT["PH-H21044"] = {"id":"PH-H21044","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a National Committee to Take Charge of the Celebration of Philippine Independence Day on June 12, 1982","orig":"Creating a National Committee to Take Charge of the Celebration of Philippine Independence Day on June 12, 1982"},"level":"law","status":"active","docNumber":"Executive Order No. 791","issuingBody":"President of the Philippines","promulgatedDate":"1982-04-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00791_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00791_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21044-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 791 April 11, 1982\nCREATING A NATIONAL COMMITTEE TO TAKE CHARGE OF THE CELEBRATION OF\nPHILIPPINE INDEPENDENCE DAY ON JUNE 12, 1982\nPursuant to the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby create a national committee to take charge of the celebration of Philippine Independence Day on June\n12, 1982.\nThe Committee shall be composed of the following:\nThe Minister of Education and Culture\nThe Minister of the Budget\nVice-Chairman\nThe Presidential Assistant on National Minorities\nThe Director-General of Media Affairs\nThe Deputy Minister of Public Works & Highways\nThe Deputy Minister of Labor and Employment\nThe Deputy Minister of National Defense\nThe Deputy Minister of Local Governments and Community Development\nThe Deputy Minister of Tourism\nThe Deputy Minister of Human Settlements\nThe Deputy Minister of Transportation and Communications\nThe Deputy Minister of Muslim Affairs\nThe Deputy Minister of Youth and Sports Development\nThe Vice-Governor of the Metro Manila Commission\nThe Mayor of Manila\nThe Chairman of the National Historical Institute\nThe Executive Director of the National Commission on the Role of Filipino Women\nThe President of the Philippine Association of Colleges and Universities\nThe President of the Civic Assembly of Women of the Philippines\nThe Presidential Protocol Officer\nMember-Secretary\nThe Committee shall meet at the call of the Chairman and for the purpose of discharging its functions, may\ncreate its sub-committees as may be necessary.\nThe Committee is hereby authorized to call upon any department, bureau, office, agency or instrumentality of\nthe Government, including government-owned or controlled corporations, for such assistance as it may need\nin the discharge of its duties and functions.\nDone in the City of Manila, this 11th day of April in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21045"] = {"id":"PH-H21045","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Implementing the Final 25% Increase in Distilled Spirits, Wines, Compounded Liquors and Fermented Liquors Pursuant to BP Blg. 82","orig":"Implementing the Final 25% Increase in Distilled Spirits, Wines, Compounded Liquors and Fermented Liquors Pursuant to BP Blg. 82"},"level":"law","status":"active","docNumber":"Executive Order No. 792","issuingBody":"President of the Philippines","promulgatedDate":"1982-04-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00792_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00792_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21045-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The final 25% increase in specific tax rates on distilled spirits, wines and compounded liquors, and\nfermented liquors under Sections 145(a); 146(b) to (h); and 147 respectively, of the National Internal Revenue\nCode as amended by BP 82 shall take effect on April 12, 1982.\nDone in the City of Manila, this 11th day of April, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21046"] = {"id":"PH-H21046","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANAN PALACE REFORMING THE NO-PAYMENT, NO PERIODIC EXAMINATION POLICY IN STATE UNIVERSITIES AND COLLEGES AND EXPANDING THE COVERAGE OF THE STUDENTS' ASSISTANCE FUND FOR","orig":"MALACANAN PALACE REFORMING THE NO-PAYMENT, NO PERIODIC EXAMINATION POLICY IN STATE UNIVERSITIES AND COLLEGES AND EXPANDING THE COVERAGE OF THE STUDENTS' ASSISTANCE FUND FOR"},"level":"law","status":"active","docNumber":"Executive Order No. 792","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00792_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00792_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21046-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Commission on Higher Education shall instruct all state\nuniversities and colleges (SUCs) to devise a flexible, socially-sensitive tuition fee\npayment plan and reform the no-payment, no periodic examination policy that is\ncurrently being applied;"}},{"id":"PH-H21046-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The administrators of the Students' Assistance Fund for\nEducation shall expand the coverage of the program. On top of tuition,\nbeneficiaries of the program should receive the following additional benefits:\n1. Monthly stipend to subsidize the students' transport fares, and\n2. Laboratory, research and book allowance."}},{"id":"PH-H21046-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Order shall take effect immediately.\nDone in the City of Manila on the 21st of April in the year of Our Lord, Two\nThousand and Nine.\nUterine Mr. herago\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nFOMA Hologram # 48087"}}],"pack":"ph-p159"};
  FT["PH-H21047"] = {"id":"PH-H21047","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Authorizing the Increase in Salaries of Metropolitan Manila Commission Officials And","orig":"Authorizing the Increase in Salaries of Metropolitan Manila Commission Officials And"},"level":"law","status":"active","docNumber":"Executive Order No. 793","issuingBody":"President of the Philippines","promulgatedDate":"1982-04-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00793_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00793_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21047-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Maximum Salary Rate for the Governor/Chairman. The annual salary of the Metropolitan Manila\nGovernor/Chairman shall be equated to that of a Cabinet Member: Provided, that it shall be automatically\nadjusted in accordance with any modification of the rate for Cabinet Members as may be subsequently"}},{"id":"PH-H21047-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Maximum Salaries of Vice Governor/ Vice Chairman, Commissioners for Finance, Planning and\nOperations and City Mayor/Vice Mayors of Manila, Quezon, Pasay and Caloocan. The annual salaries of the\nVice Governor/Vice Chairman, Commissioners for Finance, Planning and Operations and City Mayor/Vice\nMayors of Manila, Quezon, Pasay and Caloocan shall be equated to those of the Career Executive Service in\naccordance with the schedule indicated below: Provided that the rates specified herein shall be automatically\nrevised in accordance with any modification of the rates for Career Executive Service Officers as may be\nsubsequently approved.\nEquivalent CES\nRank and Grade\nVice Governor/Vice Chairman\nCommissioners for Finance, Planning and Operations\nCity Mayors/Vice Mayors\n\nQuezon/Pasay/Caloocan"}},{"id":"PH-H21047-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Funding. The amounts necessary to implement the salary increase of the above-mentioned officials\nshall be drawn from the salary savings or such other funds of the Metro Manila Commission or the city\nconcerned as are not otherwise earmarked for specific purposes.\nSec. 3. Effectivity. The increase in salaries authorized in this Order shall be retroactive to January 1981.\nDone in the City of Manila, this 26th day of April in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21048"] = {"id":"PH-H21048","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHI1,IPPINES MAKING \"GO NEGOSYq SAGOT SA KAHIRAPAN AND ENTREPRENIEURSHIP\" AS BANNER PROGRAMS OF THE ADMINISTRATION AND EXPANDING THE COMPOSITION OF THE SMALL AND MEDIUM ENTERPRISE DEVELOPMENT COUNCIL INTO THE MICRO, SMALL AND MEDIUM ENTERPRISE DEVELOPMENT COUNCIL","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHI1,IPPINES MAKING \"GO NEGOSYq SAGOT SA KAHIRAPAN AND ENTREPRENIEURSHIP\" AS BANNER PROGRAMS OF THE ADMINISTRATION AND EXPANDING THE COMPOSITION OF THE SMALL AND MEDIUM ENTERPRISE DEVELOPMENT COUNCIL INTO THE MICRO, SMALL AND MEDIUM ENTERPRISE DEVELOPMENT COUNCIL"},"level":"law","status":"active","docNumber":"Executive Order No. 793","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00793_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00793_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21048-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"\"Go Negosyo, Sagot sa Kahirapan and Entrepreneurship\" shall be made\nbanner programs of the Administration.\nExpansion of Micro, Small and Medium Enterprise Development\n(MSMED) Council.- The membership of the MSMED shall be expanded to include the\nheads of primary agencies involved in micro, small and medium finance activities of the\nnational government, such as but not limited to the following:\n1) Cooperative Development Authority\n2) National Livelihood and Development Corporation\n3) People's Credit and Finance Corporation\n4) University of the Philippines Institute for Small Scale Industries"}},{"id":"PH-H21048-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"All training and capacity-building programs shall be unified into one\nEntrepreneurship Development Framework (EDF). An Entrepreneurship Summit shall\nbe mounted to present such EDF, with specific roles from government agencies and\nprivate sector groups as identified by the MSMED Council. The EDF shall be cascaded\nto all local government units."}},{"id":"PH-H21048-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"The local officials, i.e. Governors and Mayors, shall be encouraged to\nbecome Negosyo Champions."}},{"id":"PH-H21048-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"For better communication campaign, the above shall be put under one\nbanner called Negosyo."}},{"id":"PH-H21048-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"A holistic approach shall be developed from Entrepreneur Mindset (Go\nNegosyo), Market-Orientation and Access, Product Innovations/Technology and Design,\nFinancing Support, to Fora for Networking and Mentoring (Go Negosyo) that shall be\nmade available to MSME's."}},{"id":"PH-H21048-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"The corresponding executive budget for the above program shall be\nconsolidated."}},{"id":"PH-H21048-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"The Press Secretary shall conduct an advocacy and awareness campaign\non the above."}},{"id":"PH-H21048-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"All executive issuances, rules, regulations or parts thereof which are\ninconsistent with any of the provisions hereof are hereby repealed, amended or modified\naccordingly."}},{"id":"PH-H21048-A10","no":10,"noLabel":{"en":"SECTION 10"},"text":{"en":"This Executive Order shall take effect immediately.\nCity of Manila, bpi(\n%4 ? 2009.\nBy the President:\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21049"] = {"id":"PH-H21049","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Authorizing the President of the Philippines the Importation of Fuel Oil (LOI No. 837), Diesel Fuel and Kerosene (LOI No. 839) Free From Customs Duties and Other Importation Taxes and Charges","orig":"Authorizing the President of the Philippines the Importation of Fuel Oil (LOI No. 837), Diesel Fuel and Kerosene (LOI No. 839) Free From Customs Duties and Other Importation Taxes and Charges"},"level":"law","status":"active","docNumber":"Executive Order No. 794","issuingBody":"President of the Philippines","promulgatedDate":"1982-04-06","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00794_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00794_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21049-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The tax and duty exemption on diesel fuel granted under LOI No. 839 be withdrawn."}},{"id":"PH-H21049-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Philippine National Oil Company shall, however, remain authorized to import, free from Customs\nduties and all other importation taxes and charges, upon prior clearance of the Bureau of Energy Utilization,\nsuch volumes of diesel fuel as may by necessary to alleviate the diesel fuel supply shortage in the country."}},{"id":"PH-H21049-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect immediately.\n\nDone in the City of Manila, this 6th day of April, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21050"] = {"id":"PH-H21050","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Philippine Commission for the International Youth Year and Defining Its Powers and Functions","orig":"Creating the Philippine Commission for the International Youth Year and Defining Its Powers and Functions"},"level":"law","status":"active","docNumber":"Executive Order No. 795","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-03","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00795_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00795_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21050-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Philippine Commission for the International Youth Year. There is hereby created a Commission to\nbe known as the Philippine Commission for the International Youth Year which shall be attached to the Office\nof the President for general direction and coordination."}},{"id":"PH-H21050-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Composition. The Commission shall be headed by the Chairman of the Kabataang Barangay, the KB\nbeing the premier youth organization in the country, with representatives from the following agencies as\n1. Ministry of Foreign Affairs\n2. Ministry of Education and Culture\n3. Ministry of Social Services Development\n4. Ministry of the Budget\n5. Ministry of Agriculture\n6. Ministry of Labor and Employment\n7. National Manpower and Youth Council"}},{"id":"PH-H21050-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Functions. The Commission shall have the following functions:\n1. Set forth the guidelines for proposed program of activities for the celebration of International Youth Year;\n2. Plan and coordinate all activities for the 1985 celebration;\n3. Supervise the implementation of all plans and programs for the celebration of the International Youth Year;\n4. Receive and disburse all allocated funds for the Commission.\n5. Have custody of all files and records pertaining to the International Youth Year, and tap the assistance of\nthe private sector of its functions;\n6. Undertake evaluation of all activities related to this celebration;\n7. Represent the Philippines to the United Nations Commission for the International Youth Year;\n\n8. Perform such other functions as may be necessary for the successful implementation of its programs.\nAll other government ministries and institutions, including local government, shall assist the Commission in\nthe successful implementation of its programs. The Commission shall have a Secretariat as Staff support\nwhich shall be initially manned by the PKKB until such time as the Commission shall have appointed its own"}},{"id":"PH-H21050-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Powers of the Commission.\n1. To promulgate, implement and enforce its policies with regard to the International Youth Year;\n2. To identify the requirements of the Commission and work for the fulfillment thereof;\n3. To review, coordinate, integrate and approve resolutions, rules and regulations, and decisions promulgated\nby the various committees with respect to their functions within the Commission;\n4. To appoint members to the committees which may be formed by the Commission.\n5. To promulgate such rules and regulations for the implementation of its policies;\n6. To grant allowances and per diems or fix the salaries of officials and the staff it may employ, in accordance\nwith existing law, rules and regulations."}},{"id":"PH-H21050-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Funding. The Ministry of the Budget subject to the approval of the President is hereby directed to set\naside and release from the Special Activities Funds of the President such amounts as may be necessary to\ncarry out the purposes of this Order."}},{"id":"PH-H21050-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Philippine Commission for the International Youth Year shall constitute itself immediately and\nshall exist for five (5) years from the issuance of this Order, unless earlier abolished by the President of the\nPhilippines."}},{"id":"PH-H21050-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 3rd day of May in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21051"] = {"id":"PH-H21051","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE AN ORDER ATTACHING THE NATIONAL YOUTH COMMISSION FROM THE OFFICE OF THE PRESIDENT TO THE DEPARTMENT OF SOCIAL WELFARE AND DEVELOPMENT","orig":"MALACAÑAN PALACE AN ORDER ATTACHING THE NATIONAL YOUTH COMMISSION FROM THE OFFICE OF THE PRESIDENT TO THE DEPARTMENT OF SOCIAL WELFARE AND DEVELOPMENT"},"level":"law","status":"active","docNumber":"Executive Order No. 795","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00795_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00795_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21051-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The National Youth Commission is hereby attached to the Department of\nSocial Welfare and Development."}},{"id":"PH-H21051-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 7th day of MAY\nThousand and Nine.\nin the year of Our Lord, Two\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21052"] = {"id":"PH-H21052","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Amending the Composition of the Board of Trustees of the Metropolitan Waterworks and Sewerage System","orig":"Amending the Composition of the Board of Trustees of the Metropolitan Waterworks and Sewerage System"},"level":"law","status":"active","docNumber":"Executive Order No. 796","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-06","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00796_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00796_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21052-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The composition of the Board of Trustees of the Metropolitan Waterworks and Sewerage System\n(MWSS) is hereby amended as follows;\nThe Minister of Public Works and Highways\nThe General Manager of the MWSS\nVice-Chairman\nOne (1) representative of the Labor Union representing majority of the rank and file of the employees of the\nFour (4) others appointed by the President of the Philippines"}},{"id":"PH-H21052-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Section 4 of republic Act No. 6234 is hereby modified accordingly."}},{"id":"PH-H21052-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect immediately.\nDone in the City of Manila, this 6th day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21053"] = {"id":"PH-H21053","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING THE INDUSTRY COMPETITIVENESS FUND (IF) TO SUPPORT POWER-INTENSIVE INDUSTRIES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING THE INDUSTRY COMPETITIVENESS FUND (IF) TO SUPPORT POWER-INTENSIVE INDUSTRIES"},"level":"law","status":"active","docNumber":"Executive Order No. 796","issuingBody":"President of the Philippines","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00796_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00796_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21053-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Establishment of the Industry Competitiveness Fund\n- An Industry Competitiveness Fund (ICF) is hereby established to support and\nincentivize qualified power-intensive industries which contribute significantly to\nthe economy by granting special power rates based on the criteria and quidelines\nthat will be developed for this purpose. The IC will be utilized to recover any\nfinancial impact that PSALM/PC, TRANSCO and PEZA have incurred in the grant\nof special power rate through a reimbursement mechanism that will be\ndeveloped by an inter-agency committee created herein.\nPOMA Hologram # 49007"}},{"id":"PH-H21053-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Coverage of the Industry Competitiveness Fund\n(IC) - The IC shall cover existing and future eligible preferred combined\ngeneration, transmission and distribution rates granted by PSALM/PC,\nTRANSCO and PEZA in accordance with their respective policies, rules and\nregulations, subject to the IC criteria and guidelines developed for this purpose."}},{"id":"PH-H21053-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Creation of the Inter-Agency Committee on IF - An\nInter-Agency Committee on IF to be chaired by the Department of Finance\n(DOF) and co-chaired by the Department of Energy (DOE) is hereby created with\nthe Department of Trade and Industry (DTI), Department of Budget and\nManagement (DBM), Philippine Economic Zone Authority (PEZA), Power Sector\nAssets and Liabilities Management Corporation (PSALM), National Power\nCorporation (NPC) and National Transmission\nCorporation-Government\n(TRANSCO) as members."}},{"id":"PH-H21053-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Responsibilities of the IC Inter-Agency Committee\n- The Inter-Agency Committee shall have the following mandate:\n1. Establish the criteria and guidelines for eligibility to the IF including\ndetermination of the IF entitlement\n2. Identify responsibilities of each member agencies in the implementation of\n3. Create a Technical Working Group which will evaluate and recommend\napplications for IF entitlement for approval of the IC Inter-Agency\n4. Develop the approval process for IC applicants and/or potential\nbeneficiaries of the ICF which will be the basis of the TWG for evaluation\nand recommendation"}},{"id":"PH-H21053-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Source of Funds - An initial amount of One Billion Six\nHundred Million Pesos (Php 1,600,000,000.00) from the government's collections\nof the Value Added Tax is hereby allocated for the initial beneficiaries of the ICF.\nThe Inter-Agency Committee shall identify fund sources to sustain the ICF"}},{"id":"PH-H21053-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Role of the Departments, Bureaus, Offices, Agencies,\nInstrumentalities of the Government. - All heads of departments, bureaus,\noffices, agencies and instrumentalities of the government are hereby directed to\ngive full support and assistance to PEZA, NPC, and TRANSCO in the\nimplementation of this Executive Order."}},{"id":"PH-H21053-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Implementing Guidelines. - The Inter Agency\nCommittee on IF shall promulgate the rules and regulations as may be\nnecessary to ensure the implementation of this Executive Order.\nP@MA Holoorsm & 49008"}},{"id":"PH-H21053-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Repealing Clause - All issuances, rules and regulations\ninconsistent herewith are deemed modified or repealed accordingly."}},{"id":"PH-H21053-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Separability Clause - If for any reason, any part or\nprovision of this Order shall be held unconstitutional or declared contrary to law,\nother parts or provision hereof which are not affected shall continue to be in full\nforce and effect."}},{"id":"PH-H21053-A10","no":10,"noLabel":{"en":"SECTION 10"},"text":{"en":"Effectivity - This Executive Order shall take effect fifteen\n(15) days after its publication in a national newspaper of general circulation.\nDONE in the City of Manila, this air day of MAY\nLord, Two Thousand and Nine.\n,in the year of Our\nGlair A. Aurp\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 49009"}}],"pack":"ph-p159"};
  FT["PH-H21054"] = {"id":"PH-H21054","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reorganizing the Ministry of Labor and Employment, Creating the Philippine Overseas Employment Administration, and for Other Purposes","orig":"Reorganizing the Ministry of Labor and Employment, Creating the Philippine Overseas Employment Administration, and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 797","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-01","completenessNote":"全文，共 21 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00797_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00797_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21054-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Ministry of Labor and Employment, hereinafter referred to as the Ministry, shall be the primary\npolicy, programming, coordinating and administrative entity of the executive branch of the government in the\nfield of labor and employment. The primary function of the Ministry shall be the development of employment\nopportunities, the protection of workers, and the promotion of industrial peace."}},{"id":"PH-H21054-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The authority and responsibility for the exercise of the powers and the discharge of the functions of the\nMinistry shall be vested in the Minister of Labor and Employment, hereinafter referred to as the Minister, who\nshall be appointed by the President. He shall be assisted by such Deputy Ministers as may be appointed by the\nPresident. The Minister is authorized to determine and assign the respective functional areas of responsibility\nof the Deputy Ministers, should there be more than one; provided, that such delineation of responsibilities\nshall cover the substantive functions and operations of the Ministry; and provided, further, that no Deputy\nMinister shall be assigned primarily administrative responsibilities."}},{"id":"PH-H21054-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"There is hereby created a Bureau of Local Employment, which shall assume the functions of the\nBureau of Apprenticeship and the domestic employment functions of the Bureau of Employment Services,\nand which shall absorb applicable functions, appropriations, records, equipment, property, and such personnel\nas may be necessary of the abolished units."}},{"id":"PH-H21054-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"There is hereby created a Philippine Overseas Employment Administration, hereinafter referred to as\nthe administration, which shall assume the functions of the Overseas Employment Development Board, the\nNational Seamen Board, and the overseas employment functions of the Bureau of Employment Services;\nwhich shall absorb the applicable functions, appropriations, records, equipment, property, and such personnel\nas may be necessary of the abolished units; and which shall have the powers, functions, and structure as\nprovided for below.\n(a) The Administration shall formulate and undertake in coordination where necessary with the appropriate\nentities concerned a systematic program for promoting and monitoring the overseas employment of Filipino\nworkers taking into consideration domestic manpower requirements, and to protect their rights to fair and\nequitable employment practices. It shall have original and exclusive jurisdiction over all cases, including\n\nmoney claims, involving employer-employee relations arising out of or by virtue of any law or contract\ninvolving Filipino workers for overseas employment, including seamen. This adjudicatory function shall be\nundertaken in appropriate circumstances in consultation with the Construction Industry Authority of the\nPhilippines. The governing Board of the Administration, as hereinunder provided, shall promulgate the\nnecessary rules an regulations to govern the exercise of the adjudicatory functions of the Administration.\n(b) The Administration shall have a three-man Board composed of the Minister as Chairman, the\nAdministrator, and a third member who shall be appointed by the President, who shall be well versed in the\nfield of overseas employment, and who shall serve for a term of two years. The Administrator and such\nDeputy Administrators as may be necessary shall be appointed by the President. The President may, at his\ndiscretion, designate a Deputy Administrator as the third member of the Board, and he may also confer the\nrank of Deputy Minister in a concurrent capacity to a particular incumbent of the position of Administrator.\n(c) The principal substantive subdivisions of the internal structure of the Administration shall be established\nalong the major functional areas corresponding to welfare services, placement and market development, and\nregulation. Each principal substantive subdivision shall be headed by a Director who shall be appointed by the\nPresident upon the recommendation of the Minister. The Administration shall have its own support staff.\n(d) An Advisory Board for Overseas Employment and an Advisory Board for Seamen are hereby created with\nsuch members as may be appointed by the Minister. The Advisory Boards shall have an essentially private\nsector composition to advise the Administration on its overseas operations, and its members shall be entitled\nto rates of compensation comparable to those prescribed for members of the abolished Overseas Employment\nDevelopment Board and the National Seamen Board.\n(e) The Regional Labor Office for the Middle East and Africa created under Executive Order No. 787 shall\nform part of the Administration. The head of the Regional Labor Office shall have the rank of Ambassador\n(Chief of Mission II)."}},{"id":"PH-H21054-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Bureau of Labor Standards is hereby renamed the Bureau of Working Conditions. In addition to\nits present functions, the Bureau shall assume the functions of the Institute of Occupational Health and Safety\nabolished under Executive Order No. 591."}},{"id":"PH-H21054-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Ministry proper of the Ministry shall be composed of an Office of the Minister, a Planning\nService, a Labor Statistic Service, a Financial and Management Service, an Administrative Service, an\ninformation and Publication Service, an International Labor Affair Service, and a Legal Service. The Deputy\nMinisters shall form part of the Office of the Minister."}},{"id":"PH-H21054-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Ministry shall exercise supervisions and control over the following bureaus and offices:\n(1) Bureau of Local Employment\n(2) Bureau of Labor Relations\n(3) Bureau of Working Conditions\n(4) Bureau of Rural Workers\n(5) Bureau of Women and Minors\n(6) Institute of Labor and Manpower Studies"}},{"id":"PH-H21054-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"The Ministry shall exercise administrative supervisions over the following entities:\n(1) National Labor Relation Commission\n(2) National Wages Council\n(3) Philippine Overseas Employment Administration\n(4) Welfare Fund for Overseas Workers"}},{"id":"PH-H21054-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"The following corporation is attached to the Ministry for policy and program coordination:\n\n(1) Employees Compensation Commission"}},{"id":"PH-H21054-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"The following entities are hereby abolished, and their functions, together with applicable\nappropriations, records, equipment, property, and such personnel as may be necessary are hereby transferred\nto such appropriate units of the Ministry as may be deemed suitable by the Minister:\n(1) Bureau of Employment Services\n(2) Bureau of Apprenticeship\n(3) Free Legal Assistance Office\n(4) National Seamen Board\n(5) Overseas Employment Development Board\n(6) Population/Family Planning Office"}},{"id":"PH-H21054-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"The Ministry shall have such ministry-wide regional offices as may be necessary, under the\nsupervisions and control of the Office of the Minister, in accordance with Article I, Chapter III, Part II of the\nIntegrated Reorganization Plan as amended. Each regional office shall be headed by a Regional Director who\nshall be assisted whenever necessary by an Assistant Regional Director. The Regional Director shall have\nsupervision and control over the activities of the Ministry in the region, except as may be otherwise\ndetermined by the Minister.\nThe abolition of the Arbitration Branches, the Field Services Divisions, and the Labor Relations Divisions in\nthe regional offices pursuant to Executive Order No. 591 shall be given effect, and their applicable\nappropriations, records, equipment and such personnel as may be necessary are transferred to the appropriate\nunits as determined by the Minister.\nPositions of Conciliators and Med-Arbiters which may be created under the new staffing patterns in the\nregional offices, as well as such positions in the Bureau of Labor Relations, shall have starting rates of\ncompensation which shall be equivalent to two salary ranges below those of Arbiters in the National Labor\nRelations Commission. The Minister is authorized to effect from time to time such regional reassignment of\nConciliators and Med-Arbiters as may be necessary in the interest of the service."}},{"id":"PH-H21054-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"The Ministry shall have such offices overseas as will enable it to carry out its responsibilities\neffectively, subject to prior approval by the President on the establishment of each such office abroad. The\nLabor Attache or his equivalent shall have supervisions over all other personnel of the Minister as may be\nassigned to an embassy or other foreign service post overseas, including those of the Philippine Overseas\nEmployment Administration."}},{"id":"PH-H21054-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"The Minister shall have the authority to reorganize the internal structure of the various offices and\nunits under the Ministry, as enumerated in Sections 6, 7, 8, 11, and 12 of this Executive Order."}},{"id":"PH-H21054-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"The Ministry is hereby authorized to issue such orders, rules and regulations as may be necessary to\nimplement the approval of the Office of Budget and Management is obtained relative to the new staffing\npattern including appropriate salary rates, the organizational structure at divisional and lower levels, and the\nrealignment of existing appropriations. The Minister may appoint qualified personnel of the abolished in the\nnew staffing pattern, and those not so appointed are deemed laid off."}},{"id":"PH-H21054-A15","no":15,"noLabel":{"en":"Sec 15"},"text":{"en":"All Presidential appointees of the bureaus, offices, and other entities under the supervision and\ncontrol of or under the administrative supervision of the Ministry are laid off, unless otherwise reappointed by\nthe President; provided, that those who are Career Executive Service Officers may either be reappointed or\nreassigned by the President upon the recommendation of the Minister to other appropriate positions in the\nMinistry, or assigned to the Career Executive Service Board which shall endeavor to find appropriate\nplacement for them in other ministries or agencies; provided, further, that those Career Executive Service\nOfficers who have been assigned to the Career Executive Service Board shall continue to receive their salaries\n\nfrom any available and applicable funds; and provided, finally, that those who are not placed in appropriate\npositions within six months after their assignment to the Career Executive Service Board shall be similarly"}},{"id":"PH-H21054-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"All those who are laid off under the provisions of this Executive Order shall be entitled to all benefits\nand gratuities provided for under existing laws."}},{"id":"PH-H21054-A17","no":17,"noLabel":{"en":"Sec 17"},"text":{"en":"Except as may otherwise be determined by the Minister, all present incumbents of positions in the\nreorganized units of the Ministry shall continue to exercise their usual functions, duties, and responsibilities,\npending the issuance of the appropriate implementing orders."}},{"id":"PH-H21054-A18","no":18,"noLabel":{"en":"Sec 18"},"text":{"en":"To carry out the provisions of this Executive Order such amount as may be necessary shall be made\navailable to the Ministry from any applicable appropriation item, subject to the approval of the President upon\nrecommendation of the Office of Budget and Management."}},{"id":"PH-H21054-A19","no":19,"noLabel":{"en":"Sec 19"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21054-A20","no":20,"noLabel":{"en":"Sec 20"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof, provided that such remaining portions can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21054-A21","no":21,"noLabel":{"en":"Sec 21"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this first day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21055"] = {"id":"PH-H21055","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADOPTING THE CORAL TRIANGLE INITIATIVE (CTI) NATIONAL PLAN","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADOPTING THE CORAL TRIANGLE INITIATIVE (CTI) NATIONAL PLAN"},"level":"law","status":"active","docNumber":"Executive Order No. 797","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00797_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00797_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21055-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Adoption of the CTI National Plan of Action (NPOA). The NOA is\nhereby adopted as attached to this Order. The NPOA shall serve as the primary\nframework for the development and implementation of all related plans and programs. on\nmarine and coastal resources management in the country.\n2"}},{"id":"PH-H21055-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Integration of the NPOA Priority Actions into the National Plans and\nPrograms. All agencies with coastal and marine concerns are hereby instructed to\nintegrate the NPOA priority actions into their corresponding national plans and budgets\nand contribute to the effective implementation of the NPOA."}},{"id":"PH-H21055-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Integration of the NPOA Priority Actions into the Local Plans and\nPrograms. All local government units, especially those within coastal areas, shall take\ninto consideration the NPOA Priority Actions in the preparation and implementation of\nlocal development plans and budgets and contribute to the effective implementation of"}},{"id":"PH-H21055-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Coordination Between the Department of Environment and Natural\nResources and the Department of Agriculture. The Secretary of Environment and\nNatural Resources and the Secretary of Agriculture shall coordinate the implementation\nof the NPOA. They shall jointly act as the national coordinating body for the NPOA\nimplementation and focal point of contact for the regional CT processes. They may call\nupon on other agencies/organizations/institutions for advice and assistance, as needed."}},{"id":"PH-H21055-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Joint Secretariat. The DENR-Protected Areas and Wildlife Bureau and DA-\nBureau of Fisheries and Aquatic Resources shall establish a Joint NCCC Secretariat with\nfull-time representatives from the Department of Foreign Affairs, Department of Finance,\nNational Economic and Development Authority, the non-governmental organizations, the\nacademic institutions and the business sector."}},{"id":"PH-H21055-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Financial Appropriation. An initial allocation of FIVE MILLION PESOS\n(Php 5 Million) to support the core operations of the Secretariat to leverage external\nfunds for the NPOA implementation shall be released by the Secretary of Budget and\nManagement from the budgets of the DEN and DA. The disbursement of and allocation\nof additional funds shall be subject to the submission and approval of the joint annual\nwork and financial plans of the Secretaries of DEN and DA."}},{"id":"PH-H21055-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Repealing Clause. All proclamations or executive orders, rules and\nregulations and other issuances or parts thereof, which are inconsistent with this\nExecutive Order are hereby revoked, amended, or modified accordingly.\nPGMÀ Hologram # 48477"}},{"id":"PH-H21055-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Separability. Any portion or provision of this Executive Order that maybe\ndeclared unconstitutional shall not have the effect of nullifying its other portions or\nprovisions, as long as such remaining portions call still be given effect."}},{"id":"PH-H21055-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Effectivity. This Executive Order shall take effect upon signing hereof.\nDONE in the City of Manila this 6th day of May in the year of Our Lord, Two Thousand\nTheirs a hung\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram a 48478"}}],"pack":"ph-p159"};
  FT["PH-H21056"] = {"id":"PH-H21056","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Justice System Consultative Commission","orig":"Creating the Justice System Consultative Commission"},"level":"law","status":"active","docNumber":"Executive Order No. 798","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-14","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00798_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00798_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21056-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 798 May 14, 1982\nCREATING THE JUSTICE SYSTEM CONSULTATIVE COMMISSION (JUSCCOM)\nWHEREAS, the government is committed to institute meaningful reform in the justice system;\nWHEREAS, the enactment of Batas Pambansa Blg. 129 has paved the way for the reorganization of the\njudiciary and the improvement of the performance of public service in the justice system;\nWHEREAS, there is need for a continuing search for innovative trends to systematize procedures and\nexpedite judicial processes;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution, do hereby order as follows:\n1. A commission to be known as the Justice System Consultative Commission (JUSCCOM) is hereby created\nwith the following composition:\nMinister of Justice C. Puno\nRetired Chief Justice Cesar Bengzon\nRetired Chief Justice Roberto Concepcion\nRetired Associate Justice Jose B.L. Reyes\n2. Membership in the Commission shall be honorary and the members thereof shall serve without\ncompensation.\n3. The Commission shall conduct studies of innovative trends towards the improvement of the rules of\nprocedure and the expedition of judicial processes and shall recommend legislative measures which may to\nthis end be appropriate and necessary.\n4. The Commission shall take care of its internal operations, and may for this purpose form sub-committees\nand/or call upon resource persons to aid it in its work. The Minister of Justice shall coordinate the work and\nthe internal operations of the Commission and extend to it all the necessary technical and secretarial\nassistance.\n5. The Commission shall, from time to time, report the results of its studies to the President. The President\nmay also call upon the Commission at any time for consultation upon any matter pursuant to the purposes set\nforth in this executive order.\nDone in the City of Manila this 14th day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21057"] = {"id":"PH-H21057","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG TRANSFERRING THE PHILIPPINE RECLAMATION AUTHORITY FROM THE DEPARTMENT OF PUBLIC WORKS AND HIGHWAYS TO THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES","orig":"MALACAÑANG TRANSFERRING THE PHILIPPINE RECLAMATION AUTHORITY FROM THE DEPARTMENT OF PUBLIC WORKS AND HIGHWAYS TO THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES"},"level":"law","status":"active","docNumber":"Executive Order No. 798","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00798_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00798_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21057-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Philippine Reclamation Authority is hereby transferred to the\nDepartment of Environment and Natural Resources."}},{"id":"PH-H21057-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 14M day of MAY\nTwo Thousand and Nine.\nglia to keeps\nin the year of Our Lord,\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologrom • 48856"}}],"pack":"ph-p159"};
  FT["PH-H21058"] = {"id":"PH-H21058","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Presidential Decree No. 1464, as Amended, Otherwise Known as the Tariff and Customs Code of 1978, in Order to Implement the 20%-25% Margins of Tariff Preference on Items With Import Value of $50,000 to $500,000 Cif 1978, as Recorded in the Foreign Trade Statistics of the Philippines, in Accordance With the Eleventh and Twelfth Decisions of the Asean Economic Ministers (AEM) Meetings.","orig":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Presidential Decree No. 1464, as Amended, Otherwise Known as the Tariff and Customs Code of 1978, in Order to Implement the 20%-25% Margins of Tariff Preference on Items With Import Value of $50,000 to $500,000 Cif 1978, as Recorded in the Foreign Trade Statistics of the Philippines, in Accordance With the Eleventh and Twelfth Decisions of the Asean Economic Ministers (AEM) Meetings."},"level":"law","status":"active","docNumber":"Executive Order No. 799","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00799_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00799_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21058-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The articles specifically listed in Annex 'A' hereof as classified under Section 104 of Presidential\nDecree No. 1464, as amended, shall be accorded a 20%-25% margins of tariff preference as agreed upon\nduring the Eleventh and Twelfth ASEAN Economic Ministers (AEM) Meetings. In effect, such articles shall\nbe subject to the Preferential Tariff for ASEAN in accordance with the schedule indicated opposite each\narticle as specified in Columns 8-11 of said Annex 'A'."}},{"id":"PH-H21058-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"After the date of effectivity of this Order, all the above-described articles entered or withdrawn from\nwarehouse, in the Philippines, for consumption shall be subject to the rate of import duty herein prescribed\nsubject to qualification under the Rules of Origin as specified in the Agreement on ASEAN Preferential\nTrading Arrangements ratified on August 1, 1977."}},{"id":"PH-H21058-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"This Order shall take effect on 1 February 1982.\nDone in the City of Manila, this 19th day of May in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21059"] = {"id":"PH-H21059","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 799","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00799_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00799_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21059-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Amendment of Section I' of Executive Order No. 657 (s. 2007)\n- Section | of Executive Order No. 657 (s.2007) is hereby amended to read as\n\"The Presidential Anti-Organized Crime Commission shall now be composed\nof the following:\nThe President\nThe Deputy Executive Secretary for\nFinance and Administration\nThe National Security Adviser\nThe Secretary of the Interior and Local\nVice-Chairman\nPOMA Hologram * 48897\n\nGovernment\nThe Secretary of Justice\nThe Secretary of National Defense\nThe Secretary of Transportation\nand Communications\n'The Secretary of Foreign Affairs\nFour (4) representatives from the Private\nSector to be appointed by the President\nThe President may designate a Co-Vice-Chairman from among the\nmembers representing the private sector.\""}},{"id":"PH-H21059-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Repealing Clause. All issuances or portions thereof which are\ninconsistent with this Executive Order are hereby revoked, amended or modified\naccordingly."}},{"id":"PH-H21059-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 14t _ day of May, in the year of Our Lord,\nTwo Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPORA Hologram * 48898"}}],"pack":"ph-p159"};
  FT["PH-H21060"] = {"id":"PH-H21060","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Presidential Decree No. 1464, as Amended, Otherwise Known as the Tariff and Customs Code of 1982, in Order to Implement the Margins of Preference in Accordance With the Asean Agreement on Preferential Trading Arrangements With Respect to Certain Articles Negotiated During the Thirteenth Meeting of the Asean Committee on Trade and Tourism","orig":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Presidential Decree No. 1464, as Amended, Otherwise Known as the Tariff and Customs Code of 1982, in Order to Implement the Margins of Preference in Accordance With the Asean Agreement on Preferential Trading Arrangements With Respect to Certain Articles Negotiated During the Thirteenth Meeting of the Asean Committee on Trade and Tourism"},"level":"law","status":"active","docNumber":"Executive Order No. 800","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00800_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00800_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21060-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The articles specifically listed in Annex \"A\" hereof as classified under Section 104 of Presidential\nDecree No. 1464, as amended, shall be accorded the margins of tariff preference as specified in column 7 of\nsaid Annex \"A\". In effect, such articles shall be subject to the Preferential Tariff for ASEAN in accordance\nwith the schedule indicated opposite each article as specified in columns 8-11 of said Annex \"A\"."}},{"id":"PH-H21060-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"In the event that any subsequent changes are made in the basic Philippine rate of duty on any of the\nabovementioned articles, such articles shall automatically be accorded the corresponding margins of\npreference indicated in column 7 of Annex \"A\" hereof."}},{"id":"PH-H21060-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"After the effective date of this order, all the above-described articles entered or withdrawn from\nwarehouse in the Philippines for consumption shall be subject to qualification under the Rules of Origin as\nprescribed in the Agreement on ASEAN Preferential Trading Arrangements ratified on August 1, 1977."}},{"id":"PH-H21060-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"This Order shall take effect on 16 April 1982.\nDone in the City of Manila, this 19th day of May, in the Year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21061"] = {"id":"PH-H21061","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE EXECUTIVE ORDER NO. _800 AN ORDER TRANSFERRING THE ADMINISTRATIVE SUPERVISION OF THE SECURITIES AND EXCHANGE COMMISSION FROM THE DEPARTMENT OF FINANCE TO THE DEPARTMENT OF TRADE AND INDUSTRY","orig":"MALACAÑAN PALACE EXECUTIVE ORDER NO. _800 AN ORDER TRANSFERRING THE ADMINISTRATIVE SUPERVISION OF THE SECURITIES AND EXCHANGE COMMISSION FROM THE DEPARTMENT OF FINANCE TO THE DEPARTMENT OF TRADE AND INDUSTRY"},"level":"law","status":"active","docNumber":"Executive Order No. 800","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00800_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00800_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21061-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":". The Securities and Exchange Commission Is hereby placed under the\nadministrative supervision of the Department of Trade and Industry."}},{"id":"PH-H21061-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDone In the City of Manila, this M day of MAY\nThousand and Nine.\nin the year of Our Lord, Two\nay the Fresident:\nEDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21062"] = {"id":"PH-H21062","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Upgrading the Physician Classes of Positions in the National Government","orig":"Upgrading the Physician Classes of Positions in the National Government"},"level":"law","status":"active","docNumber":"Executive Order No. 801","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-21","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00801_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00801_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21062-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 801 May 21, 1982\nUPGRADING THE PHYSICIAN CLASSES OF POSITIONS IN THE NATIONAL GOVERNMENT\nWHEREAS, there is a critical demand for medical manpower to spearhead the national government's\ncommitment to the primary health care approach to countryside development;\nWHEREAS, the unabated exodus of professionals in search of greener pasture has drained our country of the\nservice of doctors which has caused a serious problem of our government in the protection of the health of the\nWHEREAS, among the reasons for vacancies of physician positions is the low salary given to doctors in the\ngovernment.\nNOW, THEREFORE, I FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby order and direct the following measures to upgrade the compensation of\nphysician, classes of positions in the national government:\n1. The minimum salary of the lowest level physician position in the service of the national government shall\nbe increased from P1,152 to P1,894 per month;\n2. The physician classes of positions covered by the national compensation and classification plans shall be\nupgraded as follows:\nGroups/Classes\nSalary Range\nSalary Range\nMedical Officers Group\nExamining Physician\n62\n74\nJunior Physician\n62\n74\nASAC Medical Officer\n63\n75\nClinic Physician\n65\n77\nCompensation Rating Medical Officer\n65\n77\nMedical Training Officer I\n65\n77\nEpidemiologist\n66\n78\nMedico-Legal Officer\n66\n78\nMobile Radiologist\n66\n78\nPsychiatrist\n66\n78\nQuarantine Medical Officer\n66\n78\nResident Physician\n66\n78\nRural Health Physician\n66\n78\nSenior Clinic Physician\n66\n78\nSchools Division Medical Officer\n66\n78\nAviation Medical officer\n67\n79\nClinic Supervisor I\n67\n79\nMedical Services Supervisor I\n67\n79\nSenior Compensation Rating Medical Officer\n67\n79\nSenior Epidemiologist\n67\n79\nSenior Medico-Legal Officer\n67\n79\nSenior Quarantine Medical Officer\n67\n79\nSenior Resident Physician\n67\n79\nNBI Medical Officer\n67\n79\nHealth Planning Officer\n67\n79\nHealth Project Evaluation Officer\n67\n79\nSenior Health Planning Officer\n69\n80\nSenior Health Project Evaluation Officer\n69\n80\nMedical Services Supervisor II\n70\n81\nMedical Specialist I\n70\n81\nSupervising Medico-Legal Officer\n70\n81\nSupervising Resident Physician\n70\n81\nPharmacologist\n70\n81\nNBI Medical Center Chief\n70\n81\nChief Quarantine Medical Officer\n70\n81\nOverseas Employment Medical Officer\n70\n81\nAssistant Chief Compensation Rating Medical Officer\n70\n81\nMedical Standards Adviser\n70\n81\nNBI Medico-Legal Officer\n70\n81\nAssistant City Health Officer I\n68\n82\nAssistant Provincial Health Officer I\n68\n82\nSupervising Health Planning Officer\n71\n82\nSupervising Health Project Evaluating Officer\n71\n82\nNBI Psychiatrist\n71\n82\nNBI Senior Medico-Legal Officer\n71\n82\nNBI Medical Specialist I\n71\n82\nCivil Defense Medical Adviser\n72\n82\nChief Compensation Rating Medical Officer\n72\n82\nHospital Department Head\n72\n82\nMedical Specialist II\n72\n82\nUniversity Medical Supervisor\n72\n82\nAssistant Provincial Health Officer II\n69\n83\nChief of Medical Division I\n63\n83\nMedical Specialist III\n73\n83\nAssistant Chief of Medical Professional Staff\n73\n83\nNBI Supervising Medico-Legal Officer\n73\n83\nNBI Medical Specialist II\n73\n83\nAssistant Provincial Health Officer III\n70\n84\nChief Medico-Legal Officer\n74\n84\nChief of Clinics\n74\n84\nChief of Medical Division II\n74\n84\nMedical Adviser\n74\n84\nCivil Air Surgeon\n74\n84\nChief of Medical Professional Staff\n74\n84\nNBI Rehabilitation Center Assistant Administrator\n74\n84\nChief of Medical Division III\n75\n85\nChief Health Project Evaluation Officer\n75\n85\nChief Health Statistician\n75\n85\nChief Health Planning Officer\n75\n85\nChief of Hospital I\n70\n85\nChief of Sanitarium I\n70\n85\nCity Health Officer I\n72\n85\nProvincial Health Officer I\n72\n85\nChief Treatment and Rehabilitation Officer\n75\n85\nDermatology Assistant Project Director\n75\n85\nNBI Assistant Chief Medico-Legal Officer\n75\n85\nChief of Sanitarium II\n72\nChief of Hospital II\n72\nProvincial Health Officer II\n73\nCity Health Officer II\n73\nNBI Chief Medico-Legal Officer\n77\nChief of Sanitarium III\n73\nChief of Hospital III\n74\nProvincial Health Officer III\n74\nCity Health Officer III\n74\nPublic Health Specialist\n78\nDirector, RHO\n78\nDermatology Project Director\n78\nNBI Rehabilitation Center Administrator\n78\nChief of Sanitarium IV\n74\nChief of Hospital IV\n75\nAssistant Chief, National Mental Hospital\n75\nAssistant Chief, National Orthopedic Hospital\n75\nAssistant Director of Veterans Memorial Hospital\n76\nChief, Dr. J. Reyes Memorial\n77\nChief, San Lazaro Hospital\n77\nChief, Dr. Jose Fabella Memorial Hospital\n77\nChief, National Orthopedic Hospital\n77\nMedical Center Chief\n77\nChief, National Mental Hospital\n78\nDirector of Veterans Memorial Hospital\n81\nDirector, National Cancer Control Center\n81\nNutrition Group\nMedical Nutritionist I\n63\n75\nMedical Nutritionist II\n67\n79\nSchistosomiasis Control Group\nMedical Parasitologist I\n65\n77\nMedical Parasitologist II\n67\n79\nMalaria Control Group\nMalariologist\n66\n78\nChief Malariologist\n71\n82\nMedicare Group\nMedicare Officer I\n66\n78\nMedicare officer II\n67\n79\nSenior Medicare Officer\n68\n80\nSupervising Medical Officer\n70\n81\nMedicare Service Chief\n73\n83\nHealth and Sanitation Group\nIndustrial Hygienist\n65\n77\nSenior Industrial Hygienist\n67\n79\nClinical Laboratory Supervisor\n67\n79\nBacteriology Group\nBiologics Production Manager\n75\n85\nMedical Technology Group\nChief, Plasma Dehydrating Laboratory\n65\n77\n3. Adjustments shall not apply to positions/persons who are covered by the Career Executive Service or\nequivalent nor to incumbents of positions who are not licensed physicians.\n4. The Minister of the Budget shall make the necessary adjustments in cases where problems in\nsupervisor-subordinate salary relationship arise as a result of the upgrading directed by this order.\n5. Funds needed to implement this order shall be drawn from salary lapses or other personal services savings\nof the agency concerned. Any remaining deficiency shall be funded from the Salary Adjustment Fund\nprovided in Batas Pambansa Blg. 131.\n6. The salary upgrading directed by this Order shall be effective January 1, 1982.\n7. The rules and regulations needed to comply with this Order shall be formulated and issued by the Minister\nof the Budget.\nDone in the City of Manila, this 21st day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21063"] = {"id":"PH-H21063","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ENCOURAGING LOCAL GOVERNMENT UNITS (LGUS) TO ADOPT THE TECHNO GABAY IN THEIR AGRICULTURAL EXTENSION PROGRAMS AND THE CONCERNED GOVERNMENT AGENCIES TO PROVIDE THE REQUIRED ASSISTANCE FOR THE PURPOSE","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ENCOURAGING LOCAL GOVERNMENT UNITS (LGUS) TO ADOPT THE TECHNO GABAY IN THEIR AGRICULTURAL EXTENSION PROGRAMS AND THE CONCERNED GOVERNMENT AGENCIES TO PROVIDE THE REQUIRED ASSISTANCE FOR THE PURPOSE"},"level":"law","status":"active","docNumber":"Executive Order No. 801","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00801_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00801_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21063-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"hereof, to provide the required assistance for the purpose.\nSECTION 1. Scope and Coverage - The Executive Order shall cover all\nlocal government units where there are dominant agricultural areas, inclusive of\nfishery and forestry and/or whose constituents derive livelihood from farminq\nactivities such as urban agriculture and agriculture-based pro-poor\nnutrition/livelihood programs. The Technical Working Group, created under\nSection 5, hereof shall provide the criteria for determining the towns and\nprovinces, which shall be covered by this Executive Order.\nSECTION 2. Definition of Terms - For ourposes of this Executive\nOrder, the following terms or words and phrases shall mean or be understood as\nPGMA Molanean • 48882\na. Techno Gabay Program - a PCARRD-DOST initiative which serves as\na platform for developing, testing, and promoting technology transfer\nand dissemination modalities through the networking of R&D\ninstitutions in the agriculture, forestry, and natural resources (AFNR)\nsectors, namely the Regional R&D consortia and other members of the\nNational Agriculture and Resources Research and Development\nNetwork (NARD); LGUs, non-government organizations, core of\n• Farmer Scientists or Magsasaka Siyentista, and other extension service\nproviders, thereby enhancing technology utilization, adoption, and\ncommercialization.\n.49882\n\n3\nPOMA Holagram a 48883\nb. Farmers Information and Technology Services (FITS) or\nTechno Pinoy Center - serves as a one-stop service facility nearest\nto the majority of farmers, entrepreneurs and other clients in a given\narea. It provides fast access to information and technologies in forms\nappropriate to the clients' needs.\nc. Magsasaka Siyentista - is an outstanding farmer who is successful\nin his/her use of S&T-based and indigenous technologies. The MS is a\nvital link in technologies developed in the laboratories and ultimate\nadoption in farmers' fields.\nd. National Agriculture\nResources Research and\nDevelopment Network (NARD) - an aggrupation of government\nand non-government institutions working on agriculture and natural\nresources research and development (R&D).\ne. Regional Research and Development Consortia - refers to the\nPCARRD's regional consortia for R&D tasked to facilitate coordination,\nplanning, monitoring and evaluation of R&D activities and technology\npromotion and dissemination at the regional level. Each regional\nconsortium has member agencies composed of state colleges and\nuniversities, government agencies, local government units and non-\ngovernment institutions among others.\nf. Information Education Communication (IC) Strategies -\ninvolves research-and need-based communication processes aimed to\nhasten adoption of technologies by FITS and MS clients.\ng. Information and Communications Technology (ICT) - a diverse\nset of technological tools and resources used to create, store,\ncommunicate, disseminate and manage information.\nh. e-Extension service - the electronic delivery of extension service\nthru a network of institutions that provide a more efficient alternative\nto a traditional extension system for agriculture, fisheries and natural\nresources sectors.\ni. e-Learning courses - interactive electronic learning modules\nespecially designed for agricultural extension workers, enterprising\nfarmers and fisherfolks and other stakeholders.\nSECTION 3. Institutional Arrangements - This Executive Order shall\nbe implemented observing the following operational scheme between and among\nthe concerned agencies:\n48883\n\n4\nrOMA Hologram * 48884\nPCARRD-DOST shall:\n1. Provide the overall direction within the framework of the existing\nTechno Gabay Program, in coordination with its regional consortia\npartner member agencies and the DA-ATI;\n2. Conduct necessary pre-project consuitations and planning activities;\n3. Provide or facilitate the conduct of training programs for the efficient\nand effective operation of the Techno Pinoy centers;\n4. Provide technology/information through Information Education and\nCommunication (IC) materials for the Techno Pinoy;\n5. Link scientific community, the researchers and the agricultural experts\nfrom the National Agriculture and Resources Research and\nDevelopment Network (NARDN); and\n6. Monitor and evaluate the implementation of the program at the\nnational level.\nDA-Agricultural Training Institute (ATI) shall:\n1. Link DA's Extension Program to the extension delivery modalities under\nthe Techno Gabay Program, extension program of SUCs, LGUs and\nother agencies;\n2.. Provide access to online data-bases of DA on e-Learning courses and\nother agricultural information; and\n3. Complement manpower and logistic support in the conduct of trainings\nand education of LGU personnel that will be involved in this joint\nundertaking.\nRegional Research and Development Consortia shall:\n1. Coordinate with LUs regarding the implementation of the Techno\nGabay Program in the municipality;\n2. Conduct/facilitate trainings in various areas like ICT, IC development,\nskills training and other related training for the efficient and effective\noperation of the center;\n3. Provide guidance in the implementation of the FITS; and\n4. Monitor the implementation of Techno Gabay Program at the regional\nLGUs are encouraged to:\n1. Appoint/ designate the manpower need by the center;\n2. Collaborate with the DA and other concerned agencies in planning\ntechnology delivery activities in line with the agriculture deveropment\nprogram of the municipality;\n3. Provide seed money for the establishment and maintenance of the\nFITS center;\n48884\n\n5\n4. Provide the site/office for FITS establishment in the area and purchase\nequipment and fixtures, supplies necessary to operate the center; and\n5. Make available its staff to manage the project.\nSECTION 4. Funding - All local government units covered by this\nExecutive Order are encouraged to allocate funds from their respective budgets\nto cover the program's physical, human, and financial requirements.\nSupplemental budgets may also be sourced by the concerned GU from\ncontributions of public and private institutions involved in the program.\nFund utilization and disbursement shall be subiect to the usual\ngovernment accounting and auditing rules and regulations.\nSECTION 5. Implementing Rules and Regulations - The PCARRD-\nDOST, with the active participation of selected CHED-SUCs, DA, DA-ATI and\nLGUs, shall cali for the creation of a Steering Committee and a Technical Working\nCommittee that shall formulate the Implementing Rules and Regulations (IRR)\nfor the effective implementation of this Executive Order."}},{"id":"PH-H21063-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Separability Clause - If any section or provision of this\nExecutive Order shall be declared unconstitutional or invalid, the other sections\nor provision not affected thereby shall remain in full force and effect."}},{"id":"PH-H21063-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Repealing Clause - All Executive Orders, Rules and\nRegulations or parts thereof contrary to or inconsistent with this Executive Order\nare hereby repealed or modified accordingly. ."}},{"id":"PH-H21063-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Effectivity Clause - The EO shall take effect immediately.\nDONE in the city of Manila, this It day of MAY\nof our Lord, Two Thousand and Nine.\nMain to heap\n48685\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\n12"}}],"pack":"ph-p159"};
  FT["PH-H21064"] = {"id":"PH-H21064","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Amending Regulation No. 33 (A) of Letter of Implementation No.","orig":"Amending Regulation No. 33 (A) of Letter of Implementation No."},"level":"law","status":"active","docNumber":"Executive Order No. 802","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00802_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00802_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21064-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Regulation No. 33(a) of Letter of Implementation No. 23, as amended, is hereby further amended to\nread as follows:\n\"Regulation No. 33 Disqualifications. Members under any of the following circumstances are disqualified to\nbe voted upon to the position of director or committee member or continue as such in any Kilusang Bayan:\n(a) Holding any elective position in the government except barangay captains and councilmen."}},{"id":"PH-H21064-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"This order shall take effect immediately.\nDone in the City of Manila this 21st day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21065"] = {"id":"PH-H21065","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG STRENGTHENING AND RECOGNIZING THE PHILIPPINE ACCREDITATION OFFICE ATTACHED TO THE DEPARTMENT OF TRADE AND INDUSTRY AS THE NATIONAL ACCREDITATION BODY","orig":"MALACANANG STRENGTHENING AND RECOGNIZING THE PHILIPPINE ACCREDITATION OFFICE ATTACHED TO THE DEPARTMENT OF TRADE AND INDUSTRY AS THE NATIONAL ACCREDITATION BODY"},"level":"law","status":"active","docNumber":"Executive Order No. 802","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00802_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00802_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21065-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Pursuant to Section 13 of A 9236, the Philippine Accreditation Office\n(PAD), which shall be attached to the DTf, is hereby strengthened and recognized as the\nnational accreditation body. It shall be the central body to accredit inspection, testing and\ncertifying bodies, and other bodies offering conformity assessment services needed by the"}},{"id":"PH-H21065-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The PAO Council, to be chaired by the Secretary of the Department of\nTrade and Industry, is hereby created to give policy advice and provide guidance to PAO. The\nCouncil shall have ten (10) members, seven (7) from the government sector and three (3) from\nthe private sector.\nThe government sector shall be represented by the heads of the following departments\nor agencies or their authorized representatives, who must be at least an Undersecretary:\n1. Department of Science and Technology\n2. Department of Health\n3. Department of Agriculture\n4. Department of Environment and Natural Resources\n5. Department of Public Works and Highways\n6. Department of Energy\n7. Department of National Defense\n\nThe members from the private sector shall be appointed by the President from any of\nfollowing: Trade or Industry Association, Quality and Safety Foundation, Philippine Exporter's\nConfederation, Professional Association, or the Academe.\nThe Council is authorized to create the necessary Advisory Committees where other\nstakeholders are given opportunity to provide inputs in the formulation of accreditation policies."}},{"id":"PH-H21065-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"The DTI shall act as the PAO Council Secretariat. It shall ensure the\nimmediate coordination among members of the Council and the implementation of a centralized\nfacilitation, processing and release of accreditations."}},{"id":"PH-H21065-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Funding requirement that will enable PAO to pursue and implement its\nmandate shall be included in the annual. appropriations of the Department of Trade and\nIndustry. Government entities that seek accreditation from PAO for purposes of international\nrecognition shall provide funds for said purpose."}},{"id":"PH-H21065-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Laboratories that have already been accredited by other government\nagencies shall be given one year from effective date of this Order within which to seek\naccreditation against applicable international standards from PAO."}},{"id":"PH-H21065-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"All executive orders, rules and regulations and other issuances or parts\nthereof which are inconsistent with this Order are hereby revoked, amended, or modified\naccordingly."}},{"id":"PH-H21065-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"This Order shall take effect fifteen (15) days after its publication in a\nnational newspaper of general circulation.\nDONE in the City of Manila, this igthday of May in the year of Our Lord, Two Thousand\nOlearn A. Away\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram r 48902"}}],"pack":"ph-p159"};
  FT["PH-H21066"] = {"id":"PH-H21066","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"Establishing an Integrated Area Management System for Agricultural Services","orig":"Establishing an Integrated Area Management System for Agricultural Services"},"level":"law","status":"active","docNumber":"Executive Order No. 803","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-21","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00803_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00803_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21066-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"There is hereby established an integrated area management system for agricultural services which shall\nunify the operations of various government agencies involved in the delivery of agricultural services and\ninputs for any given area of operations. The desirability of its establishment is predicated on the rationale that\nthe effective coordination of government efforts at providing essential farm services in the rural areas can best\nbe attained if this were undertaken on a specific area basis.\nThe integrated area management system for agricultural services shall be managed through the administrative\nframework hereinbelow established and provided for."}},{"id":"PH-H21066-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"At the national level, the Ministry of Agriculture, as the agency primarily responsible for agricultural\ndevelopment, shall with the assistance of the National Food and Agriculture Council, formulate policies, plan,\nprograms and guidelines, including the integrated implementation of the delivery of agricultural services and\ninputs. It shall be responsible for the overseeing, general coordination and monitoring of operations and\nactivities relative thereto."}},{"id":"PH-H21066-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"At the regional level, a regional agricultural land classification committee is hereby created which shall\nbe responsible for the identification of specific areas for agricultural purposes in the provinces within the\nregion. The committee shall operate as a sub-committee of the Regional Development Council, and shall be\ncomposed of the Regional Director of the National Economic and Development Authority as Chairman, and\n\nthe Regional Directors of the Ministry of Agriculture, the Ministry of Human Settlements, the Ministry of\nLocal Government and the Ministry of Natural Resources as members.\nIn addition to the national level, the coordination of agricultural research programs and the conduct of\nagricultural training programs may be undertaken as well as at the regional level."}},{"id":"PH-H21066-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The province shall be the focal point for effecting area integration in the delivery of agricultural\nservices and inputs. The organizational framework at the provincial level shall be as follows:\n(a) The provincial governors shall have the basic responsibility and the corresponding authority for the general\ncoordination and supervision of the operations of the various agencies involved in the delivery of agricultural\nservices and inputs within the province.\nFor this purpose, the national agencies involved shall cooperate with and instruct their provincial offices or\nfield personnel to submit to the supervision of the governor as needed in order to realize an effective\nintegrated area management system at the provincial level.\n(b) There shall be established a Provincial Agricultural Council, which shall operate as a committee of the\nProvincial Development Council, to be headed by the governor. The Council shall serve as the mechanism for\nachieving coordination and harmonization of operations of agencies providing farm services and inputs in the\nprovince. It shall be responsible for providing advice to and developing operating policies for the guidance of\nthe governor.\nMore, specifically, the Council shall, among others (1) prepare and operationalize an integrated agricultural\ndevelopment program for the province on the basis of approved related national policies and programs;\nindicating among others, the preferred commodity production patterns in the agricultural lands in the\nprovince; (2) determine the extension services and inputs needed for the effective implementation of the\nprogram and, where necessary, recommend measures to appropriate ministries or agencies to ensure adequate\nand timely provision of such services and inputs; (3) adopt a deployment scheme for the extension workers\nassigned to the province on the basis of acceptable standards; and (4) monitor and evaluate on a continuing\nbasis the implementation of the program.\n(c) The Provincial Agricultural Council shall be composed of the senior representatives of agencies\nresponsible for the delivery of particular agricultural services and inputs, as follows:\n(1) The Ministry of Agriculture and the Ministry of Natural Resources through the Bureau of Fisheries and\nAquatic Resources, as the agencies responsible for agricultural technical services, including crop and livestock\nproduction and protection, cooperatives, fisheries development, and assistance to farmers/producers in the\navailment of credit;\n(2) The National Irrigation Administration Farms Systems Development Corporation, and Ministry of Public\nWorks and Highways as the agencies responsible for irrigation services;\n(3) The Philippine National Bank, Development Bank of the Philippines, Land Bank of the Philippines,\nAgricultural Credit Administration, and a representative of a provincial rural banks association, if there is any\nin the province, as the agencies responsible for providing agricultural credit;\n(4) The Ministry of Local Government together with the Ministry of Public Works and Highways, as the\nagencies responsible for farm to market roads;\n(5) The National Food Authority as the agency responsible for agricultural marketing; and\n(6) Whenever present within the province, specialized agencies such as the Ministry of Agrarian Reform,\nNational Council on Integrated Area Development, Philippine Virginia Tobacco Administration, Philippine\nTobacco Administration, Philippine Coconut Authority, Philippine Sugar Commission, and Fiber\nDevelopment Authority.\n(d) The provincial governor shall be assisted by a provincial agricultural executive officer who shall be\n\nresponsible to, and serve as the action officer of the Provincial Agricultural Council in the day-to-day\ncoordination of operations and activities pertaining to the delivery of agricultural services and inputs by the\nvarious agencies concerned. The provincial governor, with the concurrence of the Minister of Agriculture,\nshall designate the provincial agricultural executive officer, preferably the provincial agriculturist."}},{"id":"PH-H21066-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"At the city, municipal and barangay levels, there shall be city/municipal agricultural action officers to\nbe designated by the provincial governor from, as a general rule, among the appropriate senior national\ngovernment officials in the city/municipality, who shall be under overall supervision and control of the\nprovincial agricultural executive officer; Provided, That the Governor may, with the concurrence of the\nMinister of Agriculture, choose the city/municipal mayor as the agricultural action officer. They shall be\nresponsible for the direct coordination of agricultural extension workers of all agencies assigned to the various\nbarangays comprising the city/municipality.\nThey shall be responsible, among others, for (1) the direct coordination and supervision of the implementation\nof the pertinent portion of the provincial agricultural development program applicable to the city/municipality;\n(2) the assignment of extension workers to the barangays comprising the city/municipality in accordance with\nthe deployment plan adopted by the Provincial Agricultural Council; (3) the identification of operational\nproblems, including measures that may be necessary for their solution, and for this purpose, refer as needed\nmatters for appropriate action at the provincial level; and (4) the performance of such other related functions\nthat may be assigned to them."}},{"id":"PH-H21066-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Minister of Agriculture is hereby authorized to issue the necessary orders and regulations to\nimplement the provisions of this Executive Order."}},{"id":"PH-H21066-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21066-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof: Provided, That, such remaining portions can still stand\nand be given effect in their entirety to accomplish the objectives of this Executive order."}},{"id":"PH-H21066-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 21st day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21067"] = {"id":"PH-H21067","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING AND DIRECTING THE METRO MANILA INTER-AGENCY COMMITTEE ON INFORMAL SETTLERS TO PLAN, COORDINATE AND IMPLEMENT, IN COORDINATION WITH CONCERNED GOVERNMENT AGENCIES, A COMPREHENSIVE SHELTER PROGRAM FOR INFORMAL SETTLERS AFFECTED BY GOVERNMENT PRIORITY INFRASTRUCTURE PROJECTS AND THOSE LIVING IN DANGER AREAS WITHIN METRO MANILA","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING AND DIRECTING THE METRO MANILA INTER-AGENCY COMMITTEE ON INFORMAL SETTLERS TO PLAN, COORDINATE AND IMPLEMENT, IN COORDINATION WITH CONCERNED GOVERNMENT AGENCIES, A COMPREHENSIVE SHELTER PROGRAM FOR INFORMAL SETTLERS AFFECTED BY GOVERNMENT PRIORITY INFRASTRUCTURE PROJECTS AND THOSE LIVING IN DANGER AREAS WITHIN METRO MANILA"},"level":"law","status":"active","docNumber":"Executive Order No. 803","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00803_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00803_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21067-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The Metro Manila Inter Agency Committee on Informal\nSettiers. The Metro Manila Inter-Agency Committee (MMIAC) on Informal Settlers is\nhereby created, composed of the Metropolitan Mania Development Authority (MMDA) as\nchair, and the National Housing Authority (NHA) as vice chair, with the foliowing members\nthe Housing and Urban Deveiopment Coordinating Council (HUDOC; the Presidential\nCommission for the Urban Poor (PCUP); the National Anti-Foverty Commission (NAPC); the\nDepartment of Public Works and Highways (DPWHY the Department of the Interior and\nLocal Government (DILG) the Office of the President - Extemal Affairs (OPEA), the\nDepartment of Budget and Management (DBM); and a representative from the urban. poor\nas identified by the MIAC\nThe MMLAC wall invite te Commission on Human Rights (CHR) and other soco-\ncivic organizations and associations to become mebers of the Committee,\nThe concened local government unit (LGU) shall be invited and entitled to a vote\nwhenever the matter is within its jurisdiction,"}},{"id":"PH-H21067-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Assistance from Government Agencies. All goverment agencies\nare directed to actively cooperate and support the MMIAC. in tas regard, MMIAC may call\nupon any agency of the goverment for assistance and coupetation, including, but not\nlimited to, seeking the necessary technical services and support to the implementation of a\nComprehensive Shelter Program (SP), such as the provision of basic community facilities;\nincluding logistics and the conduct of continuing training and development with emphasis\non livelihood anal educational programs in collaboration with the private sector, religious\norganizations and partiopating NGOs,"}},{"id":"PH-H21067-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Lead Agencies. The MMDA and the NHA are the lead agencies in\nthe implementation of a CSP for informal settlers within Metro Manila, such as those\naffected by government Infrastructure projects, and those thing in, near or along danger\nareas such as riverbanks, esteros, roadways, sidewaiks, agueducts, bridges, railroad tracks,\ngarbage dumps, shorelines and waterways,"}},{"id":"PH-H21067-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Functions of the MMIAC. The MMIAC sall have the following\nmajor functions\na. Develop a CSP for qualified informal settlers affected by goveranent priority\ninfrastructure projects and those living in danger areas.\nb. Provide molicy directons and guidelines for the smooth and effective\nimplementation of the CSP.\nc. Seek funds and logistical support and resources from participating agencies and\nother concerned entities and the private sector for the effective and efficient\nimplementation of the CSP\n49005\n\nd. Enter into a memorandum of agreement or other local institutional arrangement\nwith and among concerned national and local government agencies, non-\ngovernment organizations and private entities for the speedy implementation of\ne. Exercise oversight functions on the implementation of the specific components of\nf. Peronn such other functions as may be assigned by the President."}},{"id":"PH-H21067-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Implementing Rules and Regulations. The MMIAC shall\npromulgate its Implementing Rules and Regulations to implement the SP as well as\nprovisions of this Executive Order."}},{"id":"PH-H21067-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Funding. The MMIAC, through MMDA, is hereby directed to set up a\ntrust fund in accordance with law, wherein funds sourced from the Office of the President,\nNational Government Agencies, LGUs (counterpart funds), Beneficiary Agencies and other\nparticipating organizations (NGOs and private sector) can be drawn from, subject to\naccounting and auditing rules and regulations, to expedite the implementation of the SP\nas well as the other housing strategies and policies developed by the MMIAC."}},{"id":"PH-H21067-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Repeal. All executive orders, rules and regulations and other\nissuances or parts thereof, which are inconsistent with this Executive Order, are hereby\nrevoked, amended, or modified accordingly."}},{"id":"PH-H21067-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Separability. Any portion or provision of this Executive Order that\nmaybe declared unconstitutional shall not have the effect of nullifying its other portions or\nprovisions, as long as such remaining portions can still be given effect."}},{"id":"PH-H21067-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Effectivity.\nThis Executive Order shall take effect immediatoly\nfollowing its publication in a national newspaper of general circulation.\nDONE in the City of Manila, this 2157 day of MAY\nLord; Two Thousand and Nine.\nin the year of Our\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMP Helogram • 49006\n3"}}],"pack":"ph-p159"};
  FT["PH-H21068"] = {"id":"PH-H21068","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":11,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for Assistants to the Prime Minister to Perform Inspectorate and Other Related Functions","orig":"Providing for Assistants to the Prime Minister to Perform Inspectorate and Other Related Functions"},"level":"law","status":"active","docNumber":"Executive Order No. 804","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-26","completenessNote":"全文，共 11 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00804_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00804_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21068-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Assistants to the Prime Minister. There are hereby provided such number of Assistants to the Prime\nMinister as may be necessary, hereinafter referred to as the Assistants, who shall serve as the field support\nmechanism of the Prime Minister in the discharge of his responsibility for the day-to-day supervisions of all\nthe ministries, particularly with respect to checking on and following-up the effective and expeditious\nimplementation of major development programs and projects undertaken by the ministries in the field.\nThe Assistants shall be appointed by the Prime Minister and serve at his pleasure on a full time basis. They\nshall be directly responsible to and be under the supervision and control of the Prime Minister. The Prime\nMinister may designate one from among them who shall coordinate the activities of the other Assistants, or\nalternatively designate the Secretary General as the coordinator.\nThe Assistants shall have such technical and support staff to be determined by the Prime Minister which, at\nhis discretion, may either be separate or shall be provided by the common support staff of the office of the\nPrime Minister."}},{"id":"PH-H21068-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Powers and Functions. The Assistants shall assist the Prime Minister in exercising his power of\nsupervision over all ministries, primarily to facilitate the implementation of priority development programs\nand projects undertaken in the field. They shall also serve as a feedback mechanism between the field\n\nagencies, project beneficiaries, and the Prime Minister.\nThe role of the Assistants is primarily to expedite the implementation of development projects and programs,\nby identifying problems in project implementation in the field and assisting in resolving such problems with\nthe concerned agencies. Their supervisory power over field agencies of the government shall be performed\nthrough inspection of priority development programs and projects. They shall serve as the personal\nrepresentatives of the Prime Minister in the regions.\nThe Assistants shall perform the following powers and functions;\n1. Assist and advise the Prime Minister in the exercise of his power of supervisions over the ministries,\nparticularly as this relates to the implementation of their development programs and projects;\n2. Report to and advise the Prime Minister on the implementation of development programs and projects,\nparticularly with respect to the effectiveness and currentness of their implementation, and bring to the\nattention of the Prime Minister anything that requires his immediate action;\n3. Conduct field inspection of the status of selected development programs and projects, identify bottlenecks\nand other problems in their implementation, and institute the necessary corrective actions to be taken;\n4. Whenever necessary and when so authorized by the Prime Minister, give direct instructions to field officials\nfor expediting action on the implementation of projects, and advise the Prime Minister and the ministries\nconcerned accordingly;\n5. Assist in developing measures for achieving the economical, efficient and effective implementation of\ndevelopment programs and projects, and where appropriate, directly negotiate remedial action with agencies\n6. Assist in promoting collaboration among field agencies of the government to facilitate project execution;\n7. Receive and act on complaints and suggestions on the implementation of development programs and\nprojects, particularly from local governments;\n8. Perform such other related power and functions as may be delegated to it by the Prime Minister."}},{"id":"PH-H21068-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Appeal. Instructions or directives of the Assistants shall be appealable to the Prime Minister."}},{"id":"PH-H21068-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Liaison Officers in Ministries and Other Government Agencies. The heads of ministries, Office of\nBudget and Management, and other government agencies to be designated by the Prime Minister shall\ndesignate their respective liaison officers of deputy minister or equivalent rank, to coordinate with the\nAssistants, to facilitate the implementation of decisions made by them and/or the Prime Minister.\nThe Constitutional Commissions, particularly the Commission on Audit and the Civil Service Commission,\nmay, upon the request of the Prime Minister, designate their respective liaison officers to coordinate with and\nextend such assistance as may be necessary to the Assistants."}},{"id":"PH-H21068-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Relationship with Agencies Performing Monitoring Functions. The Office of the Prime Minister shall,\ninstead of building up its own monitoring capability, rely primarily to existing monitoring systems.\nGovernment agencies performing monitoring functions, such as the Presidential Management Staff, the\nNational Economic and Development Authority, the Office of Budget and Management and other government\nagencies as may be determined by the Prime Minister shall furnish the Prime Minister with copies of\nnecessary monitoring reports on a regular basis."}},{"id":"PH-H21068-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Authority of the Prime Minister. The Prime Minister shall issue such orders, rules, and regulations as\nmay be necessary to implement the provisions of this Executive Order."}},{"id":"PH-H21068-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Funding. Such amount as may be necessary to carry out the provisions of this Executive Order shall be\nmade available to the office of the Prime Minister from existing appropriations. Thereafter, the appropriation\nfor the system of Assistants in the Office of the Prime Minister shall be included in the general Appropriations"}},{"id":"PH-H21068-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Abolition of the Presidential Regional Officers for Development. The abolition of the system of\nPresidential Regional Officers for Development (PRODS) pursuant to Presidential Decree No. 955 shall be\neffected immediately."}},{"id":"PH-H21068-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Repealing Clause. All laws orders proclamations, rules and regulations, or parts thereof, which are\ninconsistent with any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21068-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Separability Clause. Any portion or provision of this Executive Order that may be declared\nunconstitutional shall not have the effect of nullifying the other provisions thereof; Provided, That, such\nremaining portions can still stand and be given effect in their entirety to accomplish the objectives of this\nExecutive Order."}},{"id":"PH-H21068-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"Effectivity Clause. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of May, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21069"] = {"id":"PH-H21069","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":13,"structureMode":"ARTICLE","title":{"zh":null,"en":"Abolishing the Ministry of Youth and Sports Development, Transferring Its Functions to a Ministry of Education, Culture and Sports, and for Other","orig":"Abolishing the Ministry of Youth and Sports Development, Transferring Its Functions to a Ministry of Education, Culture and Sports, and for Other"},"level":"law","status":"active","docNumber":"Executive Order No. 805","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-26","completenessNote":"全文，共 13 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00805_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00805_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21069-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The existing Ministry of Youth and Sports Development established pursuant to Presidential Decree\nNo. 604 as amended is abolished together with its services, bureaus and similar agencies, regional offices, and\nall other entities under its supervision and control. Except as may otherwise be provided for hereinafter, its\nfunctions, including records, equipment, property, and such applicable appropriations and personnel as may be\nnecessary are hereby transferred to the Ministry of Education and Culture, which is renamed the Ministry of\nEducation, Culture and Sports and hereinafter referred to as the Ministry. The Ministry shall be headed by a\nMinister of Education, Culture and Sports, hereinafter referred to as the Minister."}},{"id":"PH-H21069-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"In addition to its current responsibilities on education and culture, the Ministry shall have the\nfollowing additional functions concerning sports:\n(1) Plan and implement an integrated program by physical fitness and amateur sports development in the\ncountry, including both those in school and out-of-school;\n(2) Plan and conduct amateur open sports competitions at different administrative levels of the government\nand provide guidelines for their implementation;\n(3) Establish or develop, as may be necessary, additional sports facilities in strategic places throughout the\ncountry, as well as a modern sports complex adequate for major international sports competitions;\n(4) Establish and maintain the necessary linkages and coordination with the national sports associations\nthrough the Philippine Olympic Committee and agencies of the government as well as private institutions and\nassociations."}},{"id":"PH-H21069-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"A Bureau of Sports Development is created as an additional bureau under the supervision and control\nof the Ministry. The Bureau shall be responsible for the development and evaluation of programs for\npromoting and improving organized sports and physical fitness for all members of the community. It shall be\n\nresponsible for formulating guidelines and standards relative to physical fitness, the promotion of organized\nand individual sports activities, and the establishment and maintenance of sports centers and facilities except\nthe Rizal Memorial Sports Complex in Manila, in Paoay, Ilocos Norte and other training centers determined\nby the President which shall be under the management of Project: Gintong Alay. It shall also develop athletic,\nsports, and physical fitness programs at local, regional and national levels, including programs for periodic\ninterscholastic and other athletic meets, and provide guidelines for their implementation.\nThe various programs of the abolished Ministry aimed at the development of the youth shall be transferred as\nappropriate to the various bureaus and regional offices of the Ministry, or to the Pambansang Katipunan ng\nKabataang Barangay ng Pilipinas or to other ministries, as may be determined by the Minister in consultation\nwith the Office of Budget and Management and the Presidential Commission on Reorganization."}},{"id":"PH-H21069-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The National Youth and Sports Development Foundation of the Philippines shall be an additional\nentity attached to the Ministry for policy and program coordination. The Minister shall be ex-officio Chairman\nof the Board of Trustees of the National Youth and Sports Development Foundation of the Philippines and\nshall recommend to the President for appointment the other members representing the government and private\nThe Gintong Alay Foundation Project: Gintong Alay is attached to the Office of the President for policy and\nprogram coordination.\nGintong Alay shall continue as the national sports training program of the country which shall have the same\ntask of recruiting, selecting and training of Filipino athletes in preparation for international competitions, in\ncoordination with the Philippine Olympic Committee and the national sports associations. For purpose of this\nnational training program, the Ministry of Education, Culture and Sports and other government ministries and\nagencies shall extend full assistance to this program.\nAny student athlete, either college or high school, recruited for training by Project: Gintong Alay should be\nallowed by the Ministry of Education, Culture and Sports to cross-enroll from their original school to an\nequivalent school in the vicinity of the Gintong Alay training camp to enable the student concerned to have an\nuninterrupted schooling within the year and for the duration of their training.\nThe Gintong Alay Foundation and Project: Gintong Alay are attached to the Office of the President for policy\nand program coordination."}},{"id":"PH-H21069-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Minister of Education, Culture and Sports shall assume the position of Chairman or member, as\nappropriate, of all boards or other bodies previously held by the Minister of Youth and Sports Development in\nan ex-officio capacity."}},{"id":"PH-H21069-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"There shall be established in each region a subsidiary unit under the supervision and control of the\nRegional Director of the Ministry which shall be responsible for the implementation in the region of an\nintegrated sports development program for both in-school and out-of-school youth. The Regional Director of\nthe head of the subsidiary unit, as appropriate, may assume the position of chairman or member as suitable of\nall councils or similar bodies previously held by the regional director of the abolished Ministry of Youth and\nSports Development in an ex-officio capacity."}},{"id":"PH-H21069-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Ministry is hereby authorized to issue such orders, rules and regulations as may be necessary to\nimplement the provisions of this Executive Order; provided, that approval of the Office of Budget and\nManagement is obtained relative to the new staffing pattern including appropriate salary rates, the\norganizational structure at divisional and lower levels, and the realignment of existing appropriations. The\nMinister may appoint qualified personnel of the abolished Ministry to appropriate positions in the Ministry of\nEducation, Culture and Sports, and those not so appointed are deemed laid off."}},{"id":"PH-H21069-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"All Presidential appointees of the abolished Ministry of Youth and Sports Development and its\nrespective bureaus, offices and other entities under the supervision and control of or under the administrative\nsupervision of the abolished Ministry are laid off, unless otherwise reappointed by the President; provided,\n\nthat those who are Career Executive Service Officers shall either be reappointed or reassigned by the\nPresident upon the recommendation of the Minister to appropriate positions in the Ministry of Education,\nCulture and Sports, or assigned to the Career Executive Service Board in which shall endeavor to find\nappropriate placement for them in other ministries or agencies; provided, further, that those Career Executive\nService Officers who have been assigned to the Career Executive Service Board shall continue to receive their\nsalaries from any available and applicable funds; and provided, finally, that those who are not placed in\nappropriate positions within six months after their assignment to the Career Executive Service Board shall be\nsimilarly laid off."}},{"id":"PH-H21069-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"All those who are laid off under the provisions of this Executive Order shall be entitled to all benefits\nand gratuities provided for under existing laws."}},{"id":"PH-H21069-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Except as may otherwise be determined by the Minister, all present incumbents of positions in the\nabolished Ministry shall continue to exercise their usual functions, duties, and responsibilities, pending the\nissuance of the appropriate implementing orders."}},{"id":"PH-H21069-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21069-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"Any portion of provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof, provided that such remaining portions can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21069-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of May in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21070"] = {"id":"PH-H21070","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING TWO SEPARATE OFFICES, THE INTELLIGENCE GROUP AND THE ENFORCEMENT GROUP, FROM THE INTELLIGENCE AND ENFORCEMENT GROUP IN THE BUREAU OF CUSTOMS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING TWO SEPARATE OFFICES, THE INTELLIGENCE GROUP AND THE ENFORCEMENT GROUP, FROM THE INTELLIGENCE AND ENFORCEMENT GROUP IN THE BUREAU OF CUSTOMS"},"level":"law","status":"active","docNumber":"Executive Order No. 805","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00805_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00805_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21070-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Creation. Two separate offices from the Intelligence and\nEnforcement Group (IEG) of the Bureau of Customs (BOC) are hereby created\nand shall be known as the Intelligence Group and the Enforcement Group\n(hereinafter abbreviated IG and EG, respectively, for brevity)."}},{"id":"PH-H21070-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Composition. The IG and EG shall each be headed by a\ndeputy commissioner, the Deputy Commissioner for Intelligence and\nInvestigation (DC-II) and the Deputy Commissioner for Enforcement and\n49048-\nPOMA Hologram 4 49048\n\nSecurity (DC-ES), who shall be both appointed by the President of the\nPhilippines.\nThe main services under the IG and EG shall be the Customs Intelligence\nand Investigation Service (CIIS) and Enforcement and Security Service (ESS),\nrespectively. The technical and support staff shall primarily be drawn from\nexisting personnel of the IEG."}},{"id":"PH-H21070-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Implementing Authority. Consistent with the principles of\neconomy, efficiency, and effectiveness, the DC-II and DC-ES may recommend to\nthe Commissioner of Customs organizational enhancements for their respective\noffices, subject to the evaluation of the Department of Finance (DOF) and the\nDepartment of Budget and Management (DBM)."}},{"id":"PH-H21070-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Appropriations. Funding shall come from the available funds\nof the Bureau of Customs (BOC) and subsequent appropriations shall be\nincorporated into the budget proposals, subject to existing accounting and\nauditing laws and procedures,"}},{"id":"PH-H21070-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity. This Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, this25tiday of\nof Our Lord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram * 49049"}}],"pack":"ph-p159"};
  FT["PH-H21071"] = {"id":"PH-H21071","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Textbook Council and the Instructional Matterials Corporation","orig":"Creating the Textbook Council and the Instructional Matterials Corporation"},"level":"law","status":"active","docNumber":"Executive Order No. 806","issuingBody":"President of the Philippines","promulgatedDate":"1982-05-27","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00806_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00806_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21071-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 806 May 27, 1982\nSubject Matter : Creating the Textbook Council and the Instructional Materials Corporation, defining their\npowers and functions and for other purposes.\nDate of Effectivity : May 27, 1982"}}],"pack":"ph-p159"};
  FT["PH-H21072"] = {"id":"PH-H21072","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"ALALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AFFIRMING THE ROLES OF EARLY CHILDHOOD CARE AND DEVELOPMENT COUNCIL AND THE COUNCIL FOR THE WELFARE OF CHILDREN","orig":"ALALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AFFIRMING THE ROLES OF EARLY CHILDHOOD CARE AND DEVELOPMENT COUNCIL AND THE COUNCIL FOR THE WELFARE OF CHILDREN"},"level":"law","status":"active","docNumber":"Executive Order No. 806","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00806_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00806_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21072-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Council for the Welfare of Children. - The Council for the\nWelfare of Children shall continue to function and exercise the same powers pursuant\nto the provisions of PD 603 and E0 233 (s. 1986). It shall be composed of the same\nagencies and organizations as identified in EO 233 (s. 1986), with the Secretary of\nSocial Welfare and Development as the Chairperson. It shall be attached to the\nDepartment of Social Welfare and Development."}},{"id":"PH-H21072-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Repealing Clause. - All executive orders, rules and regulations\nand other parts thereof which are inconsistent with this Order are hereby revoked,\namended or modified accordingly."}},{"id":"PH-H21072-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Effectivity. - This Order shall take effect immediately.\nDONE in the City of Manila, this gl\nTwo Thousand and Nine.\nday of June _, in the year of our Lord,\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Holograin + 49111"}}],"pack":"ph-p159"};
  FT["PH-H21073"] = {"id":"PH-H21073","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"Establishing the Small Contractors Module Under the Kilusang Kabuhayan at Kaunlaran and for Other Purposes","orig":"Establishing the Small Contractors Module Under the Kilusang Kabuhayan at Kaunlaran and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 807","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-10","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00807_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00807_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21073-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Establishment of Small Contractors Module. A \"small contractors module\" is hereby established as an\nintegral part of the KKK to be implemented in accordance with the guidelines and procedures provided herein."}},{"id":"PH-H21073-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Types of Projects. KKK assistance under the small contractors module may be extended for public\nworks and highways projects with an estimated contract cost of not more than Seven Hundred Thousand\nPesos (P700,000.00) each, such as school buildings, barangay roads, small flood control and drainage works,\ncommunal irrigation, wells, health centers, and similar projects."}},{"id":"PH-H21073-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Prospective Beneficiaries. To be considered as a prospective beneficiary of the KKK, an applicant\nmust be duly accredited by the District or City Engineer's Office or other equivalent instrumentality under the\nMinistry of Public Works and Highways as having met the following prequalification requirements:\na. Legal requirements\ni. The applicant must be a Filipino citizen, of legal age, and good standing in the community, or\npartnership/cooperation of good standing whose capital stock is fully owned by Filipino citizens.\nii. The key officer of the applicant must be bona fide residents for the past three (3) years of the region where\nthe subject project applied for is located. The applicant may, therefore, apply for KKK assistance only for\nproposed public works and highways contracts in his region of residence.\n\niii. The applicant must submit a sworn statement that he shall, if awarded the contract for the subject, project,\nprocure unskilled workers from the municipality or city where the subject project is located, and semi-skilled\nworkers from the province where the subject contract is situated.\nb. Technical requirements\ni. Experience. The applicant or his key construction staff must have satisfactorily completed projects with\naggregate costs of at least ten per cent (10%) of the estimated contract cost of the subject project and which\ninvolve essentially the same or similar technology as that of the subject project. Applicants whose completed\nprojects for the past year have an aggregate value of more than One Million Pesos (P1,000,000.00) are\ndisqualified.\nii. Equipment. The applicant must own at least basic construction tools, e.g. masonry, carpentry, and ditching\niii. Organization. The applicant must have in his employ at least a construct foreman with a minimum\nexperience of the (1) year in the same or similar work as that of the subject project.\nc. Financial requirements. The applicant must have a positive net worth i.e., his total assets must exceed his\ntotal liabilities, based on his latest income tax return."}},{"id":"PH-H21073-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Types of KKK Assistance. KKK assistance to pre-qualified and accredited contractors who are\nawarded a contract will come in the form of a loan bearing an interest of twelve per cent (12%) per annum,\nrepayable in accordance with Sec. 6. hereof. The loan may cover:\na. The estimated working capital requirement by the contractor for the subject project, but not to exceed the\nestimated operating expenses for one and one-half (1 1/2) months or fifteen per cent (15%) of the estimated\ncontract cost of the project, whichever is lesser and/or\nb. The estimated cost of purchasing light construction equipment needed for the project, such as concrete\nmixers, not exceeding fifteen percent (15%) of the estimated contract cost.\nThe contractor may also request the KKK designated banks to post, on behalf of the contractor, either or both\nof the following bonds, with the premiums, banking charges and other expenses incidental thereto considered\nas additional loans under the same terms and conditions as mentioned above:\na. The required bid bond in favor of the government agency concerned in the form of cash, cashier's check,\nmanager's check, letter of credit, or a combination thereof, amounting to at least two and a half (2.5%) of the\nbid price to guarantee that, if awarded the contract, the contractor will enter into corresponding agreement\nwith the government agency concerned with fifteen (15) calendar days from the date of receipt of the notice of\naward of the contract; and/or\nb. If awarded the contract, the required performance bond in favor of the government agency concerned in the\nform of cash, manager's check, cashier's check, letter of credit, or a combination thereof, amounting to at\nleast five per cent (5.0%) of the contract price, to guarantee the contractor's faithful performance of the"}},{"id":"PH-H21073-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Financing Institutions. KKK financing will be extended to accredited contractors by KKK designated\nbanks or other financing institutions duly authorized by the KKK National Secretariat."}},{"id":"PH-H21073-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Procedure. The following procedures shall be followed by all concerned in the implementation of this\na. Prequalification\ni. For every specific project that is deemed eligible for KKK assistance under the small contractors module in\naccordance with the provisions of Section 2 hereof, the government agency concerned, i.e., the District or City\nEngineer's Office or other equivalent instrumentality under the Ministry of Public Works and Highways shall\ninvite interested contractors to submit to its application for prequalification and KKK assistance for the project\n\nand, if so prequalified, to submit bids for the project contract under regular public bidding or sealed canvass\nbidding, at the discretion of the Head of the office or agency concerned.\nii. The contractor-applicant shall accomplish both application forms for prequalification and KKK assistance\nand submit them to the agency concerned before the prescribed deadline.\niii. The agency concerned shall evaluate the prequalification statement of the contractor to determine its\nconformity with requirements mentioned in Section 3 hereof. In the event of approval of the contractor's\napplication for prequalification, the agency shall endorse the application for KKK assistance to the KKK\nRegional Action Officer (RAO) concerned.\nb. Processing of application for KKK assistance. The RAO shall evaluate the application of the contractor for\nKKK financing. Upon being ascertained of the project's viability, the RAO issues a statement to the effect that\nit shall endorse to the KKK-designated bank the loan applied for in accordance with the provisions of Section\n4 hereof if and when the contractor-applicant is awarded the contract.\nc. Submission of Bid. The contractor-applicant shall then submit to the agency concerned his bid, together\nwith the aforesaid statement from the RAO, on or before the prescribed deadline.\nd. Award and Perfection of Contract. If the contractor-applicant is awarded the contract, the RAO shall\nconfirm the loan under the prescribed terms and conditions. The contract is then perfected and approved by\nthe head of the implementing government agency or his authorized representative.\ne. Deposit of Project Funds. The implementing government agency concerned shall deposit with the\nKKK-designated bank the project funds in an account which shall earn interest equal to the rediscounting rate\nof the Central Bank of the Philippines. The interest earnings of such deposit shall accrue to the National\nGovernment Treasury.\nf. Loan for Working Capital\ni. Should the proposed loan be intended to cover the financing of the working capital in accordance with\nSection 4, item a hereof, the RAO shall communicate with the KKK-designated bank to extend the loan to the\ncontractor under the terms stipulated in Section 4 hereof, based on the budget of the contractor as certified by\nthe agency concerned. The contractor, in turn, shall assign his rights under the contract to the KKK designated\nbank for the latter to directly receive from the government agency concerned the loan amortization payments\nto be proportionally deducted from the construction progress payments due to the contractor.\nii. During the implementation of the project, the agency concerned shall promptly process each request for\nprogress payment submitted by the contractor. Within one week from the receipt of a certified request, the\nagency shall issue a check in favor of the KKK-designated bank to cover the loan amount multiplied by the\nratio of the corresponding progress payment to the total contract price, plus interest and other applicable\nbanking charges. At the same time, the agency shall issue a check in favor of the contractor for the balance of\nthe certified progress payment i.e., net of the amortization payment to the KKK-designated bank, appropriate\nretention money and contractor's tax. The above process is repeated until the loan is fully amortized and\nliquidated.\ng. Loan for Purchase of Equipment\ni. Should the proposed loan be intended to cover the purchase of construction equipment in accordance with\nSec. 4, item b hereof, the RAO shall endorse the contractor's loan application to the KKK-designated bank\nunder the terms stipulated in Section 4 hereof. The contractor shall, in turn, execute a chattel mortgage in\nfavor of the KKK-designated bank.\nii. The loan is the amortized out of the progress payments through the same process stated in Section 6, Item\nh. Default. In case the contractor, through his own fault or negligence, fails to fulfill his contractual\nobligations with the government agency concerned resulting in the termination or rescission of the contract,\n\nthe standard KKK guidelines governing the livelihood projects approved by the Regional Action Officers\nshall apply. In addition he shall be blacklisted by both the government agency and the financing institution\nconcerned and shall be banned from entering into future transactions with them, without prejudice to civil\nand/or other legal actions deemed proper by the KKK."}},{"id":"PH-H21073-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Implementing Details. The Minister of Public Works and Highways, in coordination with the KKK\nNational Secretariat shall promulgate the appropriate implementing details, including forms and circulars to\ncarry out the above guidelines."}},{"id":"PH-H21073-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Repealing and Modifying Clause. All laws, decrees, charters, executive orders, administrative orders,\nrules and regulations, including the provisions of the implementing rules and regulations of Presidential\nDecree No. 1594 (Contract Policies and Procedures), or parts thereof, in conflict with this Executive Order are\nhereby repealed or modified accordingly."}},{"id":"PH-H21073-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Separability Clause. Any portion of a provision of this Executive Order that may be declared\nunconstitutional shall not have the effect of nullifying the other portions thereof, provided that such remaining\nportions can still stand be given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21073-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 10th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21074"] = {"id":"PH-H21074","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES REPEALING LETTER OF INSTRUCTION (LOI) NO. 58, AS AMENDED, LIMITING THE HECTARAGE FOR BANANA EXPORT PLANTATION TO 26,250 HECTARES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES REPEALING LETTER OF INSTRUCTION (LOI) NO. 58, AS AMENDED, LIMITING THE HECTARAGE FOR BANANA EXPORT PLANTATION TO 26,250 HECTARES"},"level":"law","status":"active","docNumber":"Executive Order No. 807","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00807_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00807_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21074-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":". Letter of Instruction No. 58 (series of 1973), as amended, is\nhereby repealed."}},{"id":"PH-H21074-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The Banana Industry Export Committee is hereby dissolved.\nInstead, the Department of Agriculture (DA) shall oversee the export banana\nindustry, as with other crops, subject to existing land use policies and plans of\nthe national and local governments and with due consideration to global market\ndemand and conditions as well as social and environmental impacts of expanding\nbanana plantation areas, among others."}},{"id":"PH-H21074-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"All presidential issuances, administrative rules and\nregulations, or parts thereof inconsistent with this Executive Order are hereby\nrepealed or modified accordingly."}},{"id":"PH-H21074-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This Executive Order shall take effect immediately upon\npublication in a national newspaper of general circulation.\nDone in the City of Manila this at day of\nof Our Lord, Two Thousand and Nine.\nMari Mr. Aura\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Mologram & 49134"}}],"pack":"ph-p159"};
  FT["PH-H21075"] = {"id":"PH-H21075","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Letter of Instruction No. 1106 Governing the Admission to or Stay in the Philippines as Temporary Visitors of Chinese Nationals Who Are Holders of Taipei Passports","orig":"Amending Letter of Instruction No. 1106 Governing the Admission to or Stay in the Philippines as Temporary Visitors of Chinese Nationals Who Are Holders of Taipei Passports"},"level":"law","status":"active","docNumber":"Executive Order No. 808","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00808_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00808_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21075-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 808 June 11, 1982\nAMENDING LETTER OF INSTRUCTION NO. 1106 GOVERNING THE ADMISSION TO OR STAY IN\nTHE PHILIPPINES AS TEMPORARY VISITORS OF CHINESE NATIONALS WHO ARE HOLDERS OF\nTAIPEI PASSPORTS\nWHEREAS, it is declared policy of the Government to make the tourist industry a positive instrument towards\naccelerated national development through which more people from other lands may visit and appreciate the\nPhilippines:\nWHEREAS, it is necessary to provided full support to the government policies and programs designed to\nattract and induce people from abroad to visit the Philippines by removing unnecessary barriers to their travel\nthrough the integration and simplification of travel regulations; and\nWHEREAS, this goal may be achieved by the revision of the applicable provisions of law/rules/regulations\nfor the issuance of visas and the admission of aliens, in order to enable Chinese nationals to obtain visas with\nease and speed and to stay for a longer period in the country as well as to assure them of courteous and\nhospitable reception.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby order the amendment of LOI 1106 so that its penultimate paragraph shall read\n\"Now, therefore, LOI 911, as amended by LOI 1106 should be, as it is hereby, further amended so as to allow\nthe issuance of tourist visas on individual basis to Chinese nationals, who are holders of Taipei passports, for\nentry into the Philippines for a stay of not more than twenty-one (21) days, without the necessity of posting\nany case bond, as an exception to the Cabinet Policy of March 10, 1954. The maximum period of stay herein\nfixed may only be extended on very compelling reasons and under exceptional circumstances by the Minister\nFor the effective implementation of this Order, the Ministry of Foreign Affairs, the Commission on\nImmigration and Deportation and the National Intelligence Security Authority (NISA) are hereby directed to\nissue the necessary joint circular enjoining strict observance of the provisions hereof by all functionaries\nThis Order shall take effect immediately.\nDone in the City of Manila, this 11th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21076"] = {"id":"PH-H21076","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES LEGAL ACTION GROUP","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES LEGAL ACTION GROUP"},"level":"law","status":"active","docNumber":"Executive Order No. 808","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00808_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00808_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21076-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Executive Order No. 493, (s. 2006) creating the Inter-Agency Legal\nAction Group (IALAG) is hereby revoked."}},{"id":"PH-H21076-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Executive officials and employees can no longer make use of Executive\nOrder No. 493 (s. 2006) in the investigation, prosecution and monitoring of offenses\nrelating to national security."}},{"id":"PH-H21076-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 15th day of May , in the year of our Lord,\nTwo Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA HOlogram « 49100"}}],"pack":"ph-p159"};
  FT["PH-H21077"] = {"id":"PH-H21077","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Letter of Instruction No. 1093 Governing the Admission to or Stay in the Philippines as Temporary Visitors of Chinese Nationals Who Are Holders of People's Republic of China Passports","orig":"Amending Letter of Instruction No. 1093 Governing the Admission to or Stay in the Philippines as Temporary Visitors of Chinese Nationals Who Are Holders of People's Republic of China Passports"},"level":"law","status":"active","docNumber":"Executive Order No. 809","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00809_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00809_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21077-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 809 June 11, 1982\nAMENDING LETTER OF INSTRUCTION NO. 1093 GOVERNING THE ADMISSION TO OR STAY IN\nTHE PHILIPPINES AS TEMPORARY VISITORS OF CHINESE NATIONALS WHO ARE HOLDERS OF\nPEOPLE'S REPUBLIC OF CHINA PASSPORTS\nWHEREAS, it is the declared policy of the Government to make the tourist industry a positive instrument\ntowards accelerated national development through which more people from other lands may visit and\nappreciate the Philippines;\nWHEREAS, it is necessary to provide full support to the government policies and programs designed to\nattract and induce people from abroad to visit the Philippines by removing unnecessary barriers to their travel\nthrough the integration and simplification of travel regulations; and\nWHEREAS, this goal may be achieved by the revision of the applicable provisions of law/rules/regulations\nfor the issuance of visas and the admission of aliens, in order to enable Chinese nationals to obtain visas with\nease and speed and to stay for a longer period in the country as well as to assure them of courteous and\nhospitable reception.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby order the amendment of LOI 1093 so that paragraph 1A thereof shall read as\n\"Tourist visas on individual basis may be issued to Chinese nationals who are holders of valid People's\nRepublic of China (PROC) passports, their accompanying spouses and minor children whose names and\npictures are included in a collective passport for entry into the Philippines for a stay of not more than\ntwenty-one (21) days, without the necessity of posting any cash bond, as an exception to the Cabinet Policy of\nMarch 10, 1954. The maximum period of stay herein fixed may only be extended on very compelling reasons\nand under exceptional circumstances by the Minister of Justice.\"\nFor the effective implementation of this Order, the Ministry of Foreign Affairs, the Commission on\nImmigration and Deportation and the National Intelligence Security Authority (NISA) are hereby directed to\nissue the necessary joint circular enjoining strict observance of the provisions hereof by all functionaries\nThis Order shall take effect immediately.\nDone in the City of Manila, this 11th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21078"] = {"id":"PH-H21078","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES 'EXECUTIVE ORDER NO.","orig":"BY THE PRESIDENT OF THE PHILIPPINES 'EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 809","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00809_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00809_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21078-A1","no":1,"noLabel":{},"text":{"en":"under a supplier's credit,\npayment plan, or other financial schemes;\n~JIIIIIIIIIIIIIIIIIIIIIIIIIIIIIIII'I\n49175\n~\n-\"\n.\n.\nSectidn 299 of ' the Local Government Code allows LCJUs to\nissue bont:fs; notes, and other evidences\nof Indebtedness to finance self-\nliquidating, income producing development or livelihood projects;\n'\"\nS~~ion 300 of the Local Government Code allows LGUs to\nsecure loans from other LGUs;\n4 \"!.JHEREAS, Section .3.R:J;$ the Local Government Code allows LGUs to\nsoul-ce additional financing frb\"M' loans secured by the National Government from.\nforeign financial institutions or other international funding agencies pursuant to\nthe power of the President to directly or indirectly relend such loans to LGlJ$;\n\"\nWHEREAS, the loans and credits secured by LGUs under the aforestated-\nprovisions of the Local Government Code are to accrue directly to the LGUs\nWHEREAS, in light of the current global financial crisis, there is an urgent\nneed to reallocate the resources of the National Government for its own priority\nprojects and to thus, rationali~\nQ.nd revitalize the sources from which LGUs can\nfund their projects, pursuant to'their\npowers under the Local Government Code\nand in accordance with the LGU Financing Framework.\nNOW, THEREFORE,\nI, GLORIA MACAPAGAL-ARROYO,\nPresident of\nthe Philippines, by virtue of the powers vested in me by law, do hereby order:\n1. The Department\nof the Interior\nand Local Government\n(DILG) and the Department of Finance (DOF) are hereby directed to implement\nthe LGU Financing Framework and shall, for this purpose, ensure that First Tier'\nLGUs be allowed\nand assisted to\nGovernment Financial Institutions\n(GFIs) and the Municipal Development Fund\nbut also with\nmultilateral\ninstitutions\nmultilateral treaties or agreements to which the Philippines is a signatory (MFIs):\nProvided, that other agencies of the government,\nincluding the Department of\n(DOJ), the Department of Education (DepEd), and the Department\nPublic Works and Highways (DPWH), are likewise directed to provide and extend\nfull support to the DILG and DOF so as to allow the full and immediate\nimplementation\nof the LGU Financing Framework; Provided furth~r, that any such\nloan obtained by any such qualified First Tier LGU shall be on a stand-alone basis\nwithout any direct or indirect National Government guarantee; Provided further,\nthat the DOF shall formulate the necessary Implementing\nRules and Regulations\nto ensure prudent borrowing of these LGUs.\n~~~~\n~~'\n[~~~'-'~\"-~~\n.~\n~IIIIIIIIIIIIIIIIIIIIIIIIIIIIIIII\n~\n-'\n.\n.\"\ns.EC;rION 2. All o'ther rules, regulations, ~d\niSSuances, or parts thereof,\nwhich are\"~nsistent\nwith this Executive Order are hereby deemed repealed or\nmodified ac,,<;prdingly.\n\\\n-\nSECTION 3, Thls Executive Oraer shall take effect immediately.\nDone in the City of Manila, this\n, in the year of our\nLord~ 1w~ Thousand ~nd Nin~~;\n,)\n(1'1\n.£'\"\nBy the President:\n~~\nEDUARDO R. ERMITA\nExecutive Secretary\n~\n'.\n'\n~IIIIIIIIIIIIIIIIIIIIIIIIIIIIIIII\nHologram ff 49177"}}],"pack":"ph-p159"};
  FT["PH-H21079"] = {"id":"PH-H21079","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Granting Salary Increases to Teaching Positions of the Philippine Science High School (PSHS) as an Accelerated Implementation of the 1979 Salary Survey","orig":"Granting Salary Increases to Teaching Positions of the Philippine Science High School (PSHS) as an Accelerated Implementation of the 1979 Salary Survey"},"level":"law","status":"active","docNumber":"Executive Order No. 810","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-12","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00810_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00810_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21079-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 810 June 12, 1982\nGRANTING SALARY INCREASES TO TEACHING POSITIONS OF THE PHILIPPINE SCIENCE HIGH\nSCHOOL (PSHS) AS AN ACCELERATED IMPLEMENTATION OF THE 1979 SALARY SURVEY\nWHEREAS, Presidential Decree No. 985 empowers the President to determine the compensation of\ngovernment employees;\nWHEREAS, Executive Order No. 722 provided for salary increases for teachers and other related teaching\npositions in the Ministry of Education and Culture;\nWHEREAS, the general and specialized functions of the Philippine Science High School (PSHS), a unique\nsecondary school, are vital, necessary and indispensable to the attainment of the goals of the national science\nand technology system;\nWHEREAS, it is the policy of the government to adjust the salary of government employees to allow them to\ncope with the increased cost of living.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby order and instruct:\n1. The salaries of teaching personnel in the Philippine Science High School shall be adjusted by four (4) salary\nsteps in the national compensation plan. The position of Director, PSHS shall be equated to Career Executive\nService Rank III, Grade I with a salary of P50,376 per annum.\n2. The salary ranges of teaching positions shall be upgraded by six (6) salary ranges based on the salary ranges\nappearing in the CY 1981 Personal Services Itemization in accordance with the salary range schedule under\n3. Funds to implement this upgrading shall be charged against salary lapses and other personnel services\nsavings of the agency. The PSHS shall generate saving from its operating expenses for CY 1982 to cover the\nadditional salary cost provided therein.\n4. The salary increases directed by this Order shall take effect December 1, 1981.\n5. The rules and regulations needed to comply with this Order shall be formulated and issued by the Director\nGeneral, Office of Budget and Management.\nDone in the City of Manila, this 12th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21080"] = {"id":"PH-H21080","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES INSTITUTIONALIZING THE CERTIFICATION SCHEME FOR DIGITAL SIGNATURES AND DIRECTING THE APPLICATION OF DIGITAL SIGNATURES IN E-GOVERNMENT SERVICES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES INSTITUTIONALIZING THE CERTIFICATION SCHEME FOR DIGITAL SIGNATURES AND DIRECTING THE APPLICATION OF DIGITAL SIGNATURES IN E-GOVERNMENT SERVICES"},"level":"law","status":"active","docNumber":"Executive Order No. 810","issuingBody":"President of the Philippines","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00810_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00810_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21080-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Adopting a Framework for National Certification Scheme for\nDigital Signatures. A National Certification Scheme for Digital Signatures in the\nPhilippines, as it appears in Annex A, is hereby adopted."}},{"id":"PH-H21080-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Guidelines to Implement the National Certification Scheme\nfor Digital Signatures in the Philippines. The Department of Trade and Industry\n(DTI) shall, by virtue of its mandate under the Electronic Commerce Act, issue the\nnecessary guidelines to implement the National Certification Scheme for Digital\nSignatures in the Philippines.\nDesignation of Government Agencies and Functions. The\nfollowing agencies are hereby designated to perform the necessary services under the\ncertification scheme:\na) Root Certification Authority (CA). The National Computer Center (NCC)\nunder the Commission on Information and Communications Technology (CICT) is\nhereby designated to operate the Root CA. As such, it shall perform the\nfollowing functions:\n1. operate the Root CA system;\n2. issue and manage certificates to accredited government and private CAs;\n3. develop and prescribe technical standards for digital signatures in collaboration\nwith the Bureau of Product Standards of the Department of Trade and Industry\n4. develop certification technology;\n5. ensure interoperability of digital certification technology;\n6. provide technical expertise in the conduct of assessment of CAs when necessary;\n7. support international cooperation on certification services including mutual\nrecognition and cross-certification;\n8. resolve disputes involving the issuance and use of digital certificates between\nconcerned parties.\nb) Government Certification Authority (CA). The CC is likewise designated to\noperate the Government CA. As such, it shall perform the following functions:\n1. issue certificates for all government transactions to government\nemployees/entities and specific purpose certificates to private individuals/entities;\n2. publish certificates and Certificate Revocation List (CRL);\n3. handle revocation requests from the owners of the certificates it has issued.\nc) Registration Authority (RA).\nGovernment agencies and instrumentalities\nproviding -government services to its clients shall perform the following\nfunctions as RA:\n1. identify the user and register the user information;\n2. transmit certificate request to government CA;\n3. validate certificates from the CA directory server and CRL;\n4. request revocation of certificates.\nPGA Hologram # 49220\n49220\n2\n\nd) Accreditation and Assessment Body. The Department of Trade and Industry\n(DTI), through its Philippine Accreditation Office (PAO), is hereby designated as\nthe accreditation and assessment body for CAs pursuant to its mandate and in\naccordance with the provisions of the E-Commerce Act. As such, DTI shall\nperform the following functions:\n1. Issue the necessary criteria and guidelines for accreditation of CAs to ensure\nsecurity and interoperability of systems and certificates, as well as compliance\nwith the prescribed standards for digital signatures;\n2. Accredit CAs, whether government or private, according to the prescribed criteria\nand guidelines for accreditation;\n3. Conduct regular assessment of CAs to ensure compliance to existing criteria,\nguidelines and standards;\n4. Revoke or suspend the license of a CA for failure to comply with prescribed\nguidelines and standards;\n5. Create an Advisory Committee which shall provide direction and advice on the\nformulation of policies pertaining to the scheme for accreditation and assessment\n6. Create other committees to perform such other functions as may be determined\nindispensable and necessary to efficiently, effectively and expediently pursue the\nduties defined under this sub-section."}},{"id":"PH-H21080-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Application of Digital Signatures in E-Government Services. All\ngovernment agencies and instrumentalities providing electronic services to its clients\nshall require the use of digital signatures in their respective -government services to\nensure confidentiality, authenticity, integrity and non-repudiation of electronic\ntransactions in government. Such projects shall be included in the Information Systems\nStrateqic Plan (ISSP) which government agencies are required to submit to NCC-CICT for\napproval and endorsement to the Department of Budget and Management (DBM) .\nThe NCC-CICT shall plan, direct and monitor the implementation of this provision\nin government. Accordingly, it shall assist concerned agencies designated as RA to\nensure the smooth implementation of the system.\nWithin three (3) months from the issuance of this Order, NCC-CICT shall submit\nto the Office of the President the implementation plan including timetable and required\nresources to implement this Order. The plan shall identify priority government agencies\nand instrumentalities and the respective e-government services that will be required to\ncomply within two (2) years from the issuance of this Order. Other government\nagencies and instrumentalities shall be given three (3) years to comply with this Order."}},{"id":"PH-H21080-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Funding and Manpower. To fast-track the implementation of this\nOrder, CICT is hereby directed to prioritize projects of government agencies which are\napplying for funding under the E-government Fund for projects that will immediately\napply the use of digital signatures in their respective e-government services. Such\n3\n4922\nPGMA Hologram # 49221\n\nproiects remain subiect to the requirements of the E-government Fund and must be\nidentified in the agencies' NCC-approved ISSP.\nAll government agencies and instrumentalities concerned shall submit its\nmanpower and budgetary requirements to the Department of Budget and Management\n(DBM) to implement this Order. The DBM is hereby directed to ensure that resources\nwill be appropriated in the regular budget of government agencies to implement this\nOrder in consultation with DTI and CICT."}},{"id":"PH-H21080-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Application of Digital Signatures in ICT Systems in the\nPrivate Sector. In line with its mandate to promote electronic commerce in the\ncountry, the DTI shall promote the application of digital signatures in ICT systems in the\nprivate sector to ensure confidentiality, authenticity, integrity and non-repudiation of\nelectronic transactions with the private sector,\nGovernment agencies or entities exercising supervisory and regulatory functions\nover private services are hereby directed to study and identify critical services that use\nelectronic systems which require high levels of security for using and storing personal\ninformation and transactions, with the view of strictly requiring the use of digital\nsignatures in such services."}},{"id":"PH-H21080-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Fees. NCC, as Root CA and Government CA, is hereby authorized to\ncharge fees for the issuance of digital certificates guided by the universal concept of user\ncharges, which is to recover at least the full cost of services rendered. Similarly,\ngovernment agencies and instrumentalities performing the functions of A are\nauthorized to charge fees for services rendered. In exceptional cases, however,\ngovernment RAs may assume the cost of the digital certificates issued to subscribers\nsubject to its contractual arrangement with the Government CA. The imposition of new\nfees or increases thereafter shall be subiect to the provision of Memorandum Circular\nNo. 137, Series of 2007, and National Economic and Development Authority (NEDA)\nCircular No. 01-2007.\nThe costs of digital certificates issued directly by private Accredited CAs (ACAs) or\nthrough their respective RAs shall be market-determined, just and reasonable. Private\nRAs have the option to assume the costs of the certificates issued to subscribers\ndepending on its contractual arrangements with the ACA."}},{"id":"PH-H21080-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Dispute Resolution. Cases arising from (1) the accreditation of\nCAs; (2) the use and issuance of digital certificates; (3) issues necessarily included\ntherein; or (4) issues which include the same, shall be heard and resolved by the\nrespective agencies designated to perform the necessary services in accordance with the\nrules and regulations to be formulated for such purpose."}},{"id":"PH-H21080-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Transitory Provision. During the initial transitory period after the\nissuance of the Rules and Regulations to implement this Order, there shall be an interim\npersonnel complement to manage and operate the Root CA and Government CA and\nperform the functions of the respective RAs. Such personnel can either be on detail,\nreassignment or secondment subject to existing rules of the Civil Service Commission on\npersonnel movements.\n49222\n4\nPOMA Hologram # 49222\n\nDTI and CICT shall determine and recommend to DBM the most appropriate\nmode of complementing the manpower requirements for the implementation of this\nIn the interim, or until such time that a private ACA becomes operational, NCC\nshall assume the role of private ACA."}},{"id":"PH-H21080-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Repealing Clause. All issuances, orders, rules and regulations, or\nparts thereof, which are inconsistent with the provisions of this Executive Order, are\nhereby repealed, amended or modified accordingly."}},{"id":"PH-H21080-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDone in the City of Manila this 15th day of June\nLord, Two Thousand and Nine.\n,in the year of Our\nBy authority of the President:\nfiner th hung\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 49223\n5\n\nCERTIFICATION SCHEME FOR DIGITAL SIGNATURES\nAccreditation/\nAssessment Body\nPUBLIC SECTOR\nPRIVATE SECTOR\nGovernment CA\nRA Management\nRA Management\nSUBSCRIBERS*\nCertificates for Government Transactions\nSUBSCRIBERS**\nGeneral/Specific Purpose Certificates\n* Government employees/entities - certificates for all government transactions\nNon-government individuals/entities - certificates specific to a government transaction\n(specific purpose certificate)\n**Private individuals/entities and government employees\n6\n\nDEFINITION OF TERMS:\nAsymmetric or public cryptosystem - a system capable of generating a secure key\npair, consisting of a private key for creating a digital signature, and a public key for\nverifying the digital signature.\nAccreditation and Assessment Body - refers to the body that accredits the CAs and\nconducts regular assessment of such CAs to ensure compliance to prescribed criteria,\nguidelines and standards.\nCertificate - an electronic document issued to support a digital signature which\npurports to confirm the identity or other significant characteristics of the person who\nholds a particular key pair. Certificates issued may be for general use or for specific\nCertification Authority (CA) - issues digitally-signed public key certificates and attests\nthat the public key embedded in the certificate belongs to the particular subscriber as\nstated in the certificate. A CA may be involved in a number of administrative tasks such\nas end-user registration, although these tasks are often delegated to the Registration\nAuthority (RA). The CA may either be a government body or private entity.\nDigital Signature - refers to an electronic signature consisting of a transformation of an\nelectronic document or an electronic data message using an asymmetric or public\ncryptosystem, such that a person having the initial untransformed document and the\nsigner's public key can accurately determine: (i) whether the transformation was\ncreated using the private key that corresponds to the signer's public key; and (i)\nwhether the initial electronic document had been altered after the transformation was\nElectronic key - refers to a secret code which secures and defends sensitive\ninformation that crosses over public channels into a form decipherable only with a\nmatching electronic key.\nGeneral Purpose Certificate - a certificate which can be used for all government and\nprivate transactions.\nRegistration Authority (RA) - refers to a third-party used by the CA to perform\nadministrative tasks such as end-user registration. The RA may either be a government\nagency or private entity performing frontline services.\nRoot CA - issues and manages certificates to government and private CAs.\nSpecific Purpose Certificate - a certificate which can only be used for a specific\ntransaction.\nSubscriber - an individual or entity applying for and using digital certificates issued by\n\nThe DTI, which is the Accreditation/Assessment Body under this scheme, shall issue the\nimplementing guidelines and the criteria for the accreditation of the Root CA (NCC), the\nGovernment CA (NCC), and the private CA. The role of the Root CA is critical to ensure\nthe interoperability of systems among accredited CAs and cross-recognition of\ncertificates within and outside the country.\nThe Government CA will issue certificates to government employees and entities which\ncan be used for all government transactions. The Government CA can also issue\nspecific purpose certificates for a specific government transaction to private individuals\nand entities (e.g. private individual and corporate taxpayers) if they do not have a\ngeneral purpose certificate issued by a private ACA. In both cases, the Government CA\nwill issue the certificates through a government agency which shall function as RA.\nGovernment employees have to apply for general or specific purpose certificates from a\nprivate ACA for personal transactions with private entities.\nGeneral purpose certificates issued by a private ACA to private individuals and entities\ncan also be used for transactions with government. The private ACA may issue the\ncertificates directly to the subscriber or through a private entity which shall function as\n8"}}],"pack":"ph-p159"};
  FT["PH-H21081"] = {"id":"PH-H21081","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Films Ratings Board, Defining Its Powers and Functions and for Other Purposes","orig":"Creating the Films Ratings Board, Defining Its Powers and Functions and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 811","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-12","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00811_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00811_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21081-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of Film Ratings Board. There is hereby created a Film Rating Board, hereinafter known in\nthis Order as the Board, under Experimental Cinema of the Philippines."}},{"id":"PH-H21081-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Composition of the Board. The Board shall be composed of a chairman and twenty-seven (27)\nmembers to be appointed by the President of the Philippines. The Members of the Board shall serve for a\nminimum term of two years.\nIn the selection of Members of the Board, a multisectoral representation shall be considered to bring about the\nhighest degree of efficiency in its operations.\nThe Chairman and Members of the Board shall receive such per diems and allowances as authorized by the\nECP Board of Trustees."}},{"id":"PH-H21081-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Aims and Objectives. Board shall endeavor to upgrade the quality of Filipino films through the\nestablishment and effective implementation of a film rating and classification system.\nSpecifically, the Board shall have the following goals:\n1. To foster intellectual, technical and aesthetic sophistication in the quality of films produced and exhibited in\nthe Philippines;\n2. To encourage the production of films that strengthen and solidify our national identity, seek to enhance the\nquality of life, contribute to the dignity and ennoblement of the human spirit, portray themes that have\nuniversal roots, and depict and examine human conditions;\n3. To increase the marketability of locally produced films in both domestic and foreign markets; and\n4. To encourage quality orientation in the film industry through recognition of outstanding performances of\nacts and talents."}},{"id":"PH-H21081-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Powers and Functions of the Board. The Board shall have the following powers and functions:\n1. Establish standards that shall govern the quality of films;\n2. Establish a film rating and classification systems;\n3. Review and update the standards to keep them aligned with the requirements of the industry;\n4. Disseminate standards on an industry wide level;\n\n5. Review and classify all local films;\n6. Develop systems and procedures that shall insure an efficient and effective method of rating films;\n7. Implement the rating system in support of the interest of the Filipino film industry;\n8. Insure proper awarding of incentives to deserving films;\n9. Coordinate with the Board of Review for Motion Pictures and Television in the discharge of the functions\nof the Films Ratings Board; and\n10. Perform such other related functions as may be required by law or the ECP Board of Trustees."}},{"id":"PH-H21081-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Director, his Functions and Duties. The chief executive officer of the Board shall be the Director who\nshall be appointed by the President upon recommendation of the Board of Trustees of the Experimental\nCinema of the Philippines. The Director shall concurrently be the Chairman of the Film Ratings Board.\nThe Director shall manage the affairs of the Board and shall with the cooperation of his staff perform such\nfunctions and duties assigned to him by law, by the ECP Board of Trustees and by the Film Ratings Board."}},{"id":"PH-H21081-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Board shall promulgate such rules and regulations as may be necessary to implement its aims and\nobjectives, subject to the approval of the ECP Board of Trustees and the President of the Philippines."}},{"id":"PH-H21081-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Board may request any ministry, bureau, office, agency, or instrumentality of the government for\nsuch assistance as it may need in the performance of its functions."}},{"id":"PH-H21081-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"All personnel of the Board shall be appointed by the ECP Director-General, upon recommendation of\nthe Director of the Board."}},{"id":"PH-H21081-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"The Board of Standards created under Executive Order No. 640-A is hereby abolished and all its\npersonnel, assets, books and records are hereby transferred to the Film Ratings Board."}},{"id":"PH-H21081-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"All executive orders, administrative orders, rules or regulations inconsistent herewith are hereby\nrepealed, amended or modified accordingly.\nDone in the City of Manila, this 12th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21082"] = {"id":"PH-H21082","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":11,"structureMode":"ARTICLE","title":{"zh":null,"en":"Adopting the First Tranche of the Modified Salary Schedule of Civilian Personnel and Base Pay Schedule of Military and Uniformed Personnel in the Government, as Well as the Modified Position Classification System Pursuant to Senate and House Representatives Joint Resolution No. 4, S. 2009 (Gloria Macapagal-Arroyo)","orig":"Adopting the First Tranche of the Modified Salary Schedule of Civilian Personnel and Base Pay Schedule of Military and Uniformed Personnel in the Government, as Well as the Modified Position Classification System Pursuant to Senate and House Representatives Joint Resolution No. 4, S. 2009 (Gloria Macapagal-Arroyo)"},"level":"law","status":"active","docNumber":"Executive Order No. 811","issuingBody":"President of the Philippines","promulgatedDate":"2009-06-17","completenessNote":"全文，共 11 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00811_2009_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00811_2009_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21082-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Purpose - This Executive Order is issued in accordance with House of Representatives Joint\nResolution No. 4, s. 2009, and shall:\n(a) prescribe the first tranche of the modified salary schedule of civilian personnel and base pay schedule of\nmilitary and uniformed personnel in the government; and\n(b) direct the review and modification of the position classification system."}},{"id":"PH-H21082-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Coverage and Exclusion -\n(a) Civilian Personnel - The modified Compensation and Position Classification System shall cover all\npositions for civilian personnel in the Executive, Legislative and Judicial Branches, the Constitutional\nCommissions, State Universities and Colleges (SUCs), Government-Owned or Controlled Corporations\n(GOCCs), Government Financial institutions (GFIs), and Local Government Units (LGUs), whether regular,\ncasual, or contractual in nature, appointive or elective, on full-time or part-time basis, now existing or\nhereafter created.\nThe following shall be excluded from the coverage of the System:\n(i) individuals and groups of personnel whose services are engaged through job orders, contracts of services,\n\nor others similarly situated; and\n(ii) positions for civilian personnel in government entities which are authorized by law to adopt, and are\nactually implementing their own compensation and position classification systems.\n(b) Military and Uniformed Personnel - The modified Base Pay Schedule provided in item (8) of said Joint\nResolution, shall cover the military personnel under the Department of National Defense (DND) and\nuniformed personnel under the Department of the Interior and Local Government (DILG), Philippine Coast\nGuard (PCG), and National Mapping and Resource Information Authority (NAMRIA)."}},{"id":"PH-H21082-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Implementation Period -\n(a) For national government agencies (NGAs), the Salary Schedule in item (4)(b) and the Base Pay Schedule\nin item (8) of said Joint Resolution, shall be implemented in four (4) equal yearly tranches, but in no case\nbeyond four (4) years.\n(b) For GOCCs, GFIs, and LGUs, the implementation period shall be four (4) years or more depending on\ntheir financial capability."}},{"id":"PH-H21082-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"First Tranche of Implementation -\n(a) For Civilian Personnel -\n(i) For NGA, GOCC and GFI Personnel -\nThe salary rates shall be in accordance with the First Tranche Monthly Salary Schedule for Civilian\nGovernment Personnel Effective July 1, 2009, attached as Annex “A”.\n(ii) For LGU Personnel -\nThe salary rates for LGU personnel shall be determined by the sanggunian, on the basis of LGU income class\nand financial capability: Provided, That such salary rates shall not exceed the applicable percentages shown in\nthe table below, pursuant to item 7(a) of the Joint Resolution: Provided, Further That the resulting personal\nservices (PS) cost shall not exceed the PS limitation in local government budgets, as provided under Sections\n325(a) and 331(b) of Republic Act No. 7160: Provided, Finally That there shall be no diminution in the basic\nsalaries of incumbents for purposes of complying with said PS limitation.\nPercentages of Salary Rates Shown in Annex \"A\"\nFor Provinces/Cities\nFor Municipalities\nSpecial Cities\n100%\n100%\n90%\n95%\n85%\n90%\n80%\n85%\n\n75%\n80%\n70%\n75%\n65%\nFor this purpose, the DBM shall issue the First Tranche Monthly Salary Schedule for Local Government\nPersonnel for each LGU income class which shall take effect January 1, 2010.\n(b) For Military and Uniformed Personnel -\nThe base pay rates shall be in accordance with the First Tranche Monthly Base Pay Schedule for Military and\nUniformed Personnel Effective July 1, 2009, attached as Annex “B.”"}},{"id":"PH-H21082-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Uniform Implementation in Case of Insufficiency of Funds\n(a) GOCCs and GFIs which do not have adequate or sufficient funds shall implement salary schedules which\nshall be at uniform percentages of the salary rates in Annex “A.”\n(b) Likewise, LGUs which do not have adequate or sufficient funds to implement the maximum salaries\nprescribed for the LGU income class shall implement salary schedules which shall be at uniform percentages\nof the salary rates in the First Tranche Monthly Salary Schedule for Local Government Personnel."}},{"id":"PH-H21082-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Changes in Position Titles and Salary Grade Assignments of Certain Positions -\nThe position titles and salary grade assignments of the entry levels of the following positions are hereby\nPosition Title\nSalary Grade\n10\n11\n10\n11\nMedical Officer I\n14\n16\nAccountant I\n11\n12\n[Legal Officer I] Attorney I\n[14]\n\n16\nThe DBM, in coordination with the Civil Service Commission (CSC), shall review the other levels of the\nabove-listed positions and other classes of positions to determine their appropriate levels, and to allocate them\nto their proper salary grades.\nAccordingly, the DBM, in coordination with the CSC, shall update the Index of Occupational Services,\nOccupational Groups, Classes, and Salary Grades, in accordance with organizational, technological,\nprofessional and other developments."}},{"id":"PH-H21082-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Non-Diminution in the Basic Salaries of Incumbent Employees - In no case shall there be any\ndiminution in the basic salaries of incumbent employees upon the implementation of the Joint Resolution and\nthis Executive Order."}},{"id":"PH-H21082-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Funding Sources - The funding sources for the amounts necessary to implement the modified\nCompensation and Position Classification System shall be as follows:\n(a) For NGAs, the amounts shall be charged against appropriations set aside for the purpose in the FY 2009\nGeneral Appropriations Act (GAA) and from savings generated by the different departments, bureaus, offices\nand agencies of the national government. Thereafter, such amounts as are needed shall be included in the\n(b) For GOCCS and GFTs, the amounts shall come from their respective corporate funds in the approved\ncorporate operating budgets.\n(c) For LGUs, the amount shall be charged against their respective local government funds."}},{"id":"PH-H21082-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Applicability to Certain Constitutional Officials. - Pursuant to Section 6 of Article VII and"}},{"id":"PH-H21082-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"of Article VI of the Constitution, the salaries prescribed herein for the President of the Philippines,\nVice-president of the Philippines, and Members of Congress shall take effect only after the expiration of the\nrespective terms of the present incumbents.\nSection 10. Subsequent Issuances. The President, upon recommendation by the DBM, shall issue such other\nExecutive Orders to fully implement the provisions of Senate and House of Representatives Joint Resolution"}},{"id":"PH-H21082-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Effectivity. - This Executive Order shall take effect immediately.\nDone in the City of Manila this 17th day of June in the year of our Lord, Two Thousand and Nine.\n(Sgd.) GLORIA MACAPAGAL-ARROYO\nBy the President:\n(Sgd.) EDUARDO R. ERMITA\nExecutive Secretary\nFirst Tranche Monthly Salary Schedule for Civilian Government Personnel\nEffective July 1, 2009 for National Government Personnel\n\n1\n6,862\n7,000\n7,140\n7,285\n7,432\n7,583\n7,737\n7,895\n2\n7,446\n7,749\n7,749\n7,906\n8,065\n8,229\n8,397\n8,569\n3\n8,080\n8,409\n8409\n8,580\n8,753\n8,932\n9,113\n9,301\n4\n8,713\n9,069\n9,069\n9,252\n\n9,441\n9,634\n9,830\n10,031\n5\n9,396\n9,780\n9,780\n9,978\n10,181\n10,390\n10,601\n10,819\n6\n10,133\n10,338\n10,548\n10,761\n10,981\n11,206\n11,434\n11,669\n7\n10,858\n11,076\n11,302\n11,531\n11,766\n12,005\n12,251\n12,503\n8\n11,636\n11,871\n12,110\n12,357\n12,607\n\n12,864\n13,128\n13,396\n9\n12,469\n12,721\n12,978\n13,242\n13,510\n13,785\n14,067\n14,353\n10\n13,333\n13,603\n13,877\n14,158\n14,445\n14,740\n15,040\n15,348\n11\n14,198\n14,483\n14,775\n15,072\n15,379\n15,691\n16,011\n16,335\n12\n15,119\n15,422\n15,733\n16,050\n16,374\n16,706\n\n17,044\n17,390\n13\n16,101\n16,424\n16,753\n17,089\n17,433\n17,786\n18,147\n18,514\n14\n17,147\n17,490\n17,839\n18,197\n18,563\n18,938\n19,321\n19,711\n15\n18,292\n18,661\n19,040\n19,426\n19,822\n20,228\n20,640\n21,064\n16\n19,514\n19,906\n20,309\n20,722\n21,142\n21,573\n22,013\n\n22,462\n17\n20,819\n21,237\n21,665\n22,102\n22,552\n23,009\n23,477\n23,995\n18\n22,214\n22,659\n23,115\n23,581\n24,057\n24,542\n25,041\n25,549\n19\n23,703\n24,177\n24,661\n25,157\n25,664\n26,182\n26,710\n27,251\n20\n25,295\n25,799\n26,314\n26,842\n27,381\n27,931\n28,494\n29,070\n\n21\n26,671\n27,200\n27,741\n28,293\n28,856\n29,433\n30,024\n30,626\n22\n28,134\n28,687\n29,254\n29,832\n30,424\n31,029\n31,647\n32,278\n23\n29,684\n30,265\n30,861\n31,467\n32,086\n32,720\n33,368\n34,030\n24\n31,334\n31,943\n32,567\n33,201\n33,853\n34,516\n35,195\n35,890\n25\n\n33,085\n33,724\n34,376\n35,044\n35,725\n36,422\n37,133\n37,862\n26\n34,945\n35,615\n36,301\n37,001\n37,716\n38,446\n39,193\n39,956\n27\n36,923\n37,627\n38,347\n39,080\n39,830\n40,597\n41,380\n42,181\n28\n39,026\n39,766\n40,521\n41,291\n42,078\n42,882\n43,705\n44,545\n29\n41,264\n\n42,041\n42,833\n43,642\n44,469\n45,314\n46,176\n47,056\n30\n45,941\n46,813\n47,705\n48,615\n49,544\n50,495\n51,464\n52,455\n31\n59,186\n60,351\n61,540\n62,757\n64,000\n65,272\n66,570\n67,898\n32\n67,677\n69,008\n70,369\n71,760\n73,181\n74,634\n76,119\n77,637\n33\n82,400\n\nFirst Tranche Base Pay Schedule for Military and Uniformed Personnel\nEffective July, 2009\nPCG and NAMRIA\nMonthly Base Pay\nBJMP and BFP\nPNP and PPSC\n8,630\nFire/Jail Officer I\nPolice Officer I\nApprentice Seaman/\nSeaman Third Class\n10,808\nPrivate First Class\nSeaman Second Class\n11,513\nFire/Jail Officer II\nPolice Officer II\nSeaman First Class\n12,210\nPetty Officer III\n12,891\nStaff Sergeant\nFire/Jail Officer III\nPolice Officer III\nPetty Officer II\n13,628\nTechnical Sergeant\nPetty Officer I\n14,540\n\nMaster Sergeant\nSenior Fire/\nJail Officer I\nSenior Police\nChief Petty\n15,513\nSenior Master\nSenior Fire/\nSenior Police\nSenior Chief\n16,552\nJail Officer II\nPetty Officer\nChief Master\nSenior Fire/\nSenior Police\nMaster Chief\n17,664\nJail Officer III\nOfficer III\nPetty Officer\nFirst Chief\nSenior Fire/\nSenior Police\nFirst Master\n18,850\nMaster Sergeant\nJail Officer IV\nChief Petty Officer\n\n18,850\nProbationary Second Lieutenant\n18,850\nSecond Lieutenant\n20,708\nFirst Lieutenant\nLieutenant Junior Grade\n21,836\nSenior Inspector\nSenior Inspector\nLieutenant\nSenior Grade\n23,128\nChief Inspector\nChief Inspector\nLieutenant Commander\n24,202\nLieutenant Colonel\nSuperintendent\nSuperintendent\n25,543\nSenior Superintendent\nSenior Superintendent\n26,967\nBrigadier General\nChief Superintendent\nChief Superintendent\n28,481\n\nMajor General\nRear Admiral\n30,090\nVice Admiral\n31,801\nLieutenant General\nDeputy Director-General\n35,428\nDirector General\n37,500"}}],"pack":"ph-p159"};
  FT["PH-H21083"] = {"id":"PH-H21083","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Extending the Period for the 1981-82 General Revision of Real Property Assessment From June 30, 1982 to June 30, 1984 and Fixing the Date of Accrual of the Real Property Tax Based on the Revised Property Valuations","orig":"Extending the Period for the 1981-82 General Revision of Real Property Assessment From June 30, 1982 to June 30, 1984 and Fixing the Date of Accrual of the Real Property Tax Based on the Revised Property Valuations"},"level":"law","status":"active","docNumber":"Executive Order No. 812","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00812_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00812_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21083-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The period for the 1981-82 general revision of real property assessments as fixed under Section 21 of\nPresidential Decree No. 464, as amended by Presidential Decree No. 1621, is hereby extended up to June 30,\n1984;"}},{"id":"PH-H21083-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The real property tax based on the revised property assessments resulting from said general revision\nshall accrue beginning January 1, 1985, instead of January 1, 1983;"}},{"id":"PH-H21083-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Minister of Finance shall issue the rules and regulations necessary for the proper implementation\nof this Order."}},{"id":"PH-H21083-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"All acts, orders, rules and regulations inconsistent with this Order are hereby modified accordingly."}},{"id":"PH-H21083-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 22nd day of June in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21084"] = {"id":"PH-H21084","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED FOR UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE COMMITMENT TO REDUCE THE TARIFF RATES ON NINETY PERCENT (90%) OF THE PRODUCTS IN THE NORMAL TRACK TO ZERO WITH FLEXIBILITY UNDER THE ASEAN-KOREA FREE TRADE AREA (AKFTA)","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED FOR UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE COMMITMENT TO REDUCE THE TARIFF RATES ON NINETY PERCENT (90%) OF THE PRODUCTS IN THE NORMAL TRACK TO ZERO WITH FLEXIBILITY UNDER THE ASEAN-KOREA FREE TRADE AREA (AKFTA)"},"level":"law","status":"active","docNumber":"Executive Order No. 812","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00812_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00812_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21084-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles specifically listed in the Annex (Articles Granted\nTariff Concession Under the Normal Track of the ASEAN - Korea Free Trade Area)\nhereof, as classified under Section 104 of the Tariff and Customs Code of 1978, as\namended, shall be subject to the AKFTA rates in accordance with the schedule\nindicated in Columns 4-6 of the Annex. The AKFTA rates so indicated shall be\naccorded to imports coming from the parties of the Agreement on Trade in Goods of\nthe Framework Agreement applying tariff concession to the same product pursuant\nto Article 3 of the Agreement on Trade in Goods of the Framework Agreement."}},{"id":"PH-H21084-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"For ASEAN 8 (i.e. Brunei Darussalam, Cambodia, Indonesia, Lao\nPeoples Democratic Republic, Malaysia, Myanmar, Singapore and Vietnam) the\napplicable rate shall be the AFTA rate, subject to the submission of the proper\nCertification of Origin, Form AK. The Tariff Commission pursuant to Section 1313(a)\nof the Tariff and Customs Code of the Philippines, as amended, may, upon request,\nissue tariff classification rulings to confirm the applicable rates of duty of particular\nproducts subject to this section."}},{"id":"PH-H21084-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"In the event that any subsequent change is made in the basic\n(MFN) Philippine rate of duty on any of the articles listed in the Annex to a rate\nlower than the rate prescribed in Columns 4-6 of the Annex, such article shall\nautomatically be accorded the corresponding reduced duty."}},{"id":"PH-H21084-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"From the date of effectivity of this Order, all articles listed in\nthe Annex entered into or withdrawn from warehouses in the Philippines for\nconsumption shall be imposed the rates of duty therein prescribed subiect to\ncompliance with the Rules of Origin as provided for in Article 5 of the Agreement on\nTrade in Goods of the Framework Agreement."}},{"id":"PH-H21084-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"All presidential issuances, administrative rules and regulations,\nor parts thereof, which are contrary to or inconsistent with this Executive Order are\nhereby revoked or modified accordingly."}},{"id":"PH-H21084-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"This Executive Order shall take effect fifteen (15) days following\nits complete publication in the official gazette or in a newspaper of general\ncirculation in the Philippines.\nDone in the Citv of Manila this isl day of\nof Our Lord, Two Thousand and Nine.\nBy the President:\n49344\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Kalonram M 49344"}}],"pack":"ph-p159"};
  FT["PH-H21085"] = {"id":"PH-H21085","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"Establishing the System of Position Classification and Compensation for the Office of the Prime Minister (Proper) as Well as the Rules and Regulations for Its Implementation","orig":"Establishing the System of Position Classification and Compensation for the Office of the Prime Minister (Proper) as Well as the Rules and Regulations for Its Implementation"},"level":"law","status":"active","docNumber":"Executive Order No. 813","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-22","completenessNote":"全文，共 15 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00813_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00813_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21085-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The System. The system consists of the Position Classification Plan and the compensation Plan for the\nOffice of the Prime Minister (Proper)."}},{"id":"PH-H21085-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Coverage. The system shall cover all regular positions in the Office of the Prime Minister (Proper),\nexcept the positions of the Prime Minister and Deputy Prime Minister."}},{"id":"PH-H21085-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Position Classification Plan. The Position Classification Plan shall consist of (a) positions in the\nOffice divided into two main categories, namely, the Career Executive Service Level and the Sub-Career\nExecutive Service Level which is sub-divided into occupational groups under which are position classes, and\n(b) the rules and regulations for its implementation and administration."}},{"id":"PH-H21085-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Position Classes and Salary Ranks. The position classes and the corresponding ranks in the Career\nExecutive Service Level are as follows:\nSecretary-General\nDeputy Secretary-General\nStaff Office Director\nSpecial Officer\n\nExecutive Officer\nDeputy Staff Office Director\nStaff Service Director\nDeputy Staff Service Director\nThe Secretary-General position shall not be covered by CES ranking and shall have a compensation equal to\ntwo-grades higher than Rank I positions.\nThe position classes and the coresponding pay ranges in the Sub-Career Executive Service Level are as\nStaff Officers Group\nChief OPM Staff Officer\n20\nSupervising OPM Staff Officer\n18\nSenior OPM Staff Officer\n16\nOPM Staff Officer\n12\nJunior OPM Staff Officer\n9\nStaff Secretarial Group\nPrivate Secretary II\n14\nPrivate Secretary I\n12\nStaff Assistants Group\nSupervising Staff Assistant\n8\nSenior Staff Assistant\n7\nStaff Assistants\n6\n\nStenographic Group\nSenior Stenographer to the Prime Minister\n16\nStenographer to the Prime Minister\n12\nStenographer Reporter\n6\nSupervising Staff Stenographer\n6\nSenior Staff Stenographer\n4\nStaff Stenographer\n3\nBuilding and Grounds Supervisor\n10\nMaintenance General Foreman\n6\nMaintenance Foreman\n4\nGeneral Utility Services Group\nSupervising Utility Man\n3\nSenior Utility Man\n2\nUtility Man\n1\nAutomotive Equipment and Operation Group\nMotorpool Superintendent\n10\nAssistant Motorpool Superintendent\n8\nOPM Chauffeur\n4\n3\nGeneral Clerical Group\nSupervising Staff Aide\n\n4\nSenior Staff Aide\n3\n2"}},{"id":"PH-H21085-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Compensation Plan. The salary scale of the Career Executive Service shall apply to CES level\npositions in the Office of the Prime Minister; Provided, that such positions shall have a one-grade advantage\nover comparable, positions in the CES Compensation Plan.\nThe salary scale for the Sub-Career Executive Service Level in the Office of the Prime Minister shall be as\n1\n2\n6240\n6888\n7608\n8400\n9288\n3\n6888\n7608\n8400\n\n9288\n10260\n4\n7608\n8400\n9288\n10260\n11328\n5\n8400\n9288\n10260\n11328\n12516\n6\n9288\n10260\n11328\n12516\n13824\n7\n10260\n11328\n12516\n13824\n15264\n8\n11328\n12516\n13824\n15264\n16860\n9\n12516\n13824\n15264\n16860\n\n18636\n10\n13824\n15264\n16860\n18636\n20580\n11\n15264\n16860\n18636\n20580\n22728\n12\n16860\n18636\n20580\n22728\n25116\n13\n18636\n20580\n22728\n25116\n27732\n14\n20580\n22728\n25116\n27732\n30624\n15\n22728\n25116\n27732\n30624\n33816\n\n16\n25116\n27732\n30624\n33816\n37344\n17\n27732\n30624\n33816\n37344\n41232\n18\n30624\n33816\n37344\n41232\n45540\n19\n33816\n37344\n41232\n45540\n50292\n20\n37344\n41232\n45540\n50292\n55536\n21\n41232\n45540\n50292\n55536\n61344\n22\n\n45540\n50292\n55536\n61344\n67764"}},{"id":"PH-H21085-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Classification Rules\na. Positions shall first be classified by the Office of Budget and Management before inclusion in the regular or\nspecial budgets.\nb. Positions shall be classified on the basis of regular and permanent duties and responsibilities attached\nthereto and the qualification requirements therefor.\nc. Proposals for the creation of new positions shall be in accordance with the provisions of Presidential Decree\nd. Reclassification of a position may be proposed whenever there are significant and permanent changes in the\nduties and responsibilities thereof. The proposal, supported by a duly accomplished position description form\nand such other papers as may be required, shall be incorporated in the budget estimates of the Office and shall\nbe processed by the Office of Budget and Management.\ne. The classification or reclassification of position to another class with the same pay range allocation or to a\nlower class shall take effect upon its approval. Reclassification action from one class to a higher class shall\ntake effect not earlier than the beginning of the next calendar year.\nf. The classification plan herein provided shall apply to all position now existing or hereafter created in the\nOffice of the Prime Minister."}},{"id":"PH-H21085-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Salary Rules\na. The hiring rate for new employees shall follow existing OBM Circulars and Memoranda.\nb. An employee may be allowed a salary rate higher than the minimum of the range allocation of the position\nin case he had previously received a higher salary in the government service; Provided, that such a salary rate\nis within the pay range allocation of the position and; Provided, Further, that there is sufficient appropriation\nfor that particular position.\nc. An employee who is promoted to a position in a higher class and whose present salary is over the maximum\nrate of the pay range allocation of the position to which he is being promoted, may be allowed to continue to\nreceive his present salary at the higher position.\nd. Upon certification by the Secretary-General that an employee's services are satisfactory, the salary may be\nincreased to the next higher step of his pay range after one year at his present step, provided there is sufficient\nappropriation in the particular position of the employee.\ne. Employees whose actual salaries are between the steps of the pay ranges of the classes to which their\npositions have been allocated shall be entitled to adjustment to the next higher step, if an appropriation has\nbeen provided therefor.\nf. Voluntary demotion may be made without loss of salary except where the current salary is higher than the\nmaximum of the class to which demoted, and provided that there is sufficient appropriation for the particular\ng. Notwithstanding the provisions of any other rule, no officer or employee shall receive a salary higher than\nthe salary of his immediate supervisor."}},{"id":"PH-H21085-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Salary Increases for Employees Paid Out of Lump-Sum Appropriations. Employees whose salaries are\n\npaid out of lump sum appropriations may be granted salary increases upon recommendation of the Minister of\nBudget and the approval of the Prime Minister. The funds for the purpose shall be charged against the\nrespective lump-sum appropriations."}},{"id":"PH-H21085-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Salary Increases. Whenever a national government salary increase is allowed on the basis of a periodic\nnation-wide salary survey conducted by the Office of Budget and Management, positions in the Office may be\ngranted across-the-board or in-step increases, upon recommendation of the Minister of the Budget and the\napproval of the President."}},{"id":"PH-H21085-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Revision of the Plans. If the results of the periodic nation-wide salary survey require the revision of\nthe Classification and Compensation Plans to keep them up-to-date, the same may be revised upon\nrecommendation of the Minister of the Budget and Prime Minister and the approval of the President."}},{"id":"PH-H21085-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"Additional Compensation. The following policies shall be adopted in the granting of additional\ncompensation:\na. Transportation and Representation Allowances\nCommutable transportation and representation allowances shall be granted only to the officials, and those of\nequivalent rank, specified in the General Provisions of the Appropriations Act. The determination of\nequivalent ranks for the purpose shall be made by the Office of Budget and Management.\nb. Cost of Living Allowances\nThe employees of the Office of the Prime Minister shall be entitled to the cost of living allowances for\nnational government employees, subject to the availability of funds.\nc. Clothing Allowances\nAll regular employees shall be granted uniform/clothing allowances at the rates authorized in the General\nProvisions of the Appropriations Act. Funds for the purpose will be charged against savings or the\nappropriations for \"other services.\"\nRegular employees in the Office of the Prime Minister shall be entitled to per diems in acccordance with the\nprovisions of Section 79, Presidential Decree No. 1177.\nThe maximum amount paid for each type of allowance shall be determined in accordance with the pertinent\nGeneral or Special Provision in the approved Personal Services Itemization."}},{"id":"PH-H21085-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"National Compensation and Position Classification Plan. The compensation and position\nclassification plans for the Office of the Prime Minister similar with the OP Classification Plan (Executive\nOrder No. 530) are established within the context of Presidential Decree No. 985 and shall not be changed\nwithout the approval of the President upon recommendation of the Minister of the Budget."}},{"id":"PH-H21085-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"Lump-Sum Appropriation. The amount of P500,000 out of any available funds from the National\nTreasury is hereby appropriated to cover the difference between the authorized and actual salary of OP\npersonnel transferred to the OPM pursuant to Executive Order No. 708."}},{"id":"PH-H21085-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"Repealing Clause. Any and all laws, executive orders, rules and regulations or part thereof\ninconsistent with this Order are hereby repealed or modified accordingly.\nIf for any reason, any section or provision of this Order is declared to be unconstitutional or invalid, the other\nsections or provisions thereof which are not affected thereby, shall continue in full force and effect."}},{"id":"PH-H21085-A15","no":15,"noLabel":{"en":"Sec 15"},"text":{"en":"Effectivity. This Order shall take effect April 1, 1982.\nDone in the City of Manila, this 22nd day of June in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21086"] = {"id":"PH-H21086","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo2009/eo_813_2009.html","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reviving the Extension Office of the President in Mindanao (Gloria Macapagal-Arroyo)","orig":"Reviving the Extension Office of the President in Mindanao (Gloria Macapagal-Arroyo)"},"level":"law","status":"active","docNumber":"Executive Order No. 813","issuingBody":"President of the Philippines","promulgatedDate":"2009-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00813_2009_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00813_2009_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21086-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Revival of Office. - The extension office of the President in Mindanao is hereby revived, to be\nheaded by a Presidential Adviser for Mindanao."}},{"id":"PH-H21086-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Functions of the Presidential Adviser for Mindanao. - The Presidential Adviser for Mindanao\nshall have the following functions, powers and responsibilities:\n(a) Oversee the Mindanao Economic Development Council and the Southern Philippines Development\n(b) Oversee the Philippine activities of the Brunei Darrusalam-Indonesia-Malaysia-Philippines East ASEAN\nGrowth Area; and\n(c) Provide support to the President on matters related to Mindanao."}},{"id":"PH-H21086-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Budget. - The extension office of the President in Mindanao shall be provided with an initial\nbudget of Ten Million Pesos (P10,000,000). Appropriations for succeeding years shall be incorporated in the\nbudget proposal of the Office of the President."}},{"id":"PH-H21086-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repealing Clause. - All orders, issuances, rules and regulations or parts thereof which are\ninconsistent with this Executive Order, particularly Executive Order No. 757, are hereby repealed or modified\naccordingly."}},{"id":"PH-H21086-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Effectivity. - This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 17th day of June in the year of Our Lord, Two Thousand and Nine.\n(Sgd.) GLORIA MACAPAGAL-ARROYO\nBy the President:\n(Sgd.) EDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21087"] = {"id":"PH-H21087","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Expanding the Program for the Appointment of Consuls Ad","orig":"Expanding the Program for the Appointment of Consuls Ad"},"level":"law","status":"active","docNumber":"Executive Order No. 814","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-26","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00814_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00814_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21087-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Nominations. The Minister of Trade and Industry, as a strategy for export promotion may nominate,\nwith the concurrence of the Minister for Foreign Affairs, honorary Philippine consuls subject to the approval\nof the President of the Philippines."}},{"id":"PH-H21087-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"MFA Accreditation. Upon approval of the President, the Ministry of Foreign Affairs shall facilitate the\naccreditation of honorary Philippine consuls nominated by the Minister of Trade and Industry, to enable them\nto assume office and perform their duties and functions effectively."}},{"id":"PH-H21087-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Role in Export Promotion. Honorary Philippine consuls nominated by the Minister of Trade and\nIndustry, in addition to their functions, duties and responsibilities under the regulations of the Ministry of\nForeign Affairs, shall undertake in their respective jurisdictions, specific export promotion programs defined\nfor them by the Minister of Trade and Industry."}},{"id":"PH-H21087-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Program for Appointment of Honorary Philippine Consuls. To implement this Executive Order, the\nMinister of Trade and Industry shall draw up a program for the appointment of honorary Philippine Consuls in\nkey commercial centers of the world where they are needed, as a strategy for the country's export promotion"}},{"id":"PH-H21087-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Coordination with the MFA. In implementing this Executive Order, the Ministry of Trade and Industry\nshall coordinate closely with the Ministry of Foreign Affairs in order to assure that the trade promotion\nobjectives are carried out effectively."}},{"id":"PH-H21087-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Repeal. All acts, decrees, executive orders and regulations inconsistent with any provision of this\nOrder are hereby repealed or amended accordingly."}},{"id":"PH-H21087-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDone in the City of Manila, this 26th day of June in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21088"] = {"id":"PH-H21088","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED FOR UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE 2009-2012 PHILIPPINE SCHEDULE OF TARIFF REDUCTION UNDER THE NORMAL TRACK OF THE ASEAN-CHINA FREE TRADE AREA ON CERTAIN PRODUCTS AND TO IMPLEMENT THE TRANSFER OF CERTAIN TARIFF LINES FROM THE SENSITIVE TRACK TO THE NORMAL TRACK CATEGORY OF THE ASEAN-CHINA FREE TRADE","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED FOR UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE 2009-2012 PHILIPPINE SCHEDULE OF TARIFF REDUCTION UNDER THE NORMAL TRACK OF THE ASEAN-CHINA FREE TRADE AREA ON CERTAIN PRODUCTS AND TO IMPLEMENT THE TRANSFER OF CERTAIN TARIFF LINES FROM THE SENSITIVE TRACK TO THE NORMAL TRACK CATEGORY OF THE ASEAN-CHINA FREE TRADE"},"level":"law","status":"active","docNumber":"Executive Order No. 814","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00814_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00814_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21088-A17","no":17,"noLabel":{"en":"Article 17"},"text":{"en":"of the Agreement of Trade in Goods of the Framework Agreement;\nWHEREAS, the NEDA Board approved on 10 February and 26 May 2009\nthe 2009-2012 tariff reduction schedule under the Normal Track of the ACTA in\ncompliance with the Philippines' commitment under the Framework Agreement;\nand the transfer of certain tariff lines from the Sensitive Track to the Normal\nWHEREAS, Section 402 of the Tariff and Customs Code of 1978 (PD\n1464), as amended, empowers the President of the Republic of the Philippines,\nupon the recommendation of the National Economic and Development Authority,\nto modify import duties for the promotion of foreign trade;\nNOW, THEREFORE, I, GLORIA MACAPAGAL-ARROYO, President of\nthe Republic of the Philippines, by virtue of the powers vested in me by law, do\nhereby order:\nSECTION 1. The articles specifically listed in Annex \"A\" hereof (2009-\n2012 Philippine Schedule of Tariff Reduction under the Normal Track of the\nACFTA), as classified under Section 104 of the Tariff and Customs Code of 1978,\nas amended, shall be subject to the ACFTA rates in accordance with the schedule\nindicated in Columns 4-7 of Annex \"A\". The ACFTA rates so indicated shall be\naccorded to imports coming from the Parties to the Agreement on Trade in\nGoods of the Framework Agreement applying tariff concession to the same\nproduct pursuant to Article 3 of the Agreement on Trade in Goods of the\nFramework Agreement.\nSECTION 2. The articles specifically listed in Annex \"B\" hereof (Articles\nTransferred from Sensitive Track to the Normal Track of the AFTA), as classified\nunder Section 104 of the Tariff and Customs Code of 1978, as amended, shall be\nsubject to the ACFTA rates in accordance with the schedule indicated in Columns\n4-7 of Annex \"B\". The ACFTA rates so indicated shall be accorded to imports\ncoming from the Parties to the Agreement on Trade in Goods of the Framework\nAgreement applying tariff concession to the same product pursuant to Article 3\nof the Agreement on Trade in Goods of the Framework Agreement.\nSECTION 3. For ASEAN 9 (i.e. Brunei Darussalam, Cambodia, Indonesia,\nLao Peoples Democratic Republic, Malaysia, Myanmar, Singapore, Thailand, and\nVietnam), the applicable rate shall be the ACFTA rate subject to the submission\nof the proper Certificate of Origin, Form E. The Tariff Commission pursuant to\nSection 1313(a) of the Tariff and Customs Code of the Philippines, as amended,\n2\n49445\nMiata hintouran : 49445\n\nmay, upon request, issue tariff classification rulings to confirm the applicable\nrates of duty of particular products subject to this section.\nSECTION 4. In the event that any subsequent changes are made in the\nbasic MFN Philippine rates of duty on any of the article listed in Annexes \"A\" and\n\"B\" to a rate lower than the rate prescribed in Columns 4-7 of said Annexes, such\narticle shall automatically be accorded the corresponding reduced duty.\nSECTION 5. From the date of effectivity of this Order, all articles listed in\nAnnexes \"A\" and \"B\" entered into or withdrawn from warehouses in the\nPhilippines for consumption shall be imposed the rates of duty therein prescribed\nsubiect to compliance with the Rules of Origin as provided for in Article 5 of he\nAgreement on Trade in Goods of the Framework Agreement.\nSECTION 6. All presidential issuances, administrative rules and\nregulations, or parts thereof, which are contrary to or inconsistent with this\nExecutive Order are hereby revoked or modified accordingly.\nSECTION 7. This Executive Order shall take effect fifteen (15) days\nfollowing its complete publication in the Official Gazette or in a newspaper of\ngeneral circulation in the Philippines.\nDONE in the City of Manila, this 30% day of. June\nof Our Lord, Two Thousand and Nine.\nArea Mr. Away\n6 49446\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGA Holouram # 49446\n3"}}],"pack":"ph-p159"};
  FT["PH-H21089"] = {"id":"PH-H21089","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"To Safeguard and Promote the Development of the Philippine Semiconductor Electronics Industry","orig":"To Safeguard and Promote the Development of the Philippine Semiconductor Electronics Industry"},"level":"law","status":"active","docNumber":"Executive Order No. 815","issuingBody":"President of the Philippines","promulgatedDate":"1982-06-26","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00815_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00815_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21089-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Policy Statement and Objectives. It is hereby declared to be the policy of the State to maintain an\ninvestment environment conducive to the growth and development of the semiconductor electronics industry.\nSuch investment environment shall:\n(a) Provide operational maximum flexibility;\n(b) Be cost competitive;\n(c) Provide an adequate supply of required skills in the manpower pool;\n(d) Provide training to ensure a future supply of highly skilled engineers and technicians;\n(e) Create the infrastructure of suppliers needed by the industry for the supply of services, materials and\n(f) Encourage investors to evolve higher levels of assembly processes, automation, forward integration into\n\ndevice testing, and backward integration into wafer fabrication;\n(g) Encourage investors to develop a viable Consumer and Industrial Electronics Products Industry to serve\nboth domestic and export markets."}},{"id":"PH-H21089-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Additional Incentives to the Semiconductor Industry. In addition to the incentives provided for firms in\nthe semiconductor electronics industry registered with the Board of Investments as export producers under\nBook I of P.D. 1789, otherwise known as the Omnibus Investments Code or R.A. 6135, otherwise known as\nthe Exports Incentives Act, such enterprise shall enjoy the incentives enumerated hereunder:\n(a) Exemption from taxes and duties on imported spare parts. Within seven years from the date of registration,\nimportation of required spare parts and supplies shall be exempt from tariff duties and compensating tax\npayable thereon, Provided, however, that such spare parts and supplies are not locally available at reasonable\nprice, sufficient quantity and comparable quality.\n(b) Exemption from contractor's tax. Gross receipts of a registered firm in the semiconductor electronics\nindustry shall be exempt from the contractor's tax under the Internal Revenue Code.\n(c) Exemption from tax on accumulated profits or surplus. Registered enterprises in the semiconductor\nelectronics industry shall be exempt from the tax on accumulated profits or surplus as provided for in Sec. 25\nof the National Internal Revenue Code, as amended.\n(d) Deemed compliance with General Order 47. Registered enterprises in the semiconductor electronics\nindustry are deemed to have complied with General Order No. 47, requiring large companies to produce rice\nand corn for their employees, Provided, however, that such company shall, in addition to the specific\nin-company training for its personnel, share in the financing of industry-wide training of engineers and\ntechnicians for the semiconductor electronics industry to be organized by the Ministry of Trade and Industry.\n(e) Declaration as vital industry. Pursuant to Article 264(g) of the Labor Code (Batas Pambansa Blg. 130 as\namended by Batas Pambansa Blg. 227), the semiconductor electronics industry is hereby declared a vital\nindustry and any labor dispute therein causing or likely to cause strikes or lockouts will adversely affect the\nnational interest. In the event of such labor dispute in the industry, the Minister of Labor and Employment\nshall immediately assume jurisdiction over such dispute and decide it or certify the same to the National Labor\nRelations Commission for compulsory arbitration. Such assumption or certification shall have the effect of\nautomatically enjoining the intended or impending strike or lockout as specified in the assumption or\ncertification order. If one has already taken place at the time of assumption or certification, all striking or\nlocked out employees shall immediately return to work and the employers shall immediately resume\noperations and readmit all workers under the same terms and conditions prevailing before the strike or\n(f) Exemption from locational clearance. Any provision of law to the contrary notwithstanding, the enterprise\nshall be exempt from the locational clearance required by any government agency.\n(g) Customs clearance. The clearance for the importation of equipment, spare parts, raw materials and\nsupplies, and exports of processed products shall be expedited by the Bureau of Customs for semiconductor\ncompanies certified by the Board of Investments.\n(h) Unrestricted use of consigned equipment. Provisions of existing laws notwithstanding machinery,\nequipment and spare parts consigned to any registered firm engaged in the manufacture of semiconductor\ndevices shall not be subject to restrictions as to period of use of such machinery, equipment and spare parts\nprovided that the appropriate re-export bond is posted."}},{"id":"PH-H21089-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Incentives to enterprises registered with the Export Processing Zone. The Board of Investments may\nextend additional incentives herein provided to firms registered with the Export Processing Zones without\nneed of complying with the registration requirements of the Board of Investments."}},{"id":"PH-H21089-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Existing Firms. Existing firms embarking in higher technological processes such as automation or in\n\nforward and/or backward integration, shall qualify to register such projects as an expansion entitled to the new\nregistration with the Board of Investments."}},{"id":"PH-H21089-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Extension of Incentives. The Board may extend the period of availment of incentives by firms in the\nsemiconductor electronics industry if such is necessary to maintain the country's competitive position in\nattracting additional investments in the industry, Provided, however, that such extension shall not be for more\nthan twice the original period under the law."}},{"id":"PH-H21089-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Assistance by the Government Agencies. The Central Bank, Ministry of Labor and Employment,\nHuman Settlements Regulation Commission, National Food Authority, Bureau of Customs, Bureau of Internal\nRevenue, Ministry of Finance, Securities and Exchange Commission and other government offices concerned\nare directed to adopt respective rules and regulations which are applicable to the semiconductor electronics\nindustry to support the full and expeditious implementation of the policy and objectives herein declared."}},{"id":"PH-H21089-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Rules and Regulations. The Board of Investments is empowered to adopt rules and regulations for the\nimplementation of this Order."}},{"id":"PH-H21089-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Repealing Clause. Any provision of law, decrees, or executive orders, instructions, rules, regulations or\ncirculars inconsistent with this Executive Order is hereby repealed or modified accordingly."}},{"id":"PH-H21089-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of June, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21090"] = {"id":"PH-H21090","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE IMPLEMENTATION OF THE ENVIRONMENTAL AND ECONOMIC DEVELOPMENT PROGRAM WITHIN LAGUNA LAKE AS A PRESIDENTIAL PRIORITY","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE IMPLEMENTATION OF THE ENVIRONMENTAL AND ECONOMIC DEVELOPMENT PROGRAM WITHIN LAGUNA LAKE AS A PRESIDENTIAL PRIORITY"},"level":"law","status":"active","docNumber":"Executive Order No. 815","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00815_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00815_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21090-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Execution. The River Basin Control Office (RBCO) under\nthe Department of Environment and Natural Resources (DENR) shall be the lead\nagency in the implementation of the Program."}},{"id":"PH-H21090-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Implementation Arrangement. The RBCO shall be\nsupported by the Laguna Lake Development Authority (LLDA), an agency under\nthe DENR. All other departments, government agencies and entities concerned\nare hereby ordered to provide full cooperation for the timely and smooth\nexecution of the Program."}},{"id":"PH-H21090-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Program Components. The components of the Program\nshall include:\na. The rehabilitation of the Laguna Lake system, specifically the\nrehabilitation and dredging of Laquna Lake as well as lakeshore\nreclamation and surface management, improvement of water quality\nand managements systems, and management of resource use such as\nfor fish production, water supply and the like.\nb. The development of transport systems, which may include\ndevelopment of Laguna Lake ferry systems and Laguna Lake ports and\nmarinas development, which shall be in support of the Government's\nNautical Highways Program.\nc. Other related components that may be deemed important in the\nimplementation of the foregoing components.\nThe RBCO, in coordination with concerned government agencies, shall\nsubmit to the President the integrated plan within sixty (60) days after the\neffectivity of this order."}},{"id":"PH-H21090-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Budgetary Support. The RBCO shall have an initial\nfunding of Five Hundred Million Pesos (P 500,000,000.00) to be sourced from\nunprogrammed funds of the DENR, and/or as may be recommended and/or\napproved by the Department of Budget and Management (DBM). The initial\nfunds shall be used for the planning, operations and administration of RBCO to\ncarry out the implementation of the Program. Starting budgetary year 2010, its\noperating budget shall be incorporated in the budgetary allocation of the DENR\nand member-agencies."}},{"id":"PH-H21090-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Inter-Agency Cooperation. The departments, bureaus,\noffices, agencies or instrumentalities, including government-owned or controlled\ncorporations, are hereby directed to extend such assistance and cooperation as\nthe RBCO may need in the discharge of its functions.\n49484\n2\nPGMA Holagram # 49484"}},{"id":"PH-H21090-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Repeal. All executive orders, rules and regulations and\nother issuances or parts thereof, which are inconsistent with this Executive\nOrder, are hereby revoked, amended, or modified accordingly."}},{"id":"PH-H21090-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Effectivity. This Executive Order shall take effect fifteen\n(15) days after its complete publication in a national newspaper of general\ncirculation and fifteen (15) days after registration with the Office of the National\nAdministrative Register.\nDONE in the City of Manila, this the day of July\nof Our Lord, Two Thousand and Nine.\nglini A. Away\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOla Malouram * 49485\n3"}}],"pack":"ph-p159"};
  FT["PH-H21091"] = {"id":"PH-H21091","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for the Abolition of the Agricultural Credit Administration and Transferring Its Functions to the Land Bank of the Philippines","orig":"Providing for the Abolition of the Agricultural Credit Administration and Transferring Its Functions to the Land Bank of the Philippines"},"level":"law","status":"active","docNumber":"Executive Order No. 816","issuingBody":"President of the Philippines","promulgatedDate":"1982-07-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00816_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00816_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21091-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Agricultural Credit Administration, hereinafter referred to as the Administration, is hereby\nabolished. Its functions, together with its assets and liabilities, applicable appropriations, records, equipment,\nand property are hereby transferred to the Land Bank of the Philippines, hereinafter referred to as the Bank.\nThe valuation of the net assets of the Administration shall be determined by the Bank jointly with the Office\nof Budget and Management and the Commission on Audit."}},{"id":"PH-H21091-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"All valid existing contracts with public and private domestic and foreign parties entered into by the\nAdministration shall continue to be honored by the Bank."}},{"id":"PH-H21091-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Bank is hereby authorized to issue such orders, rules and regulations as may be necessary to\nimplement the provisions of this Executive Order, including those that will effect changes in the present\norganization of the Bank which it may deem necessary to absorb the functions of the Administration. The\nBank may appoint qualified personnel of the Administration to appropriate positions in the Bank, and those\nnot so appointed are deemed laid off. All those who are laid off under the provisions of this Executive Order\nshall be entitled to all benefits and gratuities provided for under existing laws."}},{"id":"PH-H21091-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Except as may otherwise be determined by the Bank, all present incumbents of positions in the\nAdministration shall continue to exercise their present functions, duties and responsibilities, pending the\nissuance of the appropriate implementing orders."}},{"id":"PH-H21091-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21091-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\n\nthe effect of nullifying the other provisions thereof: Provided, That such remaining portions can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21091-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 8th day of July, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21092"] = {"id":"PH-H21092","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE RIVER BASIN CONTROL OFFICE UNDER THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES AS THE LEAD GOVERNMENT AGENCY FOR THE INTEGRATED PLANNING, MANAGEMENT, REHABILITATION AND DEVELOPMENT OF THE COUNTRY'S RIVER BASINS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE RIVER BASIN CONTROL OFFICE UNDER THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES AS THE LEAD GOVERNMENT AGENCY FOR THE INTEGRATED PLANNING, MANAGEMENT, REHABILITATION AND DEVELOPMENT OF THE COUNTRY'S RIVER BASINS"},"level":"law","status":"active","docNumber":"Executive Order No. 816","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00816_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00816_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21092-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Declaration. The River Basin Control Office (RBCO) under\nthe Department of Environment and Natural Resources (DENR) is hereby\nmandated as the oversight agency for all government efforts and initiatives\nwithin the country's river basins."}},{"id":"PH-H21092-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Power and Functions of the RBCO. The RBCO, as lead\ngovernment agency, shall specifically execute the following powers and\na. Rationalize and integrate all national plans, projects and programs\nwithin the country's river catchment basins, with the authority to serve\nas the oversight office of all various government agencies and\ncorporations with relevant and related river basin initiatives, projects\nand programs such as, but not limited to, river basin infrastructure\ndevelopment, flood control, environmental protection and integrated\nwater resources management. To this end, such government agencies\nand corporations shall coordinate their planned and ongoing river basin\ninitiatives with the RBCO, to which the RBCO shall review and endorse\napproval and funding from the national budget thereof, as may be\nprovided under existing laws, rules and regulations;\nb. Harmonize all relevant national river basin policies and formulate new\npolicies and create enabling policy environment that shall allow\neffective and efficient management and governance of the of the\ncountry's river basins. To this end, all national government agencies\nand corporation shall consult with the RBCO in such planning and\nimplementation, and have the RBCO as ex-officio member in the policy\nsteering or project implementing boards as may be created therefor;\n49480\nPOMA Hologram * 49480\n2\n\n.\nc. Serve as the national policy coordination office for local government\nunits and non-governmental organizations in the development and\nsustainability of all river and catchment basins, for which the BCO\nshall recommend the approval and funding thereof of national\ngovernment agency and corporations' support to such local and non-\ngovernment river and catchment basin initiatives;\nd. Serve as the DENR's implementing office in the implementation,\nmonitoring and evaluation of DEN's programs and projects within the\ncountry's river basins;\ne. Serve as central fund administrator for river basins appropriation\nprovided under the DEN's budget that shall allow a more rationalized\nand optimized management of government public spending; and\nf. Serve as the government's central river basin database management\nagency, to which all government agencies and existing river basin\norganizations with relevant mandates and developmental initiatives\nwithin the river basins are required to cooperate and regularly submit\ntheir updated databases for integration and consolidation by RBCO\nusing a River Basin Integrated Information Management System."}},{"id":"PH-H21092-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Budgetary Support. The RBCO shall have an initial fund\nof Two Hundred Forty Million Pesos (P 240,000,000.00) to be sourced from\nunprogrammed funds of the DENR, and/or as may be recommended and/or\napproved by the Department of Budget and Management (DBM), for the\nplanning, operations and administration of RBCO including augmentation of\nmanpower capacity to carry out its mandated functions and powers. Said\namount shall be obtained from the remaining unreleased budgetary support for\nBCO pursuant to Executive Order No. 510 dated March 5, 2006, which created\nthe RBCO under the DENR. Starting budgetary year 2010, its operating budget\nshall be incorporated in the budgetary allocation of the DENR and member-"}},{"id":"PH-H21092-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Inter-Agency Cooperation. The departments, bureaus,\noffices, agencies or instrumentalities, including government-owned or controlled\ncorporations, are hereby directed to extend such assistance and cooperation as\nthe RBCO may need in the discharge of its functions."}},{"id":"PH-H21092-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Repeal. All executive orders, rules and regulations and\nother issuances or parts thereof, which are inconsistent with this Executive\nOrder, are hereby revoked, amended, or modified accordingly."}},{"id":"PH-H21092-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Effectivity. This Executive Order shall take effect fifteen\n(15) days after its complete publication in a national newspaper of general\ncirculation and fifteen (15) days after registration with the Office of the National\nAdministrative Register.\n49484\n3\nPOMA Hologram # 49481\n\nDONE in the City of Manila, this ct day of July\nof Our Lord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nGMA Hologra:\n4"}}],"pack":"ph-p159"};
  FT["PH-H21093"] = {"id":"PH-H21093","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for the Abolition of Certain Inactive Government Corporations","orig":"Providing for the Abolition of Certain Inactive Government Corporations"},"level":"law","status":"active","docNumber":"Executive Order No. 817","issuingBody":"President of the Philippines","promulgatedDate":"1982-07-08","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00817_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00817_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21093-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Abolished Corporations. The following government corporations are hereby abolished:\n(1) Catanduanes Development Authority\n(2) Ilocos Sur Development Authority\n(3) Mindoro Development Board\n(4) Northern Samar Development Authority\n(5) Panay Development Authority\n(6) Southeastern Samar Development Authority\n(7) Sulu Development Company\n(8) Philippine National Iron and Steel Corporation"}},{"id":"PH-H21093-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Abolition of the Bicol Development Company. Bicol Development created under Republic Act No.\n4690 is hereby abolished. Its assets, liabilities, records, equipment, and property shall be transferred to the\nNational Economic and Development Authority (NEDA). NEDA may appoint qualified personnel of Bicol\nDevelopment Company to appropriate positions in NEDA, and those not so appointed are deemed laid off. All\nthose laid off as a result of its abolition shall be entitled to all benefits and gratuities provided for under\nexisting laws."}},{"id":"PH-H21093-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Abolition of Coconut Investment Company. Coconut Investment Company created under Republic Act\n\nNo. 6260 is hereby abolished.\n(a) Its powers and functions are transferred in accordance with the following:\n(1) The Philippine Coconut Authority shall assume responsibility for the conduct of technical and economic\nresearch studies, promotional programs, scholarship grants, and industrial manpower development projects for\nthe coconut industry, as provided for under Subsection (d) of Section 5 of Republic Act No. 6260. The\nPhilippine Coconut Authority may make arrangements with other entities, public or private, for the effective\nimplementation of these functions.\n(2) The Development Bank of the Philippines shall assume responsibility for the lending and investment\nfunctions provided for under Subsections (a) and (b) of Section 5 of Republic Act No. 6260.\n(b) The Coconut Investment Fund collected pursuant to Republic Act No. 6260 amounting to over one\nhundred and fifty million pesos now deposited with the Development Bank of the Philippines shall be\ndistributed as follows:\n(1) Thirty per cent of the Fund shall be transferred to the Philippine Coconut Authority as a Trust Fund to\ncarry out the functions assigned to it.\n(2) Seventy per cent of the Fund shall be retained and managed by the Development Bank of the Philippines\nas a Trust Fund to carry out the functions assigned to it."}},{"id":"PH-H21093-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Repealing Clause. All laws, decrees, orders, proclamations, rules, regulations or parts thereof, which\nare inconsistent with any of the provisions of this Executive Order are hereby repealed or modified\naccordingly."}},{"id":"PH-H21093-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Separability Clause. Any portion of this Executive Order that may be declared unconstitutional shall\nnot have the effect of nullifying the other provisions thereof, provided that such remaining portions can still\nstand and be given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21093-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 8th day of July, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21094"] = {"id":"PH-H21094","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PROVIDING FOR THE GOVERNMENT'S INTENSIFIED CAMPAIGN AGAINST LOOSE FIREARMS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PROVIDING FOR THE GOVERNMENT'S INTENSIFIED CAMPAIGN AGAINST LOOSE FIREARMS"},"level":"law","status":"active","docNumber":"Executive Order No. 817","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00817_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00817_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21094-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The AFP, NBI, BOC, the Philippine Ports Authority, the\nPhilippine Drug Enforcement Agency as well as all other Law Enforcement\nAgencies are hereby mandated to conduct continuing and intensified law\nenforcement actions, independently or jointly with the PP, to confiscate and\nseize all loose firearms."}},{"id":"PH-H21094-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"A Final General Firearms Amnesty will be implemented for a\nperiod of one month, from October 1 to 31, 2009. All individual and judicial\nentities may renew their expired licenses and/or register their unregistered\nfirearms with the PNP."}},{"id":"PH-H21094-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"The PNP Chief shall issue such Implementing Rules and\nRegulations (IRR) to effectively carry out the intents of the Final General\nFirearms Amnesty, subject to the approval/concurrence of the Secretary of the\nInterior and Local Government."}},{"id":"PH-H21094-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"The National Law Enforcement Coordinating Committee\n(NALECC), in coordination with other concerned government agencies, shall\nreview existing firearms laws and regulations and propose necessary\namendments to institute an effective National Firearms Control Program."}},{"id":"PH-H21094-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"All orders, issuances, rules and regulations or parts thereof\ninconsistent with this Executive Order are hereby repealed or modified\naccordingly."}},{"id":"PH-H21094-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"This order shall take effect immediately.\nDONE in the City of Manila, this 7th day of July in the year of Our Lord,\nTwo Thousand and Nine.\nflirin is lump\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\n12"}}],"pack":"ph-p159"};
  FT["PH-H21095"] = {"id":"PH-H21095","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Amending Presidential Decree No. 1003-A, Creating the National Academy of Science and Technology and for Related Purposes","orig":"Amending Presidential Decree No. 1003-A, Creating the National Academy of Science and Technology and for Related Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 818","issuingBody":"President of the Philippines","promulgatedDate":"1982-07-16","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00818_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00818_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21095-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Section 1 of Presidential Decree No. 1003-A is hereby amended to read as follows:\n\"Sec. 1. There is hereby created the National Academy of Science and Technology, hereinafter referred to as\nthe Academy, which shall be composed of outstanding scientists to serve as reservoir of competent scientific\nand technological manpower for the country, the Academy shall be attached to the National Science and\nTechnology Authority (NSTA) for general coordination. The Academy shall have its own\nSecretariat/Administrative Staff.\""}},{"id":"PH-H21095-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The second paragraph of Section 9 of the same Decree is hereby amended to read as follows:\n\"Initially, each member of the Academy shall receive a gratuity of six thousand pesos (P6,000.00) per annum.\nThe Academy may determine stipends, incentives and/or recommend adjustment of gratuity to/or of its\nmember subject to the approval of the National Science and Technology Authority."}},{"id":"PH-H21095-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Academy may engage in projects or programs designed to recognize outstanding achievements in\nScience to promote scientific productivity."}},{"id":"PH-H21095-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"To carry out the purposes of this Executive Order, the Office of Budget and Management is hereby\nauthorized to provide such amounts as may be necessary from available or applicable funds of the\ngovernment."}},{"id":"PH-H21095-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"All other provisions of Presidential Decree No. 1003-A not otherwise affected by this Executive Order\nshall remain in force and all laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which\nare inconsistent with any of the provisions of this Executive Order are hereby repealed or amended\naccordingly."}},{"id":"PH-H21095-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof, provided that such remaining portions can still stand and\nbe given effect in their entirely to accomplish the objectives of this Executive Order."}},{"id":"PH-H21095-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 16th day of July, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21096"] = {"id":"PH-H21096","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE EXTENDING THE EFFECTIVITY OF THE ZERO RATE OF IMPORT DUTY ON MILLING WHEAT UNDER SECTION 104 OF PRESIDENTIAL DECREE NO. 1464, OTHERWISE KNOWN AS THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, AS PROVIDED FOR UNDER","orig":"MALACAÑAN PALACE EXTENDING THE EFFECTIVITY OF THE ZERO RATE OF IMPORT DUTY ON MILLING WHEAT UNDER SECTION 104 OF PRESIDENTIAL DECREE NO. 1464, OTHERWISE KNOWN AS THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, AS PROVIDED FOR UNDER"},"level":"law","status":"active","docNumber":"Executive Order No. 818","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00818_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00818_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21096-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"OF EXECUTIVE ORDER NO. 765, SERIES OF 2008\nWHEREAS, Executive Order 765, issued on 7 November 2008,\nreduced the duty on milling wheat and feed wheat from 3% and 7%,\nrespectively, to zero, for six months, subject to further review;\nWHEREAS, pursuant to Section 3 of E. O. 765, series of 2008, a review\nwas undertaken by the Tariff and Related Matters (TRM) Committee to\ndetermine if there is a need to extend the imposition of the MN rate of duty of\nzero on milling wheat and feed wheat;\nWHEREAS, extending the zero duty on milling wheat would help\nstabilize, if not bring down further, the prices of bread and other flour-based\nWHEREAS, the NEDA Board approved on 07 July 2009 the TRM\nrecommendation to extend the imposition of the MN rate of dut of zero on\nmilling wheat for six (6) months, subject to further review;\nWHEREAS, Section 401 of the Tariff and Customs Code of 1978\n(Presidential Decree No. 1464), as amended, empowers the President of the\nRepublic of the Philippines to increase, reduce, or remove existing rates of\nimport duty, as well as to modify the form of duty and the tariff nomenclature,\nunder Section 104 of the Code;\nNOW, THEREFORE, I, GLORIA MACAPAGAL-ARROYO, President\nof the Republic of the Philippines, by virtue of the powers vested in me by law,\ndo hereby order:\nSECTION 1. The articles specifically listed in Annex \"A\" hereof, as\nclassified under Section 104 of the Tariff and Customs Code of 1978, as\namended, shall be subject to the Most-Favored-Nation (MFN) rate of import\nduty in accordance with the schedule indicated opposite each article.\nSECTION 2. The nomenclature and the rates of import duty on tariff\nheadings not enumerated and those listed but represented by the symbol \" x\nPond radian » 49744 X\" Shall remain in force and in effect.\n\nSECTION 3. Upon the effectivity of this Executive Order, all articles\nlisted in Annex \"A\" except feed wheat (AHTN Heading No. 1001.90.99) which\nare entered and withdrawn from warehouses in the Philippines for\nconsumption shall be levied the MN rate of duty of zero ad valorem for six\n(6) months, subject to further review."}},{"id":"PH-H21096-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"All Presidential issuances, administrative rules and\nregulations, or parts thereof, which are contrary to or inconsistent with this\nExecutive Order are hereby revoked or modified accordingly."}},{"id":"PH-H21096-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Executive Order shall take effect immediately\nfollowing its complete publication in the Official Gazette or in a newspaper of\ngeneral circulation in the Philippines.\nDONE in the City of Manila, this tot day of July in the year of Our Lord,\nTwo Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram * 49745\n2\n\n10.01\n1001.10.00\n1001.90\n1001.90.11\n1001.90.19\n1001.90.91\n1001.90.99\nDESCRIPTION\nWheat and meslin.\n- Durum wheat\n- - Fit for human consumption:\n3"}}],"pack":"ph-p159"};
  FT["PH-H21097"] = {"id":"PH-H21097","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Position of Presidential Regional Monitoring Officer in Every Region","orig":"Creating the Position of Presidential Regional Monitoring Officer in Every Region"},"level":"law","status":"active","docNumber":"Executive Order No. 819","issuingBody":"President of the Philippines","promulgatedDate":"1982-07-24","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00819_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00819_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21097-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The creation of the position of Presidential Monitoring Officer (PREMO) in every region except in\nRegions IX and XII where there exist the Lupong Tagapagpaganap ng Pook (LTP) Presidential Management\nStaff (Office of the President) Monitoring Units."}},{"id":"PH-H21097-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The funds, records, equipment, vehicles and all other properties of the Presidential Regional Officer\nfor Development (PROD) are hereby transferred to the PREMO. The PROD funds for Regions IX and XII are\nhereby transferred to the LTP-PMS Monitoring Task Force in Regions IX and the LTP-PMS Monitoring Unit\nin Region XII. The funds for the PREMO and the LTP-PMS Monitoring Units shall be released through the"}},{"id":"PH-H21097-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The PREMO, to be appointed by the President, and the Head of the LTP-PMS Monitoring Units in\nRegions IX and XII shall serve as monitoring and action officers of the Office of the President in the regions\nand are hereby placed under the overall supervision of the Presidential Executive Assistant (PEA). They shall\nreport to the Office of the President through the PMS."}},{"id":"PH-H21097-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The Chairman of the LTP shall automatically be the Head of the LTP-PMS Monitoring Units in\nRegions IX and XII."}},{"id":"PH-H21097-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The PREMO/Head of LTP-PMS Monitoring Units shall be assisted by Deputy PREMO/Deputy Heads\n(one for Region IX and one for Region XII) who shall be designated by the President from among the regional\nexecutives."}},{"id":"PH-H21097-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The PREMO/Head of LTP-PMS Monitoring Units shall regularly provide the President, through the\nPMS, comprehensive reports on the major problems/issues and the status of government programs and\nprojects in the regions."}},{"id":"PH-H21097-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"To ascertain the status of programs and projects, and to identify problem areas/bottlenecks, the\nPREMO/Head of LTP-PMS Monitoring Units shall regularly conduct project-inspection and initiate meetings\nwith the regional/provincial/local officials and target beneficiaries of government projects/programs.\nIf there are problems/issues in the regions which could not be solved at the regional level and which require\nPresidential intervention, the PREMO/Head of LTP-PMS Monitoring Units shall, in all cases, submit to the\nOffice of the President, through the PMS, his recommendations for corrective action. He shall be tasked to\ninstitute measures to solve the problems so identified."}},{"id":"PH-H21097-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"The PREMO/Head of LTP-PMS Monitoring Units is authorized to call on all government offices to\nprovide him necessary assistance in carrying-out his functions."}},{"id":"PH-H21097-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"The PMS is hereby directed to establish the operational system within which the PREMO can\neffectively exercise his functions and responsibilities. Mobility, rapid response, field orientation, speedy\ndecision-making, and effective Presidential control shall be the guiding features of the desired system.\nTowards this end, the PMS shall undertake the following:\n1. design the organizational set-up and the operational frame-work of the PREMO; and\n2. design the PREMO operations manual that shall prescribe, among other things, be standard operating\nprocedures and the reporting system to be followed."}},{"id":"PH-H21097-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Repealing Clause. All provisions of existing laws, proclamations, orders, decrees, instructions, rules\nand regulations or parts thereof contrary to or in conflict with the provisions of this order are hereby modified\nor repealed accordingly.\nThis order shall take effect immediately.\nDone in the City of Manila, this 24th day of July in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21098"] = {"id":"PH-H21098","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EXTENDING THE EFFECTIVITY OF THE ZERO RATE OF IMPORT DUTIES ON CEMENT AND CEMENT CLINKER UNDER SECTION 104 OF AND CUSTOMS CODE OF 1978, AS AMENDED, AS PROVIDED FOR UNDER","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EXTENDING THE EFFECTIVITY OF THE ZERO RATE OF IMPORT DUTIES ON CEMENT AND CEMENT CLINKER UNDER SECTION 104 OF AND CUSTOMS CODE OF 1978, AS AMENDED, AS PROVIDED FOR UNDER"},"level":"law","status":"active","docNumber":"Executive Order No. 819","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00819_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00819_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21098-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"OF EXECUTIVE ORDER NO. 766, SERIES OF 2008\nWHEREAS, Executive Order No. 766, issued on 7 November 2008,\nreduced the duty on cement and cement clinker from 5% to zero for six (6)\nmonths, subject to further review;\nWHEREAS, pursuant to Section 3 of E.O. 766, series of 2008, a review\nwas undertaken by the Tariff and Related Matters (TRM) Committee to determine\nif there is a need to extend the imposition of the MN rate of duty of zero on\ncement and cement clinker;\nWHEREAS, the NEDA Board approved on 07 July 2009 the TRM\nrecommendation to extend the imposition of the MN rate of duty of zero on\ncement and cement clinker for six months, subject to further review;\nWHEREAS, Section 401 of the Tariff and Customs Code of 1978\n(Presidential Decree No. 1464), as amended, empowers the President of the\nRepublic of the Philippines to increase, reduce, or remove existing rates of import\nduty, as well as to modify the form of duty and the tariff nomenclature, under"}},{"id":"PH-H21098-A104","no":104,"noLabel":{"en":"Section 104"},"text":{"en":"of the Code;\nNOW, THEREFORE, I, GLORIA MACAPAGAL-ARROYO, President of\nthe Republic of the Philippines, by virtue of the powers vested in me by law, do\nhereby order:\nSECTION 1. The articles specifically listed in Annex \"A\" hereof, as\nclassified under Section 104 of the Tariff and Customs Code of 1978, as\namended, shall be subject to the Most-Favored-Nation (MFN) rate of import duty\nin accordance with the schedule indicated opposite each article.\nSECTION 2. The nomenclature and the rates of import duty on tariff\nheadings not enumerated and those listed but represented by the symbol \"xXx\"\nshall remain in force and in effect.\nSECTION 3. Upon the effectivity of this Executive Order, all articles listed\nin Annex \"A\" which are entered and withdrawn from warehouses in the\nPOMA Holouram # 49746\n\nPhilippines for consumption shall be levied the MN rate of duty of zero ad\nvalorem for six (6) months, subject to further review.\nSECTION 4. All Presidential issuances, administrative rules and\nregulations, or parts thereof, which are contrary to or inconsistent with this\nExecutive Order are hereby revoked or modified accordingly.\nSECTION 5. This Executive Order shall take effect immediately following\nits complete publication in the Official Gazette or in a newspaper of general\ncirculation in the Philippines.\nDONE in the City of Manila, this (oth day of July in the year of Our Lord,\nTwo Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram # 49747\n2\n\n25.23\n2523.10\n2523.10.10\n2523.10.90\n2523.21.00\n2523.29\n2523.29.10\n2523.29.90\n2523.30.00\n2523.90.00\nDESCRIPTION\nPortland cement, aluminous cement, slag\ncement, supersulphate cement and similar\nhydraulic cements, whether or not coloured or\nin the form of clinkers\n- Cement clinkers\n- Portland cement\n- Other hydraulic cements\n0\n0\n0\n3"}}],"pack":"ph-p159"};
  FT["PH-H21099"] = {"id":"PH-H21099","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a National Committee to Initiate and Conduct the First National Seminar-Workshop on Monitoring and Evaluation for Effective Program and Project Implementation","orig":"Creating a National Committee to Initiate and Conduct the First National Seminar-Workshop on Monitoring and Evaluation for Effective Program and Project Implementation"},"level":"law","status":"active","docNumber":"Executive Order No. 820","issuingBody":"President of the Philippines","promulgatedDate":"1982-07-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00820_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00820_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21099-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 820 July 24, 1982\nCREATING A NATIONAL COMMITTEE TO INITIATE AND CONDUCT THE FIRST NATIONAL\nSEMINAR-WORKSHOP ON MONITORING AND EVALUATION FOR EFFECTIVE PROGRAM AND\nPROJECT IMPLEMENTATION\nPursuant to the powers vested in me by law, I FERDINAND E. MARCOS, President of the Republic of the\nPhilippines, do hereby create a national committee to initiate and conduct the First National\nSeminar-Workshop on Monitoring and Evaluation for effective program and project implementation, in\nThe Committee shall be composed of the following:\nThe Presidential Executive Assistant, Office of the President\nThe Executive Director, Presidential Management Staff\nVice-Chairman\nThe Secretary-General, Office of the Prime Minister\nThe Minister, National Economic & Development Authority\nThe Minister, Office of the Budget and Management\nThe Acting Chairman, Commission on Audit\nThe Chairman, Presidential Committee on Reorganization\nThe Committee shall consolidate and harmonize the observations and recommendations of line agencies and\ndetermine ways to upgrade their monitoring capabilities.\nThe Committee shall oversee the efficient administration of the seminar-workshop and ensure the active\nparticipation of concerned ministries/agencies.\nThe Committee shall submit a report on the results of the seminar-workshop together with its findings and\nrecommendations.\nThe Committee shall meet at the call of the Chairman and for the purpose of discharging its function, may\ncreate sub-committees as may be necessary.\nFor technical and secretarial staff, the National Committee shall utilize the Presidential Program\nImplementation Center (PPIMC) of the Presidential Management Staff (PMS).\nThe Committee is hereby authorized to call upon any ministry, bureau, office, agency or instrumentality of the\ngovernment, including government-owned or controlled corporation, for such circumstances as it may need in\nthe discharge of its duties and functions.\nDone in the City of Manila, this 24th day of July in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21100"] = {"id":"PH-H21100","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Markets Infrastructure Development Council Vesting the Same With Powers and Functions, Providing Appropriations Therefor and for Other","orig":"Creating the Markets Infrastructure Development Council Vesting the Same With Powers and Functions, Providing Appropriations Therefor and for Other"},"level":"law","status":"active","docNumber":"Executive Order No. 821","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-03","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00821_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00821_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21100-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of Markets Infrastructure Development Council. There is hereby created a Markets\nInfrastructure Development Council, hereinafter referred to as the \"COUNCIL\" composed of the following:\nHon. Imelda Romualdez Marcos, Minister of Human Settlements\nHon. Jose A. Rono, Minister of Local Government\nHon. Teodoro Pena, Minister of Natural Resources\nHon. Jesus Tanchangco, Administrator-National Food Authority\nHon. Aber Canlas, Deputy Minister-Ministry of Public Works and Highways\nHon. Jose Condrado Benitez, Deputy Minister- Ministry of Human Settlements\nHon. Salvador Escudero, Director Bureau of Animal Industry\nRepresentative from the Private Sector\n\nThe Council shall be attached to the Ministry of Human Settlements (MHS).\nThe membership of the Council may be increased or ordered upon a decision of the majority of the members.\nThe members of the Council shall receive a reasonable amount of per diem as the Council may provide for\nevery meeting actually attended by them."}},{"id":"PH-H21100-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Allocation of responsibilities. The following delineation of areas of responsibility shall be observed by\nthe Council:\n1. MHS shall, in general, have the primary responsibility of coordinating the participation of the member\nagencies involved in the programs and projects of the Council. Specifically, the MHS shall: (a) design,\nformulate, implement and administer a Markets Infrastructure Development Program, consistent with national\ndevelopment goals and strategies; (b) promote or cause the improvement of market support enterprise\nfacilities and operations through construction or upgrading, including the provisions of financial assistance\ntogether with government and private institutions, by itself or in conjunction with other person, association,\ncorporation or entity, whether government or private; and (c) develop standardized prototype designs for\nmarkets support enterprises. The MHS through the National Housing Corporation, shall produce and make\navailable such standardized pre-fabricated construction materials necessary for the construction activities;\n2. The Ministry of Local Government, through the provincial governors, municipal and city mayors, shall\nprovide, mobilize and coordinate all assistance and resources from various government agencies and the\nprivate sector at the regional, provincial, city and municipal levels as may be deemed necessary by the\n3. The National Food Authority shall, in coordination with the private sector, provide the necessary support\nand assistance for the efficient movement of commodities, particularly the supply, distribution or trading of\nKKK products and services, utilizing infrastructure facilities and operations;\n4. The Bureau of Animal Industry shall, in coordination with the private sector, provide support and assistance\nin the formulation and implementation of a livestock marketing plan;\n5. The Ministry of Natural Resources (MNR) shall, in coordination with the private sector, extended such\nsupport and assistance in the area of fish marketing, utilizing for the purpose the manpower, resources and\nexpertise of existing fisheries offices or agencies under the MNR's jurisdiction;\n6. The Ministry of Public Works and Highways shall assist in, coordinate and monitor the construction of,\ninfrastructure in identified project areas."}},{"id":"PH-H21100-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Powers and Functions. The Council shall exercise the following powers and functions:\n1. Coordinate and rationalize all planning and programming of government activities related to markets\nsupport infrastructure development;\n2. Review, evaluate and approve projects proposals for the construction of markets support enterprises and/or\ntheir upgrading against design, economic and financial feasibility criteria for endorsement to funding\n3. Supervise the operation of all public markets and for this purpose establish policies and guidelines on\nstandards of operation of public markets and its support enterprises;\n4. Determine and mobilize the organizational requirements for planning and operation of the MIDP at the\nregional, provincial and municipal levels for markets infrastructure construction and upgrading, trading,\ncommodity flow and price monitoring;\n5. Encourage, conduct and/or promote studies and researches by itself or in conjunction with other\ngovernment or private agencies on any aspect of markets infrastructure development;\n6. Enter into contracts and arrangements and perform all acts and things necessary, for the accomplishment of\n\nthe abovementioned purposes;\n7. Submit regular reports to the President on the status and progress of programs, projects and activities\npursued by the Council;\n8. Perform such other functions or activities as may be necessary to accomplish its purposes and/or objectives."}},{"id":"PH-H21100-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Executive Committee. There shall be an Executive Committee, composed of the Minister of Human\nSettlements and two (2) members designated from the Council membership, which shall manage and\nadminister the affairs, functions and activities of the Council."}},{"id":"PH-H21100-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Secretariat. The Executive Committee shall be assisted by a Secretariat under the supervision of the\nMinistry of Human Settlements composed of such personnel as maybe detailed or appointed to the Secretariat\nunder conditions and rates that may be imposed by the Council, to provide all staff and support services as\nmay be necessary in the accomplishment of the Council's purposes.\nThe Secretariat shall be headed by an Executive Director to be appointed by the Executive Committee."}},{"id":"PH-H21100-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Financial Requirements. A program cost of P2.0 Billion is hereby appropriated in the Approved\nGeneral Appropriations Act and authorized to be released chargeable against funds in the National Budget not\notherwise appropriated. The Council shall submit to the President its annual programming of funds for\napproval. For CY 1982, the Ministry of Budget shall program and release to the Ministry of Human\nSettlements from the Capital Investment Program of MPWH the amount of P100 Million.\nThe Ministry of Human Settlements shall provide the funds for the organization and operations of the\nSecretariat; in addition, the Secretariat is tasked to prepare the details and properties of the utilization of the\nabove capital investment fund for the Council's consideration."}},{"id":"PH-H21100-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Support and Assistance. In the performance of its function, the Council or its Secretariat is hereby\nauthorized to call upon any government agency, office and instrumentality for such assistance as it may deem\nnecessary for the effective discharge of its function and responsibilities."}},{"id":"PH-H21100-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Repealing Clause. All laws, executive orders, administrative orders, rules and regulations, or parts\nthereof, which are inconsistent with any provision of this Order are hereby repealed, amended or modified\naccordingly."}},{"id":"PH-H21100-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDone in the City of Manila, this 3rd day of August, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21101"] = {"id":"PH-H21101","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG PRESCRIBING THE MAXIMUM DRUG RETAIL PRICES FOR SELECTED DRUGS AND MEDICINES THAT ADDRESS DISEASES THAT ACCOUNT FOR THE LEADING CAUSES OF MORBIDITY AND MORTALITY","orig":"MALACANANG PRESCRIBING THE MAXIMUM DRUG RETAIL PRICES FOR SELECTED DRUGS AND MEDICINES THAT ADDRESS DISEASES THAT ACCOUNT FOR THE LEADING CAUSES OF MORBIDITY AND MORTALITY"},"level":"law","status":"active","docNumber":"Executive Order No. 821","issuingBody":"President of the Philippines","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00821_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00821_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21101-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"List of Medicines and Corresponding Maximum Drug Retail Price\nINGREDIENT/\nDOSAGE STRENGTH AND FORM\nANTI-HYPERTENSIVE\n1. Amlodipine\n(including its S-isomer\nand all salt form)\n9.60\nANTI-CHOLESTEROL\n| 2. Atorvastatin\n10 mg film-coated tablet\n20 mg film-coated tablet\n40 mg film-coated tablet\n80 mg film-coated tablet\nAmlodipine besilate 5 mg + Atorvastatin\ncalcium 10 mq tablet\nAmlodipine besilate 5 mg + Atorvastatin\ncalcium 20 mg tablet\nAmlodipine besilate 5 mg + Atorvastatin\ncalcium 40 mg tablet\nAmlodipine besilate 5 mg + Atorvastatin\ncalcium 80 mg tablet\nAmlodipine besilate 10 mg + Atorvastatin\ncalcium 10 mg tablet\nAmlodipine besilate 10 mg + Atorvastatin\ncalcium 20 mg tablet\nAmlodipine besilate 10 mg + Atorvastatin\ncalcium 40 mg tablet\nAmlodipine besilate 10 mg + Atorvastatin\ncalcium 80 mg tablet\nANTIBIOTIC/ ANTIBACTERIAL\n3. Azithromycin and all\nits Salt form\n22.85\n38.50\n34.45\n39.13\n50.50\n50.63\n45.75\n66.25\n84.42\n89.99\n51.13\n73.25\n91.79\n91.79\n108.50\n2\n\n200 mg/5 mL powder for suspension (15\n427.50\n4. Cytarabine\n200 mg/5 mL powder for suspension (22.50\n500 mg vial for injection\nANTI-NEOPLASTICS/ ANTI-CANCER\n100 mg/ mL ampul/vial (IV/SC)\n100 mg/ mL ampul/vial (IV/SC) (5mL) or\n100 mg/ mL ampul/vial (IV/SC) (10mL) or\n20 mg/mL (5mL) ampul/vial for injection\n10 mg powder vial for iniection\n638.00\n151.43\n992.50\n468.00\n240.00\n900.00\n1800.00\n1980.00\n1465.75\n5. Doxorubicin and all\nits Salt form\n50 mg powder vial for injection\n2265.74"}},{"id":"PH-H21101-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"APPLICABILITY.\na. This Order shall apply to all medicines covered under Section 1 which are\ncurrently BFAD-registered and are available in the market.\nb. The MDRP of all drugs and medicines stated herein shall be imposed in all\nretail outlets, public or private, including drugstores, hospitals and hospital\npharmacies, health maintenance organizations (HMOs), convenience stores and\nsupermarkets and the like.\nPrice differentials as an effect of this Order shall be shouldered by\nthe corresponding manufacturer/trader/importer.\nNo public or private entity or person shall be allowed to sell,\nreimburse, or demand from the public or patients payment or\ncompensation higher than the MDRP.\nc. This Order shall also apply to government agencies, offices and\ninstrumentalities procuring, acquiring and reimbursing drugs and medicines\ncovered in Section 1 hereof.\nc.1. The prescribed MDRP shall serve as the ceiling for the procurement\nof the herein enumerated list of drugs by the national agencies, local\ngovernment units, and all other government entities including but not\nlimited to the Philippine Charity Sweepstakes Office (PCSO) and the\nPhilippine Amusement and Gaming Corporation (PAGCOR).\nc.2. The prescribed MDRP shall serve as the ceiling for the procurement\nof the said enumerated list of drugs by government hospitals including\nthe Philippine General Hospital, hospitals managed by the Department of\nHealth including specialty centers, hospitals under the auspices of the\n3\n50053\nPOMA Hologram * 50003\n\nDepartment of National Defense and the Philippine National Police,\ngovernment-owned and controlled hospital corporations, local\ngovernment hospitals, and all other types of government hospitals.\nc.3. The prescribed MDRP shall serve as the ceiling for the retail price of\nthe said enumerated list of drugs of all drug consignment arrangements\nentered into by government hospitals including government-owned and\ncontrolled hospital corporations and local government units, and all other\ngovernment entities.\nc.4. The prescribed MDRP shall serve as the ceiling for the\nreimbursement of the said enumerated list of drugs by the Philippine\nHealth Insurance Corporation, the Social Security System and the\nGovernment Services Insurance System and all government entities\nreimbursing drugs and medicines including the PCSO."}},{"id":"PH-H21101-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"IMPLEMENTATION.\na. The Department of Health is hereby ordered to put in place all the necessary\npolicies and systems to fully implement this Order.\nb. The Bureau of Food and Drugs (BAD) shall immediately act upon any\napplication for registration of drugs and medicines listed above within fifteen\n(15) days upon its filing; thereafter, the approval or disapproval of the Certificate\nof Product Registration should be released within ninety (90) days.\nc. All government-owned and controlled television and radio stations are hereby\nordered to provide all necessary support to DOH in disseminating the list of\ndrugs, their MDRPs, and such other information as required.\nd. All other agencies of government, national and local, including Government-\nOwned Controlled Corporations (GOCCs) and Government Funding Institutions\n(GFIs) are hereby ordered to provide all necessary support to DOH for the\nenforcement and implementation of, including the dissemination of information,\nas well as monitoring compliance with this Order."}},{"id":"PH-H21101-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"VIOLATIONS AND CIRCUMVENTION OF THE MDRP. Any actions\nconstrued as circumventing or violating the intent of this Order shall be dealt\nwith accordingly."}},{"id":"PH-H21101-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"REVIEW. The list of medicines and their corresponding MDRPs shall be\nsubiect for review after three (3) to six (6) months by the DOH and as may be\nrecommended thereafter upon the effectivity of this Order or as often as\nnecessary as determined by the Secretary of Health."}},{"id":"PH-H21101-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"TRANSITION. The period from the issuance of this Order up to August 15,\n2009 shall constitute the transition period in which appropriate packaging,\nlabeling, and disposition of existing inventory should be accomplished.\nPGMA Hologram # 50054\n\nThereafter, regardless of extent of existing inventory and compliance with\npackaging and labeling requirements, strict implementation of the MDRP and this\nOrder shall be enforced."}},{"id":"PH-H21101-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"REPEALING CLAUSE.\nAll executive issuances, orders, rules and\nregulations or parts thereof inconsistent with this Executive Order are hereby\nrevoked or modified accordingly."}},{"id":"PH-H21101-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"EFFECTIVITY. This Order shall immediately be published in at least two\n(2) newspapers of general circulation and shall take effect on August 15, 2009.\nDONE on this 27th day of July in the Year of Our Lord Two Thousand and\nBy the President:\nMitre a bugs\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram k 50055\n5"}}],"pack":"ph-p159"};
  FT["PH-H21102"] = {"id":"PH-H21102","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Granting All the Uniformed Members of the Integrated National Police Quarters Allowance","orig":"Granting All the Uniformed Members of the Integrated National Police Quarters Allowance"},"level":"law","status":"active","docNumber":"Executive Order No. 822","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-08","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00822_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00822_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21102-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 822 August 8, 1982\nGRANTING ALL THE UNIFORMED MEMBERS OF THE INTEGRATED NATIONAL POLICE\nQUARTERS ALLOWANCE\nWHEREAS, Section 6 of Presidential Decree No. 855 dated December 22, 1975, authorizes the Director\nGeneral, Integrated National Police subject to approval of the Minister of National Defense, to prescribe\nreasonable allowances for the police and fire service personnel, such as, but not limited to subsistence, cost of\nliving and clothing allowances, in order to compensate for the difference in the cost of living in the different\nregions or areas of the country, and for the effective maintenance of a well-disciplined law enforcement force;\nWHEREAS, the present allowances prescribed and authorized to the uniformed members of the Integrated\nNational Police are no longer responsive to their needs due to economic recession and inflation;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution, do hereby order and direct.\n1. The grant of monthly quarters allowance to all uniformed members of the Integrated National Police at the\nrate prescribed opposite each grade as follows:\nRate Per Month\nPolice/Fire Brigadier General\nPolice/Fire Colonel\n240\nPolice/Fire Lt. Colonel\n210\nPolice/Fire Major\n180\nPolice/Fire Captain\n160\nPolice/Fire Lieutenant\n140\nPolice/Fire Sergeant\n100\nPolice/Fire Corporal\n90\nPatrolman/Fireman First Class\n80\nPatrolman/Fireman\n80\n2. Funds needed to implement this Order shall be drawn from salary savings of the Integrated National Police\nAppropriation for CY 1982. Any further augmentation shall come from the budgetary reserves of CY 1982\nGeneral Appropriation Act. Funds intended to carry out this Order for the succeeding years shall be\nincorporated in the annual appropriation of the INP.\n3. The rules and regulations needed to comply with this Order shall be formulated by the Ministry of National\n4. This Executive Order shall take effect on August 8, 1982.\nDone in the City of Manila, this 8th day of August, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21103"] = {"id":"PH-H21103","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE DEPUTY EXECUTIVE SECRETARY FOR FINANCE AND ADMINISTRATION OF THE OFFICE OF THE PRESIDENT TO SIT AS EX- OFFICIO MEMBER OF THE PAGCOR BOARD OF DIRECTORS","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE DEPUTY EXECUTIVE SECRETARY FOR FINANCE AND ADMINISTRATION OF THE OFFICE OF THE PRESIDENT TO SIT AS EX- OFFICIO MEMBER OF THE PAGCOR BOARD OF DIRECTORS"},"level":"law","status":"active","docNumber":"Executive Order No. 822","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00822_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00822_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21103-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The Deputy Executive Secretary for Finance and Administration,\nOffice of the President, shall sit as ex-officio member of the PAGCOR Board of Directors."}},{"id":"PH-H21103-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"All orders, rules and regulations and issuances or parts thereof which\nare inconsistent with this Order are hereby repealed, amended or modified accordingly."}},{"id":"PH-H21103-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"This Executive Order shall take effect immediatelv.\nDONE in the City of Manila, this 21st day of\nour Lord, two thousand and nine.\nin the vear of\nBy the President:\nEDÚARDO R. ÉRMITA\nExecutive Secretary\nPOMA Hologram * 50509"}}],"pack":"ph-p159"};
  FT["PH-H21104"] = {"id":"PH-H21104","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":11,"structureMode":"ARTICLE","title":{"zh":null,"en":"Further Amending Executive Order No. 537 Dated May 24, 1979 Creating the Garments and Textile Export Board, Abolishing the Embroidery and Apparel Control and Inspection Board, and for Other Purposes","orig":"Further Amending Executive Order No. 537 Dated May 24, 1979 Creating the Garments and Textile Export Board, Abolishing the Embroidery and Apparel Control and Inspection Board, and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 823","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-19","completenessNote":"全文，共 11 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00823_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00823_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21104-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Board Composition. The Garments and Textile Export Board created under Executive Order No. 537,\nas amended by Executive Order No. 720, hereinafter referred to as the GTEB, shall be composed of the\nfollowing: The Minister of Trade and Industry as Chairman, the Deputy Minister of Finance to be designated\nby the Minister of Finance as Vice-Chairman, the Deputy Minister of Trade and Industry to be designated by\nthe Minister of Trade and Industry, the Vice-Chairman of the Board of Investments and the Commissioner of\nthe Bureau of Customs, as members."}},{"id":"PH-H21104-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Powers and Functions of the GTEB. Section 3 of Executive Order No. 537 is hereby amended to read\n\"Section 3. Powers and Functions. The GTEB shall have the following powers and functions:\na. Negotiate, conclude and implement garments and textile agreements, whether bilateral or multilateral,\nbetween the Republic of the Philippines and other countries, and for this purpose approve quota allocations\nand export authorizations, issue export licenses and similar authorizatios;\nb. Issue licenses for the establishment and operation of all bonded garment manufacturing warehouses, and\nauthorize the importation of textile fabrics, accessories, chemicals, packages, brands, labels and other\nsupplies, whether on consignment or otherwise, without taxes and duties but under re-export bond provided\nthey are manufactured or processed, either directly or through subcontractors or other exporters into finished\ngoods for re-export; authorize the importation, without duties but under re-export bond, of machineries and\nequipment to be used in bonded manufacturing warehouses;\n\nc. Provide on a regular basis the necessary information and statistics relating to the administration of garments\nand textile export quotas and the flow of garments and textile exports, for monitoring purposes and in order to\nobtain maximum benefits from textile negotiations with other countries;\nd. Inspect and examine through its authorized personnel, books, records, shipments, importations or\ninventories of textile fabrics, accessories, chemicals and supplies, of all garments and textile exporters,\nincluding those in export processing zones, for the purpose of determining compliance with its rules and\nregulations;\ne. Maintain a data bank on statistics regarding world trade in garments and textiles for monitoring purposes\nand to obtain maximum benefits from bilateral and multilateral textile negotiations with other countries;\nf. Undertake the development and promotion of garments and textile exports to maximize the benefits derived\nfrom the implementation of garments and textile agreements and to hasten the diversification and expansion of\nexport markets;\ng. Fix and collect the following fees: for the issuance of licenses to operate bonded garment manufacturing\nwarehouses, a fee not exceeding five thousand pesos (P5,000.00); for the issuance of quota allocations and\nexport authorizations, a fee not exceeding fifty (P0.50) centavos per square yard equivalent of the quality\nallocated; and for the issuance of other licenses and related services, a fee not exceeding one fifth of one\npercent of the gross value of the goods to be imported or exported;\nh. In case of violations of its rules and regulations, cancel or suspend quota allocations, export authorizations\nand licenses for the operation of bonded garment manufacturing warehouses;\ni. Impose fines, in an amount not exceeding fifty (P0.50) centavos per square yard equivalent of the quantity\nunshipped in cases of unutilized allocation as defined by its rules and regulations, and not more than ten\npercent of the gross value of the goods to be exported in case of other violation of its rules and regulations;\nj. Promulgate and enforce rules and regulations to carry out its powers and functions, including rules in\nliquidation of bonded importations of textile fabrics, accessories and raw materials, provided that bonded\nimportations shall be re-exported within a period of twelve months from date of importation, subject to such\nmodifications and extentions as the GTEB may authorize but in no case shall the total period exceed thirty\nmonths, and provided further that the bond to be filed by the importer shall not be less than one hundred\npercent nor more than two hundred percent of the amount of taxes, duties and other charges due thereon."}},{"id":"PH-H21104-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Audit and Inspection Unit. To enforce its rules and regulations, the GTEB is hereby authorized to\ncreate its own audit and inspection unit. This unit shall be responsible for conducting regular audit and\ninspection of all phases of operations of garment and textile exportes. Upon recommendation of this unit, the\nGTEB may refer to the Ministry of Justice or to the proper fiscal's office the prosecution of those found\nviolating any law relating to the bonded importation of textile fabrics, accessories and related materials."}},{"id":"PH-H21104-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Abolition of Embroidery Board and Transfer of Certain Functions. The Embroidery and Apparel\nControl and Inspection Board created pursuant to Republic Act No. 3137 is hereby abolished and its functions\nand powers transferred to the GTEB except as otherwise provided herein. The functions of the Board of\nInvestments with respect to the regulation of raw material importations of registered enterprises engaged in\nthe manufacture of exportation of garments or textiles are hereby transferred to the GTEB."}},{"id":"PH-H21104-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Transfer of Appropriations, Properties and Records. The applicable appropriations, records and\nproperty of the Embroidery and Apparel Control and Inspection Board and the Board of Investments are\nhereby transferred to the GTEB; provided that applicable appropriations, records and property pertaining to\nwarehouse storekeeping of firms registered with the Embroidery and Apparel Control and Inspection Board\nshall be transferred to the Bureau of Customs."}},{"id":"PH-H21104-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Transfer of Personnel. Such personnel of the Embroidery and Apparel Control and Inspection Board as\nthe GTEB may deem necessary and as its Chairman may reappoint within sixty (60) days from the date of this\n\nExecutive Order are hereby transferred to the GTEB; provided that warehouse storekeepers of the Embroidery\nand Apparel Control and Inspection Board whom the Commissioner of Customs may reappoint within sixty\n(60) days from date of this Executive Order shall be transferred to the Bureau of Customs. All personnel not\nso transferred or reappointed are deemed terminated and shall be entitled to all benefits and gratuities\nprovided for under existing laws; provided that those personnel who are retirable shall be allowed to retire\nwith full benefits and gratuities under existing laws."}},{"id":"PH-H21104-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Critical Agency. The GTEB is hereby declared a critical government agency pursuant to P.D. No. 985.\nAll income from fees, fines, penalties, and other charges imposed by it are deemed corporate income for\npurposes of this Section, and such income shall be directly used by the GTEB to provide additional financial\nincentives to all its employees according to criteria to be determined by the GTEB. Such income may also be\ndirectly used by the GTEB to defray expenses of its negotiators in bilateral and multilateral textile\nnegotiations as well as to defray other expenses that the GTEB may authorize to be incurred."}},{"id":"PH-H21104-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Transition Phase. All present incumbents in the abolished Embroidery and Apparel Control and\nInspection Board shall continue to exercise their usual functions, duties and responsibilities pending issuance\nby the GTEB of the appropriate orders to implement this Executive Order which shall not be later than thirty\n(30) days from date hereof. Existing licensed bonded manufacturing warehouses engaged in the garments or\ntextile business shall continue to operate but shall register with the GTEB within three months from date of\nthis Executive Order under rules and regulations to be promulgated by the GTEB."}},{"id":"PH-H21104-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Repealing Clause. All laws, presidential issuances, administrative rules and regulations inconsistent\nwith this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21104-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Separability Clause. If any provisions of this Executive Order is declared invalid, such declaration\nshall not have the effect of nullifying the other provisions of this Executive Order; provided, that such\nremaining provisions can still be given effect in their entirety to accomplish the objectives of this Executive"}},{"id":"PH-H21104-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 19th day of August, in the year of Our Lord nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21105"] = {"id":"PH-H21105","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":12,"structureMode":"ARTICLE","title":{"zh":null,"en":"Directing Agencies of the Government to Provide Full Support for Key Process Improvement Projects (PIPS) in Order to Achieve Compact Status as Prescribed By the Millennium Challenge Corporation (Gloria Macapagal-Arroyo)","orig":"Directing Agencies of the Government to Provide Full Support for Key Process Improvement Projects (PIPS) in Order to Achieve Compact Status as Prescribed By the Millennium Challenge Corporation (Gloria Macapagal-Arroyo)"},"level":"law","status":"active","docNumber":"Executive Order No. 823","issuingBody":"President of the Philippines","promulgatedDate":"2009-07-28","completenessNote":"全文，共 12 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00823_2009_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00823_2009_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21105-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Adoption of Key Process Improvement Projects. The following key Process Improvement\nProjects (PIPs), together with their respective government partners, are hereby adopted as concrete roadmaps\ntowards compliance with eligibility requirements for compact status as prescribed by the MCC:\na. Integrated Logistics Infrastructure Masterplan for Mega Luzon (Region 3, NCR, Region 4A, accounting for\n50% of GDP) Towards World-Class Supply Chain Capability\nLead Partner: Chairman of the Subic-Clark Alliance for Development (SCAD)\nb. Development of LGU “Sparkplugs” to drive 7% p.a. economic growths in their localities via new business\nactivities and reduce dependence on IRA\nLead Partner: Secretary of the Department of the Interior and Local Government (DILG)\nPresident of League of Municipalities of the Philippines (LMP)\n\nPresident of Union of Local Authorities of the Philippines (ULAP)\nPresident of League of Provinces of the Philippines (LLP)\nc. Streamlined business permits and licensing system by 120 LGUs to be comparable to the mean of WBs\nDoing Business Report\nLead Partner: Chairman of the Civil Service Commission (CSC)\nSecretary of the DILG\nPresident of the Development Academy of the Philippines (DAP)\nChairman of the Commission on Information and Communications Technology (CICT)\nPresident of ULAP\nSecretary of the Department of Trade and Industry (DTI)\nd. Subject several key government agencies and half of the cabinet to the Balanced Scorecard Rating system\nLead Partner: Chairman of the Civil Service Commission (CSC)\nPresident of DAP\ne. Improve Transparency in the Budget Delivery Process\nLead Partner: Secretary of the Department of Budget and Management (DBM)\nChairman of the CICT\nf. Improved Import/Export of Goods to Reduce Port “Dwell Time” to 3 days\nLead Partner: Commissioner of the Bureau of Customs (BOC)\nChairman of the CICT\nDirector of the Bureau of Foods and Drugs (BFAD)\ng. For Citizen’s appeal lodged in Malacañang, install Process Monitoring System\nLead Partner: Director of the Presidential Action Center (PACE)\nChairman of the CICT\nh. Tracking of cases filed with the Office of the Ombudsman via IT Process\nLead Partner: Ombudsman, Office of the Ombudsman (OMB)\ni. Instituting a Robust Investors Assistance Process that covers BOI, PEZA, LGU application\nLead Partner: Chairperson of the Philippine Economic Zone Authority (PEZA)\nSecretary of the DTI\nChairman of the CICT"}},{"id":"PH-H21105-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Private Sector Partners. The Chairman of the private sector of the National Competitiveness\nCouncil shall name and coordinate with private sector partner for each."}},{"id":"PH-H21105-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Oversight Function of the Chairman of the MCA Task Force. The Executive Secretary as\nChairman of the Inter-Agency Task Force for the MCA, created by Executive Order No. 607 as amended,\nshall oversee the implementation of these projects. The heads of lead agencies are hereby directed to closely\ncoordinate with said task force."}},{"id":"PH-H21105-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Full Support for Key Process Improvement Projects. All concerned agencies in the Executive\nBranch are instructed to provide full support including budgetary requirements for the nine (9) PIPs to be\nundertaken jointly by the government and private groups/stakeholders."}},{"id":"PH-H21105-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Formulation of Plans and Implementation by Lead Agencies. The agencies of the government\nidentified as the government counterpart in the abovementioned PIPs shall endeavor to formulate and submit\nconcrete plans for their assigned projects by July 2009 in preparation for presentation to the MCC and take the\nlead in implementing their respective projects."}},{"id":"PH-H21105-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Participation of Constitutional Bodies and Local Government Units (LGUs) in PIPs. The Civil\nService Commission and the office of the Ombudsman are hereby requested to take the lead in PIPs where\nthey were proposed as government counterparts and to provide funding thereto based on their existing\nbudgets. Concerned local government units are urged to support and actively participate in PIPs that require\ntheir involvement and cooperation. The DILG is instructed to coordinate LGU participation."}},{"id":"PH-H21105-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Coordination with Private Sectors Partners. The heads of lead agencies are hereby instructed to\nclosely coordinate with the identified private sector counterparts and the Chairman for the Private Sector of\nthe National Competitiveness Council, in formulating and implementing these PIPs."}},{"id":"PH-H21105-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Allocation of Funds. The Office of the President (OP) and the DBM shall help in sourcing funds\nfor these projects, especially for expenditures that are not covered by the agency’s budgets."}},{"id":"PH-H21105-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Reportorial Requirements. All heads of concerned agencies are hereby directed to submit\nmonthly progress reports to the Executive Secretary as Chairman of the MCA Task Force and the\ncommunications group to be formed which shall be tasked to formulate the report to the MCC. The MCA\nTask Force shall further ensure that updates and other reports are provided to third party sources of\ninformation for MCC ratings."}},{"id":"PH-H21105-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Repealing Clause. All executive orders, rules and regulations inconsistent with any provision of\nthis Executive Order shall be deemed revoked, amended or modified accordingly."}},{"id":"PH-H21105-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Separability Clause. If any part of this Executive Order is deemed contrary to law, the same\nshall not invalidate the entire Executive Order and the remaining provisions hereof shall remain in full force"}},{"id":"PH-H21105-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDONE this 28th day of July 2009 in the City of Manila.\n(Sgd.) GLORIA MACAPAGAL-ARROYO\nBy the President:\n(Sgd.) EDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21106"] = {"id":"PH-H21106","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Adopting the Revised Rules and Regulations for Basque Pelota Games and for Other Purposes","orig":"Adopting the Revised Rules and Regulations for Basque Pelota Games and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 824","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-28","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00824_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00824_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21106-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 824 August 28, 1982\nADOPTING THE REVISED RULES AND REGULATIONS FOR BASQUE PELOTA GAMES AND FOR\nOTHER PURPOSES\nWHEREAS, Presidential Decree No. 810, as amended, mandates the operation and development of Basque\nPelota as a sport for the general public, a source of revenue for the government's socio-economic projects and\na game of amusement at par with international standards for tourism purposes; and provides inter alia, that the\nGames and Amusements Board \"shall enforce the laws, rules and regulations governing Basque Pelota as\nprovided in Commonwealth Act Numbered Four Hundred and Eighty Five, as amended,\";\nWHEREAS, the Special Study Committee on Jai-Alai (Presidential Memorandum dated 17 October 1981)\ncomposed of representatives from the Office of the President, Games and Amusements Board and Presidential\nCommission on Reorganization was created to \"recommend to the President such measures as may be\nnecessary to further improve the operations of Jai-Alai and to minimize its contribution to the country's sports\ndevelopment program\"; and in addition, was specifically directed to look into the following areas, namely; (i)\nresponsiveness of existing laws, rules and regulations, and the Games and Amusements Board's supervisory\nauthority over Basque Pelota, (ii) formulation of standards for the opening of branches for booking purposes\nwithin any place in the Philippines pursuant to Presidential Decree No. 1124, and (iii) modernization and\ndevelopment programs for Basque Pelota including its integration into the country's sports development\nWHEREAS, the aforesaid Special Committee has noted certain ambiguities in existing laws, rules and\nregulations on Basque Pelota which have abetted various charges of anomalies including game \"fixing\", and\noverlapping of functional responsibilities thereby putting the integrity of the games under a cloud of public\nsuspicion; and has consequently, recommended measures to eliminate the said ambiguities in the legal\nfoundation and institutional framework of Basque Pelota to ensure that the objectives of Presidential Decree\nNo. 810, as amended, are met in the most effective, efficient and economical manner;\nWHEREAS, there is a need to allow the opening of Basque Pelota branches for booking purposes pursuant to\nPresidential Decree No. 1121 subject to certain standards in order to provide an awareness of the availability\nof this low stake amusement game for the country's adult population as an alternative to or as a\ncounter-measure against rampant illegal gambling activities which have deprived the government of\nsubstantial revenues for its socio-economic projects;\nWHEREAS, the Philippine Jai-Alai and Amusement Corporation, the Grantee under Presidential Decree No.\n810, has undertaken various improvements in buildings and facilities including the installation of totalizators\nwith the recognition that pursuant to the provisions of Presidential Decree No. 809 \"the land and all\nimprovements including facilities thereon shall revert to the government of the Philippines without payment\",;\nand the Grantee in addition, has prepared a development program which would require sizeable additional\ninvestments to achieve the purposes of Presidential Decree No. 810, as amended; and\nWHEREAS, there is a need for the government to provide additional support and incentives for the\naccelerated development of Basque Pelota pursuant to the aforementioned decrees;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution and the authority vested in me by the Presidential Decree No. 1416, do\nhereby order the adoption of the attached Revised Rules and Regulations for Basque Pelota Games, any\nprovision of rules and regulations to the contrary notwithstanding.\nDONE in the City of Manila, this 28th day of August, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21107"] = {"id":"PH-H21107","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE NATIONAL DEVELOPMENT COMPANY (DC) TO ISSUE BONDS FOR INFRASTRUCTURE PROJECTS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE NATIONAL DEVELOPMENT COMPANY (DC) TO ISSUE BONDS FOR INFRASTRUCTURE PROJECTS"},"level":"law","status":"active","docNumber":"Executive Order No. 824","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00824_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00824_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21107-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"AUTHORIZING ND TO ISSUE BONDS FOR\nINFRASTRUCTURE PROJECTS - NDC is hereby authorized to issue bonds in\nthe total amount of up to PESOS: FIFTY BILLION (P50,000,000,000.00)\n(hereinafter referred to as \"NDC Infrastructure Bonds\").\n50175\nPONA Hologram # 50175\n\nThe proceeds of the NDC Infrastructure Bonds shall be used to fund, by\nway of loan or equity investment, the infrastructure projects identified in the\nMIPIP; Provided, that:\na. the previously approved implementation of these infrastructure\nprojects does not prohibit financing or equity investment by the\nGovernment;\nb. that the loan or equity is in accordance with the declaration of policy\nunder Section 2 of P.D. 1648, as amended and all other relevant laws\non financing of infrastructure projects;"}},{"id":"PH-H21107-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"FEATURES OF THE NDC INFRASTRUCTURE BONDS - The\nNDC Infrastructure Bonds shall be tax exempt and guaranteed by the Republic of\nthe Philippines.\nThe Monetary Board (MB), in close coordination with the Department of\nFinance (DOF) and NDC, shall promulgate such rules and regulations regarding\nthe eligibility features of the NDC Infrastructure Bonds."}},{"id":"PH-H21107-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"UTILIZATION OF THE PROCEEDS OF THE DEVELOPMENT\nBONDS - The National Economic and Development Authority (NEDA) and NDC\nare hereby directed to select which among the infrastructure projects in the\nMTPIP shall be funded from the proceeds of the NDC Infrastructure Bonds,\nsubject to the provisions of the second paragraph of Section 1 hereof.\nNDC shall issue the NDC Infrastructure Bonds based on the amount\nrequired for the funding of each and every project, and onty upon determination\nby NEDA and the appropriate implementing agency for such infrastructure\nproject that the project is already ready for implementation."}},{"id":"PH-H21107-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"RULES AND REGULATIONS - The DOF, the Department of\nBudget and Management (DBM) and NDC shall promulgate such rules and\nregulations and execute any and all documents necessary to ensure repayment\nto NDC of the funds it will lend to the selected infrastructure projects and the\neventual retirement of the bonds it will issue under this Executive Order."}},{"id":"PH-H21107-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"REPEALING CLAUSE - All executive issuances, rules and\nregulations or parts thereof which are inconsistent with this Executive Order are\nhereby revoked, amended, or modified accordingly."}},{"id":"PH-H21107-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"EFFECTIVITY - This Executive Order shall take effect\nimmediately.\n50176\nPGMA Hologram # 50176\n\nDONE in the City of Manila, this ith day of August\nLord, Two Thousand and Nine.\n, in the year of Our\nBy the President:\nfloric Me King\nEDUARDO R. ERMITA\nExecutive Secretary\n12\nPGA Holaran « 50177"}}],"pack":"ph-p159"};
  FT["PH-H21108"] = {"id":"PH-H21108","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Ordering and Authorizing the Organization of the Coconut Investment Company as a Private Corporation Under the Provisions of Republic Act Numbered Six Thousand Two Hundred Sixty (R.A. 6260)","orig":"Ordering and Authorizing the Organization of the Coconut Investment Company as a Private Corporation Under the Provisions of Republic Act Numbered Six Thousand Two Hundred Sixty (R.A. 6260)"},"level":"law","status":"active","docNumber":"Executive Order No. 825","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-28","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00825_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00825_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21108-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Philippine Coconut Authority (\"PCA\") is hereby ordered and authorized to immediately cause the\nincorporation and organization of the Coconut Investment Company (the \"Company\") as a private entity under\nBatas Pambansa Blg. 68 otherwise known as \"The Corporation Code of the Philippines\"."}},{"id":"PH-H21108-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The initial fully-paid stock of the Company shall be equal to the total collections of the COCOFUND\nincluding interest earned up to date of the Company's Incorporation as a private entity. All of the shares of\nstock of the Company shall be owned by the coconut farmers who have registered their COCOFUND receipts\nunder R.A. 6260. For purposes of incorporation of the Company as a private entity, the initial subscription to\nthe capital stock of the Company shall be placed in the name of such coconut farmers acting through PCA.\nAfter incorporation, the shares of stock shall be transferred to and in the name of such coconut farmers, in\naccordance with such rules, and regulations and procedures as the Company shall prescribe and promulgate."}},{"id":"PH-H21108-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Pending the distribution of the shares of stock to the coconut farmers who have registered their\nCOCOFUND receipts, the shares shall be voted by the Philippine Coconut Procedures Federation\n(\"COCOFED\"), being the recognized national association of coconut producers in accordance with the\nprovisions of R.A. 6260."}},{"id":"PH-H21108-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"In order to effect the incorporation of the Company as herein authorized, the trust funds distributed to\nPCA and the Development Bank of the Philippines under Section 3 (b) of Executive Order No. 817 and which\nconstitute the COCOFUND collections and earnings thereof, shall immediately be transferred to the account\nof the Company."}},{"id":"PH-H21108-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"All powers (except the power to levy), functions, privileges and rights vested on, together with all\n\noutstanding assets and liabilities of, the Coconut Investment Company created under R.A. 6260 and abolished\nby Executive Order No. 817 shall be transferred to the Company Incorporated as a private entity pursuant to\nSection 1 hereof."}},{"id":"PH-H21108-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Philippine Coconut Authority shall submit a report of its implementation of this Order not later\nthan thirty (30) days from the incorporation of the Company as a private entity."}},{"id":"PH-H21108-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 28th day of August, in the year of Our Lord, nineteen hundred eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21109"] = {"id":"PH-H21109","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Local Anti-Hunger Task Force (Gloria Macapagal-Arroyo)","orig":"Creating the Local Anti-Hunger Task Force (Gloria Macapagal-Arroyo)"},"level":"law","status":"active","docNumber":"Executive Order No. 825","issuingBody":"President of the Philippines","promulgatedDate":"2009-07-29","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00825_2009_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00825_2009_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21109-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Creation of Regional and Provincial Task Forces\n\nThe Regional/Provincial Anti-Hunger Task Force (R/PAHTF) shall be created in provinces covered by the\nAHMP to facilitate coordination, complementation and convergence of services and resources, and to widen\nthe reach of the program among the poor and hungry households in the identified priority areas of the country."}},{"id":"PH-H21109-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Composition\n2.1 Regional Level\nThe Task Force shall be under the umbrella of the regional nutrition committee (RNC) and shall be composed\nof the following:\n2.1.1 Department of Agriculture (DA)\n2.1.1.1 Philippine Coconut Authority (PCA)\n2.1.1.2 Bureau of Fisheries and Aquatic Resources (BFAR)\n2.1.1.3 National Food Authority (NFA)\n2.1.1.4 National Irrigation Administration (NIA)\n2.1.2 Department of Agrarian Reform (DAR)\n2.1.3 Department of Budget and Management (DBM)\n2.1.4 Department of Environment and Natural Resources (DENR)\n2.1.5 Department of Education (DepEd)\n2.1.6 Department of Health (DOH)\n2.1.6.1 National Nutritional Council\n2.1.6.2 Population Commission\n2.1.7 Department of the Interior and Local Government (DILG)\n2.1.7.1 Philippine National Police (PNP)\n2.1.8 Department of Labor and Employment (DOLE)\n2.1.8.1 Technical Skills and Development Authority (TESDA)\n2.1.9 Department of Public Works and Highways (DPWH)\n2.1.10 Department of Social Welfare and Development (DSWD)\n2.1.11 Department of Transportation and Communications (DOTC)\n2.1.11.1 Philippine Ports Authority and/or Port District Office (PPA-DOTC)\n2.1.11.2 Philippine Coast Guard\n2.1.12 Department of Trade and Industry (DTI)\n2.1.13 National Economic and Development Authority (NEDA)\n2.1.14 Armed Forces of the Philippines\n2.1.14.1 Philippine Navy\n2.1.14.2 Philippine Army\n2.1.15 Representative of the League of Provinces of the Philippines (LPP) Regional Executive Board\n2.1.16 Representative of the League of Cities of the Philippines Regional Executive Board\n2.1.17 Non-government organizations including faith-based organizations operating in the region\n2.1.18 Others, as may be decided on by the RNC\n2.2. Provincial level\n\nThe Task Force shall be under the umbrella of the provincial nutrition committee (PNC) and shall be\ncomposed of the following:\n2.2.1 Department/ offices of the provincial government\n2.2.1.1 Office of the Governor\n2.2.1.2 Provincial Planning and Development Office\n2.2.1.3 Provincial Nutrition Office/Unit or equivalent\n2.2.1.4 Provincial Health Office or equivalent\n2.2.1.5 Provincial Population Office or equivalent\n2.2.1.6 Provincial Budget Office\n2.2.1.7 Provincial Social Welfare and Development Office or equivalent\n2.2.1.8 Provincial Agriculture Office\n2.2.1.9 Provincial Veterinary Office\n2.2.1.10 Local office in charge of livelihood, if available\n2.2.2 Representative of the League of Municipalities of the Philippines Provincial Chapter\n2.2.3 Representative of the Federation of Liga ng mga Barangay\n2.2.4 National agencies with provincial offices\n2.2.5 Non-government organizations especially faith-based organizations operating in the province\n2.2.6 Others as may be decided on by the PNC"}},{"id":"PH-H21109-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Duties/Responsibilities of the Task Force\n1. Regional Level\n\na. The RAHTF shall:\n1 ) Coordinate with the national and provincial AHTF and oversee the implementation of the AHMP\n2 ) Ensure the convergence of services delivered by national government agencies and LGUs\n3 ) Monitor the implementation of the AHMP at the regional and provincial levels through:\na) Review of monthly progress reports on AHMP implementation\nb) Regular meetings for an update on program implementation and to discuss and resolve implementation\nc) Conduct of annual program implementation review to assess accomplishments and gaps\nd) Regular project site visits\ne) Provision of feedback horizontally (or to regional offices of national government agencies) and vertically\n(to the national and local levels)\n4 ) Recommend to the national task force policy and program adjustments to improve program efficiency\n5 ) Lead in advocacy for sustainable and region-wide support to the program\n6 ) Provide the public with regular updates on the AHMP\n7 ) Provide technical assistance to PAHTF on program management\n8 ) Coordinate with the Regional Kalahi Convergence Group to allow complementation of the AHMP with\nother poverty-alleviation efforts in the province and region\nb. The regional heads of the member-agencies of the RAHTF shall serve as the anti-hunger focal person of the\nagency. For the Autonomous Region in Muslim Mindanao (ARMM), the Department Secretary of the\naforementioned agencies could serve as the anti-hunger focal person.\nThe anti-hunger focal person of each agency shall:\n1 ) Ensure the smooth implementation of the agency’s hunger-mitigation component program\n2 ) Ensure timely disbursement of funds for the implementation of the agency’s AHMP component programs\nand facilitate the convergence of resources from among collaborating agencies for efficient service delivery\n3 ) Ensure the complementation of the agency’s hunger-mitigation component programs with the other\ncomponents of the AHMP as well as with related initiatives of LGUs\n4 ) Monitor the implementation of the agency’s hunger-mitigation component programs and report to the\nDepartment Secretary the progress of implementation, copy furnished the NNC-RO. For the ARMM,\nreporting could be to the Regional Governor of ARMM, preferably with a copy to counterpart Secretaries at\nthe national level.\n5 ) Conduct annual in-house program implementation reviews\n6 ) Advocate for sustained support for the AHMP component programs\n7 ) Provide the public with correct information on the agency’s hunger-mitigation component programs\n8 ) Provide other assistance as may be needed by the RAHTF\nc. The NNC Regional Office shall:\n1) Serve as the oversight agency for the implementation of the AHMP at the regional level\n2) Organize the RAHTF\n3) Monitor the implementation of program components of the AHMP\n4) Prepare monthly progress reports for submission to the RAHTF and NNC central office\n\n5) Maintain a data base on the AHMP and ensure its use by ‘ the R/PAHTF for program management;\nFor ARMM, the Regional Governor could designate the region’s oversight agency that will perform the\naforementioned functions to ensure that hunger-mitigation programs are in place and successfully\nimplemented:\n2. Provincial Level\na. The PAHTF shall:\n1) Formulate an annual AHMP provincial plan\n2) Coordinate and oversee the implementation of the provincial hunger mitigation plan\n3) Ensure the convergence of services delivered by national government agencies and LGUs\n4) Assist municipal and barangay governments in resource generation for hunger-mitigation programs and\n5) Monitor the implementation of the AHMP provincial plan through:\na) Preparation of monthly progress reports on AHMP Plan implementation for submission to the RAHTF\nthrough the NNC regional office, and for ARMM, to designated oversight agency\nb) Regular meetings to update implementation progress and to discuss and resolve implementation problems\nc) Conduct of annual program implementation review to assess accomplishments and gaps\nd) Regular project site visits\ne) Provision of feedback horizontally (to offices of the provincial government) and vertically (to the national,\nregional, municipal and barangay levels)\n6) Lead in advocacy for sustainable support to the program at the provincial level\n7) Provide the public with regular updates on the AHMP\nb. The governor is hereby encouraged to:\n1) Organize and chair the PAHTF\n2) Serve as anti-hunger champion and ensure that hunger mitigation programs are integrated in the annual\ninvestment plan of the province\n3) Lead and supervise the formulation and implementation of the provincial hunger mitigation plan, ensuring\na) AHMP component programs are implemented and reached out to areas and families needing more\nassistance\nb) AHMP component programs of the local government and the national government complement one another\nc) Implementation issues are identified and corrective actions continuously undertaken\nd) The community and target beneficiaries participate in program planning, implementation, and monitoring\ne) Poor and severely hungry families whose children are out-of-school be identified and given assistance\nf) Good and effective practices are documented and shared with other LGUs\ng) Good and effective practices of other LGUs are adapted and replicated\nc. The head of the provincial department or office implementing one or more of the AHMP component\nprograms is likewise encouraged:\n1 ) Ensure that hunger-mitigation programs are integrated in the annual investment plan of the respective\ndepartment or office\n\n2 ) Ensure the smooth implementation of the department’s or office’s hunger-mitigation component program\n3 ) Ensure timely disbursement of funds for the implementation of the department’s or office’s AHMP\ncomponent programs\n4 ) Ensure the complementation of the department’s or office’s hunger-mitigation component programs of the\nprovince, and national government agencies\n5 ) Monitor the implementation of the department’s or office’s hunger-mitigation component program and\nreport on the progress of implementation to the provincial governor through the designated local focal person\n6 ) Advocate for sustained support for the AHMP\n7 ) Provide the public with correct information on the province’s hunger-mitigation component programs\n8 ) Provide other assistance as may be needed by the PAHTF"}},{"id":"PH-H21109-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately after publication in a national\nnewspaper of general circulation.\nDONE in the City of Manila, this 29th day of July in the year of Our Lord, Two Thousand and Nine.\n(SGD.) GLORIA MACAPAGAL-ARROYO\nBy the President:\n(SGD.) EDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21110"] = {"id":"PH-H21110","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing Measures for the Protection of the Desiccated Coconut","orig":"Providing Measures for the Protection of the Desiccated Coconut"},"level":"law","status":"active","docNumber":"Executive Order No. 826","issuingBody":"President of the Philippines","promulgatedDate":"1982-08-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00826_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00826_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21110-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Prohibition. Except as herein provided, no government agency or instrumentality shall hereafter\nauthorize, approve or grant any permit or license for the establishment or operation of new desiccated coconut\nprocessing plants, including the importation of machinery or equipment for the purpose. In the event of a need\nto establish a new plant, or expand the capacity, relocate or upgrade the efficiencies of any existing desiccated\nplant, the Philippine Coconut Authority may, upon proper determination of such need and evaluation of the\ncondition relating to:\na. the existing market demand;\nb. the production capacity prevailing in the country or locality;\nc. the level and flow of raw materials; and\nd. other circumstances which may effect the growth or viability of the industry concerned,\nauthorize or grant the application for, the establishment or expansion of capacity, relocation or upgrading of\nefficiencies of such desiccated coconut processing plant, subject to the approval of the President."}},{"id":"PH-H21110-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Rules and Regulations. To give effect to the foregoing and in order to insure the growth and viability\nof the desiccated coconut and other allied industries, the Philippine Coconut Authority is hereby given full\npower and authority to regulate the marketing and exportation as well as to determine and impose limitations\non the production capacities of firms/entities engaged in the production of desiccated coconut and to issue\nsuch orders, rules and regulations as it may deem appropriate, including, but not limited to, the imposition of\nfloor and/or ceiling prices for all exports of aforementioned product; the prescription of quality standards;\nestablishment of maximum quantities for particular periods and particular markets; and inspection and survey\nof export shipments."}},{"id":"PH-H21110-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Additional Measures. The Authority, in consultation with associations of coconut desiccators utilizing\nfresh/matured coconuts as raw material shall study and recommend, for approval of the President, additional\nfeasible measures to further insure the growth and viability of the desiccated coconut and other allied\n\nindustries using fresh/matured coconuts as their raw material."}},{"id":"PH-H21110-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDone in the city of Manila, this 28th day of August, in the year of Our Lord nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21111"] = {"id":"PH-H21111","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DEFINING THE POWERS, FUNCTIONS, AND RESPONSIBILITIES OF GOVERNMENT AGENCIES IN RESPONSE TO EBOLA RESTON VIRUS INFECTION AND MATTERS RELATED THERETO","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DEFINING THE POWERS, FUNCTIONS, AND RESPONSIBILITIES OF GOVERNMENT AGENCIES IN RESPONSE TO EBOLA RESTON VIRUS INFECTION AND MATTERS RELATED THERETO"},"level":"law","status":"active","docNumber":"Executive Order No. 826","issuingBody":"President of the Philippines","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00826_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00826_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21111-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Crisis Managers - The Secretary of Agriculture and the\nSecretary of Health are hereby designated Over-All Crisis Managers for the Ebola\nReston virus infection in animals and humans, respertively.\nPSHA Hologran * 50417\n50417\n\nThe Department of Agriculture, through its Secretary, is hereby directed\nto act on matters pertaining to or primarily affecting livestock and poultry,\nincluding their products and by-products, as well as other types of animals."}},{"id":"PH-H21111-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Delineation of Powers and Authority - The Secretary of\nHealth is hereby granted and bestowed such powers and authority as would be\nnecessary in order to prevent, restrict, or otherwise regulate the entry,\nmovement, or surveillance of people coming from infected areas or in any place\nwhere the infection has been suspected or detected.\nThe Secretary of Agriculture is hereby granted and bestowed such powers\nand functions as would be necessary in order to contain, control, prevent,\nregulate and otherwise restrict the entry, movement, keeping, handling, or\nraising of livestock and poultry including their by-products and other types of\nanimals, which are infected, or suspected to be, infected or potential carrier of\nthe Ebola Reston virus."}},{"id":"PH-H21111-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Specific Areas of Concern and Responsibility -\nA. The Secretary of Health shall exercise such powers and prerogatives,\nincidental or otherwise, as would:\n(a) Prevent, minimize, regulate, or otherwise restrict the entry or exit of\nthe Ebola Reston virus, through the Bureau of Quarantine, by adopting,\nrestricting, or regulating the movement and entry of people coming from infected\nlocalities that are suspected to be carriers, or potential carriers of the virus,\nthrough a system of surveillance methods utilizing rigid screening and\nidentification procedures in all ports of entry, and adopting isolation and\nquarantine measures whenever deemed necessary;\n(b) Prevent, minimize and regulate the spread and local transmission of\nthe virus through enforcement of triage, contact tracing, surveillance, quarantine\nand isolation procedures of people, as may be appropriate; and\n(C) Care, render assistance, cure, or minimize sickness or possible death\nthrough effective clinical management of people, resources, hospitals, and other\nfacilities, whether public or private.\nThe Secretary of Health shall also exercise such other functions and\npowers as may be incidental, related or otherwise connected with the above\nmentioned authority.\n50418\nPOMA HOlogrAm # 50418\n\nB. The Secretary of Agriculture shall take such measures and actions as\na. Prevent, restrict, minimize or otherwise regulate the entry, movement,\nkeeping, handling or raising of livestock and poultry, including their products and\nby-products, and or other animals coming from. infected farms or localities or\nfrom any other place which are potential or suspected to be, afflicted or carriers\nof the Ebola Reston virus, including the imposition of total or partial bans on local\nshipment or export of such animals;\nb. May Condemn and slaughter pigs and other animals found to be\ninfected with Ebola Reston Virus;\nc. Conduct surveillance, mapping, identification, isolation, quarantine, or\neradication of pigs, their products and by-products, and other animals infected or\nsuspected to be infected by the Ebola Reston Virus within the country, or any\npart thereof, including the culling or stamping out of infected pigs coming from\nbackyard and commercial farms and other affected areas, as may be determined\nby the Secretary; and\nd. Monitor, trace, plot, or otherwise observe, in coordination with the\nDepartment of Environment and Natural Resources (DENR), the sanctuaries of\npossible reservoirs and their movement taking into consideration the safety and\nwell being of the people and giving due regard to nature.\nThe Secretary of Agriculture shall also exercise such other functions and\npowers as may be incidental, related or otherwise connected with the above\nmentioned authority."}},{"id":"PH-H21111-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Information Dissemination and Coordination - As\nCrisis Managers, the Secretary of Agriculture and the Secretary of Health shall\nhave the following responsibilities:\na. To continuously educate and disseminate information, as appropriate,\nin order to prepare and educate the media and the general public with a better\nunderstanding of the Ebola Reston virus, promote positive health values and\nbehavior, and prevent disinformation, confusion, or panic;\nb. To coordinate responses together with other government agencies and\nthe private sector through meetings, conferences and the like; or otherwise\nconstructively engage the public and affected sectors in general;\nc. To issue the necessary bulletins, advisories and health warnings on\nmatters concerning the foregoing.\n50418\nPOMA Hologran • 50419"}},{"id":"PH-H21111-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Assistance and Support; Close coordination with the\nNational Disaster Coordinating Council (NDCC) - The Over-All Crisis\nManagers are hereby empowered to call upon all agencies of Government for\nsupport and assistance in the enforcement of this Order, including but not\nnecessarily limited to the:\nDepartment of Interior and Local Government (DILG);\nDepartment of Foreign Affairs (DFA);\nDepartment of Transportation and Communications (DOTC);\nDepartment of Finance (DOF);\nDepartment of Education (DepEd);\nDepartment of Labor and Employment (DOLE);\nDepartment of National Defense (DND);\nNational Disaster Coordinating Council (NDCC);\nOffice of the Press Secretary (OPS);\nArmed Forces of the Philippines (AFP);\nPhilippine National Police (PNP);\nAll Local Government Units (LGUS);\nThe Crisis Managers, in close coordination with the NDCC, shall be\nempowered to coordinate with or seek the assistance and support of the above\nmentioned agencies, including their respective attached offices and the various\nLGUs in order to effectively implement the provisions of this Order.\nAll agencies, offices, managers, and personnel are hereby directed to\ncooperate and provide such assistance and support as may be requested or\nneeded by the Crisis Manager in the containment of the Ebola Reston contagion.\nDefense and law enforcement agencies, particularly the Armed Forces of\nthe Philippines (AFP), the Philippine National Police (PP) and the Philippine\nCoast Guard (PCG) shall give priority to the directives or orders issued and\npromulgated by the Crisis Manager affecting their specific areas of concern.\n50420\nPGMA Hologram * 50420"}},{"id":"PH-H21111-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Rules and Regulations - The Secretary of Health, in consultation\nwith the Secretary of Agriculture, shall promulgate such rules and regulations as may be\nnecessary, related, incidental or consistent with the purpose, intent, and objective of this"}},{"id":"PH-H21111-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Separability Clause - Should any of the provisions contained herein\nbe declared illegal or unconstitutional, the rest or other such provisions not so declared\nshall remain valid and effective."}},{"id":"PH-H21111-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Effectivity - This Executive Order shall take effect immediately.\nDONE in the City of Manila, this It day of\nLord, Two Thousand and Nine.\nAugust , in the year of Our\n50421\nBy Authority of the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPeiA Hologram k 50421"}}],"pack":"ph-p159"};
  FT["PH-H21112"] = {"id":"PH-H21112","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Exempting Coconut Oil From the Coconut Levy and Sales Tax as Well as From the Special Fund Impost to Diesel","orig":"Exempting Coconut Oil From the Coconut Levy and Sales Tax as Well as From the Special Fund Impost to Diesel"},"level":"law","status":"active","docNumber":"Executive Order No. 827","issuingBody":"President of the Philippines","promulgatedDate":"1982-09-01","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00827_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00827_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21112-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Coconut oil to be used as engine fuel, either in its pure state or as blending component for diesel fuel,\nbe exempted from the coconut levy and sale tax, and the special fund impost and specific tax normally applied\nto diesel fuel."}},{"id":"PH-H21112-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Ministry of Energy shall, in consultation with the Ministers of Finance and the NEDA and upon\nrecommendation of the Commissioner of Internal Revenue, promulgate the appropriate rules and regulations\nto implement this Order."}},{"id":"PH-H21112-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Philippine Coconut Authority and the Board of Energy shall, likewise in consolation with the\nMinisters of Energy and the NEDA, promulgate such rules and regulations as may be necessary to implement"}},{"id":"PH-H21112-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"This Order shall take effect immediately.\nDone in the city of Manila, this 1st day of September, in year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21113"] = {"id":"PH-H21113","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE CHURCH-POLICE-MILITARY-LIAISON COMMITTEE TO FORMULATE AND IMPLEMENT A COMPREHENSIVE PROGRAM TO ESTABLISH STRONG PARTNERSHIP BETWEEN THE STATE AND THE CHURCH ON MATTERS CONCERNING PEACE AND ORDER AND HUMAN RIGHTS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE CHURCH-POLICE-MILITARY-LIAISON COMMITTEE TO FORMULATE AND IMPLEMENT A COMPREHENSIVE PROGRAM TO ESTABLISH STRONG PARTNERSHIP BETWEEN THE STATE AND THE CHURCH ON MATTERS CONCERNING PEACE AND ORDER AND HUMAN RIGHTS"},"level":"law","status":"active","docNumber":"Executive Order No. 827","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00827_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00827_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21113-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Organization. The Church-Police-Military Liaison Committee\n(CPMLC) is hereby created under the Office of the President to formulate and\nimplement a comprehensive program to establish strong partnership between\nthe State and the Church."}},{"id":"PH-H21113-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Composition and Leadership. The CPMLC shall be headed\nby a Chairman to be appointed by the President with the rank of Secretary, with\nthe Chief of the Philippine National Police (PNP), the Chief of Staff of the Armed\nForces of the Philippines (AFP), and the Chief, National Prosecution Service\n(NPS), as members. The rest of the membership of the CPMLC shall, upon\ninvitation of the President, be composed of the following religious aqgrupations:\nPGMA Hologram * 52106\n\na. One (1) representative from the National Council of Churches in the\nPhilippines;\nb. One (1) representative from the Philippine Council of Evangelical\nc. One (1) representative from the Catholic Bishops Conference of the\nPhilippines;\nd. One (1) representative from Ulama-Bishops Conference; and\ne. Representatives from other religious aggrupations or faith-based\norganizations as determined by the President."}},{"id":"PH-H21113-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Powers and Functions. The CPMLC shall have, among\nothers, the following powers and functions:\na. Design and implement appropriate procedures and mechanisms for\neffective coordination between the Church and the State to eradicate\nmisunderstanding and antagonism between them on peace and order\nand human rights Issues.\nb. Conduct seminars, interfaith dialogues, workshops and capacity\nbuilding programs that will inculcate mutual respect and reverence\namong the military, the police, the Church, and faith-based\norganizations.\nc. Undertake research and studies whereby the police, military and the\nchurch may mutually engage in projects and opportunities for the\npromotion of life, peace and justice; protection of human rights;\nsanctuary programs; and the prevention of and solution to the so-\ncalled \"extrajudicial killings and enforced disappearances\".\nd. Select personnel from the PP, AFP and NPS for detail in the CPMLC\nSecretariat.\ne. Perform such other functions and carry out activities as may be\ndirected by the President."}},{"id":"PH-H21113-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Secretariat. There shall be a Secretariat headed by an\nExecutive Director with the rank of Undersecretary to be appointed by the\nPresident who will handle the administrative, operational and technical\nrequirements and activities of the Committee."}},{"id":"PH-H21113-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Assistance from Government Agencies. All government\nagencies are directed to actively cooperate and support the CPMLC. The CPMLC\nmay call upon any agency of the government for assistance and cooperation in\nthe discharge of its functions."}},{"id":"PH-H21113-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Funding. Subject to government accounting and auditing\nprocedures, the CPMLC shall be provided with an initial allocation of Ten Million\nPesos (Php10,000,000.00) for CY 2009, to be drawn from the President's\nPOMA Hologram • 52107\n\nContingency Fund and from government savings. Appropriations for the\nsucceeding years shall be incorporated in the budget proposal of the Office of\nthe President."}},{"id":"PH-H21113-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Any portion or provision of this Executive Order that maybe\ndeclared unconstitutional shall not have the effect of nullifying its other portions\nor provisions, as long as such remaining portions can still be given effect."}},{"id":"PH-H21113-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"All executive orders, rules and regulations and other issuances\nor parts thereof, which are inconsistent with this Executive Order, are hereby\nrevoked, amended or modified accordingly."}},{"id":"PH-H21113-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"This Executive Order shall take effect fifteen (15) days\nimmediately following its publication in a national newspaper of general\ncirculation.\nDONE in the City of Manila, this 237d, day of/ovember in the year of Our\nLord, Two Thousand and Nine.\nBy the President:\nPirin in then\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Holograin • 52108"}}],"pack":"ph-p159"};
  FT["PH-H21114"] = {"id":"PH-H21114","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Temporarily Suspending the Exportation of Copra","orig":"Temporarily Suspending the Exportation of Copra"},"level":"law","status":"active","docNumber":"Executive Order No. 828","issuingBody":"President of the Philippines","promulgatedDate":"1982-09-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00828_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00828_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21114-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Until otherwise ordered by the President of the Philippines, the exportation of copra by any person,\nfirm or entity is hereby temporarily suspended effective immediately while copra production is insufficient to\nsupply the requirements of the local oil mills."}},{"id":"PH-H21114-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Philippine Coconut Authority is hereby directed to suspend all applications for license to export\ncopra and, in consultation with the different sectors of the coconut industry, to formulate and recommend for\nthe approval of the President additional feasible measures to achieve increased copra production and to insure\ncopra availability to enable the country's oil millers to fulfill the requirements of the domestic and world"}},{"id":"PH-H21114-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This order shall take effect immediately.\nDone in the City of Manila, this 11th day of September, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21115"] = {"id":"PH-H21115","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE ABRA DE ILOG PORT ZONE UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE ABRA DE ILOG PORT ZONE UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)"},"level":"law","status":"active","docNumber":"Executive Order No. 828","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00828_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00828_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21115-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The Abrade Ilog Port Zone, as delineated and established\nabove, is hereby placed under the administration of the Philippine Ports\nAuthority, which shall, consistent with the regional industrial plans of the\nGovernment, implement a program for the proper zoning, planning,\ndevelopment, and utilization of the port."}},{"id":"PH-H21115-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Other orders, proclamations, and issuances, or portions\nthereof, which are inconsistent with this Executive Order, are hereby repealed or\nmodified accordingly."}},{"id":"PH-H21115-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This Order shall take effect immediately after its publication\nin a national newspaper of general circulation.\nDONE in the City of Manila, this 7th day of AUG in the year of Our Lord,\nTwo Thousand and Nine.\nglarin A. Leage\nBy the President:\n5043\nEDUARDO R. ERMITA\nExecutive Secretary\n12\nPGMA Hologram # 50437"}}],"pack":"ph-p159"};
  FT["PH-H21116"] = {"id":"PH-H21116","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Law Enforcement Coordinating Committee, Abolishing the National Committee on Anti-Organized Crime and Its Functions Absorbed By the Peace and Order Council","orig":"Creating the Law Enforcement Coordinating Committee, Abolishing the National Committee on Anti-Organized Crime and Its Functions Absorbed By the Peace and Order Council"},"level":"law","status":"active","docNumber":"Executive Order No. 829","issuingBody":"President of the Philippines","promulgatedDate":"1982-09-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00829_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00829_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21116-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 829 September 11, 1982\nCREATING THE LAW ENFORCEMENT COORDINATING COMMITTEE, ABOLISHING THE\nNATIONAL COMMITTEE ON ANTI-ORGANIZED CRIME AND ITS FUNCTIONS ABSORBED BY\nTHE PEACE AND ORDER COUNCIL\nWHEREAS, the proper enforcement and effective execution of the laws of the land is the duty and\nresponsibility of the national Government;\nWHEREAS, pursuant to Presidential Letter of Instructions No. 824 s-79, a National Committee on\nAnti-Organized Crime was established to formulate and implement plans and control all activities relative to\nthe integration of the five pillar approach to the National Criminal Justice System, particularly on organized\nWHEREAS, the Peace and Order Council created pursuant to Executive Order 727 s-81 has responsibilities\nwhich encompass those of the National Committee on Anti-Organized Crime created pursuant to Letter of\nInstruction No. 824 s-79 and to prevent overlapping of functions, a need exists to abolish the National\nCommittee on Anti-Crime;\nWHEREAS, there exist a need for closer cooperation among law enforcement agencies of the government\ninvolved in the enforcement of general and special laws to insure unified direction and integration of effort\nthroughout the country in the suppression of criminal activities on a day-to-day basis, particularly at the\noperating levels.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution, do hereby order and direct the following:\n1. The National Committee on Anti-Organized Crime, as established pursuant to Letter of Instructions No.\n824 s-79 is hereby abolished and its functions, duties, responsibilities and instrumentalities absorbed by the\nPeace and Order Council created pursuant to Executive Order No. 727 s-81.\n2. Law enforcement coordinating bodies to be known as Law Enforcement Coordinating Committees are\nhereby created and constituted as the national, regional and provincial levels of the Peace and Order Council\nto serve as a venue for the coordination of all law enforcement activities of various government law\nenforcement agencies.\n3. The Law Enforcement Coordinating Committee at the national level shall consist of:\nChief of Constabulary/Director General, Integrated National Police Chairman\nDirector, National Bureau of Investigation\nDirector, Finance Ministry Investigation Bureau\nDirector, Bureau of Fisheries and Aquatic Resources\nCommandant, Philippine Coast Guard Commissioner,\nCommissioner, Commission on Immigration and Deportation;\nChief, Operations Control, National Intelligence and Security Authority\nCommissioner, Bureau of Customs\nCommissioner, Bureau of Internal Revenue\nDirector, Bureau of Forest Development\nGeneral Manager, Philippine Ports Authority\nCommanding General, Aviation Security Command\nDirector, Bureau of Land Transportation\nDirector, Bureau of Air Transportation\nCommanding General, Civil Relations Service, AFP\nExecutive Director, NAPOCCENT, and corresponding heads of all other national government agencies with\nlaw enforcement functions.\n4. The regional Law Enforcement Coordinating Committee shall consist of the PC/INP Regional Commander,\nwho shall be the Chairman, the heads/administrators of regional or field offices of government agencies\nmentioned in paragraph 3 of this order, and the Peace and Order Coordinator of the region.\n5. The provincial Law Enforcement Coordinating Committee shall consist of the PC/INP Provincial\nCommander, who shall be the Chairman; the heads of provincial field offices or stations of government\nagencies mentioned in paragraph 3 of this order, and the Peace and Order Coordinator of the province.\n6. The law Enforcement Coordinating Committees at all levels shall each maintain a coordinating center\nthrough which it shall coordinate the day-to-day law enforcement activities of the various member-agencies.\n7. Each Law Enforcement Coordinating Committees at all levels shall meet at least once a month to discuss,\nmonitor and assess the law enforcement programs of the government.\n8. The Chairman, Peace and Order Council shall issue appropriate rules and regulations in the implementation\nof this Executive Order.\nDone in the City of Manila, this 11th day of September, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21117"] = {"id":"PH-H21117","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES FORMING A TASK FORCE ON THE MANILA BAY CLEANUP","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES FORMING A TASK FORCE ON THE MANILA BAY CLEANUP"},"level":"law","status":"active","docNumber":"Executive Order No. 829","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00829_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00829_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21117-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"- There is hereby created a Task Force on the Manila Bay Cleanup under\nthe Department of Environment and Natural Resources to fast-track the bay cleanup\nproject, similar to the Pasig River Rehabilitation Committee, so that it could be bid\nout before June 2010."}},{"id":"PH-H21117-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"- The Philippine Gaming Corporation shall take the project on as part of\nits project to build a waterfront leisure center, so that the bay cleanup project does\nnot have to get funding from the General Appropriations Act."}},{"id":"PH-H21117-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"- This order shall take effect immediatel.\nDONE in Manila on the 25th day of August in the Year of Our Lord, Two Thousand\nflown is disage\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary'\nPGMANologram 50599"}}],"pack":"ph-p159"};
  FT["PH-H21118"] = {"id":"PH-H21118","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Increasing the Capitalization of the Light Rail Transit Authority From Five Hundred Million Pesos to Three Billion Pesos","orig":"Increasing the Capitalization of the Light Rail Transit Authority From Five Hundred Million Pesos to Three Billion Pesos"},"level":"law","status":"active","docNumber":"Executive Order No. 830","issuingBody":"President of the Philippines","promulgatedDate":"1982-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00830_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00830_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21118-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Article 6, Section 15 of Executive Order 603 is hereby amended to read as follows:\nCAPITALIZATION AND FINANCING\n\"Sec. 15. Capitalization. The Authority shall have an authorized capital of THREE BILLION PESOS\n(P3,000,000,000.00) which shall be fully subscribed by the Republic of the Philippines and other government\ninstitutions, corporations, instrumentalities, and agencies, whether national or local within the framework of\ntheir respective charters.\""}},{"id":"PH-H21118-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Repealing Clause. All laws, decrees, orders, rules and regulations, policies, programs, or part thereof,\nthat are inconsistent herewith are hereby repealed, amended or modified accordingly."}},{"id":"PH-H21118-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Effectivity. This order shall take effect immediately.\nDone in the City of Manila, this 30th day of September, 1982."}}],"pack":"ph-p159"};
  FT["PH-H21119"] = {"id":"PH-H21119","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG DIRECTING THE BUREAU OF IMMIGRATION AND DEPORTATION, PHILIPPING NATIONAL POLICE, BUREAU OF CUSTOMS AND DEPARTMENT OF HEALTH IN COORDINATION WITH THE CIVIL AMATION AUTHORITY OF THE PHILIPPINES FOR ESTABLISHMENT OF PERMANENT OFFICES AND PERSONNEL COMPLEMENT AT THE KALIBO INTERNATIONAL AIRPORT","orig":"MALACANANG DIRECTING THE BUREAU OF IMMIGRATION AND DEPORTATION, PHILIPPING NATIONAL POLICE, BUREAU OF CUSTOMS AND DEPARTMENT OF HEALTH IN COORDINATION WITH THE CIVIL AMATION AUTHORITY OF THE PHILIPPINES FOR ESTABLISHMENT OF PERMANENT OFFICES AND PERSONNEL COMPLEMENT AT THE KALIBO INTERNATIONAL AIRPORT"},"level":"law","status":"active","docNumber":"Executive Order No. 830","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00830_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00830_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21119-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Coverage - The Bureau of Immigration and Deportation,\nPhilippine National Police, Bureau of Customs and Department of Health in\ncoordination with the Civil Aviation Authority of the Philippines shall establish\npermanent offices with sufficient personnel complement at the Kalibo\nInternational Airport."}},{"id":"PH-H21119-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Implementation Period - The establishinent of permanent\noffices and complement of the herein named agencies at the Kalibo International\nAirport must be completed not later than forty five (45) calendar davs from the\ndate ol signing of this Order."}},{"id":"PH-H21119-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Provision of Space and Accessibilitv - The Civil Aviation\nAuthoritv of the Philippines shall be responsible for the provision of adequate\nspace for the establishment of permanent offices and accessibility of the\npersonnel of the herein named agencies.\nreport intent,\n50803\nPOMA Moigram • 50603"}},{"id":"PH-H21119-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Cost - Expenses incurred for the establishment and\nmaintenance of the permanent oftices, the salary of the permanent emplovees\nstationed at the Kalibo International Airport and utilities shall be borne by the\nindividual/ concerned agencies."}},{"id":"PH-H21119-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity - This Executive Order shall take eftect\nimmediately.\nDone in the City of Manila this 25th day of August in the year of our Lord,\nlive Thousand Nine.\nUlean the lilingo\n30804\nBv the President:\nEDUARDO R. ERMITA\nEvecutive Secretary\nPGMA Hologram # 50604"}}],"pack":"ph-p159"};
  FT["PH-H21120"] = {"id":"PH-H21120","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Philippines-United States Business Development","orig":"Creating the Philippines-United States Business Development"},"level":"law","status":"active","docNumber":"Executive Order No. 831","issuingBody":"President of the Philippines","promulgatedDate":"1982-09-30","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00831_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00831_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21120-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creating the Philippines-United States Business Development Council. There is hereby created the\nPhilippines-United States Business Development Council."}},{"id":"PH-H21120-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Functions and Activities.\n1. The Council shall have the function of effectively promoting trade and investment opportunities in the\nPhilippines to the American business community.\n2. To implement this function, the Council shall undertake the following activities:\na. Review Philippine Government policies affecting exports to and investments from the United States and\nmake the necessary recommendations to the President whenever appropriate with the objective of expanding\nflows in these two areas of business activities;\nb. Monitor the conditions of access for Philippine products to the United States and making appropriate\nrepresentations to the United States agency for the liberalization of these conditions;\nc. Monitor Philippine quota and GSP utilization levels;\nd. Provide logistical support to the trade and investment information activities of the Philippine Embassy and\nthe various Philippine consular posts in the United States through the publication of product catalogues and\nbuyer's guide as well as the maintenance of an effective trade and investment opportunities referrals system.\ne. Assist the Philippine Embassy and the Ministry of Trade and Industry in the organization of trade and\ninvestment missions and the holding of in-store promotions;\nf. Organize trade and investment seminars in the United States."}},{"id":"PH-H21120-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Organization. The Council shall be headed by the Chairman by the Chairman who shall be the\nPhilippine Ambassador to the United States. He shall be assisted by two Vice Chairmen who shall be\nappointed by the Chairman from the membership of the Council. One Vice Chairman shall be responsible for\ncoordinating the Council's operations in Manila and leasing with government agencies and private sector\n\norganization and the other Vice Chairman shall be responsible for coordinating the Council's field activities.\nThere shall be an Executive Director who shall be the Special Trade Representative of the Ministry of Trade\nand Industry presently assigned to the Philippine Embassy to the United States who shall be responsible for\nsupervising the implementation of the Council's work program.\nThe Council shall be composed of the following:\n1. The Philippine Ambassador to the United States\n2. The Representative of the Ministry of Foreign Affairs\n3. The Representative of the Ministry of Trade and Industry\n4. The Representative of the National Economic and Development Authority (NEDA)\n5. The Presidential Executive Assistant or his representative\n6. The Representative of the Governor of the Central Bank\n7. The Representative of the Ministry of Finance\n8. The Representative of the National Food Authority\n9. The President of the Philippine Chamber of Commerce and Industry\n10. Two other representatives of the private sector who shall be appointed for a term of two years.\nThe Council shall have the responsibility of formulating its policies and preparing the annual work program to\nbe submitted to the President for his approval.\nThe Chairman of the Council is hereby authorized to call on personnel from other government agencies and to\nengage the services of technical and administrative personnel as may be deemed necessary for the proper\ndischarge of his duties and responsibilities.\nThe Council is further authorized to coordinate the activities of all U.S. consular posts, all service attaches,\nPhilippine Centers, government-operated Philippine Houses, trading centers and other government\ncorporations and their subsidiaries operating in the U.S. in connection with the effective and efficient\nimplementation of the trade and investment promotion activities of the Council."}},{"id":"PH-H21120-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Appropriations. There is hereby authorized the appropriation annually of the amount of Two Million\nPesos for the operational and maintenance expenses of the Council and the additional authorized amount of\nTwo Million Pesos for special trade and investment promotion activities in the implementation of its annual\nwork program."}},{"id":"PH-H21120-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Other Sources of Funds. The Council is hereby authorized to tap other sources of funds including\ndonations and grants from appropriate local and foreign institutions."}},{"id":"PH-H21120-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Effectivity. This Order takes effect immediately.\nDone in the City of Manila, this 30th day of September, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21121"] = {"id":"PH-H21121","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE AUTHORIZING THE DEPARTMENT OF FINANCE, FOR THE DURATION OF THE CURRENT EMERGENCY, COMPLETE DISCRETION IN AUTHORIZING TAX AND TARIFF EXEMPTIONS FOR RELIEF GOODS DONATED FROM ABROAD","orig":"MALACAÑAN PALACE AUTHORIZING THE DEPARTMENT OF FINANCE, FOR THE DURATION OF THE CURRENT EMERGENCY, COMPLETE DISCRETION IN AUTHORIZING TAX AND TARIFF EXEMPTIONS FOR RELIEF GOODS DONATED FROM ABROAD"},"level":"law","status":"active","docNumber":"Executive Order No. 831","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00831_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00831_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21121-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"For the duration of the emergency disaster situation currently existing,\nthe Secretary of Finance shall have complete discretion in authorizing tax and tariff\nexemptions for relief goods donated from abroad, provided the donated relief\ngoods/articles/equipment for free distribution to calamity declared areas and\nvictims of calamities and/or disasters shall be for the account of the Department of\nROMA Habern i 50880\n\nSocial Welfare and Development (DSWD) or any of the relief organizations, not\noperated for profit, duly registered with the DSWD."}},{"id":"PH-H21121-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Such discretion shall be done on a ONE-SHOP basis. As such, a One-Stop\nshop shall be created in all collection districts of the Bureau of Customs headed by\nthe Department of Finance and composed of representatives from the DSWD,\nDepartment of Education, Department of Health, Department of Agriculture,\nDepartment of National Defense, and other govermment agencies concerned with\nthe documentation and processing of donated relief goods/articles/equipment to\neffect their immediate release from Customs custody."}},{"id":"PH-H21121-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Any Executive Orders, memoranda, and issuances inconsistent\nherewith are hereby repealed or amended accordingly.\nSECTION &. This Order shall take effect immediately.\nDone in the City of Manila, this 14 day of October in the Year of our Lord, Two\nThousand and Nine.\nOlere Me Rivery\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nFONA Hooran • 50881"}}],"pack":"ph-p159"};
  FT["PH-H21122"] = {"id":"PH-H21122","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Furthering Amending Executive Order No. 708, Dated July 27, 1981","orig":"Furthering Amending Executive Order No. 708, Dated July 27, 1981"},"level":"law","status":"active","docNumber":"Executive Order No. 832","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-01","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00832_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00832_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21122-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"of Executive Order No. 708, dated November 19, 1981 is hereby further amended by returning\nthe Philippine Gamefowl Commission to the Office of the President and transferring the National Stud Farm\nfrom the Ministry of Education and Culture to the Ministry of Agriculture.\nDone in the City of Manila, this 1st day of October, in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21123"] = {"id":"PH-H21123","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE CREATING A SPECIAL NATIONAL PUBLIC-PRIVATE RECONSTRUCTION COMMISSION TO UNDERTAKE A STUDY OF THE CAUSES, COSTS AND ACTIONS TO BE TAKEN IN THE WAKE OF TYPHOONS ONDOY, PEPENG AND FRANK, AND TO SEEK FRESH AID TO FUND RECONSTRUCTION","orig":"MALACAÑAN PALACE CREATING A SPECIAL NATIONAL PUBLIC-PRIVATE RECONSTRUCTION COMMISSION TO UNDERTAKE A STUDY OF THE CAUSES, COSTS AND ACTIONS TO BE TAKEN IN THE WAKE OF TYPHOONS ONDOY, PEPENG AND FRANK, AND TO SEEK FRESH AID TO FUND RECONSTRUCTION"},"level":"law","status":"active","docNumber":"Executive Order No. 832","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00832_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00832_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21123-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Creation and Composition. - There is hereby created a Special National\nPublic-Private Reconstruction Commission (Commission) appointed by the\nPresident but headed by a business leader, with the Secretary of Finance and a\nleader of the Church as co-chairs, and with department heads and business groups,\nrepresentatives of Philippine and international non-government organizations as\nmembers. The Commission is hereby mandated to study the causes, costs and\nactions to be taken in the wake of Typhoons Ondoy, Pepeng and Frank, and to seek\nfresh aid to fund reconstruction in the aftermath of said typhoons."}},{"id":"PH-H21123-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Secretariat. - The National Economic and Development Authority and\nthe Office of Civil Defense shall form the Secretariat of the Commission."}},{"id":"PH-H21123-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Key Tasks. - The key tasks of the Commission shall be the following:\n1. Undertake a study of the causes, costs and actions to be taken in the wake of\nTyphoons Ondoy, Pepeng and Frank;\n2. Undertake the rehabilitation plan for wrecked infrastructure and other\npriorities;\n3. Raise funds, especially grants, to fund reconstruction;\n4. Prioritize programs;\n5. Oversea implementation;\n6. Serve as clearing house for international assistance implemented by the\ndonors themselves using the cluster approach;\nPOMA Holosram r 50952\n\n7. Request the United Nations and the World Bank to coordinate an\ninternational pledging session."}},{"id":"PH-H21123-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repealing Clause. - All Executive issuances inconsistent in whole or in\npart with this Order are hereby repealed or modified accordingly."}},{"id":"PH-H21123-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Effectivity. - This Order shall take effect immediately.\nDONE on this 12th day of October in the Year of Our Lord Two Thousand and Nine.\nMarie A hugs\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram * 50953"}}],"pack":"ph-p159"};
  FT["PH-H21124"] = {"id":"PH-H21124","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Certifying That the Production of Fiberglass Insulation Materials, as a Preferred Pioneer Industry, Shall Be Entitled to Post-Operative Tariff Protection","orig":"Certifying That the Production of Fiberglass Insulation Materials, as a Preferred Pioneer Industry, Shall Be Entitled to Post-Operative Tariff Protection"},"level":"law","status":"active","docNumber":"Executive Order No. 833","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-04","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00833_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00833_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21124-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The production in the Philippines of fiberglass insulating materials, as a preferred pioneer industry,\nshall be entitled to post-operative tariff protection by increasing the tariff rates of imported glass wool and\nmineral wool insulating products which are similar to those being manufactured or produced by ACI\nFIBERGLASS (PHILS.) INC., a BOI registered pioneer enterprise operating on a commercial scale."}},{"id":"PH-H21124-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The articles specifically listed hereunder as classified under Section 104 of Presidential Decree No.\n1464, as amended, shall pay the following rates of import duty.\nTariff Heading No.\nDescription Article\nRate of Duty\nRecommended Effective on or after January 1\n68.07\nSlag, wool, rock wool and similar mineral exfoliated, vermiculite, expanded clays, foamed slag and similar\nexpanded mineral materials; mixtures and articles of heat-insulating, sound-insulating or sound absorbing\nmineral materials, other than those falling in Heading Nos. 68.12 or 6813, or in chapter 69 ...\n(Unified rate of ad. val. 20%)\n1983-1985\n1986\n1987\nA. Panels and Boards ...\n40%\n30%\n20%\nMade of Mineral Wool\n20%\n\n20%\n20%\n70.2\nGlass fibre (including wool), yarns, fabrics and articles made therefrom:\nA. Glass fibre (including wool)…\n30%\n40%\na. Glass Fibre …\n30%\n30%\n30%\nb. Glass Wool and Products ....\n40%\n30%\n40%\n40%\n40%\n40%"}},{"id":"PH-H21124-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Any unwarranted increase in the prices of local products benefited by these tariff changes shall\nconstitute tariff rates. The Board of Investments shall make the proper representations with the Tariff\nCommission for appropriate action in accordance with Section 401 of the Tariff and Customs Code."}},{"id":"PH-H21124-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"All Orders, Rules and Regulations or parts thereof inconsistent with the provisions of this order are\nhereby repealed.\nDone in the City of Manila, this 4th day of October in the year of Our Lord, nineteen hundred and eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21125"] = {"id":"PH-H21125","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE PROPERTY VALUATION OFFICE (PO) FOR PURPOSES OF SUSTAINING AND INSTITUTING REAL PROPERTY VALUATION","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE PROPERTY VALUATION OFFICE (PO) FOR PURPOSES OF SUSTAINING AND INSTITUTING REAL PROPERTY VALUATION"},"level":"law","status":"active","docNumber":"Executive Order No. 833","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00833_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00833_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21125-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Property Valuation Office - Organization and\nStructure. The Property Valuation Office (PO) shall be headed by a Director\nand shall be composed of the following divisions: (a) Policy, Planning,\nMonitoring and Evaluation; (b) Valuation Database and Information System; (c)\nValuation Standards; (d) Valuation Education and Training; (e) Finance and\nAdministration; and (f) other divisions or units as may be deemed necessary.\nThe Property Valuation Office shall remain to exist until the legislation\ncreating a national valuation authority is in place to ensure that real property\nvaluation reforms undertaken under LAMP shall continue to benefit the national\nand local governments. In the event of discontinuation of LAMP2 and\nsubsequent projects under the LAM reform agenda of the National Government,\nthe Property Valuation Office shall continue to operate with required\nappropriations sought from the General Appropriations Act. The PO shall be\nhoused at the DOF until such time that the legislation creating a national\nvaluation authority is approved."}},{"id":"PH-H21125-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"PO Budget. Funds for Personal Services (PS) are hereby\nauthorized based on the requirements of PO as indicated in the Implementing\nRules and Regulations of this Executive Order. The Maintenance and Other\nOperating Expenses (MOOE) and Capital Outlay (CO) of the PVO shall be derived\nfrom LAMP projects as long as LAMP projects exist. In the event that the\nValuation Reform Act (VRA) bill is enacted, the PVO shall be transformed into the\nnational valuation authority and its budget would be as defined under the VRA.\nAppendix A shows the proposed annual personnel budget for the PVO."}},{"id":"PH-H21125-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Advisory Committee of PO. There is hereby created the\nProperty Valuation Advisory Committee (PAC to be headed by the Executive\nDirector of the Bureau of Local Government Finance (BLGF) and as members,\nthe Director of the PVO and representatives from the Bureau of Internal Revenue\n(BIR), National Tax Research Center (NTRC), Land Registration Authority (LRA),\nnational LGU assessors' association, national GU treasurers' association, private\nappraisal sector, civil society, and others, as may be deemed necessary. The\nterms of reference of the VAC shall be part of the IRR of this Executive Order.\nPOMA Holoaram # 50964\n\n3\nThe PVAC shall exist until subsequent advisory committee as may be required by\nthe VRA shall have been constituted."}},{"id":"PH-H21125-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"PVO Supervision.\nUntil the passage of VRA, the LAMP2\nManagement Committee (Mancom) or subsequent projects under LAM reform\nprogram, shall provide policy guidance to the PO and the PVAC. In the event\nthat the RA is not approved by Congress, the PVO shall be under the supervision\nof the DOF or its assigned agency."}},{"id":"PH-H21125-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Implementation. The DOF, in consultation with relevant\nauthorities, shall prepare the Implementing Rules and Regulations (IRR) of this\nExecutive Order in the form of a comprehensive usage manual, which shall be\nsubject to the approval of the Office of the President."}},{"id":"PH-H21125-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Repealing Clause. All other Presidential directives, issuance,\norders, rules and regulations, or parts thereof, which are inconsistent with the\nprovisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21125-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately\nupon its publication in a newspaper of general circulation.\nDone in the City of Manila, this 13th day of October. in the year of Our\nLord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 50965\n\nProposed Permanent Core Positions for PVS\nPS Central Office Position\nOffice of Acting\nPolicy Planning\nCompliance\nMonitoring)\nLegal Services\nDirector IV\nPlanning Officer IV\nPlanning Officer III\nProperty Appraiser V\nProperty Appraiser III\nPlanning Officer V\n1\nInformation\nTechnology officer IlI\nLegal Officer V\nHuman Resource Mat\nOfficer V (HRM)\nHuman Resource Mgt 1\nOfficer III (HRD)\nAccountant 1\n1\n12\nSalary Monthly\nTotal Annual\nGrade Salary\nSalary Cost\n28\n14\n22\n30,967.00 371,604.00\n8,290.00\n199,480.00\n24.473.00\n293,676.00\n18\n24\n18\n24\n124\n24\n*\n24\n18\n111\n20,138.00 241,656.00\n26,472.00 |317,664.00\n20,138.00 241,656.00\n26,472.00 317,664.00\n26,472.00 317,664.00\n26,472.00\n317,664.00\n26,472.00 317,664.00\n20,138.00 241,656.00\n13,392.00\n160,704.00\n269,896.00 3,238,752.00\nPVS Regional\nGrand Total\nPlanning Officer III\n11\n(Planning and M&E)\nProperty Appraiser II 1\nPlanning Officer III\n1\n(Planning and M&E)\nProperty Appraiser II 1\n[4\n16\n18\n15\n18\n15\n20,138.00 241,656.00\n16,494.00 197,928.00\n20,138.00 241,656.00\n16,907.00 202,884.00\n73,677.00 884,124.00\n343,573.00 14,122,876.00\ninclusive of\n\n'Proposed Permanent Core Positions for PVS\nPVS Central Office Position\n1\nOffice of Acting\nPolicy Planning\nCompliance\nMonitoring)\nLegal Services\nDirector IV\nPlanning Officer IV\nPlanning Officer III\nProperty Appraiser V\nProperty Appraiser III\nPlanning Officer V\nInformation\nTechnology officer IlI\nLegal Officer V\nHuman Resource Mgt 1\nOfficer V (HRM)\nHuman Resource Mgt 1\nOfficer III (HRD)\nAccountant 1\n12\nSalary Monthly\nTotal Annual\nGrade Salary\nSalary Cost\n28\n4\n22\n30,967.00 371,604.00\n8,290.00\n199,480.00\n24,473.00\n293,676.00\n18\n24\n18\n24\n124\n24\n* 24\n18\n11\n20,138.00\n241,656.00\n26,472.00 317,664.00\n20,138.00 241,656.00\n26,472.00 317,664.00\n26,472.00 317,664.00\n26,472.00\n317,664.00\n26,472.00 317,664.00\n20,138.00 241,656.00\n13,392.00\n160,704.00\n269,896.00 3,238.752.00\nPVS Regional\nGrand Total\nPlanning Officer III\n11\n(Planning and M&E\nProperty Appraiser II 1\nPlanning Officer III\n1\n(Planning and M&E)\nProperty Appraiser II 1\n16\n18\n15\n18\n15\n20,138.00 241,656.00\n16,494.00 197,928.00\n20,138.00 241,656.00\n16,907.00 202,884.00\n73,677.00\n884,124.00\n343,573.00 4,122,876.00\ninclusive of"}}],"pack":"ph-p159"};
  FT["PH-H21126"] = {"id":"PH-H21126","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating a National Board on the SEAFDEC Aquaculture Department Programs, Budget and Operations","orig":"Creating a National Board on the SEAFDEC Aquaculture Department Programs, Budget and Operations"},"level":"law","status":"active","docNumber":"Executive Order No. 834","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00834_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00834_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21126-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of the National Board on the SEAFDEC Aquaculture Department Programs, Budget and\nOperations. A National Board is hereby constituted as a step towards institutionalizing a more effective\ncontrol and management of the SEAFDEC Aquaculture Department in the country. It shall be composed of\nMinisters/Heads of the following agencies or their representatives:\na. Ministry of Natural Resources, Chairman\nb. Ministry of Human Settlements, Member\nc. Ministry of the Budget, Member\n\nd. University of the Philippines System, Member\ne. National Science and Technology Authority, Member\nf. National Economic and Development Authority, Member\ng. Philippine Representative to the SEAFDEC Council, Member\nThe head of the SEAFDEC Aquaculture Department shall be a non-voting member and shall provide the\nSecretariat to the National Board."}},{"id":"PH-H21126-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Functions of the Board. The National Board shall discharge the following functions and\nresponsibilities:\na. To review and approve the annual program budget of the SEAFDEC Aquaculture Department particularly\nthe Philippine contribution before presentation to the Ministry of the Budget and the approval of the\nSEAFDEC Council;\nb. To approve the internal operating budget of the Aquaculture Department to ensure adequate financial\nsupports of approved programs;\nc. To ensure efficient operation of the SEAFDEC Aquaculture Department within the country by reviewing\nperiodically its organization, management, operations and progress of its researches;\nd. To evaluate, on an annual basis, the performance of the Aquaculture Department for the assessment of\nfuture programs and budgets;\ne. To recommend such other rules and regulations that shall ensure effective internal financial administration\nof the Aquaculture Department;\nf. To recommend to the President the nominees to the SEAFDEC Council for the position of Chief of the\nAquaculture Department;\ng. To study and implement mechanisms for a more effective dissemination of research results and transfer of\ntechnology on aquaculture to relevant government institution and to private enterprise;\nh. To effect the integration of the aquaculture research efforts of the AQD and those of other leading national\nresearch institution such as the U.P. in the Visayas which shall ensure the efficient operation and management\nof the Aquaculture Department for the Philippine Government;\ni. To study the delegation of supervisory and administrative responsibility over the Aquaculture Department to\na national institution such as the U.P. in the Visayas which shall ensure the efficient operation and\nmanagement of the Aquaculture Department for the Philippine Government."}},{"id":"PH-H21126-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Regional Integrity of the Aquaculture Department. The Aquaculture Department remains an\nintegral part of the SEAFDEC subject to policies, rules and regulations of the SEAFDEC Council and the\nSEAFDEC Treaty Agreement and commitment of the host country to the regional endeavor in fisheries. The\ncreation of the National Board is an internal mechanism within the Philippines to ensure that its commitments\nto the SEAFDEC are efficiently and effectively carried out."}},{"id":"PH-H21126-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Funding. The SEAFDEC Aquaculture Department, from out of the appropriations provided by the\nPhilippine government, shall allocate an amount adequate to support the operations and maintenance of the\nNational Board."}},{"id":"PH-H21126-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Effectivity. This Order shall be effective immediately.\nDone in the City of Manila, this 14th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21127"] = {"id":"PH-H21127","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG AUTHORIZING THE NATIONAL FOOD AUTHORITY/FOOD TERMINAL INCORPORATED AND THE PHILIPPINE INTERNATIONAL TRADING CORPORATION TO INTERVENE IN THE STABILIZATION OF THE SUPPLY AND PRICE OF BASIC ITEMS","orig":"MALACANANG AUTHORIZING THE NATIONAL FOOD AUTHORITY/FOOD TERMINAL INCORPORATED AND THE PHILIPPINE INTERNATIONAL TRADING CORPORATION TO INTERVENE IN THE STABILIZATION OF THE SUPPLY AND PRICE OF BASIC ITEMS"},"level":"law","status":"active","docNumber":"Executive Order No. 834","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00834_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00834_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21127-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Intervention by the National Food Authority\nFood Terminal Incorporated and the Philippine International\nTrading Corporation. -- The National Food Authority Food (NFA),\nFood Terminal Incorporated (FTI) and the Philippine International\nTrading Corporation (PITC), are hereby authorized to include in their\ncommodity coverage basic food items other than staple cereals, which\nthey may deem necessary to stabilize the country's basic food\ncommodity supply and prices."}},{"id":"PH-H21127-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Funding. - For this purpose, the NEA, FTI and\nPITC, thru their respective boards or council, are authorized to use their\ncorporate funds, manpower and other facilities, government-guaranteed\ncredit lines and supplemental government support, as they may deem"}},{"id":"PH-H21127-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Nature of Funds. - All disbursements as well as\nadministrative and operational expenses incurred by virtue hereof shall\nbe treated as a Special Projects Account subject to the usual accounting\nand auditing rules and regulations."}},{"id":"PH-H21127-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Tax Expenditure Subsidy Scheme - All\nimportation undertaken pursuant to the provisions of the herein\nExecutive Order shall be eligible for application of the Tax Expenditure\nSubsidy scheme."}},{"id":"PH-H21127-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Minimum Access Volume. - Outstanding volumes\nnot allocated under the Minimum Access Volume (MAV) pertaining to\npork and/or chicken, shall be distributed to the private sector under\nguidelines and procedures promulgated under the existing rules\ngoverning the implementation of the country's minimum access\ncommitments."}},{"id":"PH-H21127-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Special Safeguard (SSG) Duties.\nSafeguard Duties on chicken meat and/or products may be lifted to\nencourage private sector importation under guidelines and procedures to\nbe released by the Secretary of Agriculture and the Secretary of\nFinance/Bureau of Customs."}},{"id":"PH-H21127-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Inter-Agency Support. - All agencies of the\nNational Government, particularly but not limited to, the Department of\nTrade and Industry (DTI), Department of Finance (DOF), Department of\nBudget and Management (DBM), Department of Justice (DOJ, and the\nOffice of the Government Corporate Counsel (OGCC), are enjoined to\n51034\nPOMA Hologram * 51034\n\nextend full support to the Department of Agriculture for the\nimplementation of the herein Executive Order."}},{"id":"PH-H21127-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Volume of Importation. - The Secretary of\nAgriculture is hereby authorized to determine the reasonable volume of\npork and/or chicken that will be imported within the purview of this\nExecutive Order."}},{"id":"PH-H21127-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Effectivity. - This Executive Order shall take\neffect immediately and shall remain valid until December 31, 2009.\nDone in the City of Manila, this 15th day of October, in the year\nof Our Lord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Mologram # 51035"}}],"pack":"ph-p159"};
  FT["PH-H21128"] = {"id":"PH-H21128","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":16,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for a Revised Charter of the National Council on Integrated Area Development","orig":"Providing for a Revised Charter of the National Council on Integrated Area Development"},"level":"law","status":"active","docNumber":"Executive Order No. 835","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-14","completenessNote":"全文，共 16 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00835_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00835_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21128-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Declaration of Policy. It is the declared policy of the state to promote and support the improvement,\ngrowth and development of the country-side through integrated area development consistent with the principle\nof self-help and self-reliance."}},{"id":"PH-H21128-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Creation of the National Council on Integrated Area Development. There is hereby created a National\nCouncil on Integrated Area Development, as a sub-committee of the Cabinet, under the Office of the Prime\nMinister hereinafter referred to as the Council which shall be composed of the Prime Minister as Chairman,\nwith the following as members: the Minister of Agrarian Reform, the Minister of Agriculture, the Minister of\nFinance, the Minister of Human Settlements, the Minister of Local Government, the Minister of National\nDefense, the Minister of Natural Resources, the Director General of the National Economic and Development\nAuthority, the Director General of the Office of Budget and Management, the Minister of Public Works and\nHighways, the Minister of Trade and Industry, and the Executive Director of the Council. The Prime Minister\nmay designate other Ministries as well as other heads of Offices who are members of the Cabinet to be\n\nmembers of the Council.\nThe Prime Minister shall designate a Vice-Chairman from among the members of the Council who shall\nperform the functions of the Chairman in his absence.\nThe Council may establish an Executive Committee composed of three members to be designated by the\nChairman from among the members of the Council which shall act for and in behalf of the Council when the\nlatter is not in session.\nA Program Coordinating Committee shall be formed, composed of the designated senior level representatives\nof the members of the Council, as well as of the Presidential Management Staff, and the National Irrigation\nAdministration, which shall be chaired by the Executive Director. The Committee shall assist the Council in\nexpediting inter-agency commitments to on-going and pipeline projects. The Committee may have such\nadditional members composed of designated senior level representatives of other agencies as may be\ndetermined by the Prime Minister. The Prime Minister may established such sub-committees as may be\nnecessary for coordination purposes.\nThe Council may, at its discretion, assume supervision and control of other integrated area development\nprojects not under its present jurisdiction, which are multi-sectoral in nature and which are primarily\nsub-regional and preferably multi-provincial in geographical coverage.\nThe members of the Council shall receive a reasonable amount of per diem as the Council may provide for\nevery meeting actually attended by them."}},{"id":"PH-H21128-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Powers and Functions of the Council. The Council shall have the following powers and functions:\n(a) Institutionalize the implementing mechanism for integrated area development through formal planning,\nmonitoring and budgetary controls;\n(b) Formulate an integrated framework plan to guide the development of priority areas, including depressed\nareas as determined by the Council;\n(c) Rationalize the participation of the rural people through their local governments in development planning\nand implementation;\n(d) Initiate small-scale, high-impact integrated projects utilizing indigenous resources;\n(e) Mobilize efficiently multi-sectoral resources and properly channel these into integrated rural development\nprojects, and\n(f) Generate private sector participation in integrated area development projects and establish the appropriate\nmechanism for it."}},{"id":"PH-H21128-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Powers and Functions of the Chairman. The Chairman as Chief Executive Officer shall have the\nfollowing powers and functions:\n(a) To formulate policy guidelines and approve an integrated plan of action;\n(b) To call and preside over the meetings of the Council;\n(c) To appoint the Project Directors of the various integrated area development projects;\n(d) To enter into contracts to enable it to carry out its purposes and functions under this Executive Order;\n(e) To establish a system of priorities for integrated area development and provided the basic criteria for\nselecting project areas;\n(f) To arrange and/or negotiate for funding from local and foreign financial institutions;\n(g) To approve requests of the implementing departments and agencies for budget releases for projects in\naccordance with the integrated plan of action, budget and work programs approved by the Council; Provided,\nthat such approval shall be subject to the availability of funds in accordance with the existing budgetary\n\npolicies, laws, rules and regulations which shall be approved by the Council;\n(h) To call on any department, bureau, office, agency, or state university or college and other instrumentalities\nof the government for assistance in the form of personnel, facilities and other resources as the needs arise in\nthe discharge of its functions."}},{"id":"PH-H21128-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Qualifications and Compensation of the Executive Director as Chief Operating Officer. There shall be\nan Executive Director of the Council to be appointed by the President upon consultation with the members of\nthe Council. The Executive Director shall act as the Chief Operating Officer and shall possess the following\nqualifications:\n(a) a citizen of the Philippines;\n(b) at least thirty (30) years of age; and\n(c) a proven record of executive competence in the field of public administration and/or rural development\nprojects or in the management of agricultural, industrial or commercial enterprises.\nThe annual compensation and allowances of the Executive Director shall be fixed by the Council."}},{"id":"PH-H21128-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Powers and Functions of the Chief Operating Officer. The Executive Director as Chief Operating\nOfficer of the Council shall exercise the following powers and functions:\n(a) To recommend policy guidelines and submit to the Chairman programs of work activities in consonance\nwith the policies and plans promulgated by the Council;\n(b) To implement the coordinated plan of action for integrated area development as formulated and approved\nby the Chairman;\n(c) To undertake comprehensive studies concerning critical components needed for the development of\nidentified depressed areas;\n(d) To implement on-going and proposed plans, programs and projects within the specified areas for\nintegrated area development;\n(e) To rationalize and systematize existing on-going and proposed community projects in identified areas for\ndevelopment vis-a-vis the overall integrated area development plan for the specified area;\n(f) To coordinate and monitor project implementation;\n(g) To promote fuller local participation in planning, management and program execution through closer\ncoordination with local government officials;\n(h) To establish the appropriate organizational set-up to implement the integrated plan of action to be\napproved by the Chairman;\n(i) To formulate, adopt and implement guidelines and standards for an efficient system of reporting and\nevaluation;\n(j) To avail of the expertise of any particular employee, technician or group of persons in any bureau, office or\ndepartment of the government whose services are deemed necessary for the attainment of the goals of the\n(k) To prepare and submit to the Chairman administrative rules and regulations for the effective management\nof the Council's activities;\n(l) To hire the personnel necessary for the operation of the Council and fix their compensation in accordance\nwith the plantilla and pay plan approved by the Chairman;\n(m) To remove, suspend or otherwise discipline for cause any subordinate employee of the Council;\n(n) To conduct seminars, public hearings and/or conferences on significant issues pertaining to integrated area\ndevelopment;\n\n(o) To submit periodic financial and work accomplishment reports to the Council;\n(p) To perform such other duties as maybe assigned by the Council and/or the Chairman.\nIn order to assist the Council in the performance of its functions, the Executive Director or his duty designated\nrepresentative shall be an ex-officio member of the policy or coordinating committees of the different projects\nsupports staffs under the Council."}},{"id":"PH-H21128-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Support Staffs for NACIAD Projects. The Council is hereby authorized to establish such ad hoc\nsupport staffs as may be necessary for particular integrated area development projects which shall exist only\nfor the duration of said projects. As a general rule and whenever appropriate, the project support staff shall be\nprovided by the lead agency as may be identified and designated by the Council for any particular integrated\narea development project, to be supplemented as necessary by personnel from the other cooperating agencies.\nEach project support staff shall be headed by a Project Director who shall, as much as possible, come from the\nlead agency. The Council is further authorized to reorganize or abolish project support staffs under the\nsupervision and control of the Council. The operation of the project support staffs shall be in accordance with\nsuch guidelines as may be determined and issued by the Council."}},{"id":"PH-H21128-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Appointment of Other Cabinet Coordinators. The Chairman may appoint a Cabinet Coordinator for\neach new integrated area development project. Said coordinator shall be assisted by the Executive Director,\nwho shall closely coordinate with the Provincial Governors in integrated area development project areas.\nHowever, the designated Cabinet Coordinators of the Bicol, Cagayan, Mindoro, Samar, Zamboanga Projects,\nthe Agusan-Bukidnon-Capiz/Land Settlement Project, and the Philippine Rural Infrastructure Project shall\ncontinue to assume responsibility over their respective projects unless otherwise determined by the Chairman."}},{"id":"PH-H21128-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Budgetary System. To ensure the rational allocation and timely releases of funds for specific\ncomponents of integrated area development projects, the Office of Budget and Management, in consultation\nwith the Council, shall issue the appropriate guidelines and procedures for budget preparation and execution."}},{"id":"PH-H21128-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Staff Appointment. Any provision of existing laws to the contrary notwithstanding, the appointments\nof personnel of the Council may either be on full-time basis or part-time basis and shall be exempt from the\nrequirements and restrictions of the Civil Service Law, rules and regulations, and Section Two Hundred Fifty\nNine of the Revised Administrative Code. The compensation of said employees shall be determined by the\nCouncil upon consultation with the Office of Compensation and Position Classification of the Office of the\nBudget and Management; Provided, that any government retiree employed in the said office shall not be\nrequired to reimburse or refund any gratuity received from the Government nor shall any pension or annuity to\nwhich he is entitled to be suspended or reduced on account of his employment with the Council; Provided,\nfurther that the personnel of the Council shall be permanent and career in status without prejudice to transfer,\ndetail assignment, promotion, discipline and dismissal in accordance with the Personnel Management\nPrograms of the Council and shall be entitled to benefit and privileges normally accorded to government\nagencies on detail with the Council including adequate and reasonable honoraria or allowances."}},{"id":"PH-H21128-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"Delineation of the Functions and Responsibilities of the Council and Implementing Ministries and\nAgencies. The Council, including its staff, shall be essentially policy-setting and coordinative in nature and\nshall by itself not engage in direct implementation activities. The actual implementation of operations,\nactivities and programs within declared integrated area development projects shall be undertaken through\ndesignated cooperating line agencies. All designated implementing ministries and agencies shall be\nresponsible for the execution of the projects under their respective jurisdiction and shall submit to the Council,\ntheir respective annual project plans, budgets and corresponding work programs for approval within three (3)\nmonths before the start of the ensuing calendar year. They shall also submit release and periodic\naccomplishment reports to the Council."}},{"id":"PH-H21128-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"Observance of Terms and Conditions of the Loan Agreements. It shall be the responsibility of the\nCouncil to ensure that all ministries, government agencies and local governments concerned observe strictly\n\nall terms and conditions embodied in Loan Agreement executed between the foreign funding agencies and the\nPhilippine Government for integrated area development projects."}},{"id":"PH-H21128-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"Expenditures and Disbursements. Expenditures and disbursements made by the Council for its\non-going projects shall not be subject to the procurements requirements and restriction imposed by existing\nlaws and regulations upon government agencies, instrumentalities and government-owned or controlled\ncorporations."}},{"id":"PH-H21128-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"Separability Clause. If any provision of this Executive Order shall be declared invalid, the remainder\nshall continue to be operative."}},{"id":"PH-H21128-A15","no":15,"noLabel":{"en":"Sec 15"},"text":{"en":"Repealing Clause. All laws, decrees, executive orders, administrative orders, rules and regulations or\nparts thereof, which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H21128-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 14th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21129"] = {"id":"PH-H21129","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PROFESSIONAL REGULATION COMMISSION AND OTHER CONCERNED GOVERNMENT AGENCIES THROUGH THE DEPARTMENT OF LABOR AND EMPLOYMENT TO CONDUCT A YEARLY SPECIAL PROFESSIONAL LICENSURE BOARD EXAMINATIONS (SPLBE) IN THE KINGDOM OF SAUDI ARABIA, QATAR, THE UNITED ARAB EMIRATES AND OTHER MIDDLE EAST COUNTRIES FOR THE BENEFIT OF QUALIFIED OVERSEAS FILIPINO WORKERS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PROFESSIONAL REGULATION COMMISSION AND OTHER CONCERNED GOVERNMENT AGENCIES THROUGH THE DEPARTMENT OF LABOR AND EMPLOYMENT TO CONDUCT A YEARLY SPECIAL PROFESSIONAL LICENSURE BOARD EXAMINATIONS (SPLBE) IN THE KINGDOM OF SAUDI ARABIA, QATAR, THE UNITED ARAB EMIRATES AND OTHER MIDDLE EAST COUNTRIES FOR THE BENEFIT OF QUALIFIED OVERSEAS FILIPINO WORKERS"},"level":"law","status":"active","docNumber":"Executive Order No. 835","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00835_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00835_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21129-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Coverage - The Department of Labor and Employment,\nthrough the Professional Regulation Commission, in coordination with the\nDepartment of Foreign Affairs, Bureau of Immigration, and the Philippine\nProfessional Organizations - Kingdom of Saudi Arabia shall hold and conduct\nSpecial Professional Licensure Board Examinations for the qualified overseas\nFilipino workers in the Kingdom of Saudi Arabia, Qatar, the United Arab Emirates\nand other middle east countries with whom the Philippines has diplomatic"}},{"id":"PH-H21129-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Implementation Period - The Special Professional Licensure\nBoard Examinations for the qualified overseas Filipino workers in the Kingdom of\nSaudi Arabia, Qatar, the United Arab Emirates and other middle east countries\nwith whom the Philippines has diplomatic relations shall be held once every year\nstarting December 2009."}},{"id":"PH-H21129-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Designation of Venue of Examination and Accessibility -\nThe Department of Labor, through the Professional Regulation Commission, and\nthe Department of Foreign Affairs, through its Consular Offices abroad, shall be\njointly responsible in facilitating the required permits from the host country (ies),\nthe provision of adequate and conducive venue of examinations, and the\nprocessing of travel documents for the personnel who will conduct the Special\nProfessional Licensure Board Examinations.\nPOM& Hologram # 50968"}},{"id":"PH-H21129-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Funding - The amount required for the administration of the\nSpecial Professional Licensure Board Examination shall be chargeable against the\nProfessional Regulation Commission in its appropriate funding sources as included\nin its annual budget."}},{"id":"PH-H21129-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity - This Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, this 6' day of October, in the year of Our\nLord, Two Thousand and Nine.\nThrew th. here\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 50969"}}],"pack":"ph-p159"};
  FT["PH-H21130"] = {"id":"PH-H21130","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for Separate Positions of Chairman and General Manager in the Philippine Tobacco Administration","orig":"Providing for Separate Positions of Chairman and General Manager in the Philippine Tobacco Administration"},"level":"law","status":"active","docNumber":"Executive Order No. 836","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-14","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00836_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00836_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21130-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The position of Chairman of the Board of the Philippine Tobacco Administration, hereinafter referred\nto as the Administration, shall henceforth be separate from the position of General Manager. The Chairman of\nthe Board, who shall be responsible for presiding over the meetings of the Board of Directors, hereinafter\nreferred to as the Board, shall be appointed by the President of the Philippines for a term of five (5) years."}},{"id":"PH-H21130-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Board shall have the following powers and functions:\n(a) Formulate policies necessary for the attainment of the purposes and objectives for which the\nAdministration has been organized;\n(b) Adopt by-laws not inconsistent with existing laws, promulgate rules and regulations governing the manner\nin which the general business of the Administration is to be exercised; and amend, repeal or alter such\nby-laws, rules and regulations;\n(c) Recommend for appointment by the President of the Philippines the General Manager of the\nAdministration;\n(d) Determine the organizational structure of the Administration and create such positions as may be\nnecessary for the economical, effective and efficient discharge of its functions and responsibilities;\n(e) Pass upon and approve the annual and supplemental budgets submitted to it by the General Manager;\n(f) Pass upon and approve management contracts and proposals for the utilization and disposition of profits;\n(g) Submit to the Office of Budget and Management fiscal plans and statements of financial condition at such\ntime and in such form as may be prescribed. The Office of Budget and Management shall include in the\nbudget document the fiscal plans, financial statements and other informative data showing the\nadministration's actual and anticipated income and expenditures for the preceding, current and ensuing\ncalendar years;\n(h) Adopt rules and procedures and for the time and place for holding meetings, provided that one regular\n\nmeeting shall be held monthly; and\n(i) Exercise such other powers and perform such other duties as may be required by law."}},{"id":"PH-H21130-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"There is hereby created a position of General Manager in the Administration, which shall be separate\nfrom the position of Chairman of the Board. The General Manager shall be appointed by the President of the\nPhilippines, upon recommendation of the Board, for a term of six (6) years."}},{"id":"PH-H21130-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The General Manager shall be the chief executive officer of the Administration and shall have the\nfollowing functions:\n(a) Direct and manage the affairs and operation of the Administration and, for this purpose, delegate some or\nany of his administrative responsibilities and duties to other officers of the Administration;\n(b) Execute the policies and programs approved by the Board;\n(c) Recommend to the Board such policies and measures which he may deem necessary for the efficient,\neffective and economical implementation of the Administration's approved policies, plans and programs;\n(d) Submit, through the Board, within sixty days after the close of the calendar year an annual report to the\nPresident, the Batasang Pambansa and the Minister of Agriculture;\n(e) Appoint subordinate employees as may be necessary for the proper discharge of the functions of the\nAdministration subject to the confirmation of the Board, and\n(f) Remove, suspend, or otherwise discipline for cause any subordinate employees of the Administration in\naccordance with applicable Civil Service laws, rules and regulations."}},{"id":"PH-H21130-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21130-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof: Provided, That such remaining portion can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21130-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 14th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21131"] = {"id":"PH-H21131","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG EXECUTIVE ORDER NO._836 TRANSFORMING THE RISK MANAGEMENT GROUP OF THE BUREAU OF CUSTOMS INTO RISK MANAGEMENT OFFICE","orig":"MALACAÑANG EXECUTIVE ORDER NO._836 TRANSFORMING THE RISK MANAGEMENT GROUP OF THE BUREAU OF CUSTOMS INTO RISK MANAGEMENT OFFICE"},"level":"law","status":"active","docNumber":"Executive Order No. 836","issuingBody":"President of the Philippines","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00836_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00836_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21131-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Risk Management Office. The Risk Management Group of the Bureau of\nCustoms is hereby transformed into Risk Management Office (RMO)."}},{"id":"PH-H21131-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Composition. The RMO shall be headed by a Chief of Office and shall be\ncomposed of the following units:\n1. Administrative Staff\n2. Strategic Assessment Unit\n3. Research and Analysis Unit, and\n4. Operational Risk Assessment Unit."}},{"id":"PH-H21131-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Structure. To ensure its integrity and autonomous character, the RMO is\nplaced directly under the Commissioner of Customs while its day-to-day operations shall be\nmanaged by the Deputy Commissioner for the Intelligence Group, Bureau of Customs."}},{"id":"PH-H21131-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Functions. The RMO shall undertake the following functions:\na. Review and update parameters of the Selectivity Screen of the Selectivity\nSystem of the Bureau of Customs;\nPOnd Holouram « 51132\n\nb. Establish a viable system of setting and changing the said parameters;\nc. Ensure an efficient and secure information pipeline from all sources to the MO;\nd. Conduct a continuing study/profile of importers, exporters and customs brokers;\ne. Maintain a database of all smuggling cases and related data; and\nRecommend to the Commissioner of Customs policies and programs to increase\nefficiency and effectivity of the BOC's Selectivity System.\nThe Commissioner of Customs may impose additional functions to the RMO to\nensure that the aims and obiectives of this order are achieved."}},{"id":"PH-H21131-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Implementing Authority. The Deputy Commissioner of the Intelligence\nGroup, in his capacity as manager of the RMO, may recommend to the Commissioner of\nCustoms new policies and organizational improvements. to the MO to increase its\nefficiency."}},{"id":"PH-H21131-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Appropriations. The necessary funding for the efficient and effective\noperations of the MO shall be taken from the original appropriations of the RMG to be\naugmented from the available funds of the BOC. Its subsequent appropriations shall be\nincorporated into the BOC's budget proposals."}},{"id":"PH-H21131-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Oversight Function of the Office of the President Over the RMO. - The\nOffice shall submit a quarterly report of its work program and accomplishments to the\nSecretary of Finance and the Office of the President."}},{"id":"PH-H21131-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this _ 20th day of October\nof Our Lord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram # 51133"}}],"pack":"ph-p159"};
  FT["PH-H21132"] = {"id":"PH-H21132","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Vesting the Jurisdiction, Control and Regulation Over the Watershed Areas of the Manito, Albay and Bacon, Sorsogon Geothermal Reservation Established Under Proclamation No. 2036-A With the Ministry of Energy, Pursuant to the Provision of Presidential Decree No. 1515, as Amended By Presidential Decree No. 1749","orig":"Vesting the Jurisdiction, Control and Regulation Over the Watershed Areas of the Manito, Albay and Bacon, Sorsogon Geothermal Reservation Established Under Proclamation No. 2036-A With the Ministry of Energy, Pursuant to the Provision of Presidential Decree No. 1515, as Amended By Presidential Decree No. 1749"},"level":"law","status":"active","docNumber":"Executive Order No. 837","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00837_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00837_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21132-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The jurisdiction, control and regulation over the watershed areas of the Manito, Albay and Bacon,\nSorsogon Geothermal Reservation established and described under Proclamation No. 2036-A shall be vested\nwith the Ministry of Energy."}},{"id":"PH-H21132-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Ministry of Energy, through the National Power Corporation, shall be responsible for the\nmanagement, protection, development and rehabilitation of the aforementioned watershed areas in accordance\nwith Section 2 of Presidential Decree No. 1515, as amended."}},{"id":"PH-H21132-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect immediately.\n\nDone in the City of Manila, this 14th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21133"] = {"id":"PH-H21133","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES AN ORDER PLACING THE FILM DEVELOPMENT COUNCIL OF THE PHILIPPINES UNDER THE OVERSIGHT OF THE DEPARTMENT OF EDUCATION","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES AN ORDER PLACING THE FILM DEVELOPMENT COUNCIL OF THE PHILIPPINES UNDER THE OVERSIGHT OF THE DEPARTMENT OF EDUCATION"},"level":"law","status":"active","docNumber":"Executive Order No. 837","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00837_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00837_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21133-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Film Development Council of the Philippines is placed under the\noversight of the Department of Education."}},{"id":"PH-H21133-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 20th day of October in the year of Our Lord, Two\nThousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPaMA Hologram * 51137"}}],"pack":"ph-p159"};
  FT["PH-H21134"] = {"id":"PH-H21134","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Revising the Percentage Tax on Sales of Automobiles Under Section 195(A) of the National Internal Revenue Code of 1977, as Amended","orig":"Revising the Percentage Tax on Sales of Automobiles Under Section 195(A) of the National Internal Revenue Code of 1977, as Amended"},"level":"law","status":"active","docNumber":"Executive Order No. 838","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00838_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00838_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21134-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Section 195(A) of the National Internal Revenue Code, as amended, is hereby amended whichever is\n(a) For locally manufactured automobiles. If the suggested retail or list price or actual retail price whichever is\n15%\nOver P65,000 but not over P85,000\n25%\nOver P85,000 but not over P120,000\n35%\n45%"}},{"id":"PH-H21134-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Minister of Finance, upon recommendation of the Commissioner of Internal Revenue, shall\npromulgate the necessary rules and regulations for the implementation of this Executive Order."}},{"id":"PH-H21134-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 20th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21135"] = {"id":"PH-H21135","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING A SPECIAL NATIONAL PUBLIC RECONSTRUCTION COMMISSION TO UNDERTAKE A STUDY OF THE CAUSES, COSTS AND ACTIONS TO BE TAKEN IN THE WAKE OF TYPHOONS ONDOY, PEPENG AND FRANK, TO SEEK FRESH AIDS TO FUND RECONSTRUCTION AND TO ENTER INTO A PARTNERSHIP WITH THE PRIVATE SECTOR FOR THE FOREGOING PURPOSES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES CREATING A SPECIAL NATIONAL PUBLIC RECONSTRUCTION COMMISSION TO UNDERTAKE A STUDY OF THE CAUSES, COSTS AND ACTIONS TO BE TAKEN IN THE WAKE OF TYPHOONS ONDOY, PEPENG AND FRANK, TO SEEK FRESH AIDS TO FUND RECONSTRUCTION AND TO ENTER INTO A PARTNERSHIP WITH THE PRIVATE SECTOR FOR THE FOREGOING PURPOSES"},"level":"law","status":"active","docNumber":"Executive Order No. 838","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00838_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00838_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21135-A1","no":1,"noLabel":{},"text":{"en":"(3) To tap the resources of the private sector and to enhance and facilitate the\ncooperation and coordination between the Philippine Government and the private\nsector in formulating and implementing the Philippine Government's reconstruction\n(4) To raise funds, especially grants, to fund reconstruction;\n(5) To prioritize the proiects and programs for the reconstruction efforts;\n(6) To oversee the implementation of the reconstruction program;\n(7) To serve as clearing house for the international assistance implemented by the\ndonors themselves using the cluster approach; and\n(8) To request the United Nations and the World Bank to coordinate an International\nPledging Session.\nPrivate Sector. The Public Commission is mandated to tap the resources of\nthe private sector for the foregoing reconstruction efforts and for this purpose, the Public\nCommission is authorized to enter into a partnership through a Cooperation Agreement\n\"Cooperation Agreement\") with a Private Sector Reconstruction Commission (the \"Private\nCommission\") headed by a business leader who will assist and support the Philippine\nGovernment's reconstruction efforts in his capacity as a private citizen and assist the\nGovernment in tapping the resources of the private sector towards this end. The Public\nCommission and all Government agencies and instrumentalities are mandated to extend all\nassistance and support to the Private Commission and all projects that the Private\nCommission and the private sector may undertake in support of the Philippine\nGovernment's reconstruction efforts and strategy. The Private Commission and the private\nsector that will contribute manpower, expertise, funds and resources to the Private\nCommission shall remain a separate private organization and private citizens and entities,\nrespectively, and will not form part of the Public Commission.\naccordingly.\nRepealing Clause. All Executive Issuances inconsistent in whole or in part\nwith this Order, including Executive Order No. 832, are hereby repealed or amended\nEffectivity. This Executive Order shall take effect immediately.\nDONE in the City of Manila on this 22nd day of October in the Year of Our Lord Two\nThousand and Nine.\nBy the President\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram # 51188"}}],"pack":"ph-p159"};
  FT["PH-H21136"] = {"id":"PH-H21136","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Directing the Reorganization of the National Food Authority","orig":"Directing the Reorganization of the National Food Authority"},"level":"law","status":"active","docNumber":"Executive Order No. 839","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-26","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00839_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00839_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21136-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"For purpose of the reorganizational needs, the NFA Council is hereby authorized and directed to:\na. Group, coordinate, consolidate or integrate positions and functions in the NFA;\nb. Create, classify and abolish positions; and\nc. Fix salaries and other compensation of NFA officials and employees."}},{"id":"PH-H21136-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The NFA Council shall likewise promulgate the necessary implementing guidelines to carry out the\nreorganization, such guidelines to include the internal organization of units and offices."}},{"id":"PH-H21136-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"All appointments to be made by the NFA Council under this Executive Order shall be based on merit\nand fitness."}},{"id":"PH-H21136-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Hereafter, all personnel actions in the NFA including the fixing of salaries and other compensation of\nofficials and employees, shall not be subject to the regulations of the Office of Compensation and Position\nClassification."}},{"id":"PH-H21136-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21137"] = {"id":"PH-H21137","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING OIL INDUSTRY PLAYERS TO MAINTAIN PRICES OF PETROLEUM PRODUCTS PREVAILING ON THE LAST LANDFALL OF TYPHOON \"PEPENG\" (PARMA) DURING THE PERIOD EMERGENCY IN THE ENTIRE ISLAND OF LUZON","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING OIL INDUSTRY PLAYERS TO MAINTAIN PRICES OF PETROLEUM PRODUCTS PREVAILING ON THE LAST LANDFALL OF TYPHOON \"PEPENG\" (PARMA) DURING THE PERIOD EMERGENCY IN THE ENTIRE ISLAND OF LUZON"},"level":"law","status":"active","docNumber":"Executive Order No. 839","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00839_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00839_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21137-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Directive to Oil Industry Players. - Pursuant to Section 14(e) of\nRA No. 8479, and for. the duration of the state of emergency in the entire Luzon, oil\nindustry players are hereby directed to retain the level of the retail price of petroleum\nproducts prevailing on October 15, 2009, which was one (1) week after the last landfall\nof typhoon \"Pepeng\" (Parma)."}},{"id":"PH-H21137-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"DOJ-DOE Task Force. - The DOJ-DOE Task Force is hereby\ndirected to monitor the implementation of this Order, and to institute complaints\nagainst violators of this directive and the provisions of RA No. 8479. The Joint Task\nForce is further directed to submit its report to the President through the Executive"}},{"id":"PH-H21137-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Effectivity. - This Executive Order shall take effect immediately\nupon publication in a newspaper of general circulation.\nDone in the City of Manila this 23 day of October in the year of Our Lord, Two\nThousand and Nine.\nplease in hung\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOM) Hologram • 51198"}}],"pack":"ph-p159"};
  FT["PH-H21138"] = {"id":"PH-H21138","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Completion of the National Agriculture and Life Sciences Research Complex at the University of the Philippines at Los Baos","orig":"Completion of the National Agriculture and Life Sciences Research Complex at the University of the Philippines at Los Baos"},"level":"law","status":"active","docNumber":"Executive Order No. 840","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00840_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00840_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21138-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The following new institution are hereby established at the University of the Philippines at Los Baños\nto form part of the national agriculture and life sciences research complex thereat, namely:\nFarming Systems and Soil Resources Institute\nInstitute of Food Science and Technology\nInstitute of Animal Science\nThe Board of Regents of the University of the Philippines is hereby authorized to organize the\nabove-mentioned institutes from out of existing staff, physical facilities and programs of the University and its\nconstituent units."}},{"id":"PH-H21138-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Each of the above institutes shall receive for Calendar Year 1982 an initial support of at least Three\nMillion Pesos (P3,000) and a similar amount for Calendar Year 1983 from the Special Activities Fund and/or\nany other appropriate sources for their current operating expenses."}},{"id":"PH-H21138-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Ministers of Budget and Management and Public Works and Highways are hereby directed to\nprovide for the capital outlay requirements of these institutes within a three-year period starting Calendar Year\n1984."}},{"id":"PH-H21138-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The seven research institutes comprising the national agriculture and life sciences research complex\nand such other institutes, centers and laboratories which may be organized later, are hereby authorized to call\nupon qualified scientists and experts from other government entities and from the private sector, and to pay\nthese scientists and experts, including their own, the appropriate allowances, honoraria, and other incentives\nsubject to guidelines covering such matters issued by the Director-General of the National Science and\nTechnology Authority."}},{"id":"PH-H21138-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The institutes in the complex are likewise hereby exempted from government limitations in the\npurchase of scientific and research-related equipment and attendance abroad to scientific and technology\nmeetings and conferences upon certification by the Director-General of the National Science and Technology\nDone in the City of Manila, this 16th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21139"] = {"id":"PH-H21139","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE 1,551.1416-HECTARE PROPERTY OF THE DEPARTMENT OF FINANCE LOCATED IN BARANGAYS TARTARO, CALUMPANG, SIBUL, KINAMATAYANG KABAYO, STA. LUCIA AND MALIBAY, ALL IN SAN MIGUEL, BULACAN, AS A HOUSING SITE FOR GOVERNMENT EMPLOYEES AND AS A RELOCATION SITE FOR INFORMAL SETTLER","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE 1,551.1416-HECTARE PROPERTY OF THE DEPARTMENT OF FINANCE LOCATED IN BARANGAYS TARTARO, CALUMPANG, SIBUL, KINAMATAYANG KABAYO, STA. LUCIA AND MALIBAY, ALL IN SAN MIGUEL, BULACAN, AS A HOUSING SITE FOR GOVERNMENT EMPLOYEES AND AS A RELOCATION SITE FOR INFORMAL SETTLER"},"level":"law","status":"active","docNumber":"Executive Order No. 840","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00840_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00840_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21139-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Segregation and Disposition of the Property as Housing and\nRelocation Sites. - The subject 1,551.1416-hectare property is hereby declared as\nhousing and relocation sites for government employees and informal settler-families\nliving in danger areas, respectively, to be subdivided and disposed in the following\nmanner: (a) 300 hectares for the Armed Forces of the Philippines [AFP]; (b) 300\nhectares for the Philippine National Police [PP]; (c) 300 hectares for teachers; (d) 300\nhectares for other government employees; and (e) the remaining 351.1416 hectares for\nthe informal settler-families living in danger areas whose homes were destroyed by\nTyphoon Ondoy, and those who may be similarly situated caused by future\ncatastrophes.\n+451.240 37\nPGMA Holouram # 51210"}},{"id":"PH-H21139-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Transfer, development and administration of property. - Within\nthirty (30) days from the effectivity of this Order, the BSP and DOF shall execute the\nnecessary instruments to ensure the transfer of ownership of the 1,551.1416-hectare\nproperty to the NHA."}},{"id":"PH-H21139-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Funding allocation. The NHA, as administrator of the housing site,\ntogether with the Department of Budget and Management, shall secure the allocation of\na budget to implement this Executive Order, taking into account the funding\nrequirement for varicus activities to be undertaken in connection hereof, such as, but\nnot limited to, the establishment of a fund sourcing scheme to finance the project.\nThe AFP, PNP and the Department of Education (DepEd) shall provide\ncorresponding funds from their respective savings for site development cost and other\nlogistical requirements for this project."}},{"id":"PH-H21139-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Implementing Rules and Regulations. - An Executive Committee\ncomposed of the General Manager of NHA as Chairperson and representatives from the\nDepartment of Social Welfare and Development, HUDCC, AFP, PNP and DepEd, as\nmembers, is hereby created to formulate the policies (i.e., qualification of beneficiaries,\nlot pricing or payment scheme, etc.) for the effective implementation of this Executive"}},{"id":"PH-H21139-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Separability. - Any portion or provision of this Executive Order that\nmaybe declared unconstitutional shall not have the effect of nullifying its other portions\nor provisions, as long as such remaining portions can still be given effect."}},{"id":"PH-H21139-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Repealing Clause. - All executive orders, rules and regulations and\nother parts thereof which are inconsistent with this Order are hereby revoked, amended\nor modified accordingly."}},{"id":"PH-H21139-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Effectivity. - This Order shall take effect immediately.\nDONE in the City of Manila, this 23rd day of October, in the year of Our Lord,\nTwo Thousand and Nine.\nglove Mr. Array\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\n12\nPGMA Hologram 4 51211"}}],"pack":"ph-p159"};
  FT["PH-H21140"] = {"id":"PH-H21140","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the Kabataang Barangay National Secretariat, Defining Its Powers and Functions, Providing for Its Organizational Structure and for Other Purposes","orig":"Creating the Kabataang Barangay National Secretariat, Defining Its Powers and Functions, Providing for Its Organizational Structure and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 841","issuingBody":"President of the Philippines","promulgatedDate":"1982-10-28","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00841_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00841_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21140-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of the Kabataang Barangay National Secretariat. There is hereby created the Kabataang\nBarangay National Secretariat to serve as the staff support for the Pambansang Katipunan ng Kabataang\nBarangay (PKKB) hereinafter referred to as the KB National Secretariat;"}},{"id":"PH-H21140-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Powers and Functions of the KB National Secretariat. The KB National Secretariat shall have the\nfollowing objectives and functions:\n1. To ensure the effective and efficient implementation of the wide-ranging programs and projects of the\nPKKB covering the socio-economic, sports, cultural and political aspects.\n2. To plan and promote development programs and projects aimed at preparing and training the youth for\nfuture leadership and for gainful employment as productive members of the Philippine society.\n3. To supervise the different KB organizations with the end in view of coordinating the efforts of these various\norganizations in accordance with the goals of the PKKB."}},{"id":"PH-H21140-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Administration of the KB National Secretariat. The KB National Secretariat shall be headed by an\nExecutive Director who shall be appointed by the President of the Philippines upon the recommendation of\nthe KB National Executive Committee. The Executive Director shall exercise executive powers and shall\nadminister the internal operations of the National Secretariat as well as the implementation of the various\nprograms/projects of the PKKB."}},{"id":"PH-H21140-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Organization of the KB National Secretariat. The KB National Secretariat shall comprise of the\nfollowing offices:\n1. The Program Development Office which shall formulate and monitor plans, projects and activities geared at\nenchanting the productivity of the youth sector of the country thereby enabling them to contribute more\nfruitfully to the country's economic, educational, socio-cultural and sports development.\n2. The Operations Office which shall be responsible for the efficient and effective implementation of projects\nand activities initiated by the various offices as well as the continuous and periodic evaluation thereof.\n\n3. The Special Projects Office which shall plan, initiate and supervise the undertaking of special projects\nsolely or in coordination with concerned private and government agencies.\n4. The Administrative/Finance Office which shall provide personnel, legal, budgetary and other services\nsupportive of the functions and activities of the various offices of the secretariat.\n5. The Office of the Executive Director which shall consist of the following:\n5.1 The International Relations Staff which shall initiate, promote and develop plans and programs as well as\nsupport foreign programs in order to enhance and strengthen relations of the youth in the Philippines with\ntheir foreign counterparts.\n5.2 The Political Affairs Staff which shall be responsible for the conceptualizations, supervision and\nevaluation of leadership training programs for potential youths.\n5.3 The Information and Publication Staff which shall plan, undertake and supervise information, publication\nand public relations programs for nation wide dissemination of information regarding the programs/projects of\nthe Kabataang Barangay, thus drawing more participation in such activities.\n6. The thirteen (13) Regional Offices which shall serve as the implementing arm of the KB National\nSecretariat at the regional level. Each of these Regional Offices shall be headed by a KB Regional\nCoordinator.\nThe necessary staffing pattern of the KB National Secretariat shall be in accordance with the provisions of\nPresidential Decree No. 1177."}},{"id":"PH-H21140-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Additional Appropriations for the Pambansang Hall Katipunan ng Kabataang Barangay ng Pilipinas. In\naddition to the amount already appropriated for the PKKB, the amount of million pesos is hereby set aside\nfrom the Special Activities Fund for CY 1982 to support the personnel complement of the KB National\nSecretariat and its development programs. Thereafter all the amounts needed for the operations and programs\nof the PKKB shall be included in the General Appropriation Act."}},{"id":"PH-H21140-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Repealing Clause. All provisions of decrees, orders and other rules, regulations or parts thereof which\nare inconsistent with any of the provisions of this Executive Order are hereby repealed or modified\naccordingly."}},{"id":"PH-H21140-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 28th day of October, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21141"] = {"id":"PH-H21141","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"DIRECTING ALL LOCAL CHIEF EXECUTIVES AND LOCAL DEVELOPMENT IMMEDIATELY REVISIT/REFORMULATE/FORMULATE THEIR RESPECTIVE COMPREHENSIVE LAND USE PLANS, IDENTIFYING FOR THE PURPOSE THE AREAS FOR SOCIALIZED HOUSING AND RESETTLEMENT/RELOCATION, FURTHER DIRECTING THE HOUSING AND URBAN DEVELOPMENT COORDINATING COUNCIL (HUDCC) TO FACILITATE THE INVENTORY OF GOVERNMENT-OWNED LANDS SUITABLE FOR SOCIALIZED HOUSING PURPOSES.","orig":"DIRECTING ALL LOCAL CHIEF EXECUTIVES AND LOCAL DEVELOPMENT IMMEDIATELY REVISIT/REFORMULATE/FORMULATE THEIR RESPECTIVE COMPREHENSIVE LAND USE PLANS, IDENTIFYING FOR THE PURPOSE THE AREAS FOR SOCIALIZED HOUSING AND RESETTLEMENT/RELOCATION, FURTHER DIRECTING THE HOUSING AND URBAN DEVELOPMENT COORDINATING COUNCIL (HUDCC) TO FACILITATE THE INVENTORY OF GOVERNMENT-OWNED LANDS SUITABLE FOR SOCIALIZED HOUSING PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 841","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00841_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00841_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21141-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Establishment of Task Force on CLUP - Local\nGovernment Units are hereby ordered to create a Task Force for\nthe purpose of updating/formulating/reformulating the CLUP to\nensure its completion within six (6) months from the effectivity of this\nOrder. The Task Force shall be constituted and composed of all\nmembers of the local development councils to be chaired by the\nlocal chief executive."}},{"id":"PH-H21141-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Responsibilities - The Task Force shall have the\nfollowing responsibilities;\nUpdate/reformulate/formulate the CLUP within the given\nFacilitate the identification and inventory of government-\nowned lands which have not been used for the purpose for which\nthey have been reserved for the past ten (10) ears from the\neffectivity of RA 7279, and initiate the transfer of the same to HA\nfor purposes of utilizing these lands for socialized housing and\nresettlement/relocation areas;\nFormulate the mechanics for the relocation and\nresettlement of persons living in danger areas such as esteros,\nrailroad tracks, garbage dumps, riverbanks, shorelines, waterways,\nand other public places such as sidewalks, roads, parks and\nplaygrounds;\nInstitute programs for the provision of basic services,\nfacilities and access to employment and livelihood opportunities to\nmeet the basic needs of the affected families in the\nrelocation/resettlement sites;\nCoordinate with other government agencies to ensure\ncompliance of this Order;\nf. Prepare implementing guidelines as may be necessary;\nPGMA Hologram * 51241"}},{"id":"PH-H21141-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Administrative Support - The Department of\nInterior and Local Government (DILG) and the Housing & Urban\nDevelopment Coordinating Council shall provide the secretariat\nsupport to the Task Force in the performance of its tasks.\nAll government agencies, instrumentalities, subdivisions and\ngovernment owned or controlled corporations that HUDCC may call\nupon to participate are herebydirected to give priority attention to the\nProgram and provide HUDCC with full cooperation and support."}},{"id":"PH-H21141-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Reportorial Requirement - The Task Force shall\nsubmit the completed CLUP, duly approved by the Sangguniang\nPanglungsod/Pangbayan, and\nstatus report of its\nresponsibilities/tasks to the President, through the Presidential\nManagement Staff (PMS), within six (6) months from the effectivity\nof this Order;"}},{"id":"PH-H21141-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Repealing Clause - All issuances, orders, rules\nand regulations or any parts thereof, which are inconsistent,\nherewith are hereby repealed or modified accordingly."}},{"id":"PH-H21141-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Effectivity - This Executive Order shall take effect\nimmediately.\nDone in the City of Manila, this 26th\nin the Year of Our Lord, Two Thousand and Nine.\nday of october\nBy theresident\nEDUARDO R. ERMITA\nExecutive Secretary\nPGA Hologram # 51242"}}],"pack":"ph-p159"};
  FT["PH-H21142"] = {"id":"PH-H21142","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creation of the National Development Fund","orig":"Creation of the National Development Fund"},"level":"law","status":"active","docNumber":"Executive Order No. 842","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00842_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00842_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21142-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of the National Development Fund. The National Development Company (\"NDC\") is hereby\nauthorized to enter into investment whereby NDC shall undertake to manage the funds of said investors. The\nfunds contributed by said investors shall, however, be pooled for administrative purposes in a fund or\nsub-funds to be collectively known as the \"National Development Fund\" (the \"Fund\") which shall be invested\nin, among others, economically viable projects of NDC."}},{"id":"PH-H21142-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Issuance of National Development Fund Certificates. To evidence the investments made in the Fund,\nNDC, is hereby authorized to issue certificates, to be called \"National Development Fund Certificates\" (\"NDF\nCertificates\") to the investors. In issuing the NDF Certificates, NDC shall not be considered as exercising\n\"quasi-banking functions\" nor \"financial intermediations\" as defined under Section 2-D of the General\nBanking Act, and the NDF Certificates shall not be considered as \"deposit substitutes\" as defined under"}},{"id":"PH-H21142-A100","no":100,"noLabel":{"en":"Section 100"},"text":{"en":"A of the General Banking Act.\nSec. 3. Management. The Fund shall be managed by NDC, as the agent of the investors, and NDC shall not\nchange a management fee nor share in the income of the Fund, although it shall be entitled to reimbursement\nof expenses. As investment manager, NDC is hereby authorized to formulate the specific features of the Fund\nand the NDF Certificates as well as the guidelines in the operation thereof.\nSec. 4. Board of Trustees. The investors shall be represented by a Board of Trustees to whom NDC will report\non the operations of the Fund.\nSec. 5. Protection of Investment. To safeguard the interest of the investors in the Fund such that the\ninvestment of each investor can be redeemed at least at the face value of each NDT Certificate, NDC as\ninvestment manager, is hereby directed to stand ready to purchase any of the investments of the Fund in the\nevent the total net asset value of the Fund falls below its total original acquisition cost.\nSec. 6. Taxes. For purposes of taxation, the Fund shall not be considered a \"corporation\" under the National\nInternal Revenue Code and as such will not be subject to income tax. The Fund shall be deemed owned by the\ninvestors in proportion to their respective interests and all income earned by the Fund shall be deemed the\nincome of the investors for which said investors shall bear all taxes. In cases, therefore, where the income\nearned by the Fund is subject to final taxes, said taxes shall be deemed paid by the investors.\n\nSec. 7. Auditor. NDC shall appoint an independent Certified Public Accountant to be the auditor of the\nNational Development Fund.\nSec. 8. Separability Clause. Should any provision of this Order be held to be unconstitutional, no other\nprovision thereof shall be affected thereby.\nSec. 9. Effectivity. This Order shall take effect immediately.\nDone in the City of Manila, this 5th day of November, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21143"] = {"id":"PH-H21143","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DESIGNATING THE DEPUTY EXECUTIVE SECRETARY FOR LEGAL AFFAIRS (DESLA) AS ADDITIONAL MEMBER OF THE PRESIDENTIAL ANTI-GRAFT COMMISSION (PAGC) CREATED UNDER EXECUTIVE ORDER NO. 12, SERIES OF 2001, AS AMENDED","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DESIGNATING THE DEPUTY EXECUTIVE SECRETARY FOR LEGAL AFFAIRS (DESLA) AS ADDITIONAL MEMBER OF THE PRESIDENTIAL ANTI-GRAFT COMMISSION (PAGC) CREATED UNDER EXECUTIVE ORDER NO. 12, SERIES OF 2001, AS AMENDED"},"level":"law","status":"active","docNumber":"Executive Order No. 842","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00842_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00842_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21143-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 2 of Executive Order No. 12 is hereby further amended to\ninclude the Deputy Executive Secretary for Legal Affairs (DESLA) of the Office of the\nPresident as ex-officio Commissioner."}},{"id":"PH-H21143-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"All Executive Orders, rules, regulations and other issuances or parts\nthereof which are inconsistent with the provisions of this Executive Order are hereby\nrepealed, amended or otherwise modified accordingly."}},{"id":"PH-H21143-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"This Executive Order shall take effect immediately after it has been\npublished in a newspaper of general circulation.\nDONE in the City of Manila, Philippines this 30th day of October, 2009\nthere Mr. King\nEDUARDO R. ERMITA\nPGA Hologram * 51446 Executive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21144"] = {"id":"PH-H21144","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating a Commission on Export Procedures","orig":"Creating a Commission on Export Procedures"},"level":"law","status":"active","docNumber":"Executive Order No. 843","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-05","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00843_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00843_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21144-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Commission shall have the following powers and duties:\n(1) to undertake and overall review of existing documentation requirements for the exportation of goods,\nincluding rules and regulations, administrative orders, circulars, guidelines and procedures governing exports\nto the end that bureaucratic red tape be eliminated;\n(2) to review the procedural and documentation requirements of all government agencies which have\nfunctions connected with the export of products to pinpoint cause of delays and to find ways and means to\neliminate such causes of delay;\n(3) to revise, amend, introduce innovations, consolidate and simplify all rules and regulations, administrative\norders, circulars, guidelines and procedures to expedite exports and to dispense with excessive documentation\nand inspection requirements under such safeguards as the Commission may deem proper and sufficient;\n(4) to pass upon any proposed export document requirements by any government agency before its\nimplementation and to disapprove or suspend the same if it will unduly delay exportation; and\n(5) to promulgate its own rules of review and such regulations to implement its powers and duties."}},{"id":"PH-H21144-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Ministry of Trade and Industry shall provide the Secretariat of the Commission to be headed by an\n\nExecutive Director, appointed by the Commission, the functions of which shall be prescribed by the\nCommission."}},{"id":"PH-H21144-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Commission, after a thorough study, may set up an Export Documentation Center whose\npersonnel shall be detailed from government agencies involved with exports such as Central Bank, Bureau of\nCustoms, and other agencies, to process any application to export without need of referring the said\napplication to their respective offices and thus facilitate exportation."}},{"id":"PH-H21144-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The Center is authorized to charge reasonable fees for services rendered to the exporters which may be\nimmediately used by the Center to maintain its operations."}},{"id":"PH-H21144-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 5th day of November, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21145"] = {"id":"PH-H21145","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES RELEASE OF THE FIFTEEN PERCENT (15%) SHARE OF BENEFICIARY GOVERNMENT UNITS (LGUs) CONSISTING OF PROVINCES, CITIES, AND MUNICIPALITIES PRODUCING BURLEY AND NATIVE TOBACCO IN THE TOTAL INCREMENTAL REVENUE COLLECTED FROM THE EXCISE TAX ON TOBACCO PRODUCTS ACCUMULATED FROM","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES RELEASE OF THE FIFTEEN PERCENT (15%) SHARE OF BENEFICIARY GOVERNMENT UNITS (LGUs) CONSISTING OF PROVINCES, CITIES, AND MUNICIPALITIES PRODUCING BURLEY AND NATIVE TOBACCO IN THE TOTAL INCREMENTAL REVENUE COLLECTED FROM THE EXCISE TAX ON TOBACCO PRODUCTS ACCUMULATED FROM"},"level":"law","status":"active","docNumber":"Executive Order No. 843","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00843_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00843_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21145-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"RELEASE OF THE ACCUMULATED SHARES OF THE\nBENEFICIARY LGUs FROM 1997 TO 2007. The Department of Finance\n(DOF), Department of Budget and Management (DBM), Bureau of Internal\nRevenue (BIR and National Tobacco Administration (NTA) shall all take the\nnecessary steps to ensure that the beneficiary LGUs get their respective shares\nfrom the unreleased 15% of the incremental revenue from the excise tax on\ntobacco products for years 1997 to 2007 amounting to P6,370,708,183.73 either\non installment basis for a period of seven (7) years starting FY 2010 up to FY\n2016, or avail in advance their respective shares through a monetization"}},{"id":"PH-H21145-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"MONETIZATION PROGRAM. The Monetization Program (MP),\nshould this be availed of by the beneficiary LGUs, will give such beneficiaries the\noption to collect in advance from the trustee bank/s their respective shares at a\ndiscounted value, net of interest and other charges."}},{"id":"PH-H21145-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"RESPONSIBILITIES.\nA. Bureau of Internal Revenue. The BIR shall:\n• Submit to DBM a certification representing the 15% of the\nincremental revenue collected from the excise tax on tobacco\nproducts for the purpose of providing an appropriation cover.\nB. National Tobacco Administration. The NTA shall:\n• Submit to DBM a certification showing the list of burley and/or\nnative tobacco production LGUs and its respective volume of\nacceptances (in kilograms) duly approved by the NTA\nadministrator.\nC. Department of Budget and Management. The DBM shall:\n• Determine the share of each beneficiary LGU in the unpaid 15%\nof the incremental revenue on the basis of the BIR certification\nand NTA certification of volume of acceptances and issue the\ncorresponding Notice of Payment Schedule (NPS) to inform the\nbeneficiary LGU's of their shares and the schedule of payment.\n• Provide an annual appropriation cover for the purpose.\nPGMA Holaram « 51510\n\nD. Department of Finance. The DOF shall;\n• Provide the letter of confirmation of the National Government\nthat the P6,370,708,183.73 constitutes an obligation of the\nRepublic of the Philippines.\n• Favorably endorse to the Bangko Sentral ng Pilipinas or other\nregulatory agencies, as the case may be the application to\nsecure the necessary financial features for the investment\ncertificates that may be issued to improve the net proceeds to\nthe beneficiaries.\n• At the option of the recipient LGU, make arrangement with the\ntrustee bank on the requirements for the opening of the\nnecessary Special Trust Account; and\n• Make available the facilities of the Bureau of the Treasury,\nincluding but not limited to, the Registry of Scripless Securities\n(RoSS), the Automated Debt Auction Processing System\n(ADAPS), and such other facilities as may be required and\nnecessary for the auctioning process and the implementation of\nthe Monetization Program.\nE. Government Financial Institution/s. The government financial\ninstitution/§ (GFI/s) designated by the recipient LGU for this\nundertaking shall serve as trustee bank/s for purposes of monetizing\nthe shares of beneficiary LGUs. All transactions relative to the\nmonetization program shall be undertaken in accordance with the\nexisting accounting, auditing, and budgeting rules and regulations. A\nlist of the beneficiary LGUs that availed of the MP shall be submitted to\nF. Local Government Units. The beneficiary LGUs which will enroll in\nthe monetization scheme shall accomplish and submit the pertinent\ndocuments required in the monetization program.\nG. Commission on Audit. The COA shall provide guidelines in the\nrecording of the obligation in the books of account of the National\nGovernment."}},{"id":"PH-H21145-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"SEPARABILITY CLAUSE. If any section or provisions of this\nExecutive Order shall be declared unconstitutional or invalid, the other sections\nor provisions not affected thereby shall remain in full force and effect.\nimmediately.\nEFFECTIVITY.\nThis Executive Order shall take effect\nPOMA Hologram # 51511\n\nDone in the City of Manila, this 5th\nLord, Two Thousand and Nine.\nday of Novewbcar, in the year of the\nOliver h. King\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram * 51512"}}],"pack":"ph-p159"};
  FT["PH-H21146"] = {"id":"PH-H21146","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Increasing the Number of Directors of the National Power Corporation From Seven (7) to Nine (9)","orig":"Increasing the Number of Directors of the National Power Corporation From Seven (7) to Nine (9)"},"level":"law","status":"active","docNumber":"Executive Order No. 844","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-08","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00844_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00844_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21146-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 844 November 8, 1982\nINCREASING THE NUMBER OF DIRECTORS OF THE NATIONAL POWER CORPORATION FROM\nSEVEN (7) TO NINE (9)\nWHEREAS, it is desirable for national development planning to coordinate forestry development with power\ndevelopment particularly with reference to hydro-based power and to coordinate industrial development\nplanning with energy development planning;\nWHEREAS, under Presidential Decree No. 1416, as amended, the President is empowered to undertake such\norganizational and related improvements as may be appropriate in the light of changing circumstances and\nnew developments;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution and the authority vested in me by Presidential Decree No. 1416, as amended,\ndo hereby order that the number of directors of the Board of the National Power corporation be increased from\nseven (7) to nine (9) to include the Minister of Natural Resources and the Minister of Trade and Industry.\nDone in the city of Manila, this 8th day of November, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21147"] = {"id":"PH-H21147","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE PLACING THE COUNCIL OF INTERFAITH INITIATIVES UNDER THE NATIONAL SECURITY COUNCIL","orig":"MALACAÑAN PALACE PLACING THE COUNCIL OF INTERFAITH INITIATIVES UNDER THE NATIONAL SECURITY COUNCIL"},"level":"law","status":"active","docNumber":"Executive Order No. 844","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00844_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00844_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21147-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The Council of Interfaith Initiatives (CII) shall be placed under the\noversight of the National Security Council;"}},{"id":"PH-H21147-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The National Security Adviser shall be the Vice-Chair of the CII;"}},{"id":"PH-H21147-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"All issuances inconsistent with this order are hereby repealed or\namended accordingly."}},{"id":"PH-H21147-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 6th day of November in the Year of Our Lord, Two\nThousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p159"};
  FT["PH-H21148"] = {"id":"PH-H21148","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating a Foreign Investments Assistance Center","orig":"Creating a Foreign Investments Assistance Center"},"level":"law","status":"active","docNumber":"Executive Order No. 845","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00845_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00845_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21148-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"There is hereby created a Foreign Investments Assistance Center within the Board of Investments."}},{"id":"PH-H21148-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Central Bank, Securities and Exchange Commission, Human Settlements Regulatory Commission\nand Export Processing Zone Authority shall detail representatives of appropriate senior rank to the Center."}},{"id":"PH-H21148-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"In addition to said offices, the Center is authorized to require the detail from time to time, of personnel\nfrom other offices concerned with foreign investments to assist it in disposing of any problems related to the\nsetting up of business by foreign investors."}},{"id":"PH-H21148-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The Foreign Investments Assistance Center shall be a one-stop shop for foreign investors with\nauthority to act on any problems concerning the setting up of business by foreign investors."}},{"id":"PH-H21148-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Board of Investments shall formulate rules and regulations to implement the intent and purposes\nof this Executive Order."}},{"id":"PH-H21148-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Letter of Implementation No. 5 is hereby amended and all laws, decrees, orders, proclamations, rules,\nregulations, or parts thereof, which are inconsistent with any of the provisions of this Executive Order are\nhereby repealed or modified accordingly."}},{"id":"PH-H21148-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 8th day of November, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21149"] = {"id":"PH-H21149","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 845","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00845_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00845_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21149-A1","no":1,"noLabel":{},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila this 15 day of November in the year of Our Lord, Two\nThousand and Nine.\nQuinta hugs\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram # 51838"}}],"pack":"ph-p159"};
  FT["PH-H21150"] = {"id":"PH-H21150","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Amending Executive Order No. 827 Dated September 1, 1982","orig":"Amending Executive Order No. 827 Dated September 1, 1982"},"level":"law","status":"active","docNumber":"Executive Order No. 846","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00846_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00846_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21150-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Section 1 of Executive Order No. 827 is hereby amended to read as follows:\n\"Sec. 1. Coconut oil sold to the Philippine National Oil Company to be used as engine fuel, either in its pure\nstate or has blending component for diesel fuel, shall be exempted from the coconut levy and miller's tax for\ncrude coconut oil and sales tax for refined coconut oil, and the special fund impost and specific tax normally\napplied to diesel fuel.\""}},{"id":"PH-H21150-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Section 2 of the same order is hereby amended to read as follows:\n\"Sec. 2. The Ministry of Finance shall, in consultation with the Ministers of Energy and the National\nEconomic and Development Authority and upon recommendation of the Commissioner of Internal Revenue,\npromulgate the appropriate rules and regulations to implement this Order.\""}},{"id":"PH-H21150-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect immediately.\nDone in the City of Manila, this 10th day of November, in the year of Our Lord, nineteen hundred and eighty"}}],"pack":"ph-p159"};
  FT["PH-H21151"] = {"id":"PH-H21151","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MONETIZATION OF THE UNAPPROPRIATED AND UNRELEASED SHARE OF LOCAL GOVERNMENT UNITS PRODUCING VIRGINIA TOBACCO FROM THE 15% EXCISE TAX COLLECTION ON LOCALLY MANUFACTURED VIRGINIA-TYPE CIGARETTES FOR THE CALENDAR YEARS 2002 TO 2009 AMOUNTING TO P5,810,192,796.00","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MONETIZATION OF THE UNAPPROPRIATED AND UNRELEASED SHARE OF LOCAL GOVERNMENT UNITS PRODUCING VIRGINIA TOBACCO FROM THE 15% EXCISE TAX COLLECTION ON LOCALLY MANUFACTURED VIRGINIA-TYPE CIGARETTES FOR THE CALENDAR YEARS 2002 TO 2009 AMOUNTING TO P5,810,192,796.00"},"level":"law","status":"active","docNumber":"Executive Order No. 846","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00846_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00846_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21151-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"RELEASE OF THE ACCUMULATED SHARES OF THE\nBENEFICIARY LGUs FROM 2002 TO 2009. The Department of Finance (DOF),\nDepartment of Budget and Management (DBM), Bureau of Internal Revenue (BIR) and\nthe National Tobacco Administration (NTA) shall all take the necessary steps to ensure\nthat the beneficiary LGUs get their respective shares from the unreleased and\nunappropriated portion of the 15% of the excise tax collection on Virginia-type\nCigarettes for CYs 2002 to 2009 amounting to P5,810,192,796.00 through a\nmonetization program.\nPOMA Hologram * 51839"}},{"id":"PH-H21151-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"MONETIZATION PROGRAM. Monetization Program (MP), should\nbe this availed of by the beneficiary LGUs, will give such beneficiaries the option to\ncollect in advance from the trustee bank/s their respective shares at a discounted value,\nnet of interests and other charges."}},{"id":"PH-H21151-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"RESPONSIBILITES.\nA. Bureau of Internal Revenue. The BIR shall:\n• Submit to DBM a certification representing the 15% of the\nexcise tax collection on Virginia-type cigarettes for the purpose\nof providing an appropriation cover.\nB. National Tobacco Administration. The NTA shall:\n• Submit to DBM a certification, duly approved by the NTA\nAdministrator, of Virginia Tobacco production and Virginia\nTobacco acceptances by province, including congressional\ndistricts, cities and municipalities of each beneficiary province.\nC. Department of Budget and Management. The DBM shall:\n• Determine the share of each beneficiary LGU from the\nunreleased portion of 15% excise tax collection on the basis of\nthe BIR certification and NTA certification of volume and\nproduction and trade acceptances.\n• Issue the corresponding Notice of Payment Schedule (NPS) to\ninform the beneficiary LGUs of their shares.\n• Provide an annual appropriation cover for the purpose.\nD. Department of Finance. The DOF shall:\n• Provide the letter of confirmation of the National Government\nthat the P5,810,192,796.00 constitutes an obligation of the\nRepublic of the Philippines.\n• Favorably endorse to the Banqko Sentral ng Pilipinas or other\nregulatory agencies, as the case may be, the application to\nsecure the necessary financial features for the investment\ncertificates that may be issued to improve the net proceeds to\nthe beneficiaries.\n• At the option of the recipient LGU, make an arrangement with\nthe trustee bank on the requirements for the opening of the\nnecessary Special Trust Account; and\nPOMA Hologram # 51840\n\nArrange with the Bureau of Treasury to make available its\nfacilities, including but not limited to, the Registry of Scripless\nSecurities (ROSS), the Automated Debt Action Processing\nSystem (ADAPS), and such other facilities as may be required\nand necessary for the auctioning process and the\nimplementation of the Monetization Program.\nE. Government Financial Institution/s. The government financial\ninstitution/s (GFI/s) designated by the recipient LGU for this\nundertaking shall serve as trustee banks for purposes of monetizing\nthe shares of beneficiary LGUs. All transactions relative to the\nmonetization program shall be undertaken in accordance with the\nexisting accounting, auditing and budgeting rules and regulations. A\nlist of the beneficiary LGUs that availed of the MP shall be submitted\nF. Local Government Units. The beneficiary LGUs which will enroll in\nthe monetization scheme shall accomplish and submit the pertinent\ndocuments required in the monetization program.\nG. Commission on Audit. The CO shall provide guidelines in the\nrecording of the obligation in the books of account of the National\nGovernment."}},{"id":"PH-H21151-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"SEPARABILITY CLAUSE. If any section or provision of this\nExecutive Order shall be declared unconstitutional or invalid, the other sections or\nprovisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H21151-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"EFFECTIVITY. This Executive Order shall take effect immediately.\nDONE in the City of Manila this It day of November , in the year\nof Our Lord, Two Thousand and Nine.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Holagram • 51841"}}],"pack":"ph-p159"};
  FT["PH-H21152"] = {"id":"PH-H21152","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE OFFICE OF THE SENIOR DEPUTY COMMISSIONER IN THE BUREAU OF INTERNAL REVENUE","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES CREATING THE OFFICE OF THE SENIOR DEPUTY COMMISSIONER IN THE BUREAU OF INTERNAL REVENUE"},"level":"law","status":"active","docNumber":"Executive Order No. 847","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00847_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00847_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21152-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Creation of the Office of the Senior Deputy\nCommissioner. There is hereby created the Office of the Senior Deputy\nCommissioner under the Office of the Commissioner of Internal Revenue. The\nSenior Deputy Commissioner position shall have a rank of Director IV."}},{"id":"PH-H21152-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Functions. The Senior Deputy Commissioner shall have the\nfollowing functions and responsibilities:\n1. Provide support to the Commissioner of Internal Revenue in administering\nthe operations of the BIR and in directing all the officers and employees of\n2. Provide policies and pursue programs in the strategic and tactical aspects of\ntax administration, to include among others, enhancing taxpayer service and\n50422\nGMA Hologram 4 50422\n\ninformation dissemination; implementing a media campaign to project the\npositive projects and activities of the BIR; conduct regular assessments of\npublic perception of BIR activities; formation of a Tax Academy or Training\nInstitute institutionalizing an effective tax practitioner accreditation program;\nimproving the performance of the Large Taxpayers Service; conduct\nenforcement activities directed on major transactions that have significant\ntax potential; coordination with government offices in the implementation of\ninvestment incentives policies and programs; initiating practical\ninternationally accepted tax administration trends and practices; upgrading\nthe research and knowledge data base of the BIR; adoption of viable\ntechnology in tax administration processes; and, other activities that may be\ndirected by the Commissioner of Internal Revenue; and,\n3. Perform the function of the Commissioner in the absence of said functionary."}},{"id":"PH-H21152-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Annual Report. The Office of the Senior Deputy\nCommissioner, within three months after the end of every fiscal year, shall\nsubmit an annual report to the Secretary of Finance, through the Commissioner\nof Internal revenue."}},{"id":"PH-H21152-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repeal. All issuances, rules and regulations, or parts thereof,\nwhich are inconsistent with this Executive Order, are hereby repealed or modified\naccordingly."}},{"id":"PH-H21152-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Effectivity. This Executive Order shall take effect\nimmediately.\nDone in the City of Manila, this Mi day of August in the year of Our\nLord, two thousand and nine.\nMari Mr. Airy,\n50423\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 50423"}}],"pack":"ph-p159"};
  FT["PH-H21153"] = {"id":"PH-H21153","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reorganizing the Management Board of All Philippine Centers in the United States of America","orig":"Reorganizing the Management Board of All Philippine Centers in the United States of America"},"level":"law","status":"active","docNumber":"Executive Order No. 848","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00848_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00848_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21153-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The powers, functions and duties of the Office of the Chairman of the Management Board of all\nPhilippine Centers in the United States of America, as created under Presidential Decree Nos. 188 and 487,\nare hereby transferred from the Philippine Consul General in New York and the various Chiefs of Mission\nconcerned to the Chairman of the Philippines- United States Business Development Council. Henceforth, the\nChairman of the Philippines-United States Business Development Council shall be the Chairman of the\nManagement Board of all Philippine Centers in the United States of America. The Philippine Consul General\nin New York shall be the Co-Vice Chairman of the Management Board of the Philippine Center in New York,\nwhile each of Chief of Mission shall be the Co-Vice Chairman of the appropriate Management Board of the\nother Philippine Centers in the United States of America."}},{"id":"PH-H21153-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Chairman of the Management Board is hereby authorized to promulgate new rules and regulations\nor to amend existing ones issued by the said Management Board governing the operations of Philippine\nCenters as may be consistent with the objectives of Executive Order No. 831."}},{"id":"PH-H21153-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, Philippines this 19th day of November, in the year of Our Lord, nineteen hundred\nand eighty-two."}}],"pack":"ph-p159"};
  FT["PH-H21154"] = {"id":"PH-H21154","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE USE OF THE SPECIAL ACCOUNT IN THE GENERAL FUND (FUND 151) OF THE DEPARTMENT OF ENERGY FOR PURPOSES AS MAY BE DIRECTED BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE USE OF THE SPECIAL ACCOUNT IN THE GENERAL FUND (FUND 151) OF THE DEPARTMENT OF ENERGY FOR PURPOSES AS MAY BE DIRECTED BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 848","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00848_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00848_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21154-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Implementing Agency. The IA shall be responsible for the\nimplementation of the programs\ndisbursements/expenditures shall be subject to applicable laws and budgeting,\naccounting and auditing rules and regulations.\nFor recording purposes, the DBM shall authorize the IA to open and\nmaintain a SAG for the amounts released pursuant to this Executive Order (EO).\nIn case the IA is a Local Government Unit, the SAG shall be issued to DBM; and\nif the IA is a Government Owned or Controlled Corporation, the SAGF shall be\nissued to the BTr."}},{"id":"PH-H21154-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Repealing Clause. All EOs, rules, regulations and other\nissuances or parts thereof, which are inconsistent with the provisions of this E0,\nare hereby repealed or modified accordingly."}},{"id":"PH-H21154-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Effectivity. This EO shall take effect immediately.\nDone in the City of Manila, this 13th day of October, in the year of Our\nLord, Two Thousand and Nine.\nplease in Ring\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram * 52469"}}],"pack":"ph-p159"};
  FT["PH-H21155"] = {"id":"PH-H21155","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Increasing the Loan Value and Guarantee Coverage Under the Food Quedan Financing Program and for Other Purposes","orig":"Increasing the Loan Value and Guarantee Coverage Under the Food Quedan Financing Program and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 849","issuingBody":"President of the Philippines","promulgatedDate":"1982-11-26","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00849_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00849_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21155-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The loan value for food quedans pledged and/or mortgaged under the Food Quedan Financing Program\nshall be increased from 70% to 80%."}},{"id":"PH-H21155-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Correspondingly, the guarantee coverage under the said program shall be increased from 70% to 80%\nof outstanding loan."}},{"id":"PH-H21155-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The increase both in loan value and guarantee coverage shall be subject to all other existing rules and\nregulations."}},{"id":"PH-H21155-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"In order to lend more impetus to the attainment of the vital objectives of the Food Quedan Financing\nProgram, the Quedan Guarantee Fund Board shall streamline and expand its organization so as to cover more\nrice and corn producing provinces and that said Board, which is attached to the National Food Authority, is\nhereby granted the exemption on all personnel matters as are provided the latter under Executive Order No.\n839."}},{"id":"PH-H21155-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of November, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21156"] = {"id":"PH-H21156","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE ORGANIZATION OF THE MILLENNIUM CHALLENGE ACOUNT-PHILIPPINES AS A SUBSIDIARY OF THE DEVELOPMENT BANK OF THE PHILIPPINES MANAGEMENT CORPORATION TO FUNCTION AS THE ACCOUNTABLE ENTITY OR CENTRAL POINT OF CONTACT FOR THE MILLENNIUM CHALLENGE ACCOUNT COMPACT ASSISTANCE TO THE PHILIPPINES AND SETTING GENERAL GUIDELINES THEREFOR","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE ORGANIZATION OF THE MILLENNIUM CHALLENGE ACOUNT-PHILIPPINES AS A SUBSIDIARY OF THE DEVELOPMENT BANK OF THE PHILIPPINES MANAGEMENT CORPORATION TO FUNCTION AS THE ACCOUNTABLE ENTITY OR CENTRAL POINT OF CONTACT FOR THE MILLENNIUM CHALLENGE ACCOUNT COMPACT ASSISTANCE TO THE PHILIPPINES AND SETTING GENERAL GUIDELINES THEREFOR"},"level":"law","status":"active","docNumber":"Executive Order No. 849","issuingBody":"President of the Philippines","completenessNote":"全文，共 21 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00849_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00849_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21156-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Coordination. The DBPMC, in close consultation and\ncoordination with the DOF and the MCC, shall organize and incorporate the\nsubsidiary MCA-Philippines and shall take the steps necessary to ensure that the\ngoverning documents of MCA-Philippines are consistent with its mission towards\nCompact implementation and comply with MCC Guidelines.\n1.1. The DBPMC shall cause to be extended to it the authorities, permits,\nprimary and secondary licenses, and all other approvals necessary\nfor the purpose from administrative and regulatory bodies such as,\nbut may not be limited to, the DOF, Bangko Sentral ng Pilipinas\n(BSP), Office of the President (OP), and the Securities and Exchange\nCommission (SEC).\n1.2. The DOF, in consultation and coordination with the MCC and\nrelevant government authorities, shall manage all essential activities\nneeded to be undertaken preparatory to the operation of MCA-\nPhilippines and Compact implementation. The DOF may issue\nclarificatory guidelines, directives, or memoranda pursuant to this\n1.3. The DOF shall undertake Subsection 1.2 above with guidance from\nthe Inter-Agency Task Force for the MCA chaired by the Executive\nPOMA Hologram 4 52744\n2\n\nPOMA Hologram * 52745\nSecretary under Executive Order No. 607, s. 2007, as amended by\nExecutive Order No. 607-A, s. 2009.\nII. BOARD OF TRUSTEES\nGeneral Functions"}},{"id":"PH-H21156-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Oversight. - The Board of Trustees (\"Board\") shall oversee the\nfunctions of the Management Unit (\"Management) and shall be responsible for\nevaluating and approving major decisions to be implemented by MCA-Philippines.\n2.1. The Board shall perform its functions in accordance with the articles\nof incorporation and by-laws of MCA-Philippines and the laws and\nregulations pertinent to corporations prevailing in this jurisdiction.\n2.2. The Board must follow the governing documents of MCA-Philippines,\ncarry out its mission to implement the Compact, ensure MCC funding\nis used only for permitted purposes, and judiciously follow MCC\nguidelines.\n2.3. The Board shall protect, preserve, and manage program assets\nconsistent with the Compact and in accordance with applicable law.\nComposition"}},{"id":"PH-H21156-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Voting Members - Upon incorporation, the Board shall be\nreorganized to be composed of thirteen (13) voting members from the\ngovernment serving in ex officio capacity and from the non-government sector, as\nindicated hereunder:\n3.1. The Executive Secretary, Office of the President, or his/her\nrepresentative Deputy/Undersecretary;\n3.2. The Secretary, Department of Foreign Affairs, or his/her\nrepresentative Undersecretary;\n3.3. The Secretary, Department of Finance, or his/her representative\nUndersecretary;\n3.4. The Secretary, Department of Budget and Management (DBM) or\nhis/her representative Undersecretary;\n3.5. The Director General, National Economic and Development\nAuthority, or his/her representative Deputy Director General;\n3.6.\nThe Secretary, Department of Social Welfare and Development\n(DSWD) or his/her representative Undersecretary;\n3.7. The Secretary, Department of Public Works and Highways (DPWH)\nor his/her representative Undersecretary;\n3\n\n3.8. The Managing Director of the MCA-Philippines;\n3.9. Three (3) Representatives from non-governmental organizations\n(NGOs) to be selected by the government in consultation with MCC;\n3.10. The President of DBP; and\n3.11. The President of DBPMC."}},{"id":"PH-H21156-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Non-Voting Members - The Board shall have three (3) non-\nvoting members who shall assist in identifying implementation issues and help\npromote transparency in the decision-making process of the Board.\n4.1. There shall be one (1) representative from the MCC; and\n4.2.\nTwo (2) nominees from the Stakeholders Committee."}},{"id":"PH-H21156-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Election of Chair - The Board shall elect by a majority vote its\nChairperson from among the voting Members. The Chairperson, who shall preside\nover meetings, shall serve for a year, or until a new election is held."}},{"id":"PH-H21156-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Voting Power - All voting Board shall be entitled to one (1)\nvote, except that the Chair shall vote only in case of a tie."}},{"id":"PH-H21156-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Quorum. The presence of a simple majority of the voting\nmembers shall constitute a quorum for the purpose of transacting its business,\nprovided that the presence of at least one (1) voting Non-government Board\nmember shall be indispensable in constituting a quorum."}},{"id":"PH-H21156-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Requisites for Non-Government Board Members - Non-\ngovernment nominees shall be chosen not by the government but through a.\ntransparent process established by the Stakeholders Committee and agreed with\nthe MCC. They should be selected on the basis of his/her stakeholder\nrepresentation with respect to the projects involved in the program and his/her\ncapability to make the time commitment required as voting and non-voting Board\nStakeholders Committee"}},{"id":"PH-H21156-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Function - The Board shall create a Stakeholders Committee,\nwhich shall provide a mechanism for the government to continue the consultative\nprocess by allowing stakeholders opportunity both to be informed and to provide\ninputs regarding MCC-funded projects and various activities attendant thereto."}},{"id":"PH-H21156-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Composition - The committee shall be composed of not less\nthan seven (7) but not more than nine (9) representatives from non-governmental\norganizations, civil society, private sector, and local and regional government\nbeneficiaries.\nPGMA Holoaram # 52746\n\nPOMA Halogram « 52747\nIII. THE MANAGEMENT UNIT"}},{"id":"PH-H21156-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Function - MCA-Philippines shall have a Management Unit\nresponsible for its day-to-day program management, subject to the direction and\nguidance of the Board."}},{"id":"PH-H21156-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"Composition and Key Staff - The Management Unit shall be\ncomposed of qualified experts and at least of the following Key Staff, as defined\nunder MCC Guidelines or as may be defined hereafter in Compact documents:\n12.1. Managing Director\n12.2. Deputy Managing Director\n12.3. Director for Finance\n12.4. Director for Legal/General Counsel\n12.5. Director for Procurement\n12.6. Director for Social and Environmental Assessment\n12.7. Director for Monitoring and Evaluation\n12.8. Relevant Project Directors"}},{"id":"PH-H21156-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Selection Process for Key Staff - Key Staff shall be selected\nthrough an open and competitive recruitment and selection process and appointed\nin accordance with governing documents of MCA-Philippines and subject to MCC"}},{"id":"PH-H21156-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"Support Staff - MCA-Philippines may engage the professional\nservices of other support staff, as expertise and manpower are needed, and as\nexigencies require to carry out effectively the Management Unit's responsibilities.\nIV. REMUNERATION"}},{"id":"PH-H21156-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Remuneration - Remuneration rules for MCA-Philippines shall\nconform strictly with the provisions of the MCC Guidelines regarding compensation\nand reimbursement of Board Members, to wit:\n15.1. Members of the Board shall not be entitled to salaries, honoraria, or\nthe like from either MCC funding or government funding. However,\nthey will be entitled to reimbursement of reasonable expenses from\nMCC funding, provided such expenses arise from a Board member's\nattendance at special or regular board meetings of MCA-Philippines\n15.2. Members of the Stakeholders Committee of MCA-Philippines shall\nnot be entitled to salaries, honoraria, or the like from either MCC\nfunding or government funding. However, they will be entitled to\n5\n\nreimbursement of reasonable expenses from MCC funding, provided\nsuch expenses arise from a Stakeholders Committee member's\nattendance at special or regular Stakeholders Committee meetings of\nMCA-Philippines.\n15.3. Remuneration of the officers and staff of the Management Unit of\nMCA-Philippines shall be solely from MCC funding during the term of\nthe Compact and in accordance with MCC guidelines on remuneration."}},{"id":"PH-H21156-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Funding - The Government shall provide the MCA-Philippines\nan initial funding of Twenty Million Pesos (P20,000,000.00) to cover expenses of\nMCA-Philippines not covered by MCC funding and those required to be covered by\nthe Government under MCC rules such as but not limited to office space rental,\ninitial operating expenses, incorporation expenses, applicable taxes, and other\nnecessary implementation activities (\"Government counterpart\") to be drawn from\navailable funds of the Government and/or sources to be identified by. DBM subject\nto existing budgeting, accounting, and auditing rules and regulations. Said\nGovernment counterpart shall be maintained at an annual level of P20,000,000.00\nand/or subject to the actual operating requirements of the MCA-Philippines.\nVI. TAXATION; THIRD -PARTY AUDIT"}},{"id":"PH-H21156-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Taxation - The Government, through the DBM or the Fiscal\nIncentives Review Board, shall assume all taxes, duties and other fiscal levies which\nmay be imposed in the Republic of the Philippines, including any taxes, duties, and\nother fiscal levies imposed by local government units on MCA-Philippines, other\nparties involved in the development and implementation of the Compact, and\ntransactions related to the development and implementation of the Compact except\nfor taxes, imposed on the income, profits or gross receipts of natural persons who\nare citizens or permanent residents of the Philippines and legal persons organized\nunder Philippine laws. The DOF and relevant tax authorities shall promptly issue\nthe guidelines and procedures necessary to carry out this provision."}},{"id":"PH-H21156-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"Audit - Notwithstanding the jurisdiction of the Commission on\nAudit, MCA-Philippines shall be subject to independent third party audit to be\nfinanced using MCC funds.\nVII. FINAL PROVISIONS"}},{"id":"PH-H21156-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"Repeal - All issuances, rules and regulations, or parts thereof,\nwhich are inconsistent with this Executive Order, are hereby repealed or modified\naccordingly.\nPOMA Hologram # 52748\n6"}},{"id":"PH-H21156-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Principles for Implementation and Construction - The\nimplementation of the provisions of this Executive Order shall be guided by the\nprinciples of good governance, transparency, operational independence, and\naccountability. Any and all provisions subject to construction must be liberally\ninterpreted with the view of giving effect to the letter and rationale of the\ngoverning documents, agreements, and related or contemporaneous guidelines\npromulgated in pursuit of the same."}},{"id":"PH-H21156-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"Effectivity - This Executive Order shall take effect immediately\nupon its publication in a newspaper of general publication.\nDONE in the City of Manila this 15th day of December in the vear of\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram 4 52749"}}],"pack":"ph-p159"};
  FT["PH-H21157"] = {"id":"PH-H21157","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":22,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reorganizing the Ministry of Foreign Affairs","orig":"Reorganizing the Ministry of Foreign Affairs"},"level":"law","status":"active","docNumber":"Executive Order No. 850","issuingBody":"President of the Philippines","promulgatedDate":"1982-12-01","completenessNote":"全文，共 22 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00850_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00850_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21157-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Pursuant to the provisions of the Constitution, the President shall formulate the national guidelines and\noverall policies on foreign affairs. The Ministry of Foreign Affairs, hereinafter referred to as the Ministry,\nshall be the ministry primarily responsible for the planning, implementation and coordination of the\nappropriate supportive policies and programs in the field of foreign affairs, in accordance with the general\npolicies formulated by the President. The primary function of the Ministry shall be the promotion and conduct\nof the country's foreign relations, and the provision of such services to Filipino nationals abroad as may be\nThe President shall exercise control over the Ministry and the Prime Minister shall supervise the Ministry. The\nPrime Minister and the Cabinet shall be responsible to the Batasang Pambansa for the general program of\ngovernment."}},{"id":"PH-H21157-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The authority and responsibility for the exercise of the powers and the discharge of the functions of the\nMinistry shall be vested in the Minister of Foreign Affairs, hereinafter referred to as the Minister, who shall be\nappointed by the President. He shall be assisted by such Deputy Ministers as may be appointed by the\nPresident. The Minister is authorized to determine and assign the respective functional areas of responsibility\nof the Deputy Ministers, should there be more than one; provided, that such delineation of responsibilities\nshall cover the substantive functions and operations of the Ministry; and provided, further, that there shall be\nno Deputy Minister for Administration, and that the assignment of administrative responsibilities to any\nDeputy Minister shall be in addition to his substantive responsibilities."}},{"id":"PH-H21157-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"There is hereby created an Office of Inspection, Intelligence and Legal Services which shall absorb the\napplicable functions, appropriations, records, equipment, property, and personnel of the Office of Legal\nAffairs, the Inspection Division and the Intelligence and Research Division, which are hereinafter abolished.\nThe Office shall be responsible for enforcing high standards of performance in all foreign service posts\n\nthrough a system of periodic inspection. It shall also be responsible for the strict enforcement of security\nmeasures in the Ministry and the Foreign Service. It shall likewise be responsible for providing legal services\nin the negotiation of treaties as well as in their interpretations.\nThe Head of the Office of Inspection, Intelligence and Legal Services shall serve as Inspector General."}},{"id":"PH-H21157-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"There is hereby created an Office of Personnel and Management Services which shall be responsible\nfor the efficient management of services for the personnel of the Ministry and the Foreign Service."}},{"id":"PH-H21157-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Office of Press and Public Affairs is hereby renamed the Office of Public Affairs. It shall be\nresponsible for the handling of Ministry relations with the local and foreign media and educational institutions\nas well as in the regular dissemination of relevant information to all Foreign Services posts."}},{"id":"PH-H21157-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Office of Fiscal Affairs is hereby renamed the Office of Fiscal Services. It shall be responsible for\nall budget, financial and accounting services of the Ministry and the Foreign Service."}},{"id":"PH-H21157-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Office of Consular Affairs is hereby renamed the Office of Consular Services which shall be\nresponsible for the effective and efficient discharge of passport, visa and notarization services as well as the\nprovision of requisite assistance to Filipino citizens abroad."}},{"id":"PH-H21157-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"The Office of Protocol is retained. It shall be responsible for the handling of all activities of the\nMinistry concerning protocol, ceremonies and socials. It shall also be responsible for the proper observance\nand enforcement of all formalities, courtesies and facilities required by the Vienna conventions on Diplomatic\nRelations and Consular Relations as well as other related conventions and agreements."}},{"id":"PH-H21157-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"There are hereby created the following Offices:\n(1) Office of American Affairs\n(2) Office of Asian and Pacific Affairs\n(3) Office of European Affairs\n(4) Office of Middle East and African Affairs\n(5) Office of ASEAN Affairs.\nEach of the Offices shall be responsible for providing staff support and policy guidance to the Office of the\nMinister in the supervision of, as well as for monitoring and reporting of, the activities and operations of\nPhilippine diplomatic missions and posts within its geographical coverage. Such responsibility shall be in the\ncontext, among others, of providing a more aggregative perspective of policy issues, including its economic,\npolitical and cultural aspects, involving each particular geographic group or region. It shall also monitor the\nactivities of, and provide the necessary staff support in handling relationships with, foreign diplomatic\nmissions accredited to the Philippine government from the region concerned. The Minister shall determine the\nspecific diplomatic missions under each of the Offices.\nThe Office of ASEAN affairs shall be responsible for providing staff support and policy guidance to the office\nof the Minister in the supervision of, as well as for monitoring and reporting of, the activities and operations\nof the Philippine Government in ASEAN. It shall also serve as the secretariat of, and the coordinating agency\nfor, Philippine participation in ASEAN meetings and conferences.\nThe provision of staff support and policy guidance, as well as the monitoring and reporting responsibilities\ndefined above, of a sub-regional nature may be undertaken through such sub-regional desks within each\nOffice as may be created from time to time by the Minister."}},{"id":"PH-H21157-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"The Office of United Nations and International Organizations is retained. It shall be responsible for\nproviding staff support and policy guidance to the Office of the Minister in the supervision of, as well as for\nmonitoring and reporting of, the activities and operations of the Philippine Government in the United Nations,\nits specialized agencies and other inter-governmental organizations except ASEAN, as well as for Philippine\nparticipations in conferences therein. It shall also serve as the secretariat of all Philippine National\n\nCommissions and Councils created pursuant to commitments in the United Nations and its specialized"}},{"id":"PH-H21157-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"There is hereby created a Board of Foreign Service Administration to be composed of the Minister as\nchairman, and the Deputy Minister or Ministers, the heads of Offices, and a senior official of the Civil Service\nCommission as designated by the Chairman of the Commission, as members. The Minister, at his discretion,\nmay assign the chairmanship of the Board to the Deputy Minister, or where there is more than one Deputy\nMinister, to any of the Deputy Ministers. The Board shall be responsible for considering and recommending\npolicies for the efficient and economical discharge of the administrative operations of the Ministry and the\nForeign Service. It shall also consider and submit recommendations on policy and other important matters\nconcerning personnel including the appointment, assignment, and promotion of all Foreign Service Staff\nEmployees, Foreign Service Staff Officers as well as to recommend, through the Minister, to the President the\nappointment and promotion of Foreign Service Officers, Counselors and Chiefs of Missions. It shall likewise\nact and submit recommendations on administrative cases involving personnel of the Ministry and the Foreign"}},{"id":"PH-H21157-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"The Board of Foreign Service Examiners is retained. It shall be responsible for planning and\nadministering the Career Foreign Service Examinations. It shall have the Chairman of the Civil Service\nCommission or a Commissioner thereof designated by the Chairman of the Commission as chairman, and the\nDeputy Minister, or where there is more than one Deputy Minister a Deputy Minister designated by the\nMinister, the Head of the Office of Personnel and Management Services, and a senior official of the Ministry\nof Trade and Industry as designated by the Minister of Trade and Industry, as members."}},{"id":"PH-H21157-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"The Minister may designate as Special Advisers such as Chiefs of Missions on home assignment in\nspecific areas of their expertise as may be required by the exigencies of the service. The Minister may also\ncreate such advisory boards and committees as he may deem necessary to assist and provide him with advice\nin the formulation of substantive policies."}},{"id":"PH-H21157-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"The Ministry shall exercise supervision and control over the following offices:\n(1) Office of Asian and Pacific Affairs\n(2) Office of Middle East and African Affairs\n(3) Office of American Affairs\n(4) Office of European Affairs\n(5) Office of ASEAN affairs\n(6) Office of United Nations and International Organizations\n(7) Office of Protocol\n(8) Office of Inspection, Intelligence and Legal Services\n(9) Office of Personnel and Management Services\n(10) Office of Public Affairs\n(11) Office of Fiscal Services\n(12) Office of Consular Services\n(13) Board of Foreign Service Administration"}},{"id":"PH-H21157-A15","no":15,"noLabel":{"en":"Sec 15"},"text":{"en":"The Ministry shall exercise administrative supervision over the following entities:\n(1) Foreign Service Institute\n(2) UNESCO National Commission of the Philippines\n(3) Committee on State Visits\n\n(4) Technical Assistance Council\n(5) Board of Foreign Service Examiners"}},{"id":"PH-H21157-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"The following entities are hereby abolished, and their functions, together with applicable\nappropriations, records, equipment, property, and personnel are hereby transferred to such appropriate units of\nthe Ministry as may be deemed suitable by the Minister:\n(1) Office of Administration\n(2) Office of Legal Affairs\n(3) Office of Policy Planning\n(4) Office of Cultural Affairs\n(5) Office of Economic Affairs\n(6) Office of Islamic Affairs\n(7) Office of Political Affairs\n(8) ASEAN National Coordinating Agency of the Philippines\n(9) Board of Foreign Service\n(10) Promotion Board created under Section 11 of Executive Order No. 523\n(11) Inspection Division\n(12) Intelligence and Research Division"}},{"id":"PH-H21157-A17","no":17,"noLabel":{"en":"Sec 17"},"text":{"en":"The Ministry shall have such diplomatic missions and establishments abroad as may be necessary,\nunder the supervision and control of the Office of the Minister."}},{"id":"PH-H21157-A18","no":18,"noLabel":{"en":"Sec 18"},"text":{"en":"The Ministry is hereby authorized to issue such implementing rules and regulations as may be\nnecessary to implement the provisions of this Executive Order, provided that approval of the Office of Budget\nand Management is obtained relative to the new staffing pattern including appropriate salary rates, the\norganizational structure at divisional and lower levels, and the realignment of existing appropriations."}},{"id":"PH-H21157-A19","no":19,"noLabel":{"en":"Sec 19"},"text":{"en":"Except as may otherwise be determined by the Minister, all present incumbents of positions in the\nabolished units shall continue to exercise their usual functions, duties, and responsibilities, pending the\nissuance of the appropriate implementing orders."}},{"id":"PH-H21157-A20","no":20,"noLabel":{"en":"Sec 20"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith any of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21157-A21","no":21,"noLabel":{"en":"Sec 21"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof, provided that such remaining portions can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21157-A22","no":22,"noLabel":{"en":"Sec 22"},"text":{"en":"This Executive order shall take effect thirty days from the date of signing hereof.\nDone in the City of Manila, this 1st day of December, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21158"] = {"id":"PH-H21158","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENT TO ELIMINATE THE TARIFF RATES ON THE REMAINING PRODUCTS IN THE INCLUSION LIST IN YEAR 2010 UNDER THE COMMON EFFECTIVE PREFERENTIAL TARIFF (CEPT SCHEME FOR THE ASEAN FREE TRADE AREA (AFTA)/ASEAN TRADE IN GOODS AGREEMENT (ATIGA)","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENT TO ELIMINATE THE TARIFF RATES ON THE REMAINING PRODUCTS IN THE INCLUSION LIST IN YEAR 2010 UNDER THE COMMON EFFECTIVE PREFERENTIAL TARIFF (CEPT SCHEME FOR THE ASEAN FREE TRADE AREA (AFTA)/ASEAN TRADE IN GOODS AGREEMENT (ATIGA)"},"level":"law","status":"active","docNumber":"Executive Order No. 850","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00850_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00850_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21158-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles specifically listed in the Annex (Articles Granted\nZero Duty in 2010 under the CEPT Scheme for the AFTA) hereof, as classified\nunder Section 104 of the Tariff and Customs Code of 1978, as amended, shall be\nsubiect to the ASEAN CEPT rates in accordance with the schedule indicated in\nColumns 4 and 5 of said Annex. The ASEAN CEPT rates so indicated shall be\naccorded to imports coming from ASEAN Member States applying CEPT\nconcession to the same products pursuant to Article 4 of the CEPT Agreement\nand its Interpretative Notes."}},{"id":"PH-H21158-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"From the date of effectivity of this Executive Order, all\narticles listed in the Annex which are entered or withdrawn from warehouses in\nthe Philippines for consumption shall be imposed the rates of duty therein\nprescribed subiect to compliance with the Rules of Origin as provided in the\nAgreement on the CEPT Scheme for the AFTA signed on 28 January 1992, as"}},{"id":"PH-H21158-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"The tariff rates listed in the Annex and all relevant Executive\n•Orders issued in compliance with CEPT tariff reduction/elimination commitments\nare in accordance with the obligations under Articles 19 (Reduction or Elimination\nof Import Duties) and 21 (Issuance of Legal Enactments) of the ATIGA."}},{"id":"PH-H21158-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Nothing in this Executive Order shall preclude the Philippines\nfrom invoking its right of recourse to all trade remedy measures provided for in\nits law, this Agreement and relevant international agreements as an effective\ndevice against import surges."}},{"id":"PH-H21158-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"The provisions of this Executive Order are hereby declared\nseparable and in the event any such provision is declared invalid or\nunconstitutional; the other provisions, which are not affected thereby, remain in\nforce and effect."}},{"id":"PH-H21158-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"All presidential issuances, administrative rules and\nregulations, or parts thereof, which are inconsistent with this Executive Order are\nhereby revoked or modified accordingly."}},{"id":"PH-H21158-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"This Executive Order shall take effect on 01 January 2010\nfollowing its complete publication in the Official Gazette or in a national\nnewspaper of general circulation.\n2\n\nDONE in the City of Manila, this23rdlay of December, in the year of Our\nLord, Two Thousand and Nine.\nThere an hung\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nrAtiolooram # 52932"}}],"pack":"ph-p159"};
  FT["PH-H21159"] = {"id":"PH-H21159","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":23,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reorganizing the Ministry of Health, Integrating the Components of Health Care Delivery Into Its Field Operations, and for Other Purposes","orig":"Reorganizing the Ministry of Health, Integrating the Components of Health Care Delivery Into Its Field Operations, and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 851","issuingBody":"President of the Philippines","promulgatedDate":"1982-12-02","completenessNote":"全文，共 23 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00851_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00851_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21159-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Ministry of Health, hereinafter referred to as the Ministry, shall be the ministry having primary\nresponsibility for the formulation, planning implementation and coordination of policies and programs in the\nfield of health. The primary function of the Ministry is the promotion, protection, and preservation of the\nhealth of the people, through efficient, effective, encompassing, equitable and adequate health services.\nThe functions, authority and responsibilities of the Ministry shall be within the context of and subject to the\nconstitutional mandate on the formulation of national guidelines and the control of the ministries by the\nPresident, the supervision of the ministries by the Prime Minister, and the responsibility to the Batasang\nPambansa of the Prime Minister and the Cabinet for the general program of government.\nA. ORGANIZATION OF THE MINISTRY"}},{"id":"PH-H21159-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The authority and responsibility for the exercise of the powers and the discharge of the functions of the\nMinistry shall be vested in the Minister of Health, hereinafter referred to as the Minister. He shall be assisted\nby such Deputy Ministers as may be appointed by the President. The Minister is authorized to determine and\nassign the respective functional areas of responsibility of the Deputy Ministers, should there be more than one:\nProvided, That such delineation of responsibilities shall cover the substantive functions and operations of the\nMinistry; and Provided further, That there shall be Deputy Minister for Administration and that the\nassignment of administrative responsibilities to any Deputy Minister shall be in addition to his substantive\nresponsibilities.\nThe Ministry shall be composed of the Ministry proper, staff and line bureaus, special projects, medical\ncenters and special hospitals, and regional offices and their component units."}},{"id":"PH-H21159-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"There is hereby created a Health Education and Manpower Development Service which shall assume\nthe functions of the Office of Health Education and Personnel Training and those of the Medical Manpower\nDevelopment Committee, both of which are hereby abolished. The new service shall also be responsible for\nproviding the necessary staff support in the implementation of the Rural Health Practice Program. It shall\nabsorb applicable functions, appropriations, records, equipment, property, and such personnel as may be\nnecessary of the abolished units."}},{"id":"PH-H21159-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"There is hereby created a Bureau of Food and Drugs which shall assume the functions of the Food and\nDrug Administration which is hereby abolished. The functions to be assumed by the Bureau shall not include\nthose previous functions of the Narcotic Drugs Division of the Food and Drug Administration which have\nalready been assumed by the Dangerous Drugs Board pursuant to Batas Pambansa Blg. 179.\nIn addition to those functions transferred from the Food and Drug Administration, the Bureau shall have the\nauthority to prescribe general standards and guidelines with respect to the veracity of nutritional and medicinal\nclaims in the advertisement of food, drugs and cosmetics in the various media, to monitor such\nadvertisements, and to call upon any erring manufacturer, distributor, or advertiser to desist from such\ninaccurate or misleading, nutritional or medicinal claims in their advertising. Should such manufacturer,\ndistributor or advertiser refuse or fail to obey the desistance order issued by the Bureau, he shall be subject to\nthe applicable penalties as may be prescribed by law and regulations."}},{"id":"PH-H21159-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Bureau of Quarantine shall continue to perform its present functions, including supervision over\nrat proof zones in designated international ports and airports, and over medical examination of aliens for\nimmigration purposes.\nThe function of the Ministry regarding supervision over the sanitation of interisland vessels may be exercised\nby the Ministry through such of its field offices or the Bureau of Quarantine as it may indicate."}},{"id":"PH-H21159-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The staff bureaus and special projects enumerated under Section 8 hereunder may, operating through\nthe Minister, directly exercise line functions in the National Capital Region; Provided, that written delegation\nof authority has been obtained from the Minister; Provided, further, that such an arrangement will be\npermissible only for as long as the regional office of the Ministry for the National Capital Region has not been\nestablished."}},{"id":"PH-H21159-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Ministry proper shall be composed of the following units:\n(1) Office of the Minister\n(2) Planning Service\n(3) Financial and Management Service\n(4) Administrative Service\n(5) Disease Intelligence Center, which is hereby renamed Health Intelligence Service\n(6) Health Education and Manpower Development Service"}},{"id":"PH-H21159-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"The Minister shall exercise supervision and control over the following staff bureaus and special\n(1) Bureau of Dental Health Services\n(2) Bureau of Foods and Drugs\n(3) Bureau of Health Services\n(4) Bureau of Medical Services\n(5) Bureau of Research and Laboratories\n(6) Dermatology Research and Training Project, which is hereby renamed Dermatology Research and\nTraining Service\n(7) National Family Planning Office, which is hereby renamed Family Planning Service\n(8) Malaria Eradication Service\n(9) National Cancer Control Center, which is hereby renamed Cancer Control Center\n(10) National Nutrition Service, which is hereby renamed Nutrition Service\n\n(11) Radiation Health Office, which is hereby renamed Radiological Health Service\n(12) Schistosomiasis Control and Research Service"}},{"id":"PH-H21159-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"The Minster shall exercise supervision and control over the following line bureau:\n(1) Bureau of Quarantine"}},{"id":"PH-H21159-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"The Minister shall exercise supervision and control over the following medical centers, hospitals, and\nresearch institutes:\n(1) Jose R. Reyes Memorial Hospital, which is hereby renamed Jose R. Reyes Memorial Medical Center\n(2) Rizal Medical Center\n(3) Hospital ng Bagong Lipunan\n(4) Jose Fabella Memorial Hospital\n(5) National Children's Hospital\n(6) National Mental Hospital\n(7) National Orthopedic Hospital\n(8) Quirino Memorial General Hospital\n(9) San Lazaro Hospital\n(10) Research Institute for Tropical Medicine\nMedical centers and regional hospitals which are not listed above which are located outside of Metro Manila\nshall be under the supervision and control of the appropriate Regional Health Office."}},{"id":"PH-H21159-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"The Minister shall exercise administrative supervision over the following entities:\n(1) Dangerous Drugs Board\n(2) Philippine Medical Care Commission\n(3) Schistosomiasis Control Council"}},{"id":"PH-H21159-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"The following corporation shall be attached to the Ministry for policy and program coordination:\n(1) Tondo General Hospital and Medical Center, which is hereby renamed Tondo Medical Center.\nB. FIELD SERVICES OF THE MINISTRY"}},{"id":"PH-H21159-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"Regional Health Offices.\n(1) The Ministry shall have such ministry-wide regional offices as may be necessary, under the supervision\nand control of the Minister, in accordance with Article I, Chapter III, Part II of the Integrated Reorganization\nPlan as amended. Each Regional Health Office shall be headed by a Regional Director assisted by an\nAssistant regional Director.\nThe Regional Health Office shall be responsible for the field operations of the Ministry in the region and for\nproviding the region with effective health and medical services, utilizing the Primary Health Care approach\nwhich provides that health and medical services shall be responsive to the prioritized needs of the community\nas expressed by its members, and which mandates community participation in the determination of its own\nhealth care requirements.\nThe Regional Health Office shall have supervision and control over the Regional Hospital, over such medical\ncenters as may exist in the region, and over the various provincial health offices in the region.\n(2) The Regional Hospital shall have as part of its integrated facilities such Regional Laboratories and\nRegional Mental Hospitals as may exist in the region, subject to the following provisions. The Regional\nHospital shall be headed by a Chief of Regional Hospital, who shall be under the supervision and control of\n\nthe Regional Director.\nThe Regional Laboratory, formerly directly under the Regional/Health Office, shall be transferred to and\nmade part of either the Regional Hospital or the Medical Center in the region, whichever is nearer in location,\nincluding applicable appropriations, records, equipment, property, and such personnel as may be necessary.\n(3) The line functions of the Family Planning Service, the Malaria Eradication Service, the Nutrition Service,\nand the Schistosomiasis Control and Research Service shall be integrated into the appropriate Regional Health\nOffice, including applicable appropriations, records, equipment, property, and such personnel as may be"}},{"id":"PH-H21159-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"Provincial Health Offices.\n(1) The Provincial Health Office and the Provincial Hospital are hereby merged to constitute a new integrated\nProvincial Health Office. It shall be responsible for the complete integration of the promotive, preventive,\ncurative, and rehabilitative components of health care delivery within the province, as provided by the\nNational Government. It shall absorb the applicable functions, appropriations, records, equipment, and\nproperty of the merged units. The positions of Provincial Health Officer and Chief of the Provincial Hospital\nshall be merged into one position, and the staff of the new Office shall be a combination of the qualified\npersonnel of the two merged offices. Neither the incumbent provincial health officer nor the incumbent head\nof the provincial hospital shall have a prior right to be appointed or assigned as head of the new integrated\nProvincial Health Office. The Provincial Health Office shall be under the supervision and control of the\nRegional Director.\nThe Provincial Health Office shall exercise supervision and control over district hospitals and other field\nhealth units of the Ministry in the province, except those placed directly under the Office of the Minister under\nSection 10 hereof and the regional hospitals and medical centers under Section 13 (1) hereof. The provincial\nhealth officers and the assistant provincial health officers shall be appointed by the Minister of Health;\nProvided, That their assignments to particular provinces shall be made only upon consultation with the\ngovernor concerned. Their compensation shall be paid out of national funds.\n(2) The emergency hospitals, which shall henceforth be known as district hospitals, shall exercise supervision\nand control over all field health units in their respective areas as the first step in the implementation of the\nintegrated concept of health and medical services in the province. The rural health units and specialized field\nhealth units, in addition to their present functions, shall serve as the outpatient services of the district hospitals\nin their respective areas. Barangay health stations shall in turn be considered as extensions of rural health\nunits. Eventually, all personnel of field health units who are permanently assigned in the catchment areas\nthereof shall be absorbed by the district hospitals.\n(3) The functions of the Family Planning Service, the Malaria Eradication Service, the Nutrition Service, and\nthe Schistosomiasis Control and Research Service, insofar as they pertain to field operations, shall be\nintegrated into the Provincial Health Office within a period of two years after approval of the reorganization\nof the Ministry. This integration shall include applicable appropriations, records, equipment, property, and\nsuch personnel as may be necessary.\nSec. 14. City Health Offices. The city health officers and the assistant city health officers shall be appointed\nby the Minister of Health; Provided, That their assignments to particular cities shall be made only upon\nconsultation with the city mayor concerned. Their compensation shall be paid out of national funds."}},{"id":"PH-H21159-A15","no":15,"noLabel":{"en":"Sec 15"},"text":{"en":"Local Government Health Services. The provision by the Ministry of Health and Medical Services\nshall be without prejudice for any provincial or city government to establish its own health and medical\nservices; Provided, That the Ministry shall provide the necessary technical supervision in the provision of\nsuch health and medical services by the provincial or city government."}},{"id":"PH-H21159-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"The Minister shall have the authority to delegate such substantive and administrative powers and\nauthorities as may be necessary to the heads of the Regional Health Offices, in addition to such administrative\n\nauthorities as have been mandated for delegation for all Ministries by the President. The Minister shall also\ndelegate such powers and authorities to the heads of the Provincial Health Offices and those of other\nsubordinate units of the Regional Health Offices as in his judgment would make for a more efficient and\neffective administration of health and medical services."}},{"id":"PH-H21159-A17","no":17,"noLabel":{"en":"Sec 17"},"text":{"en":"The Minister is authorized to phase out the schools of nursing operated by the Ministry within a\nperiod of two years."}},{"id":"PH-H21159-A18","no":18,"noLabel":{"en":"Sec 18"},"text":{"en":"Appointments to supervisory positions in the field health services of the Ministry which are outside\nthe scope of the Career Executive Service, such as provincial and city health officers and assistant provincial\nand city health officers, shall be made on a general basis. The Minister shall have the authority to indicate the\nspecific assignments of the appointees, such as to a specific geographical area or a specific hospital facility,\nand to rotate or transfer them as necessary; Provided, That there shall be no diminution of their salaries as a\nresult of such rotation or transfer.\nC. MISCELLANEOUS PROVISIONS"}},{"id":"PH-H21159-A19","no":19,"noLabel":{"en":"Sec 19"},"text":{"en":"The Minister is hereby authorized to issue such orders, rules and regulations as may be necessary to\nimplement the provisions of this Executive Order; Provided, that approval of the Office of Budget and\nManagement is obtained relative to the new staffing pattern including appropriate salary rates, the\norganizational structure at divisional and lower levels, and the realignment of existing appropriations. The\nMinister may appoint qualified personnel to appropriate positions in the reorganized Ministry and those not so\nappointed are deemed laid off."}},{"id":"PH-H21159-A20","no":20,"noLabel":{"en":"Sec 20"},"text":{"en":"All those who are laid off under the provisions of this Executive Order shall be entitled to all benefits\nand gratuities provided under existing laws."}},{"id":"PH-H21159-A21","no":21,"noLabel":{"en":"Sec 21"},"text":{"en":"All laws, decrees, orders, proclamations, rules, regulations, or parts thereof, which are inconsistent\nwith nay of the provisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H21159-A22","no":22,"noLabel":{"en":"Sec 22"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying the other provisions thereof; Provided, that such remaining portions can still stand and\nbe given effect in their entirety to accomplish the objectives of this Executive Order."}},{"id":"PH-H21159-A23","no":23,"noLabel":{"en":"Sec 23"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 2nd day of December, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21160"] = {"id":"PH-H21160","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENTS ON TRADE IN GOODS CHAPTER OF THE AGREEMENT ESTABLISHING THE ASEAN-AUSTRALIA-NEW ZEALAND FREE TRADE AREA","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENTS ON TRADE IN GOODS CHAPTER OF THE AGREEMENT ESTABLISHING THE ASEAN-AUSTRALIA-NEW ZEALAND FREE TRADE AREA"},"level":"law","status":"active","docNumber":"Executive Order No. 851","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00851_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00851_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21160-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles listed in the Annex (Schedules of Tariff\nCommitments under. the AANZFTA) hereof, and accompanied by the proper\nCOMA Halogram # 52933\n\nCertificate of Origin (CO) Form AANZ, shall be subject to the rates of import duty as\nindicated in Columns 4 to 15 of said Annex."}},{"id":"PH-H21160-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"For Australia, New Zealand and ASEAN 9 (i.e. Brunei\nDarussalam, Cambodia, Indonesia, Lao Peoples Democratic Republic, Malaysia,\nMyanmar, Singapore, Thailand and Vietnam) the applicable rate shall be the\nAANZFTA preferential tariff, subject to the submission of the proper CO Form AANZ.\nPursuant to Section 1313(a) of the Tariff and Customs Code of the Philippines, as\namended, the Tariff Commission may, upon request, issue tariff classification rulings\nto confirm the applicable rates of duty of particular products covered by this\nExecutive Order."}},{"id":"PH-H21160-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"From the date of effectivity of this Executive Order, all articles\nlisted in the Annex which are entered or withdrawn from warehouses in the\nPhilippines for consumption shall be imposed the rates of duty therein prescribed\nsubject to compliance with the Rules of Origin as provided for in Chapter 3 of the\nAANZETA Agreement."}},{"id":"PH-H21160-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Nothing in this Executive Order shall preclude the Philippines\nfrom invoking its right of recourse to all trade remedy measures provided for in\nits law, the AANZFTA Agreement and relevant international agreements as an\neffective device against import surges."}},{"id":"PH-H21160-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"The provisions of this Executive Order are hereby declared\nseparable and in the event any such provision is declared invalid or\nunconstitutional, the other provisions, which are not affected thereby, remain in\nforce and effect."}},{"id":"PH-H21160-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"All presidential issuances, administrative rules and regulations,\nor parts thereof, which are inconsistent with this Executive Order are hereby\nrevoked or modified accordingly."}},{"id":"PH-H21160-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"This Executive Order shall take effect on 01 January 2010\nfollowing its complete publication in the Official Gazette or in a national newspaper\nof general circulation.\nDONE in the City of Manila, this 23rd day of December, in the year of Our\nLord, Two Thousand and Nine.\nGlair in hunger\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPÓMA Hologram P 52934"}}],"pack":"ph-p159"};
  FT["PH-H21161"] = {"id":"PH-H21161","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for More Effective Coordination Between National Development and Security Operations","orig":"Providing for More Effective Coordination Between National Development and Security Operations"},"level":"law","status":"active","docNumber":"Executive Order No. 852","issuingBody":"President of the Philippines","promulgatedDate":"1982-12-03","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00852_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00852_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21161-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Coordination at the National Level. The National Security Council, hereinafter referred to as the\nCouncil, shall, in addition to its present powers and functions, be responsible for effecting greater\ncoordination of development and security efforts at all levels of government, especially at the national,\nregional, and provincial levels, to achieve a more meaningful interaction between the civil and the military\nservices in both the planning and implementation aspects of development for specific areas, particularly those\nof higher security priority.\nThe term \"development and security\" when used in this Executive Order shall refer to the peace and order\naspects of the formulation and implementation of development programs and projects, especially those of an\narea-specific nature. It should not be construed to extend to purely development matters without security\nimplications, or vice versa.\nTowards these ends, the Council shall exercise the following additional specific powers and functions:\n(a) Monitor development plans, programs, and projects, particularly those of an area-specific nature, with\nrespect to their security implications;\n(b) Identify and indicate to the appropriate agencies the types of programs and projects and the specific areas\nthat are of higher security priority, for consideration both in the planning process and in the implementation\n\n(c) Provide guidelines to the various Regional Development Councils with respect to the security implications\nof their development programs and projects; and\n(d) Perform such other related functions or activities as may be necessary to accomplish its purposes and\nobjectives.\nIn exercising its functions of coordinating development and security programs, the Council shall be convened\nby the President or in his absence and through delegated authority by the Prime Minister, who is hereby\ndesignated as Vice Chairman of the Council, as often as may be necessary. Other Officials who are not\nmembers of the Council may participate, as deemed desirable by the President. The Council may also hold\njoint meetings with other entities and aggrupations, at the discretion of the President."}},{"id":"PH-H21161-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Coordination at the Regional Level. In addition to its other functions and responsibilities, the Regional\nDevelopment Council shall (a) coordinate the implementation of those area-specific programs and projects\nwith development and security implications at the individual regional level, (b) consider security conditions in\nthe regional planning process, particularly in the identification of programs and projects in areas requiring\npreferrential attention from the security standpoint, (c) consult and interact on a continuing basis with other\nregional bodies such as the Regional Peace and Order Council and other appropriate organizations, in\nfurtherance of their objectives, and (d) assist in coordinating the roles, functions, responsibilities and\nassignments of involved civil government entities in larger-scale military operations in the region as\nThe Regional Development Council may hold separate special meetings on development and security matters,\nor may at its discretion from a subcommittee for the purpose.\nThe membership of the Regional Development Council is hereby modified to include (a) the Regional\nCommander of the Philippine Constabulary, and (b) the Regional Director of the Ministry of Human\nSettlements.\nThe primary functions of the representatives of the military in the Regional Development Council shall be (a)\nto apprise the Council of security conditions in the various areas affected by the various programs and\nprojects, (b) to suggest, in the light of their perceptions of security conditions, priorities in attention in the\nformulation and implementation of area-specific programs and projects, both existing and prospective, and (c)\nto interface with other Council members on such security problems as may hamper the execution of\ndevelopment programs and projects.\nThe above-mentioned role of the military representatives in the various councils shall not in any way be\nconstrued to mean that the attainment of security is the exclusive responsibility of the armed forces, nor that\ndevelopment is the exclusive concern of the civilian government; rather, it shall be viewed within the context\nthat the attainment of security, like the attainment of development, is the collective responsibility of the\ngovernment as a whole."}},{"id":"PH-H21161-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Priority Areas. While the envisioned concerted development and security effort shall be on a\nnationwide basis, the initial focus shall be directed to such priority areas as may be identified by the Council."}},{"id":"PH-H21161-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Funding Requirements. The agencies involved in the projected cooperative endeavor shall operate\nwithin their approved appropriations, without prejudice to such additional funding as may be needed for added\noperational requirements. Whenever or wherever practicable, however, the implementing ministries and other\nagencies shall redirect their program thrusts to indicated priority areas in order to provide the desired support\nto the total effort."}},{"id":"PH-H21161-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Repealing Clause. All laws, executive orders, administrative orders, rules and regulations, or parts\nthereof, which are inconsistent with any provision of this Executive Order are hereby repealed, amended or\nmodified accordingly."}},{"id":"PH-H21161-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\n\nDone in the City of Manila, this 3rd day of December, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21162"] = {"id":"PH-H21162","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENTS UNDER THE TRADE IN GOODS CHAPTER OF THE AGREEMENT ON COMPREHENSIVE ECONOMIC PARTNERSHIP AMONG MEMBER STATES OF THE ASSOCIATION OF SOUTHEAST ASIAN NATIONS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED IN ORDER TO IMPLEMENT THE COMMITMENTS UNDER THE TRADE IN GOODS CHAPTER OF THE AGREEMENT ON COMPREHENSIVE ECONOMIC PARTNERSHIP AMONG MEMBER STATES OF THE ASSOCIATION OF SOUTHEAST ASIAN NATIONS"},"level":"law","status":"active","docNumber":"Executive Order No. 852","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00852_2009.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00852_2009.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21162-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles listed in the Annex (Articles Granted Concessions\nunder the AJCEPA) hereof, and accompanied by Certificate of origin (CO) Form\nAJ, shall be subject to the rates of import duty as indicated in Columns 4 to 14 of"}},{"id":"PH-H21162-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"For Japan and ASEAN 9 (i.e. Brunei Darussalam, Cambodia,\nIndonesia, Lao Peoples Democratic Republic, Malaysia, Myanmar, Singapore,\nThailand and Vietnam) the applicable rate shall be the AJCEPA preferential tariff,\nsubject to the submission of the proper Certificate of Origin Form AJ. Pursuant to\nSection 1313(a) of the Tariff and Customs Code of the Philippines, as amended,\nthe Tariff Commission may, upon request, issue tariff classification rulings to\nconfirm the applicable rates of duty of particular products covered by this\nExecutive Order."}},{"id":"PH-H21162-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"From the date of effectivity of this Executive Order, all\narticles listed in the Annex which are entered or withdrawn from warehouses in\nthe Philippines for consumption shall be imposed the rates of duty therein\nprescribed subiect to compliance with the Rules of Origin as provided for in\nChapter 3 of the AJCEPA."}},{"id":"PH-H21162-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Nothing in this Executive Order shall preclude the Philippines\nfrom invoking its right of recourse to all trade remedy measures provided for in\nits law, the AJCEPA and relevant international agreements as an effective device\nagainst import surges."}},{"id":"PH-H21162-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"The provisions of this Executive Order are hereby declared\nseparable and in the event any such provision is declared invalid or\nunconstitutional, the other provisions, which are not affected thereby, remain in\nforce and effect."}},{"id":"PH-H21162-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Except for Executive Order No. 767, s. 2008, which remains\nin force and effect, all presidential issuances, administrative rules and\nregulations, or parts thereof, which are inconsistent with this Executive Order are\nhereby revoked or modified accordingly.\n2\nPOMA Hologram # 53624"}},{"id":"PH-H21162-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"This Executive Order shall take effect fifteen (15) days\nfollowing its complete publication in the Official Gazette or in a national\nnewspaper of general circulation.\nDONE in the City of Manila, this23rdday of December, in the year of Our\nLord, Two Thousand and Nine.\ntheir a king.\nBy the President:\n5365\nEDUARDO R. ERMITA\nExecutive Secretary\nPGMA Hologram • 53625\n3"}}],"pack":"ph-p159"};
  FT["PH-H21163"] = {"id":"PH-H21163","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a Committee to Take Charge of the Planning and Execution of the Commemorative Activities for the 1984 Teodoro M. Kalaw Centennial Anniversary","orig":"Creating a Committee to Take Charge of the Planning and Execution of the Commemorative Activities for the 1984 Teodoro M. Kalaw Centennial Anniversary"},"level":"law","status":"active","docNumber":"Executive Order No. 853","issuingBody":"President of the Philippines","promulgatedDate":"1982-12-06","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00853_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00853_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21163-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 853 December 6, 1982\nCREATING A COMMITTEE TO TAKE CHARGE OF THE PLANNING AND EXECUTION OF THE\nCOMMEMORATIVE ACTIVITIES FOR THE 1984 TEODORO M. KALAW CENTENNIAL\nANNIVERSARY\nWHEREAS, 1984 marks the centenary of the birth of the late Teodoro M. Kalaw, lawyer, journalist, author,\nscholar, historian and statesman;\nWHEREAS, it is fitting and proper to commemorate the occasion with appropriate activities and/or\nceremonies, and;\nWHEREAS, to insure the successful celebration of this event, there is need to create a committee to take\ncharge of the planning and execution of the commemorative activities;\nNOW, THEREFORE, I, FERDINAND E. MARCOS President of the Philippines, by virtue of the powers\nvested in me by law, do hereby constitute and create a committee to formulate plans and devise ways and\nmeans for the successful execution of appropriate activities and/or ceremonies for the commemoration of the\n1984 Teodoro M. Kalaw Centennial Year. The Committee shall be composed of the following:\nDr. Serafin D. Quiason\nDr. Teodoro A. Agoncillo\nMr. Carlos Quirino\nMr. Esteban A. de Ocampo\nDr. Gloria Feliciano\nMr. Mariano Querol\nDr. Vedasto G. Suarez\nThe Chairman is hereby empowered to request any agency of the Government to assist in the discharge of the\nCommittee's functions and duties and to designate such personnel as he may require for the purpose.\nDone in the City of Manila, this 6th day of December, in the year of Our Lord, nineteen hundred and"}}],"pack":"ph-p159"};
  FT["PH-H21164"] = {"id":"PH-H21164","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DESIGNATING THE DEPARTMENT OF JUSTICE (DOJ) AS THE REPRESENTATIVE OF THE PRESIDENT OF THE PHILIPPINES IN THE IMPLEMENTATION OF PD1718 ON MATTERS INVOLVING THE AIRLINE INDUSTRY","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES DESIGNATING THE DEPARTMENT OF JUSTICE (DOJ) AS THE REPRESENTATIVE OF THE PRESIDENT OF THE PHILIPPINES IN THE IMPLEMENTATION OF PD1718 ON MATTERS INVOLVING THE AIRLINE INDUSTRY"},"level":"law","status":"active","docNumber":"Executive Order No. 853","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00853_2010.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00853_2010.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21164-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The Secretary of Justice is hereby designated as the representative of the\nPresident of the Philippines in the implementation of PD 1718 with regard to the enforcement of\nany foreign judgment as specified in Section 4 thereof, or compliance with any request, order,\ndirective or subpoena issued by any legislative, administrative or judicial authority in any\njurisdiction outside of the Philippines involving the documents and information referred to in\nSections 3 and 5 also of PD 1718, insofar as they pertain directly or indirectly to matters\ninvolving the airline industry."}},{"id":"PH-H21164-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The Civil Aeronautics Board (CAB) and the Department of Transportation\nand Communications (DOTC) are directed to coordinate and assist the Secretary of Justice, as the\ndesignated representative of the President of the Philippines, to facilitate the resolution of issues\nand concerns affecting airline companies involving the implementation of PD 1718."}},{"id":"PH-H21164-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"A Secretariat is hereby created to be composed of: one (1) Assistant\nSolicitor General (ASG) and two (2) Solicitors whom the Solicitor General shall designate, two\n(2) representatives from the Legal Office of the Office of the President (LO-OP), and one (1)\nrepresentative each from the CAB and the DOTC, who shall assist and extend their support to the\nSecretary of Justice for the efficient discharge of his duties and functions."}},{"id":"PH-H21164-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This order shall take effect immediately.\nDone in the City of Manila, this 5t day of January.\nTwo Thousand and Teb.\nin the Year of Our Lord,\nglen Mr. Aeroy\nBy the President:"}}],"pack":"ph-p159"};
  FT["PH-H21165"] = {"id":"PH-H21165","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for the Rationalization of the Desiccated Coconut","orig":"Providing for the Rationalization of the Desiccated Coconut"},"level":"law","status":"active","docNumber":"Executive Order No. 854","issuingBody":"President of the Philippines","promulgatedDate":"1982-12-06","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00854_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00854_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H21165-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Philippine Coconut Authority is hereby ordered to take such action as may be necessary to reduce\nthe number of existing desiccated coconut processing plants to a level which will insure the survival of the\nremaining plants. The Authority is hereby directed to determine which of the existing processing plants should\nbe phased out and to enter into appropriate contracts with such plants for the above purpose."}},{"id":"PH-H21165-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"To finance the acquisition of the facilities of the plants to be phased out and such other contracts which\nthe Authority may enter into, the Authority is hereby authorized to incur such loans as may be necessary. To\nrepay the above loans, the remaining desiccators are hereby assessed such amounts as the Authority may deem\nreasonable for the purpose. The Authority is hereby authorized to promulgate such rules and regulations as\nmay be necessary to fully and effectively implement this Order, specifically in respect to the acquisition of the\nexcess production facilities and their disposition. The assessment shall take effect upon such time as the\nAuthority may determine."}},{"id":"PH-H21165-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The assessment herein authorized as well as the assets to be acquired, will be subject to the exclusive\naudit by a reputable public accounting firm to be designated by the Authority upon consultation with the\ndesiccated coconut industry."}},{"id":"PH-H21165-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"This Order shall take effect immediately.\nDONE in the City of Manila, this 6th day of December 1982."}}],"pack":"ph-p159"};
